import { IPage } from "../../types/internal";
import { APageComponent } from "../APageComponent";
import { PageSchema, Events, IDragNDropComponent } from "../../types/external";
import { PageEventsMap } from "../../types/external";
import { getAllHandlers } from "./DragNDropHandlers";
import { IInstance } from "../../types/external";

export default class DragNDropComponent
    extends APageComponent<"dragndrop">
    implements IDragNDropComponent
{
    public name: "dragndrop" = "dragndrop";
    constructor(data: PageSchema["dragndrop"], page: IPage) {
        super(data, page);
    }
    public override onCreated(): void {
        super.onCreated();
        this.onDropped = this.onDropped.bind(this);
        this.onStartDrag = this.onStartDrag.bind(this);
        this.page.events.on(Events.INSTANCE_DROPPED, this.onDropped);
        this.page.events.on(Events.INSTANCE_START_DRAG, this.onStartDrag);
    }

    public override onDestroyed(): void {
        super.onDestroyed();
        this.page.events.off(Events.INSTANCE_DROPPED, this.onDropped);
        this.page.events.on(Events.INSTANCE_START_DRAG, this.onStartDrag);
    }

    public dropInstance(instance: IInstance): void {
        this.page.events.emit(Events.INSTANCE_DROPPED, {
            selectedInstance: instance,
        });
        instance!.events.emit(Events.INSTANCE_DROPPED, {
            selectedInstance: instance,
        });
    }

    /**
     * An object was picked up - remove it from wherever necessary
     * @param eventData
     */
    private onStartDrag(eventData: PageEventsMap[typeof Events.INSTANCE_START_DRAG]): void {
        const handlers = getAllHandlers(this.page, eventData.selectedInstance);
        handlers.forEach((handler) => {
            handler.onStartDrag();
        });
    }
    private onDropped(eventData: PageEventsMap[typeof Events.INSTANCE_DROPPED]): void {
        const handlers = getAllHandlers(this.page, eventData.selectedInstance);

        // find the first one that works and then stop
        const success = handlers.some((handler) => {
            return handler.handleDrop();
        });
        if (!success) {
            // fail
            handlers.forEach((handler) => {
                handler.onFail();
            });
        }
    }
}
