import {Circle as FCircle, Point as FPoint} from "@flatten-js/core";
import { Point } from "../../types/external";
import { drawCircle } from "../PolygonUtils";
import { AShape } from "./Shapes";
import { rotatePoint, translatePoint } from "../PolygonUtils";
export class CircleShape extends AShape {
    private _implementation: InstanceType<typeof FCircle>;

    constructor(
        private centre: Point,
        private radius: number,
    ) {
        super();
    }

    public getImplementation(): InstanceType<typeof FCircle> {
        if(!this._implementation){
            this._implementation = new FCircle(new FPoint(this.centre.x, this.centre.y), this.radius);
        }
        return this._implementation;
    }

    public getRadius(): number {
        return this.radius;
    }

    public override containsPoint(p: Point): boolean {
        return this.getImplementation().contains(new FPoint(p.x, p.y));
    }

    public override getCentre(): Point {
        return this.centre;
    }

    public override offset(p: Point): CircleShape {
        const newCentre = {
            x: this.centre.x + p.x,
            y: this.centre.y + p.y,
        };
        return new CircleShape(newCentre, this.radius);
    }

    public override transform(trans: Point, scale: Point, rot: number, origin: Point): CircleShape {
        const scaleToUse = Math.min(scale.x, scale.y); //has to stay as a circle
        const newR = this.radius * scaleToUse;
        const r = rotatePoint(this.centre, rot, origin)
        const newCentre = translatePoint(r, trans);
        return new CircleShape(newCentre, newR);
    }

    public toJSON(){
        return {
            centre: this.centre,
            radius: this.radius
        }
    }

    public override drawIn(ctx: CanvasRenderingContext2D): void {
        return drawCircle(this.centre, this.radius, ctx);
    }
}
