import Salad from "../../../index";
import { IActivityBackupComponent } from "../../../types/external";
import { AActivityComponent } from "../AActivityComponent";
import { ActivityOptions } from "../../../types/internal";
import { clone } from "../../../utils/utils";

export class ActivityBackupComponent extends AActivityComponent implements IActivityBackupComponent{

    constructor(private activity: Salad.IActivity, private options: ActivityOptions) {
        super();
    }

    public async resetPage():Promise<void>{
        const index = this.activity.getComponent("pages").getCurrentPageIndex();
        const pages = clone(this.options.backup!.pages);
        if(pages && pages[index]){
            this.activity.destroyCurrentPage();
            this.options.pages[index] = clone(pages[index]);
            await this.activity.gotoPageByIndex(index);
        }
    }

    public async resetActivity():Promise<void>{
        // destroy the current page
        this.activity.destroyCurrentPage();

        const pages = clone(this.options.backup!.pages);

        // reset the pages using the backup
        this.options.pages.forEach((_, i) => {
            this.options.pages[i] = pages[i];
        });

        this.options.data = clone(this.options.backup!.data);
        this.options.history = clone(this.options.backup!.history);

        return this.activity.start();
    }

}
