import Salad from "../../../index";
import { ActivityOptions } from "../../../types/internal";
import { AActivityComponent } from "../AActivityComponent";
import { IActivitySettingsComponent } from "../../../types/external";

export class PlayActivitySettingsComponent extends AActivityComponent implements IActivitySettingsComponent{

    private settings: Salad.IActivitySettings | undefined;

    constructor(private activity: Salad.IActivity, private options?: ActivityOptions) {
        super();
        this.settings = options?.settings;
        this.applySettings();
    }

    /**
     * update settings
     * @param settings 
     */
    public updateSettings(settings: Partial<Salad.IActivitySettings>):void{
        this.settings = {
            ...this.settings!,
            ...settings
        }
        
        this.applySettings();
        this.activity.save();        
    }

    public toggleFullScreen():void{
        const myDiv = this.options.container;

        if (!document.fullscreenElement) {
            if (myDiv.requestFullscreen) {
                myDiv.requestFullscreen();
            }
            //@ts-ignore
            else if (myDiv.mozRequestFullScreen) {
                //@ts-ignore
                myDiv.mozRequestFullScreen();
            }
            //@ts-ignore
            else if (myDiv.webkitRequestFullscreen) { // Chrome, Safari and Opera
                //@ts-ignore
                myDiv.webkitRequestFullscreen();
            }
            //@ts-ignore
            else if (myDiv.msRequestFullscreen) { // IE/Edge
                //@ts-ignore
                myDiv.msRequestFullscreen();
            }
        }
        else {
            // Exit fullscreen mode
            if(document.exitFullscreen) {
                document.exitFullscreen();
            }
            //@ts-ignore
            else if (document.mozCancelFullScreen) { // Firefox
                //@ts-ignore
                document.mozCancelFullScreen();
            }
            //@ts-ignore
            else if (document.webkitExitFullscreen) { // Chrome, Safari and Opera
                //@ts-ignore
                document.webkitExitFullscreen();
            }
            //@ts-ignore
            else if (document.msExitFullscreen) { // IE/Edge
                //@ts-ignore
                document.msExitFullscreen();
            }
        }
    }

    private applySettings(): void {
        const page = this.activity.getCurrentPage();
        if(page){
            // apply the settings to the page
            page!.getComponent("sound").setMuted(!!this.settings!.muted);
        }
        this.activity.events.emit(Salad.Events.ACTIVITY_APPLY_SETTINGS, this.settings);
    }

    /**
     * get settings
     * @returns 
     */
    public getSettings(): Salad.IActivitySettings {
        return this.settings!;
    }

    public override destroy(): void {
        this.settings = undefined;
    }


}
