/**
 * Class that represents a droppable component, that you can drop other objects into
 */

import { IDroppableComponent, IInstance } from "../../types/external";
import { Schema } from "../../types/external";
import { IPage } from "../../types/internal";
import { AComponent } from "../AComponent";

type DropAcceptanceFunction = (instance: IInstance) => boolean;

export default abstract class ADroppableComponent
    extends AComponent<"droppable">
    implements IDroppableComponent
{
    // Will this droppable accept the draggable? A custom function can be used if you want to
    private _acceptanceFunction: DropAcceptanceFunction | undefined = undefined;

    public name: "droppable" = "droppable";

    constructor(data: Schema["droppable"], instance: IInstance, page: IPage) {
        super(data, instance, page);
    }

    /**
     * droppables are of two types - contain and point.
     * contains means there is an area which you must drop into
     * type means that there is a point you must drop on
     * @returns
     */
    public getType(): Schema["droppable"]["type"] {
        return this.data.type;
    }

    public setType(type: Schema["droppable"]["type"]) {
        this.data.type = type;
    }

    public getTolerance(): number {
        return this.data.tolerance;
    }

    public getEnabled(): boolean {
        return this.data.enabled;
    }

    /**
     * clear the accepts
     */
    public clearAccepts() {
        this.data.acceptsInstances = undefined;
        this._acceptanceFunction = undefined;
    }

    /**
     * Set a custom acceptance function
     * @param acceptanceFunction
     */
    public setAcceptanceFunction(acceptanceFunction: DropAcceptanceFunction): void {
        this._acceptanceFunction = acceptanceFunction;
    }

    /**
     * Filter acceptance by instance name
     * @param instanceNames
     */
    public setAcceptsByInstanceName(instanceNames: string[]): void {
        this.data.acceptsInstances = instanceNames;
    }

    public addContent(instance: IInstance): void {
        //nothing in edit mode
    }

    public removeContent(instance: IInstance): void {
        //nothing in edit mode
    }

    /**
     * Returns the function to use to decide if we will accept this instance or not
     * Build it up by considering
     *   i) any custom function specified
     *   ii) the acceptsInstances properties
     * @returns
     */
    protected getAcceptanceFunction(): DropAcceptanceFunction {
        // user set this in the code, just use it
        if (this._acceptanceFunction) {
            return this._acceptanceFunction;
        } else {
            return (instance: IInstance): boolean => {
                const instanceName = instance.getName();

                if (this.data.acceptsInstances && this.data.acceptsInstances.length >= 1) {
                    return this.data.acceptsInstances.includes(instanceName);
                }

                return true;
            };
        }
    }

    /**
     * Will this droppable accept the draggable?
     *
     * @param droppedInstance
     * @returns boolean
     */
    public getWillAcceptInstance(droppedInstance: IInstance): boolean {
        return false;
    }

    override getDependencies() {
        return ["render"] as const;
    }
}
