import { IPage } from "../types/internal";
import { IAssetManager } from "../types/internal";
import { PageComponentName, IPageComponent, Events } from "../types/external";
import { PageSchema } from "../types/external";
import { proxied, HandlerFor } from "../utils/utils";
import { DependenciesForPage } from "../types/external";
import { PageComponentsMap } from "../types/internal";
import { KeyOfPageComponent } from "../types/external";
import { UpdateForPageComponent } from "../types/external";
import { PageComponentUpdate } from "../types/external";
import {ITranslator} from "../types/internal";
import { ISoundSequencer } from "../types/internal";

const createEventDataForUpdate = <K extends PageComponentName, T extends KeyOfPageComponent<K>>(
    page: IPage,
    component: APageComponent<K>,
    key: T,
    value: PageSchema[K][T],
) => {
    type Update = UpdateForPageComponent<K> & PageComponentUpdate;

    const payload: UpdateForPageComponent<K>["payload"] = {
        key,
        value,
    } as UpdateForPageComponent<K>["payload"]

    const updateForPageComponent: UpdateForPageComponent<K> = {
        component,
        payload
    };
    const update: Update = updateForPageComponent as Update;

    return {
        ...update,
        target: page,
    };
};

/**
 * Users of the Monaco code editor see the external definitions only
 */
export abstract class APageComponent<K extends PageComponentName> implements IPageComponent<K> {
    public abstract name: K;

    /**
     * data for this component
     * eg. position {x:10, y:10}
     */
    protected data: PageSchema[K];

    /**
     * the page
     */
    protected page: IPage;

    /**
     * Proxy the data object and emit events when anything changes
     * @param data
     * @param page
     */
    constructor(data: PageSchema[K], page: IPage) {
        const handler: HandlerFor<PageSchema[K] & object> = <T extends KeyOfPageComponent<K>>(key: T, value: PageSchema[K][T]) => {
            const eventData = createEventDataForUpdate(this.page, this, key, value);
            page.events.emit(Events.PAGE_COMPONENT_UPDATED, eventData);
            page.events.c[this.name].emit(Events.PAGE_COMPONENT_UPDATED, eventData);
        }
        this.data = proxied<PageSchema[K]>(data, handler);this.page = page;
        this.page = page;
    }

    public getData(): PageSchema[K] {
        return this.data;
    }

    /**
     * lifecycle
     * Override this to do something when the component is created
     */
    public onCreated(): void {
        this._checkDependencies();
    }

    /**
     * lifecycle
     * Override this to do something when the component is destroyed
     */
    public onDestroyed(): void {}

    /**
     * override this to specify the components that this component depends on
     * @returns
     */
    public getDependencies(): DependenciesForPage<K> {
        return [];
    }

    private _checkDependencies(): void {
        const componentNames = this.getDependencies();
        componentNames.forEach((componentName) => {
            if (!this.page.getComponent(componentName)) {
                throw new Error(`Component ${componentName} is required but is not present`);
            }
        });
    }

    /**
     * Get a page component.
     * You are only allowed to get ones that you specified in 'getDependencies'
     * @param name
     * @returns
     */
    protected getPageComponent<K extends ReturnType<this["getDependencies"]>[number]>(
        name: K,
    ): PageComponentsMap[K] {
        return this.page.getComponent(name) as PageComponentsMap[K];
    }

    /**
     * Every component gets an asset resolver
     * @returns
     */
    protected getAssetManager(): IAssetManager {
        /**
         * Converts 'bg' into path /images/sdk/whatever.jpg
         */
        return this.page.getAssetManager();
    }

    protected getTranslator(): ITranslator {
        return this.page.getTranslator();
    }

    protected getSoundSequencer(): ISoundSequencer {
        return this.page.getSoundSequencer();
    }

}
