import Salad from "../../../index";
import { IActivityPreloaderComponent } from "../../../types/external";
import { AActivityComponent } from "../AActivityComponent";
import { ActivityOptions } from "../../../types/internal";
import { getPreloader } from "../../preloader/ActivityPreloader";

const DEFAULT_THEME = "rgb(200,200,200,0.5)";

export class ActivityPreloaderComponent extends AActivityComponent implements IActivityPreloaderComponent{

    constructor(private activity: Salad.IActivity, private options: ActivityOptions) {
        super();
    }

    public async preload(): Promise<void> {
        const settings = this.activity.getComponent("settings").getSettings();
        const themeColor = settings?.themeColor || DEFAULT_THEME;
        const preloader = getPreloader({
            container: this.options.container,
            pages: this.options.pages,
            assetManager: this.options.api.assetManager,
            themeColor
        });
        await preloader.preload();
    }

}
