import { getLottieAsImageSrc } from "./lottieImageCache";
import Salad from "..";
const preloadedPaths: {[key: string]: boolean} = {};

export class AssetPreloader {

    constructor(private resolver: Salad.IResolver, private soundSequencer: Salad.ISoundSequencer) {}

    private hasPreloaded(path: string): boolean {
        return !!preloadedPaths[path];
    }
    
    private setPreloaded(path: string): void {
        preloadedPaths[path] = true;
    }

    private async preloadImage(path: string): Promise<void> {
        return new Promise((resolve) => {
            const img = new Image();
            img.onload = () => {
                this.setPreloaded(path);
                resolve();
            };
            img.onerror = () => {
                this.setPreloaded(path);
                resolve();
            };
            console.log("Preloading", path);
            img.src = path;
        });
    }

    private async preloadLottie(path: string): Promise<void> {
        try{
            await getLottieAsImageSrc(path);
        }
        catch(e){
            console.log("Failed to preload lottie", e)
        }
        this.setPreloaded(path);
    }

    private async preloadSound(path: string): Promise<void> {
        return new Promise((resolve) => {
            this.soundSequencer.preloadSound(path, path, ()=>{
                this.setPreloaded(path);
                resolve();
            })
        });
    }

    public async preload(type: string, resolvedPath:string): Promise<void> {
        if(this.hasPreloaded(resolvedPath)){
            return;
        }
        else if ((window as any).isJestEnvironment) {
            return;
        }
        else if (type === "image") {
            return await this.preloadImage(resolvedPath);
        }
        else if (type === "lottie") {
            return await this.preloadLottie(resolvedPath);
        }
        else if (type === "sound") {
            return await this.preloadSound(resolvedPath);
        }
    }
}
