
import { Schema, IInstance } from "../../types/external";
import { IPage } from "../../types/internal";
import ASelectComponent from "./ASelectComponent";
import { cover } from "../../utils/domElementFactory";

export default class EditSelectComponent extends ASelectComponent {

    //a div that floats on top to prevent editing and to allow easy dragging
    private cover: HTMLElement | undefined;

    constructor(data: Schema["select"], instance: IInstance, page: IPage) {
        super(data, instance, page);
    }

    protected override _redrawUI(): void {
        super._redrawUI();
        if (this._select) {
            this._select.setAttribute("disabled", "disabled");
            if(!this.cover){
                this.cover = this.getCover();
            }
        }
    }

    private getCover(): HTMLElement{
        return cover(this._element!);
    }

    protected override_destroyElement(): void {
        super._destroyElement();
        if (this.cover) {
            this.cover.remove();
            this.cover = undefined;
        }
    }


}
