import { Point } from "../../types/external";
import { getRect } from "../../utils/PolygonUtils";
import { rotateHandle, HANDLE_SIZE } from "../../utils/domElementFactory";
import { IInstance } from "../../types/external";

const guard = (val: number, min: number, max: number) => Math.max(min, Math.min(max, val));

export interface IHandle{
    destroy(): void;
    getWasHit(pos: Point): boolean;
}

export class Handle implements IHandle{

    private element: HTMLElement;
    private scale = 1;

    constructor(private instance: IInstance){
        const parent = this.instance.getComponent("render").getElement();
        this.element = rotateHandle(parent);
        const size = this.instance.getComponent("size").getSize();
        const minSize = Math.min(size.width, size.height);
        // scale the blob so it looks good on small objects
        if(minSize < 100){
            this.scale = 0.75;
        }
        const userDefinedHandlePosition = this.instance.getComponent("rotateable").getHandlePosition();

        let pos: Point;
        // is it valid?
        if(userDefinedHandlePosition && (userDefinedHandlePosition.x !== 0 || userDefinedHandlePosition.y !== 0)){
            pos = userDefinedHandlePosition;
        }
        else{
            pos = this.getBestHandlePosition();
        }
        Object.assign(this.element.style, {
            left: `${pos.x}px`,
            top: `${pos.y}px`,
            marginLeft: `${-HANDLE_SIZE/2}px`,
            marginTop: `${-HANDLE_SIZE/2}px`,
            transform: `scale(${this.scale})`,
            transformOrigin: "center"
        })
    }

    private getBestHandlePosition(): Point{
        const transComp = this.instance.getComponent("transform");
        const sizeComp = this.instance.getComponent("size");
        // put the blob on a corner furthest from the origin
        const size = sizeComp.getSize();
        const corners = getRect(size.width, size.height);
        const originPoint = transComp!.getOriginPoint();
        const distances = corners.map(corner => Math.sqrt((originPoint.x - corner.x) ** 2 + (originPoint.y - corner.y) ** 2));
        const uniq = [
            ...new Set(distances)
        ];
        let bestIndex:number;
        if(uniq.length === 1){
            // choose bottom-right because it looks good
            bestIndex = 2;
        }
        else{
            // get the maximum distance from the centre
            const maxDist = Math.max(...distances);
            bestIndex = distances.indexOf(maxDist);
        }
        const corner = corners[bestIndex];

        const displace = HANDLE_SIZE * this.scale;

        const x = corner.x === 0 ? displace : size.width - displace;
        const y = corner.y === 0 ? displace : size.height - displace;

        return {
            x,
            y
        }
    }

    public getWasHit(pos: Point): boolean{
        const handleRect = this.element.getBoundingClientRect();
        return (pos.x > handleRect.left && pos.x < handleRect.right && pos.y < handleRect.bottom && pos.y > handleRect.top);
    }

    public destroy(): void{
        this.instance = undefined!;
        this.element.remove();
    }
}
    
