import { Point } from "../../types/external";
import { Schema } from "../../schema/schema";

type DraggableAxis = Schema["draggable"]["axis"];

/**
 *
 * @param currentPos
 * @param newPos
 * @param axis
 * @returns
 */
export const applyAxis = (currentPos: Point, newPos: Point, axis: DraggableAxis): Point => {
    if (axis === "x") {
        return {
            x: newPos.x,
            y: currentPos.y,
        };
    } else if (axis === "y") {
        return {
            x: currentPos.x,
            y: newPos.y,
        };
    } else {
        return newPos;
    }
};
