import { IRenderComponent, IInstance } from "../../types/external";
import { Schema, CSSDomUpdate } from "../../types/external";
import { IPage } from "../../types/internal";
import { instance } from "../../utils/domElementFactory";
import { AComponent } from "../AComponent";

export default abstract class ARenderComponent
    extends AComponent<"render">
    implements IRenderComponent
{
    protected _element: HTMLElement | undefined = undefined;
    public name: "render" = "render";

    constructor(data: Schema["render"], instance: IInstance, page: IPage) {
        super(data, instance, page);
    }

    private updateZIndex(): void {
        const element = this.getElement();
        const css: CSSDomUpdate["css"] = {
            transform: {
                translateZ: `${this.data.zIndex}px`,
            }
        }
        this.page.getComponent("domupdate").addCSSUpdate({
            element,
            css,
        })
    }

    public getRenderLayer(): Schema["render"]["renderLayer"]{
        return this.data.renderLayer;
    }

    public setLayoutPaint(layoutPaint: boolean): void {
        this.data.layoutPaint = layoutPaint;
        this.updateLayoutPaint();
    }

    public setMouseEnabled(enabled: boolean):void{
        this.data.mouseEnabled = enabled;
    }

    public addClass(className: string): void {
        this._element!.classList.add(className);
    }

    public removeClass(className: string): void {
        this._element!.classList.remove(className);
    }

    protected abstract updateLayoutPaint(): void;

    private updateOpacity(): void {
        const element = this.getElement();
        this.page.getComponent("domupdate").addCSSUpdate({
            element,
            css: {
                opacity: this.data.opacity,
            }
        })
    }

    public abstract getRespondsToMouseEvents(): boolean;

    public override update(data: Schema["render"]) {
        super.update(data);
        this.updateZIndex();
        this.updateOpacity();
        this.updateLayoutPaint();
    }

    public setOpacity(opacity: number): void {
        this.data.opacity = opacity;
        this.updateOpacity();
    }

    public getOpacity(): number {
        return this.data.opacity;
    }

    public setZIndex(zIndex: number): void {
        this.data.zIndex = zIndex;
        this.updateZIndex();
    }

    /**
     * Bring the instance to the front of the z-index stack
     */
    public bringToFront(): void {
        this.page.instances.bringToFront(this.instance);
    }

    /**
     * Send the instance to the back of the z-index stack
     */
    public sendToBack(): void {
        this.page.instances.sendToBack(this.instance);
    }

    public getZIndex(): number {
        return this.data.zIndex;
    }

    public getElement(): HTMLElement {
        return this._element!;
    }

    /**
     * lifecycle - onCreated
     */
    public override onCreated() {
        this._element = instance();
        this.addToLayer();
        this.updateZIndex();
        this.updateOpacity();
        this.updateLayoutPaint();
    }

    protected addToLayer(): void {
        const layerName = "instances";
        const layersComp = this.page.getComponent("layers");
        layersComp.addChildToLayer(this._element, layerName);
    }

    /**
     * lifecycle - onDestroyed
     */
    public override onDestroyed() {
        super.onDestroyed();
        if (this._element && this._element.parentElement) {
            this._element.parentElement.removeChild(this._element);
        }
        this._element = undefined;
    }
}
