/**
 * page collisions in play mode
 *
 *
 */
import { IPage } from "../../types/internal";
import { APageComponent } from "../APageComponent";
import { PageSchema, IInstance, IPageCollisionsComponent, CollisionHashKey } from "../../types/external";
import {
    ICollisionsManager,
    getCollisionsManager,
    CollisionHash,
    CollisionData,
    getCollisionHashKeyForInstances,
} from "./CollisionsManager";
import { PageEventsMap, Events } from "../../types/external";
import { IShape } from "../../types/external";
export default class PlayPageCollisionsComponent
    extends APageComponent<"collisions">
    implements IPageCollisionsComponent
{
    /**
     * this will handle figuring out which collisions have started/ended
     * it stores a hash of "current collisions" where the key is a string like "instance1Id:instance2Id
     * and emits events when one starts or ends
     */
    private _collisionsManager: ICollisionsManager;

    /**
     * Are we running or not?
     * If no instances with a valid "group" have been added then don#t bother listening for collisions at all
     */
    private _started: boolean = false;

    public name: "collisions" = "collisions";

    constructor(data: PageSchema["collisions"], page: IPage) {
        super(data, page);
        this.onEnterFrame = this.onEnterFrame.bind(this);
        this.onInstanceCreated = this.onInstanceCreated.bind(this);
    }

    /**
     * lifecycle
     * get a collisions manager and listen to when something changes
     */
    override onCreated() {
        super.onCreated();
        this.page.events.on(Events.INSTANCE_CREATED, this.onInstanceCreated);
    }

    /**
     * lifecycle
     * clean up
     */
    public override onDestroyed(): void {
        super.onDestroyed();
        if (this._collisionsManager) {
            this._collisionsManager.removeAllListeners();
            this._collisionsManager.destroy();
        }
        this.page.events.off(Events.ENTER_FRAME, this.onEnterFrame);
    }

    private onInstanceCreated(eventData: PageEventsMap[typeof Events.INSTANCE_CREATED]): void {
        const group = eventData.target.getComponent("collision")!.getGroup();
        if (group && !this._started) {
            this.start();
            this._started = true;
        }
    }

    private start() {
        this._collisionsManager = getCollisionsManager();

        /**
         * Helper function
         * We emit the collision events on the page and both of the instances
         * You can listen to the event on either
         * @param eventName
         * @param data
         */
        const emit = (
            eventName: typeof Events.COLLISION_START | typeof Events.COLLISION_END,
            data: CollisionData,
        ) => {
            // emit event on the page
            this.page.events.emit(eventName, data);

            // also on instance1
            data.instance1.events.emit(eventName, data);

            const swappedData = {
                instance1: data.instance2,
                instance2: data.instance1,
            };

            // and on instance2
            data.instance2.events.emit(eventName, {
                ...data,
                ...swappedData,
            });
        };
        this._collisionsManager.on("collisionStart", (eventData: { data: CollisionData }) => {
            emit(Events.COLLISION_START, eventData.data);
        });
        this._collisionsManager.on("collisionEnd", (eventData: { data: CollisionData }) => {
            emit(Events.COLLISION_END, eventData.data);
        });

        this.page.events.on(Events.ENTER_FRAME, this.onEnterFrame);
    }

    public getCurrentCollisions(): CollisionHashKey[] {
        if (this._collisionsManager) {
            return this._collisionsManager.getCurrentCollisions();
        }
        return [];
    }

    public getCollides(instance1: IInstance, instance2: IInstance): boolean {
        if (this._collisionsManager) {
            const key = getCollisionHashKeyForInstances(instance1, instance2);
            return this._collisionsManager.getCollides(key);
        }
        return false;
    }

    /**
     * each frame, update the hash and check for collisions
     */
    private onEnterFrame(): void {
        const hash = this._buildCollisionHash();
        if (this._collisionsManager) {
            this._collisionsManager.update(hash);
        }
    }

    /**
     * instances can be assigned to groups and only those in the same group collide
     * the group can be any string, even ""
     * @returns
     */
    private _getGroupedInstances(): { [groupName: string]: IInstance[] } {
        const instances = this.page.instances.getAllInstances();
        const groupedInstances: { [groupName: string]: IInstance[] } = {};
        instances.forEach((instance: IInstance) => {
            const canCollide = instance.getComponent("render").getRenderLayer() === "instances";
            const groupName = (instance.getComponent("collision")!.getGroup() || "").trim();
            if (canCollide && groupName.length >= 1) {
                // a valid group
                const currentGroup = groupedInstances[groupName];
                groupedInstances[groupName] =
                    typeof currentGroup === "undefined" ? [instance] : [...currentGroup, instance];
            }
        });
        return groupedInstances;
    }

    /**
     * process each group and store which are colliding in a hash using the 'getTransformedShape' function
     * @returns
     */
    private _buildCollisionHash(): CollisionHash {
        const hash: CollisionHash = {};

        const groupedInstances = this._getGroupedInstances();

        const processGroup = (group: IInstance[]) => {
            if (group.length >= 2) {
                const sortedById = group.sort((a: IInstance, b: IInstance) => {
                    const idA = a.getId();
                    const idB = b.getId();
                    return idA === idB ? 0 : idA < idB ? -1 : 1;
                });

                const canCollide:boolean[] = [];
                const shapes:IShape[] = [];
                const isStatic:boolean[] = [];
                for (let i = 0; i < sortedById.length; i++) {
                    canCollide[i] = sortedById[i].getComponent("visibility")!.getCanCollide();
                    shapes[i] = sortedById[i].getComponent("collision")!.getTransformedShape();
                    isStatic[i] = sortedById[i].getComponent("collision")!.getIsStatic();
                }

                // check each pair of instances, loop from 0 to sortedById.length - 1
                for (let i = 0; i < sortedById.length - 1; i++) {
                    const instance1 = group[i];
                    const canCollide1 = canCollide[i];
                    const shape1 = shapes[i];

                    /**
                     * check which ones have collided.
                     * Loop from i + 1 to avoid processing the same one twice in the same frame
                     */
                    for (let j = i + 1; j < sortedById.length; j++) {
                        const instance2 = group[j];
                        const key = getCollisionHashKeyForInstances(instance1, instance2);
                        const shape2 = shapes[j];
                        const canCollide2 = canCollide[j];
                        const bothStatic = isStatic[i] && isStatic[j];
                        hash[key] = {
                            instance1,
                            instance2,
                            collides: bothStatic ? false : (canCollide1 && canCollide2 && shape1.intersects(shape2)),
                        };
                    }
                }
            }
        };
        Object.values(groupedInstances).forEach(processGroup);

        return hash;
    }
}
