/**
 * Abstract class for all navigation components
 * This allows you to specify 'go to nect page' for examaple
 */

import { INavigationComponent, IInstance, Schema } from "../../types/external";
import { IPage } from "../../types/internal";
import { AComponent } from "../AComponent";

export default abstract class ANavigationComponent
    extends AComponent<"navigation">
    implements INavigationComponent
{
    public name: "navigation" = "navigation";

    constructor(data: Schema["navigation"], instance: IInstance, page: IPage) {
        super(data, instance, page);
    }

    override getDependencies() {
        return ["render"] as const;
    }
}
