import { Schema, IInstance } from "../types/external";
import { IPage, InstanceData, IInstanceBuilder } from "../types/internal";
import { getInstance } from "../world/Instance";
import { IComponentFactory } from "../types/internal";
import { mergeDefaultsIntoSchema } from "./utils";
import type { DeepPartial } from "./utils";
import Salad from "../index";
class InstanceBuilder<T extends DeepPartial<Schema> = Schema> implements IInstanceBuilder<T> {
    constructor(
        private page: IPage,
        private factory: IComponentFactory,
        private defaultSchema: T,
    ) {}

    private build(schema: DeepPartial<T>): IInstance {
        if (!schema.identity?.displayName) {
            throw new Error("Please ensure you specify identity.displayName");
        }
        const name = schema.identity.displayName;
        const displayName = this.page.getComponent("instances")!.getNonDuplicateName(name);
        schema.identity.displayName = displayName;
        const id = Salad.Utils.getUUID();
        const instance = getInstance(id);
        const merged = mergeDefaultsIntoSchema<T>(this.defaultSchema, schema);
        const components = this.factory.buildAllComponents(merged, instance, this.page);
        instance.setComponents(components);
        return instance;
    }

    public buildInstanceUsingSchema(schema: DeepPartial<T>): IInstance {
        return this.build(schema);
    }

    public getInstanceFromData(instanceData: InstanceData): IInstance {
        let instance = getInstance(instanceData.id);
        let schema = instanceData.schema as DeepPartial<T>;
        const merged = mergeDefaultsIntoSchema<T>(this.defaultSchema, schema);
        const components = this.factory.buildAllComponents(merged, instance, this.page);
        instance.setComponents(components);
        return instance;
    }

    /**
     * Return this instance's data
     * @param instanceData
     * @returns
     */
    public getDataFromInstance(instance: IInstance): InstanceData {
        const id = instance.getId();
        return {
            id,
            schema: instance.toSchema(),
        };
    }
}

export const getInstanceBuilder = <T extends DeepPartial<Schema> = Schema>(
    page: IPage,
    factory: IComponentFactory,
    defaultSchema: T,
): IInstanceBuilder<T> => {
    return new InstanceBuilder<T>(page, factory, defaultSchema);
};
