/**
 * Debug component - draws debug information on the screen
 * The grid
 * The collision shapes
 */

import { IPage, IDebugComponent } from "../../types/internal";
import { APageComponent } from "../APageComponent";
import { PageSchema } from "../../types/external";
import { debug, canvas, grid } from "../../utils/domElementFactory";
import { IDebugDrawer, CollisionsDrawer, GridDrawer, ContainmentDrawer, BoundingCircle } from "./DebugDrawers";
export default class DebugComponent extends APageComponent<"debug"> implements IDebugComponent {
    // the element we will draw in
    private _element: HTMLElement;

    // we will update on an interval to keep it simple (we don't update when a polygon changes for example) - this is never used in play mode anyway
    private _interval: ReturnType<typeof setInterval> | undefined;

    // draw the stuff on the screen
    private _debugDrawers: {[key in keyof PageSchema["debug"]]: IDebugDrawer};

    public name: "debug" = "debug";

    constructor(data: PageSchema["debug"], page: IPage) {
        super(data, page);
        this._redraw = this._redraw.bind(this);
    }

    override onCreated() {
        super.onCreated();

        // make elements that we will draw inside

        // container
        this._element = debug();

        // draw collisions, containment and grid
        const collisonsCanvas = canvas(this._element);
        const containmentCanvas = canvas(this._element);
        const boxCanvas = canvas(this._element);
        const gridDiv = grid(this._element);

        const bgSize = this.page.getComponent("background").getSize();

        collisonsCanvas.width = bgSize.width;
        collisonsCanvas.height = bgSize.height;

        containmentCanvas.width = bgSize.width;
        containmentCanvas.height = bgSize.height;

        boxCanvas.width = bgSize.width;
        boxCanvas.height = bgSize.height

        Object.assign(gridDiv.style, {
            width: `${bgSize.width}px`,
            height: `${bgSize.height}px`,
        });

        // make drawers that will 'do the work' of drawing stuff
        this._debugDrawers = {
            boundingCircle: new BoundingCircle(this.page, boxCanvas),
            collision: new CollisionsDrawer(this.page, collisonsCanvas),
            grid: new GridDrawer(this.page, gridDiv),
            containment: new ContainmentDrawer(this.page, containmentCanvas),
        }
            
        // register a layer for this element so it gets resized properly
        const layerComp = this.getPageComponent("layers");
        layerComp.initLayer("collisions", this._element, {
            type: "full",
        });
        this.update();
    }

    public override onDestroyed(): void {
        super.onDestroyed();
        this._stopInterval();
    }

    public getElement(): HTMLElement {
        return this._element;
    }

    public override getDependencies() {
        return ["layers"] as const;
    }

    /**
     * Redraw everything
     */
    private _redraw() {
        const keys: (keyof PageSchema["debug"])[] = Object.keys(this.data) as (keyof PageSchema["debug"])[];
        keys.forEach((key) => {
            const drawer = this._debugDrawers[key];
            if (this.data[key]) {
                // enabled
                drawer?.redraw();
            }
            else{
                drawer?.clear();
            }
        });
    }

    // for simplicity we will just redraw everything on an interval
    private _startInterval(): void {
        this._interval = setInterval(this._redraw, 250);
    }

    private _stopInterval(): void {
        const keys: (keyof PageSchema["debug"])[] = Object.keys(this.data) as (keyof PageSchema["debug"])[];
        keys.forEach((key) => {
            const drawer = this._debugDrawers[key];
            drawer?.clear();
        });
        clearInterval(this._interval);
        this._interval = undefined;
    }

    /**
     * start/stop
     */
    public update(): void {
        const anyEnabled = Object.values(this.data).some((enabled) => enabled);
        if (anyEnabled) {
            this._startInterval();
        }
        else {
            this._stopInterval();
        }
    }

    public getEnabled(key: keyof  PageSchema["debug"]): boolean {
        return this.data[key];
    }

    public setEnabled(key: keyof  PageSchema["debug"], enabled: boolean): void {
        this.data[key] = enabled;
        this.update();
    }
}
