/**
 * Handles panning
 */
import { IInstance } from "../../types/external";
import { Point } from "../../types/external";
import { ICameraComponent, ICameraPanner } from "../../types/external";
import { PageSchema } from "../../types/external";

type Box = PageSchema["camera"]["view"];

const PAN_DISTANCE_PX = 100;

export class CameraPanner implements ICameraPanner {
    constructor(private cameraComp: ICameraComponent) {}

    /**
     * move the camera
     * @param amount
     * @param duration
     */
    public left(amount: number = PAN_DISTANCE_PX, duration?: number): void {
        this.by(-amount, 0, duration);
    }
    public right(amount: number = PAN_DISTANCE_PX, duration?: number): void {
        this.by(amount, 0, duration);
    }
    public up(amount: number = PAN_DISTANCE_PX, duration?: number): void {
        this.by(0, -amount, duration);
    }
    public down(amount: number = PAN_DISTANCE_PX, duration?: number): void {
        this.by(0, amount, duration);
    }

    /**
     * moev by a specific amount
     * @param amountX
     * @param amountY
     * @param duration
     */
    public by(
        amountX: number = PAN_DISTANCE_PX,
        amountY: number = PAN_DISTANCE_PX,
        duration?: number,
    ): void {
        const view = this.cameraComp.getView();
        this.cameraComp.moveToView(
            {
                ...view,
                left: view.left + amountX,
                top: view.top + amountY,
            },
            duration,
        );
    }

    private getViewForCentreAndSize(p: Point, size: {width: number, height: number}): Box {
        return {
            left: p.x - size.width / 2,
            top: p.y - size.height / 2,
            width: size.width,
            height: size.height, 
        };
    }

    public getViewForCentreOnInstance(instance: IInstance, zoom:number): Box{
        const zoomedView = this.cameraComp.zoom.getViewForZoom(zoom);
        const centre = instance.getComponent("collision").getCentre();
        return this.getViewForCentreAndSize(centre, zoomedView);
    }

    /**
     * centre on a point
     * @param p
     * @param duration
     */
    public centreOn(p: Point, duration?: number): void {
        const view = this.cameraComp.getView();
        const newView = this.getViewForCentreAndSize(p, view);
        this.cameraComp.moveToView(
            newView,
            duration,
        );
    }

    /**
     * centre the camera on an instance
     * @param instance
     * @param duration
     */
    public centreOnInstance(instance: IInstance, duration?: number): void {
        const centre = instance.getComponent("collision").getCentre();
        this.centreOn(centre, duration);
    }

    public destroy(): void {
        
    }
}
