/**
 * Abstract UI component
 * The UI displays things like buttons that float on top
 */

import { IPage, IUIComponent } from "../../types/internal";
import { APageComponent } from "../APageComponent";
import { ui } from "../../utils/domElementFactory";
import { PageSchema } from "../../types/external";
import { ButtonName } from "../../types/internal";
export default abstract class AUIComponent extends APageComponent<"ui"> implements IUIComponent {
    
    // make the element that we will use as a container for everything
    protected _element: HTMLElement;

    public name: "ui" = "ui";

    constructor(data: PageSchema["ui"], page: IPage) {
        super(data, page);
        this._element = ui();
    }

    public override getDependencies() {
        return ["layers", "camera"] as const;
    }

    public setNextPageHandler(handler: () => void): void {}

    public setPrevPageHandler(handler: () => void): void {}

    public getPageHandler(name: "prev" | "next"): (() => void) | undefined {
        return undefined;
    }

    // override this to set the enabled state of a button
    public abstract enable(name: "prev" | "next" | "scroll", enabled: boolean): void;

    public setScrollMethod(ui: PageSchema["ui"]["scroll"]): void{
        this.data.scroll = ui;
    }
    
    public getScrollMethod(): PageSchema["ui"]["scroll"]{
        return this.data.scroll;
    }
    
    public setNextMethod(ui: PageSchema["ui"]["next"]): void{
        this.data.next = ui;
    }
    
    public getNextMethod(): PageSchema["ui"]["next"]{
        return this.data.next;
    }

    public setPrevMethod(ui: PageSchema["ui"]["prev"]): void{
        this.data.prev = ui;
    }

    public getPrevMethod(): PageSchema["ui"]["prev"]{
        return this.data.prev;
    }

    public getElement(): HTMLElement {
        return this._element;
    }

    public isEnabled(name:ButtonName): boolean {
        return false;
    }
}
