import { DrawingToolSetting } from "../../../../types/external";
import { smearCanvas } from "../Smear";
import { cutOff } from "./utils";
import { ISimpleBrush, DrawingArea } from "./types";

export abstract class ASimpleBrush implements ISimpleBrush {
    protected ctx: CanvasRenderingContext2D;
    protected canvas: HTMLCanvasElement;
    protected options: DrawingArea["options"];

    constructor(
        protected drawingArea: DrawingArea,
        protected settings: DrawingToolSetting,
    ) {
        this.canvas = this.drawingArea.canvas;
        this.options = this.drawingArea.options;
        this.ctx = this.canvas.getContext("2d")!;
        this.ctx!.lineJoin = "round";
        this.ctx!.lineCap = "round";
    }

    /**
     * Lines get smaller further from the user
     * @param y
     * @returns
     */
    protected getDrawingSize(y: number): number {
        const perspective = cutOff(y, this.options.perspectiveScale, 1, {
            min: 0,
            max: this.canvas.height / 2,
        });
        return Math.ceil(this.settings.options.size * perspective);
    }

    /**
     * smear the pixels, make it look realistic-ish
     * @param x0
     * @param y0
     * @param x1
     * @param y1
     */
    protected smearFromTo(x0: number, y0: number, x1: number, y1: number, mix: number = 0.7) {
        /**
         * smear a circle slightly larger than the brush size into a circle slightly smaller than the brush size
         * the circles are centered on the start and end points of the line (x0, y0) and (x1, y1)
         */

        const minSize = 14;

        const size = Math.max(minSize, this.settings.options.size);

        const sizeSrc = Math.ceil(size * 1.25);
        const sizeDest = Math.ceil(size * 0.75);

        const src = {
            x: x0 - sizeSrc / 2,
            y: y0 - sizeSrc / 2,
            size: sizeSrc,
        };
        const dest = {
            x: x1 - sizeDest / 2,
            y: y1 - sizeDest / 2,
            size: sizeDest,
        };
        smearCanvas(this.canvas, src, dest, mix);
    }

    public abstract start(x: number, y: number): void;
    public abstract move(x: number, y: number): void;
    public abstract end(): void;
}
