/**
 * Spawn component in edit mode
 */

import { Schema, ISpawnComponent, IInstance } from "../../types/external";
import { IPage } from "../../types/internal";
import { AComponent } from "../AComponent";

export default class ASpawnComponent extends AComponent<"spawn"> implements ISpawnComponent {
    public name: "spawn" = "spawn";
    constructor(data: Schema["spawn"], instance: IInstance, page: IPage) {
        super(data, instance, page);
    }

    public getType(): Schema["spawn"]["type"] {
        return this.data.type;
    }

    public setType(type: Schema["spawn"]["type"]): void {
        this.data.type = type;
    }
    
    public getName(): string {
        return this.data.name;
    }
    
    public setName(name: string): void {
        this.data.name = name;
    }

    public getSpawnParent(): string {
        return this.data.spawnParent;
    }

}
