/**
 * ticker component
 * handles frame updates
 */

import { IPage } from "../../types/internal";
import { PageSchema, Events } from "../../types/external";
import { ILogger, Logger } from "./Log";
import { ATickerComponent } from "./ATickerComponent";
import {  getTimeUtils  } from "./TimeUtils";
import { ITimeUtils } from "../../types/internal";

export default class PlayTickerComponent extends ATickerComponent {
    // when did the page start?
    private _startTime: number | undefined = undefined;

    private _stopTime: number = 0;

    // is it running (could be paused)
    private _running: boolean = false;

    private logger: ILogger | undefined;

    // the time provider - get the time now. Mockable in tests
    private _timeUtils: ITimeUtils = getTimeUtils();

    constructor(data: PageSchema["ticker"], page: IPage) {
        super(data, page);
        this.tick = this.tick.bind(this);
        this.logger = new Logger(this);
    }

    public override setTimeNow(time: number) {
        this._timeUtils.setTimeNow(time);
    }

    /**
     * Stop ticking
     */
    public override stop() {
        this._running = false;
        this._stopTime = this.getActivityTime();
        this._startTime = undefined;
        this._timeUtils.stop();
    }

    /**
     * Start ticking
     */
    public override start(): void {
        if (!this._running) {
            this._running = true;
            this._startTime = this._timeUtils.getTimeNow();
            this._timeUtils.raf(this.tick);
        }
    }

    /**
     * Ensure that we get consistent time even if the ticker is paused
     * @returns 
     */
    private getActivityTime(): number {
        const now = this._timeUtils.getTimeNow();
        return now - this._startTime! + this._stopTime;
    }

    public override onCreated(): void {
        this.logger!.createUI();
        super.onCreated();
    }

    public override onDestroyed(): void {
        if (this._running) {
            this.stop();
        }
        if(this.logger){
            this.logger.destroy();
            this.logger = undefined;
        }
        super.onDestroyed();
    }

    /**
     * Do one tick
     */
    public override tick(): void {
        if (this._running) {
            const time = this.getActivityTime();
            this.page.events.emit(Events.ENTER_FRAME, {
                time
            });
            this._timeUtils.raf(this.tick);
            this.logger!.logTime(time);
        }
        else {
            throw new Error("ticker is not running");
        }
    }

    public override getIsRunning(): boolean {
        return this._running;
    }
}
