/**
 * DroppableHandler - Handles the drop event for a droppable instance
 */

import { ADropHandler, IDropHandler } from "./types";
import { IInstance, Events } from "../../types/external";

export class DroppableHandler extends ADropHandler implements IDropHandler {
    // find the instance that will accept the dropped instance
    private getAcceptingInstance(): IInstance | undefined {
        let droppedOn: IInstance | undefined = undefined;

        const instances = this.allInstances
            .filter((instance: IInstance) => {
                const droppableComponent = instance.getComponent("droppable");
                // find ones that are enable
                return (
                    instance !== this.droppedInstance &&
                    droppableComponent &&
                    droppableComponent.getEnabled()
                );
            })
            .sort((instanceA: IInstance, instanceB: IInstance) => {
                // find the top-most one
                const zA = instanceA.getComponent("render").getZIndex();
                const zB = instanceB.getComponent("render").getZIndex();
                return zA === zB ? 0 : zA < zB ? 1 : -1;
            });

        for (let i = 0; i < instances.length; i++) {
            const instance = instances[i];
            const droppableComponent = instance.getComponent("droppable");
            if (droppableComponent.getWillAcceptInstance(this.droppedInstance)) {
                droppedOn = instance;
                break;
            }
        }
        return droppedOn;
    }

    /**
     * Handle the drop
     * @returns
     */
    public handleDrop(): boolean {
        // we dropped on this one
        const instanceDroppedOn = this.getAcceptingInstance();
        if (instanceDroppedOn) {
            const dropComponent = instanceDroppedOn.getComponent("droppable");
            //drop on it
            dropComponent.addContent(this.droppedInstance);
            this.page.events.emit(Events.INSTANCE_ACCEPTED, {
                selectedInstance: this.droppedInstance,
            });
            this.droppedInstance.events.emit(Events.INSTANCE_ACCEPTED, {
                selectedInstance: this.droppedInstance,
            });
            return true;
        } else {
            return false;
        }
    }

    /**
     * remove it from droppables
     */
    public onStartDrag(): void {
        this.allInstances.forEach((instance: IInstance) => {
            instance.getComponent("droppable").removeContent(this.droppedInstance);
        });
    }

    /**
     * Drop failed. Snap back to original position if needed
     */
    public override onFail(): void {
        const dragComponent = this.droppedInstance.getComponent("draggable");
        if (dragComponent.getSnapsBackOnFail()) {
            const spawnComponent = this.droppedInstance.getComponent("spawn");
            if(spawnComponent.getSpawnParent()) {
                this.page.instances.destroyInstance(this.droppedInstance);
            }
            else{
                dragComponent.resetPosition();
            }
        }
    }
}
