/**
 * Abstract class for highlighting an instance
 */

import { IHoverComponent, IInstance, Schema } from "../../types/external";
import { IPage } from "../../types/internal";
import { AComponent } from "../AComponent";

export default abstract class AHoverComponent
    extends AComponent<"hover">
    implements IHoverComponent
{
    public name: "hover" = "hover";

    constructor(data: Schema["hover"], instance: IInstance, page: IPage) {
        super(data, instance, page);
    }

    public override update(data: Schema["hover"]): void {
        super.update(data);
    }

    // apply the highlight
    public setHover(type: Schema["hover"]["type"]): void {
        this.data.type = type;
    }

    override getDependencies() {
        return ["render"] as const;
    }
}
