/**
 * Edit events -
 * We listen to dom events because we need to handle some mouse events in edit mode (eg. dblclick on textareas to edit them)
 */

import { IPage } from "../../types/internal";
import { PageSchema } from "../../types/external";
import AEventsComponent from "./AEventsComponent";
import { EditPointerEventHandler } from "./pointer/EditPointerEventHandler";
import { getResizeEventHandler } from "./ResizeEventHandler";
export default class EditEventsComponent extends AEventsComponent {
    public name: "events" = "events";
    constructor(data: PageSchema["events"], page: IPage) {
        super(data, page);
    }

    public override onCreated(): void {
        super.onCreated();
        this.pointerEventHandler = new EditPointerEventHandler(this.page);
        this.resizeEventHandler = getResizeEventHandler(this.page);
    }
}
