import { Schema, IRotateableComponent, IInstance, Events } from "../../types/external";
import { IPage } from "../../types/internal";
import ARotateableComponent from "./ARotateableComponent";
import { InstanceEventsMap } from "../../types/external";
import { Point } from "../../types/external";
import { getEventPosition } from "../../utils/utils";
import { IHandle, Handle } from "./Handle";

export default class PlayRotateableComponent
    extends ARotateableComponent
    implements IRotateableComponent
{

    private startPos: Point | undefined;
    private startRot: number | undefined;
    private center: Point | undefined;
    private dragDisabled: boolean = false;
    private handle: IHandle | undefined;
    
    constructor(data: Schema["rotateable"], instance: IInstance, page: IPage) {
        super(data, instance, page);
        this.onPointerDown = this.onPointerDown.bind(this);
        this.onPointerDrag = this.onPointerDrag.bind(this);
        this.onPointerUp = this.onPointerUp.bind(this);
    }

    public override onCreated(): void {
        super.onCreated();
        const spawn = this.instance.getComponent("spawn");
        // you can't rotate these
        if(this.data.enabled && spawn.getType() === "none"){
            this.addListeners();
            this.addHandle();
        }
    }

    private _removeHandle():void{
        if(this.handle){
            this.handle.destroy();
            this.handle = undefined;
        }
    }

    private addHandle():void{
        if(this.handle){
            return;
        }
        else{
            this.handle = new Handle(this.instance);
        }
    }

    private addListeners() {
        this.instance.events.on(Events.INSTANCE_POINTERDOWN, this.onPointerDown);
    }

    private _removeListeners() {
        this.instance.events.off(Events.INSTANCE_POINTERDOWN, this.onPointerDown);
        this.instance.events.off(Events.INSTANCE_POINTERDRAG, this.onPointerDrag);
        this.page.events.off(Events.PAGE_POINTERUP, this.onPointerUp);
    }

    private onPointerUp() {
        // round off using step
        const transComp = this.instance.getComponent("transform")!;
        const rot = transComp.getRotation();
        const newRot = Math.round(rot / this.data.step) * this.data.step;
        transComp.setRotation(newRot);

        // remove event listeners
        this.instance.events.off(Events.INSTANCE_POINTERDRAG, this.onPointerDrag);
        this.page.events.off(Events.PAGE_POINTERUP, this.onPointerUp);

        if(this.dragDisabled){
            // turn it back on if we turned it off!
            this.instance.getComponent("draggable")!.enable();
            this.dragDisabled = false;
        }
    }

    private onPointerDown(eventData: InstanceEventsMap[typeof Events.INSTANCE_POINTERDOWN]) {
        // you hit the handle, so start rotating
        const pos = getEventPosition(eventData.originalEvent);
        const started = this.handle?.getWasHit(pos);
        // if our rotate was started, add the listeners for moving and stopping
        if(started){
            this.instance.events.on(Events.INSTANCE_POINTERDRAG, this.onPointerDrag);
            this.page.events.on(Events.PAGE_POINTERUP, this.onPointerUp);

            const dragComp = this.instance.getComponent("draggable");
            const transComp = this.instance.getComponent("transform");

            const centre = transComp!.getCurrentOriginPoint();
            this.startPos = eventData.point;
            this.startRot = transComp.getRotation();
            this.center = centre;

            const isDraggable = dragComp?.getEnabled();
            if(isDraggable){
                this.instance.getComponent("draggable")!.disable();
                this.dragDisabled = true;
            }
        }
        else{
            this.dragDisabled = false;
        }
    }

    /**
     * they moved the pointer, so rotate the object.
     * @param eventData 
     */
    private onPointerDrag(eventData: InstanceEventsMap[typeof Events.INSTANCE_POINTERDRAG]) {
        const newPos = eventData.point;

        // calculate the angle between the start position and the new position
        const startDx = this.startPos!.x - this.center!.x;
        const startDy = this.startPos!.y - this.center!.y;
        const newDx = newPos.x - this.center!.x;
        const newDy = newPos.y - this.center!.y;
        const angle = Math.atan2(newDy, newDx) - Math.atan2(startDy, startDx);
        
        // the angles are in degrees, so convert to radians
        const newRot = this.startRot! + 180 * angle / Math.PI;
        this.instance.getComponent("transform")!.setRotation(newRot);
    }

    override onDestroyed() {
        super.onDestroyed();
        this._removeListeners();
        this._removeHandle();
    }

}
