/**
 * events component
 */
import { IPage } from "../../types/internal";
import { APageComponent } from "../APageComponent";
import { PageSchema } from "../../types/external";
import { IInstance } from "../../types/external";
import { Point } from "../../types/external";
import { IPointerHandler } from "./pointer/APointerEventHandler";
import { IResizeEventHandler } from "./ResizeEventHandler";
import { Events, IEventsComponent } from "../../types/external";

export default abstract class AEventsComponent
    extends APageComponent<"events">
    implements IEventsComponent
{
    // these handle various events that we listen to
    protected pointerEventHandler: IPointerHandler;
    protected resizeEventHandler: IResizeEventHandler;

    constructor(data: PageSchema["events"], page: IPage) {
        super(data, page);
    }

    /**
     * get the instances under the mouse. In order of z-index (top-most first)
     * Take into account getRespondsToMouseEvents
     * @param {Point} p - pointer position, relative to the container (top-left of the container - not the browser - is 0,0)
     * @returns
     */
    public getTargetInstancesUnderPoint(p: Point): IInstance[] {
        return this.pointerEventHandler.getTargetInstancesUnderPoint(p);
    }

    public override onCreated(): void {
        super.onCreated();
        setTimeout(() => {
            this.page.events.emit(Events.PAGE_RESIZE, {});
        });
    }

    public override onDestroyed(): void {
        super.onDestroyed();
        this.pointerEventHandler.destroy();
        this.resizeEventHandler.destroy();
    }

    public getPointerPosition(): Point {
        return this.pointerEventHandler.getCurrentPos();
    }

    public isKeyPressed(code: string): boolean{
        return false;
    }
}
