import { IVisibilityComponent, IInstance } from "../../types/external";
import { Schema } from "../../types/external";
import { IPage } from "../../types/internal";
import { AComponent } from "../AComponent";

export default abstract class AVisibilityComponent
    extends AComponent<"visibility">
    implements IVisibilityComponent
{
    public name: "visibility" = "visibility";

    constructor(data: Schema["visibility"], instance: IInstance, page: IPage) {
        super(data, instance, page);
    }

    public override update(data: Partial<Schema["visibility"]>) {
        super.update(data);
        this.setVisibility(data.visibility || "visible");
    }

    protected updateVisibility(): void {
        // override
    }

    public getVisibility(): Schema["visibility"]["visibility"] {
        return this.data.visibility;
    }

    public setVisibility(visibility: Schema["visibility"]["visibility"]): void {
        this.data.visibility = visibility;
        this.updateVisibility();
    }

    /**
     * lifecycle - onCreated
     */
    public override onCreated() {
        this.updateVisibility();
    }

    /**
     * Only take effect in edit mode
     * @param visible
     */
    public abstract setEditorVisibility(visible: boolean): void;

    public abstract getCanCollide():boolean;

    public getEditorVisibility(): boolean {
        return this.data.editorVisible;
    }

    public abstract toggleEditorVisibility(): void;
}
