/**
 * Handles the time of an animation. Eg. delay, elapsed time, progress, repeat, etc.
 */


import { AnimationSettings } from "../../schema/schema";

export interface IAnimationTime{
    isComplete():boolean;
    isWaiting():boolean;
    setCurrentTime(time:number):void;
    getHasRepeated():boolean;
    getDuration():number;
    getRepeat():number;
    getDelay():number;
    getTotalDuration():number;
    getProgressTime():number;
    getDelta():number;
    getNormalizedTime():number;
    getCurrentIteration():number;
    setDelta(delta:number):void;
}

export class AnimationTime implements IAnimationTime{

    private settings:AnimationSettings;
    private _delta:number | undefined = undefined;
    private _previousNormalizedTime:number = 0;
    private _hasRepeated:boolean = false;
    private _startTime: number | undefined = undefined;

    constructor(settings:AnimationSettings){
        this.settings = settings;
    }

    /**
     * 
     * @returns done?
     */
    public isComplete():boolean{
        return this.getProgressTime() >= this.getTotalDuration();
    }

    /**
     * 
     * @returns does the animation support repeating
     */
    private canRepeat():boolean{
        const repeat = this.getRepeat();
        return repeat === -1 || repeat >= 1;
    }

    /**
     * 
     * @returns waiting - are we in the delay phase
     */
    public isWaiting():boolean{
        return this._delta! < this.getDelay();
    }

    
    /**
     * 
     * @returns the start time in milliseconds
     */
    public getStartTime():number{
        return this._startTime!;
    }

    /**
     * Set the start time
     * -  If we loaded an incomplete animation, we need to set the start time using the delta.
     *    For example, if the delta was 2s (the incomplete animation was 2s in when it was saved), we need to set the start time to 2s ago from now.
     * - Otherwise the animation will just start from now.
     * @param time 
     */
    private setStartTime(time:number):void{
        const delta = typeof this._delta === "number" ? this._delta : 0;
        this._startTime = time - delta;
    }

    /**
     * Set the current time and store the delta
     * @param time in milliseconds
     */
    public setCurrentTime(time:number):void {
        if(typeof this._startTime === "undefined"){
            this.setStartTime(time);
        }
        // update delta
        this._delta = time - this._startTime!;

        // check if we have repeated just now
        const normalizedTime = this.getNormalizedTime();
        this._hasRepeated = this.canRepeat() && normalizedTime < this._previousNormalizedTime;
        this._previousNormalizedTime = normalizedTime;
    }

    public getHasRepeated(): boolean{
        return this._hasRepeated;
    }

    
    /**
     * 
     * @returns duration in milliseconds
     */
    public getDuration(): number {
        const DEFAULT_DURATION = 1;
        const secs = typeof(this.settings?.duration) === "number" ? this.settings.duration : DEFAULT_DURATION;
        return secs * 1000;
    }

    /**
     * 
     * @returns number of times to repeat the animation. -1 means forever
     */
    public getRepeat(): number {
        // -1 means forever
        const DEFAULT_REPEAT = 0;
        return typeof(this.settings?.repeat) === "number" ? this.settings.repeat : DEFAULT_REPEAT;
    }

    /**
     * 
     * @returns delay in milliseconds
     */
    public getDelay(): number {
        const DEFAULT_DELAY = 0;
        const secs = typeof(this.settings?.delay) === "number" ? this.settings.delay : DEFAULT_DELAY;
        return secs * 1000;
    }

    
    /**
     * 
     * @returns total duration in milliseconds, excluding the delay
     */
    public getTotalDuration(): number {
        const repeat = this.getRepeat();
        if(repeat === -1){
            return Infinity;
        }
        return this.getDuration() * (repeat + 1);
    }

    
    /**
     * 
     * @returns the progress in ms, excluding any delay
     */
    public getProgressTime(): number {
        const delay = this.getDelay();
        if(this._delta! < delay){
            return 0;
        }
        return this._delta! - delay;
    }

    /**
     * 
     * @returns number between 0 and 1
     */
    public getNormalizedTime(): number {
        const iteration = this.getCurrentIteration();
        const duration = this.getDuration();
        const progressTime = this.getProgressTime();
        const timeInIteration = progressTime - iteration * duration;
        return timeInIteration / duration;
    }

    /**
     * 
     * @returns the current iteration of the animation. 1st is 0 etc
     */
    public getCurrentIteration(): number {
        const time = this.getProgressTime();
        if(time <= 0){
            return 0;
        }
        return Math.ceil(time / this.getDuration()) - 1;
    }

    public getDelta():number{
        return this._delta!
    }

    public setDelta(delta: number):void{
        this._delta = delta;
    }
}
