/**
 * Listen to all the relevant events on the page
 */

import { IPage } from "../../types/internal";
import { IActivity } from "../../types/internal";
import { Events } from "../../types/external";
import { AActivityListeners, IActivityListeners } from "./AActivityListeners";
import { PageEventsMap } from "../../types/external";

// edit mode
export class EditActivityListeners extends AActivityListeners implements IActivityListeners{
    constructor(activity: IActivity) {
        super(activity);
        this.onSelectionChange = this.onSelectionChange.bind(this);
        this.onChange = this.onChange.bind(this);
    }

    private onSelectionChange(eventData: PageEventsMap[typeof Events.SELECTION_CHANGE]) {
        this.activity.events.emit(Events.ACTIVITY_CHANGE_SELECTION, eventData);
    }

    public listenToPage(page: IPage): void {
        page.events
            .on(Events.SELECTION_CHANGE, this.onSelectionChange)
            .on(Events.INSTANCE_CREATED, this.onChange)
            .on(Events.INSTANCE_DESTROYED, this.onChange)
            .on(Events.PAGE_COMPONENT_UPDATED, this.onChange)
            .on(Events.COMPONENT_UPDATE, this.onChange);
    }

    public stopListening(page: IPage): void {
        page.events
            .off(Events.SELECTION_CHANGE, this.onSelectionChange)
            .off(Events.INSTANCE_CREATED, this.onChange)
            .off(Events.INSTANCE_DESTROYED, this.onChange)
            .off(Events.PAGE_COMPONENT_UPDATED, this.onChange)
            .off(Events.COMPONENT_UPDATE, this.onChange);
    }

    protected onChange(): void {
        this.activity.save();
    }

}