/**
 * Listen to all the relevant events on the page
 */

import { IPage } from "../../types/internal";
import { Events } from "../../types/external";
import { AActivityListeners, IActivityListeners } from "./AActivityListeners";

export class PlayActivityListeners extends AActivityListeners implements IActivityListeners {
    public listenToPage(page: IPage): void {
        page.events
            .on(Events.RESET_PAGE, this.onResetPage)
            .on(Events.RESET_ACTIVITY, this.onResetActivity)
            .on(Events.CHANGE_PAGE, this.onChangePage)
    }

    public stopListening(page: IPage): void {
        page.events
            .off(Events.RESET_PAGE, this.onResetPage)
            .off(Events.RESET_ACTIVITY, this.onResetActivity)
            .off(Events.CHANGE_PAGE, this.onChangePage)
    }
}
