import Salad from "../index";
import { getPage } from "./Page";
import { ActivityOptions } from "../types/internal";
import {getDefaultComponentFactory} from "../components/DefaultComponentFactories";
import {getDefaultPageComponentFactory} from "../pageComponents/DefaultPageComponentFactories";

export interface IPageFactory {
    setup(): void;
    createPage(): Salad.IPage;
}

export class PageFactory implements IPageFactory {

    private page:Salad.IPage | undefined;

    constructor(private pageData:Salad.IPageData, private options?: ActivityOptions){

    }

    public setup(): void {
        const pageData = this.pageData;
        if(this.page){
            this.page
            .loadPageData(pageData.schema)
            .loadInstancesData(pageData.instances);

            if(this.options.mode === "play"){
                this.page.getComponent("ticker").start();
            }
        }
    }

    public createPage(): Salad.IPage{

        const pageData = this.pageData;

        if(!pageData){
            throw new Error("Cannot find page")
        }

        const newPage = getPage(pageData.id, this.options.container, this.options.pageContainer);
        
        if(this.options.modalHelper){
            newPage.setModalHelper(this.options.modalHelper)
        }

        const compFactory = getDefaultComponentFactory(this.options.mode);
        if(this.options.componentsMap){
            const extras = this.options.componentsMap[this.options.mode];
            compFactory.merge(extras);
        }

        const pageCompFactory = getDefaultPageComponentFactory(this.options.mode);
        if(this.options.pageComponentsMap){
            const extras = this.options.pageComponentsMap[this.options.mode];
            pageCompFactory.merge(extras);
        }

        newPage
            .setFactories(
                compFactory,
                pageCompFactory
            )
            .setAssetManager(this.options.api.assetManager)
            .setTranslator(this.options.api.translator)
            .setSoundSequencer(this.options.api.soundSequencer)

        this.page = newPage;

        return newPage;
    }
}

export const getPageFactory = (data:Salad.IPageData, options?: ActivityOptions): IPageFactory => {
    return new PageFactory(data, options);
}