
import { CSSDomUpdate } from "../../types/external";
import {ADomUpdateComponent} from "./ADomUpdateComponent";
import { PageSchema } from "../../types/external";
import { IPage } from "../../types/internal";
import { Events } from "../../types/external";
export default class PlayDomUpdateComponent extends ADomUpdateComponent{

    private needsCSSFlush:boolean = false;
    private needsAppendFlush:boolean = false;
    
    constructor(data: PageSchema["domupdate"], page: IPage) {
        super(data, page);
        this.onTick = this.onTick.bind(this);
    }
    
    public override onCreated() {
        super.onCreated();
        this.page.events.on(Events.ENTER_FRAME, this.onTick);
    }

    private onTick(): void {
        if(this.needsCSSFlush){
            this.flushCSS();
            this.needsCSSFlush = false;
        }
        if(this.needsAppendFlush){
            this.flushAppend();
            this.needsAppendFlush = false;
        }
    }

    public override onDestroyed() {
        super.onDestroyed();
        this.page.events.off(Events.ENTER_FRAME, this.onTick);
    }
    
    //in play mode we apply the updates in the next frame
    public override addCSSUpdate(update: CSSDomUpdate): void {
        super.addCSSUpdate(update);
        this.needsCSSFlush = true;
    }

    public override addAppend(callback: () => void): void {
        super.addAppend(callback);
        this.needsAppendFlush = true;
    }
}
