/**
 * Render component for play mode
 */

import ARenderComponent from "./ARenderComponent";

export default class PlayRenderComponent extends ARenderComponent {
    /**
     * @returns boolean
     */
    public override getRespondsToMouseEvents(): boolean {
        const visComp = this.instance.getComponent("visibility");
        const vis = visComp.getVisibility();
        if(!this.data.mouseEnabled){
            return false;
        }
        else if(!["visible", "hidden"].includes(vis)){
            return false;
        }
        else{
            const buttonComp = this.instance.getComponent("button");
            if(buttonComp && buttonComp.getEnabled() && buttonComp.getState() !== "enabled"){
                return false;
            }
        }
        return true;
    }

    protected override addToLayer(): void {
        const layerName = this.data.renderLayer === "instances" ? "instances" : "instances-hud";
        const layersComp = this.page.getComponent("layers");
        layersComp.addChildToLayer(this._element, layerName);
    }

    public override onCreated() {
        super.onCreated();
        if(!this.data.mouseEnabled){
            this._element?.classList.add("instance-mouse-disabled");
        }
        else{
            this._element?.classList.remove("instance-mouse-disabled");
        }
    }

    protected override updateLayoutPaint(): void {
        this._element?.classList.toggle("layout-paint", this.data.layoutPaint);
    }

}
