/**
 * text component for play mode
 */
import { Schema, IInstance } from "../../types/external";
import { IPage } from "../../types/internal";
import ATextComponent from "./ATextComponent";
import { disableTextArea, disableDomElement } from "../../utils/utils";
import { InstanceEventsMap, Events } from "../../types/external";
import { cover } from "../../utils/domElementFactory";

export default class PlayTextComponent extends ATextComponent {
    constructor(data: Schema["text"], instance: IInstance, page: IPage) {
        super(data, instance, page);
    }

    protected override addElement(): void {
        super.addElement();
        if (!this.data.editable) {
            disableTextArea(this.textElement!);
            disableDomElement(this.textElement!);
        }
    }

    protected getisEditable(): boolean {
        return this.data.editable;
    }

    protected getCover(){
        return cover(this.element!, true);
    }

    protected override onComponentUpdated(eventData: InstanceEventsMap[typeof Events.COMPONENT_UPDATE]): void {
        super.onComponentUpdated(eventData);
        if (eventData.component.name === "text" && !!this.data.dataProperty && this.data.editable) {
            this.page.getComponent("data").setValueForKey(this.data.dataProperty, eventData.payload!.value as string);
        }
    }
}
