/**
 * Abstract class for a sound components
 */

import { ISoundsComponent, IInstance } from "../../types/external";
import { Schema } from "../../types/external";
import { IPage } from "../../types/internal";
import { AComponent } from "../AComponent";

export default abstract class SoundsComponent
    extends AComponent<"sounds">
    implements ISoundsComponent
{
    public name: "sounds" = "sounds";

    constructor(data: Schema["sounds"], instance: IInstance, page: IPage) {
        super(data, instance, page);
    }

    public override update(data: Schema["sounds"]): void {
        super.update(data);
    }

    override getDependencies() {
        return ["render"] as const;
    }
}
