/**
 * transform component. Handles rotation, scale, and origin
 */

import { IGameControlComponent, IInstance, Schema } from "../../types/external";
import { IPage } from "../../types/internal";
import { AComponent } from "../AComponent";
import {
    getInputKeyListener,
    IInputKeyListener,
    IFireListener,
    getFireListener,
} from "./keylisteners/AKeyListener";

export default class PlayGameControlComponent
    extends AComponent<"gamecontrol">
    implements IGameControlComponent
{
    public name: "gamecontrol" = "gamecontrol";

    // handles the actual user input
    private inputKeyListener: IInputKeyListener | undefined = undefined;

    // handles the actual user input
    private fireListener: IFireListener | undefined = undefined;

    constructor(data: Schema["gamecontrol"], instance: IInstance, page: IPage) {
        super(data, instance, page);
    }

    override onCreated() {
        super.onCreated();
        this.initListeners();
    }

    public override onDestroyed(): void {
        if (this.inputKeyListener) {
            this.inputKeyListener.destroy();
        }
        if (this.fireListener) {
            this.fireListener.destroy();
        }
    }

    public fire(instanceName: string, speed: number = 5): void {
        const instanceToFire = this.page.instances.cloneByName(instanceName);
        if (instanceToFire) {
            // degrees
            const angleFacing = this.instance.getComponent("transform").getDirectionFacing();

            // parent position
            const pos = this.instance.getComponent("position").getPosition();

            // parent size
            const size = this.instance.getComponent("size").getSize();

            // bullet size
            const bulletSize = instanceToFire.getComponent("size").getSize();

            const newPos = {
                x: pos.x + size.width / 2 - bulletSize.width / 2,
                y: pos.y + size.height / 2 - bulletSize.height / 2,
            };

            instanceToFire.getComponent("position").setPosition({
                x: newPos.x,
                y: newPos.y,
            });
            instanceToFire.getComponent("visibility").setVisibility("visible");
            instanceToFire.getComponent("velocity").setVelocity({
                x: speed * Math.cos((angleFacing * Math.PI) / 180),
                y: speed * Math.sin((angleFacing * Math.PI) / 180),
            });
            instanceToFire.getComponent("transform").setRotationWithOffset(angleFacing);

            // we probably want this
            instanceToFire.getComponent("movement").setDestroy(true);
        }
    }

    private initListeners(): void {
        if (this.inputKeyListener) {
            this.inputKeyListener.destroy();
        }
        if (this.fireListener) {
            this.fireListener.destroy();
        }
        if (this.data.input.enabled) {
            this.inputKeyListener = getInputKeyListener(
                this.instance,
                this.page,
                this.data["input"],
            );
        }
        if (this.data.fire.enabled) {
            this.fireListener = getFireListener(this.instance, this.page, this.data["fire"]);
        }
    }
}
