/**
 * Make various svg elements (shapes)
 */

import { Schema, Size } from "../types/external";
import { createArrow } from "./shapes/arrows";
import { createLine } from "./shapes/lines";

type SVGType = Schema["shape"]["type"];

const basePath = "http://www.w3.org/";
const svgns = `${basePath}2000/svg`;

const chunkyArrow = (svg: SVGElement, type: SVGType, fill: string)=>{
    svg.setAttribute("preserveAspectRatio", "none");
    const sizeAttr: string = "100%";
    svg.setAttribute("width", sizeAttr);
    svg.setAttribute("height", sizeAttr);
    svg.setAttribute("viewBox", "0 0 24 24");
    const path = document.createElementNS(svgns, "path") as SVGElement;
    const d:string = "M 1.1108462,12.133492 A 1.2987661,1.2987661 0 0 1 2.4096123,10.834726 H 17.457116 L 11.880215,5.2604219 a 1.3004068,1.3004068 0 1 1 1.839053,-1.8390528 l 7.792596,7.7925959 a 1.2987661,1.2987661 0 0 1 0,1.839053 l -7.792596,7.792597 a 1.3004068,1.3004068 0 0 1 -1.839053,-1.839053 l 5.576901,-5.574304 H 2.4096123 A 1.2987661,1.2987661 0 0 1 1.1108462,12.133492 Z";
    path.setAttribute("d", d);
    path.setAttribute("transform-origin", "center");
    const rot = (type === "chunkyArrowRight") ? 0 : (type === "chunkyArrowLeft") ? 180 : (type === "chunkyArrowDown") ? 90 : -90;
    path.setAttribute("transform", `rotate(${rot})`);
    path.setAttribute("fill", fill);
    svg.append(path);
    return svg;
}

const rect = (svg: SVGElement, type: SVGType, fill: string) => {
    const sizeAttr: string = "100%";

    svg.setAttribute("width", sizeAttr);
    svg.setAttribute("height", sizeAttr);
    svg.setAttribute("viewBox", "0 0 100 100");

    svg.setAttribute("preserveAspectRatio", "none");
    let newRect = document.createElementNS(svgns, "rect");
    newRect.setAttribute("x", "0");
    newRect.setAttribute("y", "0");
    newRect.setAttribute("width", sizeAttr);
    newRect.setAttribute("height", sizeAttr);
    newRect.setAttribute("fill", fill);
    svg.append(newRect);
};

const roundrect = (svg: SVGElement, type: SVGType, fill: string) => {
    const radiusPercent = 10;
    const sizeAttr: string = "100%";

    svg.setAttribute("width", sizeAttr);
    svg.setAttribute("height", sizeAttr);
    const viewBoxSize = 100;
    svg.setAttribute("viewBox", `0 0 ${viewBoxSize} ${viewBoxSize}`);

    svg.setAttribute("preserveAspectRatio", "none");
    let newRect = document.createElementNS(svgns, "rect");
    newRect.setAttribute("x", "0");
    newRect.setAttribute("y", "0");
    newRect.setAttribute("width", sizeAttr);
    newRect.setAttribute("height", sizeAttr);
    newRect.setAttribute("fill", fill);

    const radius = (radiusPercent / 100) * viewBoxSize;
    newRect.setAttribute("rx", radius.toString());
    newRect.setAttribute("ry", radius.toString());

    svg.append(newRect);
};


const svgPoly = (radius: number, numSides: number) => {
    var radians = (deg: number) => (Math.PI * deg) / 180;
    var vb = 2 * radius;
    var points = Array(numSides)
        .fill(radians(90 - (180 - 360 / numSides) / 2))
        .map((offset, idx) => [
            vb / 2 + radius * Math.cos(offset + radians((360 / numSides) * idx) + Math.PI / 2),
            vb / 2 + radius * Math.sin(offset + radians((360 / numSides) * idx) + Math.PI / 2),
        ]);
    return points.join(" ");
};

const polygon = (numSides: number) => {
    const f = (svg: SVGElement, type: SVGType, fill: string) => {
        const sizeAttr: string = "100%";

        svg.setAttribute("width", sizeAttr);
        svg.setAttribute("height", sizeAttr);
        svg.setAttribute("viewBox", "0 0 100 100");

        svg.setAttribute("preserveAspectRatio", "none");
        let poly = document.createElementNS(svgns, "polygon");
        poly.setAttribute("fill", fill);
        poly.setAttribute("points", svgPoly(50, numSides));
        svg.append(poly);
    };

    return f;
};

const circle = (svg: SVGElement, type: SVGType, fill: string) => {
    const sizeAttr: string = "100%";
    svg.setAttribute("width", sizeAttr);
    svg.setAttribute("height", sizeAttr);
    svg.setAttribute("viewBox", "0 0 100 100");

    svg.setAttribute("preserveAspectRatio", "xMidYMid meet");
    let newRect = document.createElementNS(svgns, "circle");
    newRect.setAttribute("cx", "50%");
    newRect.setAttribute("cy", "50%");
    newRect.setAttribute("r", "50%");
    newRect.setAttribute("fill", fill);
    svg.append(newRect);
};

const star = (svg: SVGElement, type: SVGType, fill: string) => {
    svg.setAttribute("preserveAspectRatio", "none");
    const sizeAttr: string = "100%";
    svg.setAttribute("width", sizeAttr);
    svg.setAttribute("height", sizeAttr);

    svg.setAttribute("viewBox", "0 0 24 24");

    const path = document.createElementNS(svgns, "path") as SVGElement;
    path.setAttribute(
        "d",
        "M12 .587l3.668 7.568 8.332 1.151-6.064 5.828 1.48 8.279-7.416-3.967-7.417 3.967 1.481-8.279-6.064-5.828 8.332-1.151z",
    );
    path.setAttribute("fill", fill);
    svg.append(path);
};

type SVGMaker = (svg: SVGElement, type: SVGType, fill: string, size: Size) => void;

const mapTypeToFunction: { [key in SVGType]: SVGMaker } = {
    rect,
    roundrect: roundrect,
    triangle: polygon(3),
    pentagon: polygon(5),
    hexagon: polygon(6),
    octagon: polygon(8),
    circle,
    star,
    arrowup: createArrow,
    arrowdown: createArrow,
    arrowdiag: createArrow,
    arrowleft: createArrow,
    arrowright: createArrow,
    linevertic: createLine,
    linehoriz: createLine,
    linediag: createLine,
    chunkyArrowRight: chunkyArrow,
    chunkyArrowLeft: chunkyArrow,
    chunkyArrowUp: chunkyArrow,
    chunkyArrowDown: chunkyArrow,
};

export const svg = (parent: HTMLElement, type: SVGType, fill: string, size: Size): SVGElement => {
    const nsAttrs = [`${basePath}2000/xmlns/`, "xmlns:xlink", `${basePath}1999/xlink`];
    const svg = document.createElementNS(svgns, "svg") as SVGElement;
    svg.setAttributeNS(nsAttrs[0], nsAttrs[1], nsAttrs[2]);
    const fn = mapTypeToFunction[type];
    fn(svg, type, fill, size);
    parent.append(svg);
    return svg;
};
