/**
 * Screen background = background of the entire window, not just the page
 */
import { IPage, IPageModalsListComponent } from "../../types/internal";
import { APageComponent } from "../APageComponent";
import { PageSchema } from "../../types/external";

type Modals = PageSchema["modalslist"]["modals"];

export default class PageModalsListComponent
    extends APageComponent<"modalslist">
    implements IPageModalsListComponent
{
    public name: "modalslist" = "modalslist";

    constructor(data: PageSchema["modalslist"], page: IPage) {
        super(data, page);
    }

    override onCreated() {
        super.onCreated();
    }

    public getModalNames(): string[] {
        return Object.keys(this.data.modals);
    }

    public setModals(modals: Modals): void {
        this.data.modals = modals;
    }

    public getModalByName(name: string): Modals[string] {
        return this.data.modals[name];
    }

    public getModals(): Modals {
        return this.data.modals;
    }
}
