/**
 * Image component - displays an image
 */

import { Schema } from "../../types/external";
import { IShape } from "../../types/external";
import { PolygonShape } from "../../utils/shapes/PolygonShape";
import { CircleShape } from "../../utils/shapes/CircleShape";
import { ContainmentRect } from "../../schema/schema";

type Shape = Schema["containment"]["shape"];

type ExtractType<T, K extends string> = T extends { type: K } ? T : never;

const toPolygon = (shape: ContainmentRect) => {
    return [
        {
            x: shape.left!,
            y: shape.top!,
        },
        {
            x: shape.right!,
            y: shape.top!,
        },
        {
            x: shape.right!,
            y: shape.bottom!,
        },
        {
            x: shape.left!,
            y: shape.bottom!,
        },
    ];
};

const makers: { [T in Shape["type"]]: (shape: ExtractType<Shape, T>) => IShape | undefined } = {
    rect: (shape) => {
        return new PolygonShape(toPolygon(shape));
    },
    circle: (shape) => {
        const centre = {
            x: shape.cx!,
            y: shape.cy!,
        };
        return new CircleShape(centre, shape.radius!);
    },
    polygon: (shape) => {
        return new PolygonShape(shape.points);
    },
    none: () => undefined,
    page: () => undefined,
};

export const getRect = (w:number, h:number)=>{
    return new PolygonShape([
        {x:0, y:0},
        {x:w, y:0},
        {x:w, y:h},
        {x:0, y:h}
    ]);
}

export const dataToShape = (shape: Shape): IShape | undefined => {
    if (shape.type === "none") {
        return undefined;
    }
    else if (shape.type === "page") {
        return undefined;
    }
    else if (shape.type === "rect") {
        return makers.rect(shape);
    }
    else if (shape.type === "circle") {
        return makers.circle(shape);
    }
    else if (shape.type === "polygon") {
        return makers.polygon(shape);
    }
    else {
        return undefined;
    }
};
