export const builtInFunctions = `

// helper functions
function sin(v){
    return Math.sin(v);
}
function cos(v){
    return Math.cos(v);
}
function rand(a, b){
    if (typeof a === "undefined" && typeof b === "undefined"){
        a = 0;
        b = 1;
    }
    else if (typeof b === "undefined"){
        a = 0;
        b = a;
    }
    return Math.random() * (b - a) + a;
}

function floor(v){
    return Math.floor(v);
}
function ceil(v){
    return Math.ceil(v);
}

function frac(v){
    return v - Math.floor(v);
}

function round(v){
    return Math.round(v);
}

var PI = 3.14159265;
var pi = PI;

//  gives a value -1 to 1, which is always 0 when v = 0 and 0 when v = 1. Not really random, just a jitter
var noise = function(v){
    const vPI = v * PI;
    const period1 = 13;
    const period2 = 37;
    const s1 = Math.sin(vPI * period1 + __random_seed__);
    const s2 = Math.sin(vPI * period2 + __random_seed__);
    const c1 = Math.cos(vPI * period1 + __random_seed__);
    const c2 = Math.cos(vPI * period2 + __random_seed__);
    return 0.363 * Math.sin(vPI) * (s1 + s2 + c1 + c2);
}

var step = function(t, val1, val2, cutOff){
    return t < cutOff ? val1 : val2
};


`;
