import { Size, Schema } from "../../types/external";

const getPath = (type: Schema["shape"]["type"], size: Size): string => {
    let x0, y0, x1, y1: number;

    if (type === "arrowdiag") {
        x0 = 0;
        y0 = 0;
        x1 = size.width;
        y1 = size.height;
    } else if (type === "arrowup") {
        x0 = size.width / 2;
        y0 = size.height;
        x1 = size.width / 2;
        y1 = 0;
    } else if (type === "arrowdown") {
        x0 = size.width / 2;
        y0 = 0;
        x1 = size.width / 2;
        y1 = size.height;
    } else if (type === "arrowright") {
        x0 = 0;
        y0 = size.height / 2;
        x1 = size.width;
        y1 = size.height / 2;
    } else if (type === "arrowleft") {
        x0 = size.width;
        y0 = size.height / 2;
        x1 = 0;
        y1 = size.height / 2;
    } else {
        x1 = 0;
        y1 = 0;
        x0 = size.width;
        y0 = size.height;
    }

    return `M${x0},${y0}, L${x1},${y1}`;
};

export const createArrow = (
    svg: SVGElement,
    type: Schema["shape"]["type"],
    fill: string,
    size: Size,
): void => {
    svg.setAttribute("width", "" + size.width);
    svg.setAttribute("viewBox", `0 0 ${size.width} ${size.height}`);
    svg.setAttribute("height", "" + size.height);

    svg.setAttribute("preserveAspectRatio", "none");
    const basePath = "http://www.w3.org/";
    const svgns = `${basePath}2000/svg`;
    let markerPath = document.createElementNS(svgns, "path");
    markerPath.setAttribute("fill", fill);

    const markerWidth = 6;
    const markerHeight = 4;

    markerPath.setAttribute("d", `M0,0 L${markerWidth},${markerHeight / 2} L 0,${markerHeight} Z`);

    let marker = document.createElementNS(svgns, "marker");
    marker.setAttribute("id", "head");
    marker.setAttribute("orient", "auto");
    marker.setAttribute("markerWidth", "" + markerWidth);
    marker.setAttribute("markerHeight", "" + markerHeight);
    marker.setAttribute("refX", "" + markerWidth);
    marker.setAttribute("refY", "" + markerHeight / 2);
    marker.append(markerPath);

    let defs = document.createElementNS(svgns, "defs");
    defs.append(marker);

    let newRect = document.createElementNS(svgns, "path");
    newRect.setAttribute("marker-end", "url('#head')");
    newRect.setAttribute("stroke-width", "4");
    newRect.setAttribute("vector-effect", "non-scaling-stroke");
    newRect.setAttribute("fill", "none");
    newRect.setAttribute("stroke", fill);
    newRect.setAttribute("d", getPath(type, size));
    svg.append(defs);
    svg.append(newRect);
};
