import { MoveableOptions } from "moveable";
import { IInstance, IPageExternal } from "../types/external";
import { ADragger } from "./ADragger";
import { InstanceEventsMap, Events } from "../types/external";
import { DraggerOptions, MoveableEventData } from "./types";
import { getMoveable } from "./MoveableFactory";

/**
 * A dragger for edit mode
 */

export class EditDragger extends ADragger {
    
    constructor(page: IPageExternal, instance: IInstance) {
        super(page, instance);
        this.initMoveable();
        // liste for changes that effect this component
        this.onComponentUpdated = this.onComponentUpdated.bind(this);
        this.instance!.events.c.transform.on(Events.COMPONENT_UPDATE, this.onComponentUpdated);
    }

    // options for edit mode - include rotation for example
    protected override getMoveableOptions(): MoveableOptions {
        return {
            draggable: true,
            resizable: true,
            rotatable: true,
            pinchable: true,
            transformOrigin: "center",
            renderDirections: ["se"],
        };
    }

    protected initMoveable(): void {
        const renderComponent = this.instance!.getComponent("render");
        const target = renderComponent!.getElement();
        const positionComponent = this.instance!.getComponent("position");
        const transformComponent = this.instance!.getComponent("transform");
        const lockAspectRatio = transformComponent!.getLockAspectRatio();
        const transformOrigin = transformComponent!.getOrigin();
        const sizeComponent = this.instance!.getComponent("size");
        const grid = this.page.grid;
        const id = this.instance!.getId();

        let startPos = positionComponent!.getPosition();
        let startSize = sizeComponent!.getSize();
        let startRotation = transformComponent!.getRotation();

        // make the handlers
        const options: DraggerOptions = {
            onClick: () => {},
            onDragStart: () => {
                startPos = positionComponent!.getPosition();
            },
            onDragEnd: () => {
                if (grid!.getSnapToGrid()) {
                    const size = grid!.getGridSize();
                    positionComponent!.round(size);
                }
                const endPos = positionComponent!.getPosition();
                this.page.undo.onDragEnd(id, startPos, endPos);
            },
            onDrag: (e: MoveableEventData["drag"]) => {
                const newPos = {
                    x: startPos.x + e!.beforeTranslate[0],
                    y: startPos.y + e!.beforeTranslate[1],
                };
                newPos.x = Math.round(newPos.x);
                newPos.y = Math.round(newPos.y);
                positionComponent!.update(newPos);
                this.moveable!.updateRect();
            },
            onResize: (e: MoveableEventData["resize"]) => {
                let width = e!.width;
                let height = e!.height;
                if (lockAspectRatio && lockAspectRatio > 0) {
                    height = width / lockAspectRatio;
                }
                sizeComponent!.update({
                    width,
                    height,
                });
            },
            onRotate: (e: MoveableEventData["rotate"]) => {
                // we always rotate about the center regardless of what the origin is
                const origin = transformComponent!.getOrigin();
                transformComponent!.setOrigin("50% 50%");
                transformComponent!.setRotation(Math.round(e!.rotate)); // degrees not radians
                transformComponent!.setOrigin(origin);
            },
            onResizeStart: (e:MoveableEventData["resizeStart"]) => {
                startSize = sizeComponent!.getSize();
            },
            onRotateStart: (e:MoveableEventData["rotateStart"]) => {
                startRotation = transformComponent!.getRotation();
            },
            onResizeEnd: (e:MoveableEventData["resizeEnd"]) => {
                const undoComp = this.page.undo;
                const endSize = sizeComponent!.getSize();
                undoComp.onResizeEnd(id, startSize, endSize);
            },
            onRotateEnd: (e:MoveableEventData["rotateEnd"]) => {
                const undoComp = this.page.undo;
                const endRotation = transformComponent!.getRotation();
                undoComp.onRotateEnd(id, startRotation, endRotation);
            }
        };
        const keepRatio:boolean = typeof lockAspectRatio === "number" && lockAspectRatio > 0;

        const moveableOptions: MoveableOptions = {
            ...this.getMoveableOptions(),
            keepRatio,
            transformOrigin,
        };
        // get the moveable instance
        this.moveable = getMoveable(target, this.page.getPageContainer(), moveableOptions, options);
    }

    private onComponentUpdated(eventData: InstanceEventsMap[typeof Events.COMPONENT_UPDATE]) {
        if (eventData.payload!.key === "lockAspectRatio") {
            this.refreshMoveable();
        }
    }

    protected override destroyMoveable(): void {
        super.destroyMoveable();
        this.instance!.events.c.transform.off(Events.COMPONENT_UPDATE, this.onComponentUpdated);
    }

    private refreshMoveable() {
        this.destroyMoveable();
        setTimeout(() => {
            this.initMoveable();
        });
    }
}
