/**
 * Page instances component
 */
import {
    IPage,
    IInstancesComponent,
    IInstanceBuilder,
    InstanceData,
    InstanceLayerInfo,
} from "../../types/internal";
import { APageComponent } from "../APageComponent";
import { ComponentName, PageSchema, IInstance, Events } from "../../types/external";
import { getInstanceBuilder } from "../../utils/InstanceBuilder";
import { instances, instancesStatic, instancesContainer } from "../../utils/domElementFactory";
import { clone } from "../../utils/utils";
import Salad from "../..";
import { resolveDependencies } from "../../utils/utils";
import { NameNonDupe } from "./NameNonDupe";

export default abstract class AInstancesComponent
    extends APageComponent<"instances">
    implements IInstancesComponent
{
    /**
     * list of all instances
     */
    private _instances: IInstance[] = [];

    /**
     * html element for the instances
     */
    private _container: HTMLElement;
    private _element: HTMLElement;
    private _elementStatic: HTMLElement;

    /**
     * a way to build instances
     */
    private _builder: IInstanceBuilder;

    public name: "instances" = "instances";

    constructor(data: PageSchema["instances"], page: IPage) {
        super(data, page);
        this._container = instancesContainer();
        this._element = instances();
        this._elementStatic = instancesStatic();
        this._builder = getInstanceBuilder(
            page,
            page.getComponentFactory(),
            page.getDefaultSchema(),
        );
        this.destroyInstance = this.destroyInstance.bind(this);
        this.addInstance = this.addInstance.bind(this);
    }

    override getDependencies() {
        return ["events", "layers"] as const;
    }

    /**
     * lifecycle
     * Make a layer for all instances to go in
     */
    public override onCreated(): void {
        super.onCreated();
        const layerComp = this.getPageComponent("layers");
        layerComp.initLayer("instances-container", this._container, {
            type: "container",
        });
        layerComp.initLayer("instances", this._element, {
            type: "full",
        }, "instances-container");
        layerComp.initLayer("instances-hud", this._elementStatic, {
            type: "hud",
        }, "instances-container");
    }

    public override onDestroyed(): void {
        const layerComp = this.getPageComponent("layers");
        layerComp.removeLayer("instances-container");
        layerComp.removeLayer("instances");
        layerComp.removeLayer("instances-hud");
        super.onDestroyed();
    }

    /**
     * make an html element
     * @returns
     */
    public getElement(): HTMLElement {
        return this._element;
    }

    /**
     * add instances using data (schema)
     * @param instanceData
     */
    public addInstancesData(instanceData: InstanceData[]): IInstance[] {
        const instances = instanceData.map((data: InstanceData) => {
            return this._builder.getInstanceFromData(data);
        });
        // do not emit the event yet, otherwise in the 'oncreated' function some of the instances might not exist
        this.addInstances(instances, { emit: false });
        instances.forEach((instance: IInstance) => {
            this.page.events.emit(Events.INSTANCE_CREATED, {
                target: instance,
            });
        });

        return instances;
    }

    /**
     * Get all data for all instances
     * @returns
     */
    public getInstanceData(): InstanceData[] {
        return this._instances.map((instance: IInstance) => {
            return this._builder.getDataFromInstance(instance);
        });
    }

    /**
     * Get all instances
     * @returns
     */
    public getAllInstances() {
        return this._instances;
    }

    /**
     *
     * @param instance
     */
    public destroyInstance(instance: IInstance): void {
        const keys: ComponentName[] = Object.keys(instance.getComponents()) as ComponentName[];
        keys.forEach((key: ComponentName) => {
            // run the destroy function on each one
            instance.getComponent(key)!.onDestroyed();
        });

        instance.destroy();

        // remove the instance from the list
        const index = this._instances.indexOf(instance);
        this._instances.splice(index, 1);

        // emit an event
        this.page.events.emit(Events.INSTANCE_DESTROYED, {
            target: instance,
        });
    }

    /**
     * destroy an instance by name
     * @param name
     */
    public destroyInstanceByName(name: string): boolean {
        const instance = this.getInstanceByName(name)
        if(instance){
            this.destroyInstance(instance);
        }
        return !!instance;
    }

    /**
     * remove all instances
     */
    public destroyAllInstances(): void {
        // clone because we are going to remove from the array
        const clone = [...this._instances];
        //this will call the 'onDestroy' methods on each component inside each instance, and then on each instance
        clone.forEach(this.destroyInstance);
    }

    /**
     * Get instance by name
     * @param name
     * @returns
     */
    public getInstanceByName(name: string): IInstance | undefined{
        return this._instances.find((instance: IInstance) => {
            return instance.getName() === name
        });
    }

    /**
     * Get instance by id
     * @param id
     */
    public getInstanceById(id: string): IInstance | undefined{
        return this._instances.find((instance: IInstance) => instance.getId() === id);
    }

    /**
     * eg.
     * shape_5 -> shape_6 unless there is already a shape_6, in which case _7 etc
     * shape -> shape_1
     */
    public getNonDuplicateName(name: string): string{
        const names = this._instances.map((instance: IInstance) => {
            return instance.getName();
        })
        return new NameNonDupe(names).getNonDuplicateName(name);
    };

    /**
     * Clone an instance and return it
     * @param instance
     * @returns
     */
    public cloneInstance(instance: IInstance): IInstance {
        const name = instance.getName();
        // get the data
        const instanceData = this._builder.getDataFromInstance(instance);
        const cloned = clone(instanceData);

        // make a new id for it
        cloned.id = Salad.Utils.getUUID();

        // make sure the first created script doesnt run

        const newInstance = this._builder.getInstanceFromData(cloned);

        // remove the 'hasRun' property
        const scriptComp = newInstance.getComponent("script");
        scriptComp?.setHasRunOnce(true);

        // make a new name. Eg. shape_1 -> shape_2
        const newName = this.getNonDuplicateName(name);
        newInstance.getComponent("identity")!.setDisplayName(newName);

        // bring to the front
        this.addInstance(newInstance);

        newInstance.getComponent("render")!.bringToFront();

        return newInstance;
    }

    /**
     * Get by name and then clone
     * @param name
     * @returns
     */
    public cloneByName(name: string): IInstance | undefined {
        const instance = this.getInstanceByName(name);
        if (instance) {
            return this.cloneInstance(instance);
        }
        return undefined;
    }

    /**
     * Give the data and get an instance
     * @param schema
     * @returns
     */
    public addInstanceUsingSchema(schema: Salad.PartialSchema): IInstance {
        console.log("addInstanceUsingSchema", schema);
        const instance = this._builder.buildInstanceUsingSchema(schema);
        // add it to the world
        this.addInstance(instance);
        // bring it to the top
        const renderComponent = instance.getComponent("render");
        renderComponent!.bringToFront();
        return instance;
    }

    /**
     * Add an instance
     * @param instances
     */
    public addInstances(instances: IInstance[], options?: { emit?: boolean }): void {
        instances.forEach((instance: IInstance) => {
            this.addInstance(instance, options);
        });
    }

    /**
     * map an HTML element to an instance which uses it
     * Used when you select HTML elements with the mouse
     * @param element
     * @returns
     */
    public getInstanceForElement(element: HTMLElement): IInstance | undefined{
        const allInstances: IInstance[] = this.getAllInstances();
        let foundInstance: IInstance | undefined = undefined;
        allInstances.forEach((instance: IInstance) => {
            const elt = instance.getComponent("render")!.getElement();
            if (element === elt) {
                foundInstance = instance;
            }
        });
        return foundInstance;
    }

    public findInstanceByFilter(filter: (instance: IInstance) => boolean) {
        return this.getAllInstances().find(filter);
    }

    /**
     * Add an instance
     * @param instance
     */
    public addInstance(instance: IInstance, options?: { emit?: boolean }): void {
        const components = instance.getComponents();
        const dependencyMap = new Map<ComponentName, Set<ComponentName>>();
        const componentNames: ComponentName[] = Object.keys(components) as ComponentName[];

        // make the map
        componentNames.forEach((key) => {
            const component = instance.getComponent(key);
            dependencyMap.set(key, new Set(component!.getDependencies() || []));
        })

        // resolve it
        const orderedComponentNames = resolveDependencies(dependencyMap);
       
        // components are made now. Push into the array
        this._instances.push(instance);

        // call the onCreated hooks
        orderedComponentNames.forEach((name: ComponentName) => {
            instance.getComponent(name).onCreated();
        });

        // emit the instanceCreated event
        if (options?.emit !== false) {
            this.page.events.emit(Events.INSTANCE_CREATED, {
                target: instance,
            });
        }
    }

    /**
     * Get all layers info
     * eg. name, depth, instance - shown in the UI for moving elements up and down
     * Sorted so that the first one is the topmost (highest zIndex)
     * @returns layer info
     */
    public getLayers(): InstanceLayerInfo[] {
        const instanceToLayerInfo = (instance: IInstance): InstanceLayerInfo => {
            const renderComp = instance.getComponent("render");
            const identityComp = instance.getComponent("identity");

            return {
                instance,
                depth: renderComp!.getZIndex(),
                name: identityComp!.getDisplayName(),
            };
        };
        const instances = this.page.instances.getAllInstances();
        const layers = instances.map(instanceToLayerInfo);

        layers.sort((a, b) => {
            return a.depth < b.depth ? 1 : a.depth === b.depth ? 0 : -1;
        });
        return layers;
    }

    public bringToFront(selectedInstance: IInstance): void {
        const renderComp = selectedInstance.getComponent("render");
        const instances: IInstance[] = this.getAllInstances();
        const zIndices = instances.map((instance: IInstance) => {
            const renderComponent = instance.getComponent("render");
            return renderComponent!.getZIndex();
        });
        const maxZIndex = Math.max(...zIndices);
        const currentZIndex = renderComp!.getZIndex();
        const numWithMaxZIndex = zIndices.filter((zIndex: number) => {
            return zIndex === maxZIndex;
        }).length;

        if (currentZIndex >= maxZIndex && numWithMaxZIndex === 1) {
            // it is already the one at the top
            return;
        }
        else{
            renderComp!.setZIndex(maxZIndex + 1);
        }
    }

    public sendToBack(selectedInstance: IInstance): void {

        const MIN_ALLOWED_Z_INDEX = 0;
        const currentZIndex = selectedInstance.getComponent("render")!.getZIndex();

        const instances: IInstance[] = this.page.instances.getAllInstances();
        const zIndices = instances.map((instance: IInstance) => {
            const renderComponent = instance.getComponent("render");
            return renderComponent!.getZIndex();
        });
        const minZIndex = Math.min(...zIndices);

        const numWithMinZIndex = zIndices.filter((zIndex: number) => {
            return zIndex === minZIndex;
        }).length;

        if( currentZIndex === minZIndex && numWithMinZIndex === 1) {
            // it is already the one at the bottom
            return;
        }
        else if (minZIndex - 1 >= MIN_ALLOWED_Z_INDEX) {
            // ok to set it as "min - 1"
            selectedInstance.getComponent("render")!.setZIndex(minZIndex - 1);
        }
        else {
            // uh oh, we need to re-arrange them all, I dont want any going below 1
            const instancesSortedByZIndex = instances.sort((instanceA, instanceB) => {
                const zA = instanceA.getComponent("render")!.getZIndex();
                const zB = instanceB.getComponent("render")!.getZIndex();
                return zA > zB ? 1 : zA === zB ? 0 : -1;
            });

            let newIndex = MIN_ALLOWED_Z_INDEX + 1;
            instancesSortedByZIndex.forEach((instance) => {
                let indexToUse: number;
                if (instance === selectedInstance) {
                    indexToUse = MIN_ALLOWED_Z_INDEX;
                }
                else {
                    indexToUse = newIndex;
                    newIndex++;
                }
                instance.getComponent("render")!.setZIndex(indexToUse);
            });
        }
    }

    public runScripts(): void {
        
    }
}
