/**
 * page layers component
 */
import { APageLayer } from "./APageLayer";
import { PageSchema } from "../../../types/external";

type Box = PageSchema["camera"]["view"];

export class FullPageLayer extends APageLayer {
    public showView(view: Box, globalScale: number): void {
        const bgComp = this.page!.getComponent("background");
        const bgSize = bgComp.getSize();
        const transform = `scale(${globalScale}) translate(${-view.left}px, ${-view.top}px)`;
        this.setLayerSize(bgSize);
        this.element.style.transform = transform;
    }
}
