import { DrawingToolSetting } from "../../../../types/external";
import { ConstructorOf } from "../../../../types/utils";
import { ISimpleBrush, DrawingArea } from "./types";
import { SimpleBrushPencil } from "./SimpleBrushPencil";
import { SimpleBrushEraser } from "./SimpleBrushEraser";
import { SimpleBrushPen } from "./SimpleBrushPen";
import { SimpleBrushChalk } from "./SimpleBrushChalk";
import { SimpleBrushSmear } from "./SimpleBrushSmear";
import { SimpleBrushRake } from "./SimpleBrushRake";
import { setOpacity } from "../../../../utils/colorUtils";

const mapToolToClass: {
    [key in DrawingToolSetting["tool"]]: ConstructorOf<
        ISimpleBrush,
        [DrawingArea, DrawingToolSetting]
    >;
} = {
    chalk: SimpleBrushChalk,
    pen: SimpleBrushPen,
    pencil: SimpleBrushPencil,
    eraser: SimpleBrushEraser,
    rake: SimpleBrushRake,
    stick: SimpleBrushSmear,
    mouse: SimpleBrushSmear,
};

type ModifierSetting = { [tool in DrawingToolSetting["tool"]]?: { alpha: number } };

type ToolModifiers = { [type in "empty" | "paper"]?: ModifierSetting };


/**
 * How do the tools behave on different surfaces?
 */
const toolModifiers: ToolModifiers = {
    empty: {
        pen: {
            alpha: 24/255,
        },
        pencil: {
            alpha: 24/255,
        },
        chalk: {
            alpha: 60/255,
        },
    },
    paper: {},
};

const getModifiedTool = (
    surface: "paper" | "empty",
    toolSetting: DrawingToolSetting,
): DrawingToolSetting => {
    const modifier = toolModifiers[surface]?.[toolSetting.tool];
    if (modifier) {
        toolSetting = {
            ...toolSetting,
            options: {
                ...toolSetting.options,
                color: setOpacity(toolSetting.options.color!, modifier.alpha),
            },
        };
    }
    return toolSetting;
};

export const getTool = (
    surface: "paper" | "empty",
    drawingArea: DrawingArea,
    toolSetting: DrawingToolSetting,
) => {
    let Klass = mapToolToClass[toolSetting.tool];
    const modifiedToolForSurface = getModifiedTool(surface, toolSetting);
    return new Klass(drawingArea, modifiedToolForSurface);
};
