
import { ITimeUtils } from "@root/salad/types/internal";

class TimeUtils implements ITimeUtils{

    // return value of requestAnimationFrame
    private _animationFrame: number | undefined = undefined;

    public getTimeNow(): number {
        return Date.now();
    }

    public raf(fn: ()=>void): void {
        this._animationFrame = window.requestAnimationFrame(fn);
    }

    public stop(): void {
        if(this._animationFrame) {
            window.cancelAnimationFrame(this._animationFrame);
            this._animationFrame = undefined;
        }
    }

    public setTimeNow(time: number): void {
        throw new Error("Only use in tests");
    }
}

export const getTimeUtils = (): ITimeUtils => {
    return new TimeUtils();
}
