import { AActivityComponent } from "../AActivityComponent";
import { IActivityLoggerComponent } from "../../../types/external";

const height = 500;
const width = 500;
const top = 100;
const right = 60;
export class ActivityLoggerComponent extends AActivityComponent implements IActivityLoggerComponent{

    private logger: HTMLElement | undefined;
    private clearButton: HTMLElement | undefined;

    constructor() {
        super();
    }

    private isOpen():boolean{
        return document.getElementById("logger") !== null;
    }

    private addUI():void{
        const css = {
            position: "fixed",
            top: `${top}px`,
            right: `${right}px`,
            width: `${width}px`,
            height: `${height}px`,
            fontSize: "8pt",
            background: "lemonchiffon",
            zIndex: 100000,
            overflow: "auto",
            fontFamily: 'Consolas, "Courier New", monospace',
        };

        this.logger = document.createElement("div");
        Object.assign(this.logger.style, css);
        document.body.appendChild(this.logger);

        this.clearButton = document.createElement("button");
        this.clearButton.innerHTML = "Clear";
        this.clearButton.onclick = () => {
            this.clear();
        };
        document.body.appendChild(this.clearButton);

        Object.assign(this.clearButton.style, {
            position: "fixed",
            top: `${top + height + 10}px`,
            right: `${right}px`,
            zIndex: 100001,
        });
    }

    public log(message: any):void{
        if(!this.logger){
            this.addUI();
        }
        if(typeof message === "object") {
            message = JSON.stringify(message);
        }
        this.logger!.innerHTML += message + " | ";

        //@ts-ignore - doesnt exist in jest
        if(this.logger!.scrollTo){
            this.logger!.scrollTo(0, this.logger!.scrollHeight);
        }
    }

    public clear():void{
        if (this.logger) {
            this.logger.innerHTML = "";
        }
    }

    public override async onPageIn():Promise<void>{
        if(this.isOpen()){
            this.log("-- onPageIn --\n");
        }
    }

    public override async onPageOut():Promise<void>{
        if(this.isOpen()){
            this.log("-- onPageOut --\n");
        }
    }

    public override destroy(){
        if (this.logger && this.logger.parentNode) {
            this.logger.parentNode.removeChild(this.logger);
        }
        if(this.clearButton && this.clearButton.parentNode){
            this.clearButton.parentNode.removeChild(this.clearButton);
        }
    }
}
