import Salad from "../../../index";
import { AActivityComponent } from "../AActivityComponent";
import { IActivityTransitionComponent } from "../../../types/external";

export class PlayActivityTransitionsComponent extends AActivityComponent implements IActivityTransitionComponent{
    constructor(private activity: Salad.IActivity) {
        super();
    }

    public override async onPageOut(oldPage: Salad.IPage): Promise<void> {
        if (oldPage) {
            const transitionComp = oldPage.getComponent("transitions");
            await transitionComp.playTransition("out");
        }
    }

    public override async onPageIn(newPage: Salad.IPage): Promise<void> {
        const transitionComp = newPage.getComponent("transitions");
        await transitionComp.playTransition("in");
    }

}
