/*
simple type events emitter
Uses an instance of EventEmitter to handle the events
Provide your own event map to define the events
Eg.  {change: payload}, {update: payload}
*/

import { ITypedEventEmitter } from "../types/external";
import { EventEmitter } from "events";

const MAX_LISTENERS = 128;

const DEBUG = false;

export abstract class TypedEventEmitter<T extends { [key in string]: object | number | string | undefined}>
    implements ITypedEventEmitter<T>
{
    private _emitter: EventEmitter;

    constructor() {
        this._emitter = new EventEmitter();
        this._emitter.setMaxListeners(MAX_LISTENERS);
    }
    
    public removeAllListeners() {
        this._emitter.removeAllListeners();
    }

    private _log(s:string){
        console.table(this.listenerCount);
    }

    public on<E extends keyof T>(event: E, listener: (eventData: T[E]) => any): this {
        this._emitter.on(<string>event, listener);
        if(DEBUG){
            this._log("on");
        }
        return this;
    }

    public off<E extends keyof T>(event: E, listener?: (eventData: T[E]) => any): this {
        if(listener){
            this._emitter.off(<string>event, listener);
        }
        else{
            this._emitter.removeAllListeners(<string>event);
        }
        if(DEBUG){
            this._log("off");
        }
        return this;
    }

    public emit<E extends keyof T>(event: E, eventData?: T[E]): void {
        this._emitter.emit(<string>event, eventData);
    }

    public get listenerCount(): {map: { [key:string]: number }, total: number} {
        const map:{ [key:string]: number } = {};
        let total = 0;
        this._emitter.eventNames().forEach((eventName:any) => {
            if(!eventName.toString().startsWith("__")){
                const num = this._emitter.listenerCount(eventName);
                map[eventName as string] = num;
                total += num;
            }
        })
        return {
            map,
            total
        }

    }

}
