/**
 * Abstract class for a velocity component
 */
import { Schema, IVelocityComponent, IInstance } from "../../types/external";
import { IPage } from "../../types/internal";
import { AComponent } from "../AComponent";

export default abstract class AVelocityComponent
    extends AComponent<"velocity">
    implements IVelocityComponent
{
    public name: "velocity" = "velocity";

    constructor(data: Schema["velocity"], instance: IInstance, page: IPage) {
        super(data, instance, page);
    }

    override getDependencies() {
        return ["position"] as const;
    }

    public override update(data: Schema["velocity"]): void {
        super.update(data);
    }

    /**
     * Set the direction of travel (not the direction facing), without changing the speed
     * @param angleDeg
     */
    public setDirection(angleDeg: number): void {
        const speed = this.getSpeed();
        this.setVelocity({
            x: speed * Math.cos((angleDeg * Math.PI) / 180),
            y: speed * Math.sin((angleDeg * Math.PI) / 180),
        });
    }

    /**
     * Make it travel towards a point
     * @param x
     * @param y
     */
    public setDirectionTowardsPoint(x: number, y: number): void {
        const pos = this.getInstanceComponent("position").getPosition();
        const dy = y - pos.y;
        const dx = x - pos.x;
        const angle = Math.atan2(dy, dx);
        this.setDirection((angle * 180) / Math.PI);
    }

    /**
     * Change the speed, keeping the direction the same
     * @param speed
     */
    public setSpeed(speed: number): void {
        if (speed < 0) {
            throw new Error("speed cannot be negative");
        }
        const currentSpeed = Math.sqrt(this.data.x * this.data.x + this.data.y * this.data.y);
        if (currentSpeed === 0) {
            this.setVelocity({
                x: 0,
                y: 0,
            });
        } else {
            const scale = speed / currentSpeed;
            this.setVelocity({
                x: this.data.x * scale,
                y: this.data.y * scale,
            });
        }
    }

    public getSpeed(): number {
        return Math.sqrt(this.data.x * this.data.x + this.data.y * this.data.y);
    }

    public stop(): void {
        this.setVelocity({ x: 0, y: 0 });
    }

    public increaseForwardSpeed(speed: number): void {
        const currentSpeed = this.getSpeed();
        this.setForwardSpeed(currentSpeed + speed);
    }

    /**
     *
     * @param speed
     */
    public setForwardSpeed(speed: number): void {
        const rot = this.instance.getComponent("transform").getRotation();
        const offset = this.instance.getComponent("movement").getOffsetAngle();
        const angle = rot + offset;
        this.setVelocity({
            x: speed * Math.cos((angle * Math.PI) / 180),
            y: speed * Math.sin((angle * Math.PI) / 180),
        });
    }

    /**
     * increment
     * @param x
     * @param y
     */
    public increaseBy(x: number, y: number): void {
        this.setVelocity({
            x: this.data.x + x,
            y: this.data.y + y,
        });
    }

    /**
     * set the velocity
     */
    public setVelocity(point: Schema["velocity"]): void {
        const maxSpeed = this.instance.getComponent("movement").getMaxSpeed();
        const speed = Math.sqrt(point.x * point.x + point.y * point.y);
        if (speed > maxSpeed) {
            const scale = maxSpeed / speed;
            point.x *= scale;
            point.y *= scale;
        }
        this.data.x = point.x;
        this.data.y = point.y;
    }

    public getVelocity(): { x: number; y: number } {
        return {
            x: this.data.x,
            y: this.data.y,
        };
    }
}
