/**
 * See if a 'drop' was
 */

import { IInstance } from "../../types/external";
import { Schema } from "../../types/external";

export class DropSuccessDecorator{

    private type: Schema["droppable"]["type"];

    /**
     * There are 2 different kinds of droppables
     * @param droppableInstance
     * @param droppedInstance 
     * @returns 
     */
    private static pointHandler(droppableInstance: IInstance, droppedInstance: IInstance) {
        const collisionComponent = droppableInstance.getComponent("collision");
        const droppableComponent = droppableInstance.getComponent("droppable");
        const tolerance = droppableComponent!.getTolerance();
        const vec = collisionComponent!.getVectorToCentre(droppedInstance);
        return Math.sqrt(vec.x * vec.x + vec.y * vec.y) < tolerance;
    }

    private static containHandler(droppableInstance: IInstance, droppedInstance: IInstance) {
        const collisionComponent = droppableInstance.getComponent("collision");
        const droppableComponent = droppableInstance.getComponent("droppable");
        const tolerance = droppableComponent!.getTolerance();
        return collisionComponent!.contains(droppedInstance, tolerance)
    }

    private static readonly mapTypeToContains: {
        [key in Schema["droppable"]["type"]]: (
            droppableInstance: IInstance,
            droppedInstance: IInstance,
        ) => boolean;
    } = {
        point: DropSuccessDecorator.pointHandler,
        contain: DropSuccessDecorator.containHandler
    }

    constructor(private droppableInstance: IInstance, private droppedInstance: IInstance) {
        this.type = droppableInstance.getComponent("droppable").getType();
    }   

    /**
     * Check if the droppable contains the dropped instance
     * In other words is it in the right place
     * @param droppableInstance
     * @param droppedInstance
     * @returns
     */
    public getSuccess() {
        const handler = DropSuccessDecorator.mapTypeToContains[this.type];
        return handler(this.droppableInstance, this.droppedInstance);
    }

    public snapIntoPosition(){
        if (this.type === "point") {
            // move it to the exact spot in the middle
            const collisionComponent = this.droppableInstance.getComponent("collision");
            const d = collisionComponent!.getVectorToCentre(this.droppedInstance);
            this.droppedInstance.getComponent("position")!.increaseBy(d.x, d.y);
        }
    }

}
