import { IPage } from "../../types/internal";
import { APageComponent } from "../APageComponent";
import { PageSchema, IPageDataComponent } from "../../types/external";

export default class PageDataComponent
    extends APageComponent<"data">
    implements IPageDataComponent
{
    public name: "data" = "data";

    constructor(data: PageSchema["data"], page: IPage) {
        super(data, page);
    }

    public getValue(): PageSchema["data"]["value"] {
        return this.data.value;
    }

    /**
     *
     * @param key get value for key
     * @returns
     */
    public getForKey(key: string): PageSchema["data"]["value"][string] {
        return this.data.value[key];
    }

    /**
     * set value for key
     * @param key
     * @param value
     */
    public setValueForKey(key: string, value: PageSchema["data"]["value"][string]): void {
        this.data.value[key] = value;
    }

    public setValue(value: PageSchema["data"]["value"]): void {
        this.data.value = value;
    }
}
