import { DrawingRect } from "./types";

/**
 * Return y0 if x < cutOffMin
 * Else return y1 if x > cutOffMax
 * Else linear interpolate
 * @param x
 * @param y0
 * @param y1
 * @param cutOffMin
 * @param cutOffMax
 * @returns
 */
export const cutOff = (
    x: number,
    y0: number,
    y1: number,
    cutOff: { min: number; max: number },
): number => {
    if (x < cutOff.min) {
        return y0;
    } else if (x > cutOff.max) {
        return y1;
    } else {
        return y0 + ((y1 - y0) * (x - cutOff.min)) / (cutOff.max - cutOff.min);
    }
};

export const getPointRect = (x: number, y: number, radius: number = 1): DrawingRect => {
    return {
        left: x - radius,
        right: x + radius,
        top: y - radius,
        bottom: y + radius,
    };
};

export const expandRect = (r: DrawingRect, x: number, y: number, radius: number = 1): void => {
    r.left = Math.min(r.left, x - radius);
    r.right = Math.max(r.right, x + radius);
    r.top = Math.min(r.top, y - radius);
    r.bottom = Math.max(r.bottom, y + radius);
};

export const drawImageRotated = (
    context: CanvasRenderingContext2D,
    image: CanvasImageSource,
    angleInRad: number,
    x: number,
    y: number,
    w: number,
    h: number,
): void => {
    context.translate(x, y);
    context.rotate(angleInRad);
    context.drawImage(image, -w / 2, -h / 2, w, h);
    context.rotate(-angleInRad);
    context.translate(-x, -y);
};
