/**
 * Lottie in play mode
 * Make a lottie animation and pass in the actual properties
 */
import { Schema, IInstance, ILottieAnimationItem } from "../../types/external";
import { IPage } from "../../types/internal";
import ALottieComponent from "./ALottieComponent";
import { lottie } from "../../utils/lottieFactory";
import { Events } from "../../types/external";
import { destroyLottie } from "../../utils/lottieFactory";
import { getLottieAsImageSrc } from "../../utils/lottieImageCache";

export default class PlayLottieComponent extends ALottieComponent {
    private placeholderImage: HTMLImageElement | undefined;

    constructor(data: Schema["lottie"], instance: IInstance, page: IPage) {
        super(data, instance, page);
        this.onDrawnFrame = this.onDrawnFrame.bind(this);
        this.onComplete = this.onComplete.bind(this);
        this.onClick = this.onClick.bind(this);
        this.onDrop = this.onDrop.bind(this);
        this.onAccepted = this.onAccepted.bind(this);
    }

    private async makeLottie(): Promise<ILottieAnimationItem | undefined> {
        const resolvedPath = await this.getAssetManager().getPathForKey(this.data.path);

        const frame0 = await getLottieAsImageSrc(resolvedPath);

        if(this.placeholderImage){
            this._element!.removeChild(this.placeholderImage);
        }

        this.placeholderImage = document.createElement("img");
        this.placeholderImage!.src = frame0;

        this._element?.append(this.placeholderImage)

        // play if autoplay is true and we havent set the state, or if have set the state, saved the file and opened it again
        const autoplay =
            typeof this.data.currentState === "undefined"
                ? this.data.autoPlay
                : this.data.currentState === "play";

        this.item = await lottie(this._element!, resolvedPath, {
            autoplay,
            loop: this.data.loop
        });

        try{
            this._element!.removeChild(this.placeholderImage);
        }
        catch(e: any){
            
        }
        
        this.item.addEventListener("drawnFrame", this.onDrawnFrame);
        this.item.addEventListener("complete", this.onComplete);

        this.data.currentState = autoplay ? "play" : "stop";
        
        // the frame we are on is either the default frame or the current frame
        this.data.currentFrame = this.data.currentFrame || 0;

        return this.item;
    }

    protected override destroyLottie() {
        super.destroyLottie();
        if (this.item) {
            this.item.removeEventListener("drawnFrame", this.onDrawnFrame);
            this.item.removeEventListener("complete", this.onComplete);
            //@ts-ignore
            destroyLottie(this.item);
            this.item = undefined;
        }
        if (this.animationItemPromise) {
            this.animationItemPromise = undefined;
        }
    }

    public override async setLoop(loop: boolean): Promise<void> {
        super.setLoop(loop);
        const anim = await this.getOrMakeLottie();
        anim.setLoop(loop);
    }

    protected async getOrMakeLottie(): Promise<ILottieAnimationItem> {
        if (this.item) {
            return Promise.resolve(this.item);
        }
        else {
            if (!this.animationItemPromise) {
                this.animationItemPromise = new Promise(async (resolve) => {
                    const resolvedPath = await this.getAssetManager().getPathForKey(this.data.path);
                    if (resolvedPath) {
                        this.item = await this.makeLottie();
                        resolve(this.item as ILottieAnimationItem);
                    }
                });
            }
            return this.animationItemPromise;
        }
    }

    public override async stop(frame?: number): Promise<void> {
        super.stop(frame);
        this.data.currentState = "stop";
        const anim = await this.getOrMakeLottie();
        if (typeof frame === "undefined") {
            frame = anim.currentFrame;
        }
        anim.goToAndStop(frame);
    }

    public override async play(frame?: number): Promise<void> {
        super.play(frame);
        const anim = await this.getOrMakeLottie();
        if (typeof frame === "undefined") {
            frame = anim.currentFrame;
        }
        anim.goToAndPlay(frame);
        this.data.currentState = "play";
    }

    public override async playSegments(segment: [number, number]): Promise<void> {
        super.playSegments(segment);
        const anim = await this.getOrMakeLottie();
        anim.playSegments(segment, true);
        this.data.currentState = "play";
    }

    protected onComplete(eventData?: any): void {
        this.data.currentState = "stop";
    }

    protected onDrawnFrame(eventData?: any): void {
        this.data.currentFrame = this.item?.currentFrame;
    }

    override onCreated(): void {
        super.onCreated();
        this._addListeners();
    }

    public override onDestroyed(): void {
        super.onDestroyed();
        this.destroyLottie();
        this._removeListeners();
    }

    protected _removeListeners() {
        this.instance.events.off(Events.INSTANCE_CLICK, this.onClick);
        this.instance.events.off(Events.INSTANCE_DROPPED, this.onDrop);
        this.instance.events.off(Events.INSTANCE_ACCEPTED, this.onAccepted);
    }

    private async playFromFrame(data: { frame: number; loop: boolean }) {
        await this.setLoop(data.loop);
        await this.play(data.frame);
    }

    private async onClick() {
        if (typeof this.data.onInstanceClick.frame === "number") {
            this.playFromFrame(this.data.onInstanceClick);
        }
    }

    private async onDrop() {
        if (typeof this.data.onInstanceDropped.frame === "number") {
            this.playFromFrame(this.data.onInstanceDropped);
        }
    }

    private async onAccepted() {
        if (typeof this.data.onInstanceAccepted.frame === "number") {
            this.playFromFrame(this.data.onInstanceAccepted);
        }
    }

    protected _addListeners(): void {
        // if you want to play a specific frame on click
        if (this.data.onInstanceClick?.enabled) {
            this.instance.events.on(Events.INSTANCE_CLICK, this.onClick);
        }
        if (this.data.onInstanceDropped?.enabled) {
            this.instance.events.on(Events.INSTANCE_DROPPED, this.onDrop);
        }
        if (this.data.onInstanceAccepted?.enabled) {
            this.instance.events.on(Events.INSTANCE_ACCEPTED, this.onAccepted);
        }
    }
}
