/**
 * shape component
 */

import { IShapeComponent, IInstance, Schema } from "../../types/external";
import { IPage } from "../../types/internal";
import { AComponent } from "../AComponent";
import { shape } from "../../utils/domElementFactory";

type Color = Schema["shape"]["fill"];
type ChildPosition = Schema["text"]["position"];

export default class ShapeComponent extends AComponent<"shape"> implements IShapeComponent {
    // the actual svg
    private element: SVGElement;

    public name: "shape" = "shape";

    constructor(data: Schema["shape"], instance: IInstance, page: IPage) {
        super(data, instance, page);
    }

    public setFill(clr: Color): void {
        this.data.fill = clr;
        this._destroyElement();
        this._update();
    }

    // rect, circle, polygon...
    public setType(type: Schema["shape"]["type"]): void {
        this.data.type = type;
        this._destroyElement();
        this._update();
    }

    public getElement(): SVGElement {
        return this.element;
    }

    override update(data: Schema["shape"]): void {
        super.update(data);
        this._destroyElement();
        this._update();
    }

    override getDependencies() {
        return ["render", "size"] as const;
    }

    override onCreated() {
        super.onCreated();
        this._update();
    }

    public override onDestroyed(): void {
        super.onDestroyed();
        this._destroyElement();
    }

    public setChildPosition(pos: ChildPosition): void {
        this.data.position = pos;
        this._updatePosition();
    }

    private _updatePosition() {
        Object.assign(this.element.style, {
            ...this.data.position,
        });
    }

    public getChildPosition(): ChildPosition {
        return this.data.position;
    }

    /**
     * Make the element
     */
    private _addElement() {
        const parent = this.getInstanceComponent("render").getElement();
        const sizeComp = this.getInstanceComponent("size");
        this.element = shape(parent, {
            type: this.data.type,
            fill: this.data.fill,
            size: sizeComp.getSize()!,
        });
        this._updatePosition();
    }

    private _destroyElement() {
        if (this.element) {
            this.element.remove();
        }
    }

    private _update(): void {
        if (this.data.enabled) {
            this._addElement();
        } else {
            this._destroyElement();
        }
    }
}
