import Moveable, { MoveableOptions } from "moveable";
import { DraggerOptions, IMoveable } from "./types";

/**
 * Get a moveable instance using the daybrush moveable library
 * @param target
 * @param container
 * @param moveableOptions
 * @param dragOptions
 * @returns
 */
export const getMoveable = (
    target: HTMLElement,
    container: HTMLElement,
    moveableOptions: MoveableOptions,
    dragOptions: DraggerOptions,
): IMoveable => {

    console.log("moveableOptions", moveableOptions);

    const moveable = new Moveable(container, {
        target,
        container,
        ...moveableOptions,
    })
        .on("click", dragOptions.onClick)
        .on("dragStart", dragOptions.onDragStart)
        .on("dragEnd", dragOptions.onDragEnd)
        .on("drag", dragOptions.onDrag);

        if(dragOptions.onResize) {
            moveable.on("resize", dragOptions.onResize);
        }
        if(dragOptions.onRotate) {
            moveable.on("rotate", dragOptions.onRotate);
        }
        if(dragOptions.onResizeEnd) {
            moveable.on("resizeEnd", dragOptions.onResizeEnd);
        }
        if(dragOptions.onRotateEnd) {
            moveable.on("rotateEnd", dragOptions.onRotateEnd);
        }
        if(dragOptions.onRotateEnd) {
            moveable.on("rotateEnd", dragOptions.onRotateEnd);
        }
        if(dragOptions.onRotateEnd) {
            moveable.on("rotateEnd", dragOptions.onRotateEnd);
        }
        return moveable;
};


