import Salad from "../../../index";
import { IActivityScriptComponent } from "../../../types/external";
import { AActivityComponent } from "../AActivityComponent";
import { ActivityOptions } from "../../../types/internal";
import { IScript } from "../../../types/internal";
import { CodeGenerator } from "@root/salad/pageComponents/coderunner/CodeGenerator";

export class ActivityScriptComponent extends AActivityComponent implements IActivityScriptComponent{

    private script:IScript;
    private transpiledCode: string | null = null;
    private globals: any = null;
    private hasRunOnce: boolean = false;

    constructor(private activity: Salad.IActivity, private options: ActivityOptions) {
        super();
        this.script = options.script;
    }

    public getContent(): string {
        return this.script?.content;
    }

    public setContent(content: string): void {
        this.script.content = content;
        this.transpiledCode = null;
    }

    public getGlobals(): {[functionName:string]: Function} {
        if(!this.hasRunOnce){
            const transpiledCode = this.getTranspiledCode();
            const finalCode = `
${transpiledCode}
return getGlobals(arguments[0]);
`;
            const f = new CodeGenerator().getFunctionToExecute(finalCode, false);
            this.globals = f.apply(this.activity, [this.activity]);
            this.hasRunOnce = true;
        }
        return this.globals;
    }

    private getTranspiledCode(): string {
        const content = this.script?.content;
        if(!content){
            return "";
        }
        else if(!this.transpiledCode){
            this.transpiledCode = Salad.Utils.Code.transpileCode(this.script?.content);
        }
        return this.transpiledCode;
    }

}
