/**
 * Class that represents a droppable component, that you can drop other objects into
 */

import ADroppableComponent from "./ADroppableComponent";
import { droppable } from "../../utils/domElementFactory";
import { Schema } from "../../schema/schema";

export default class EditDroppableComponent extends ADroppableComponent {
    private _element: HTMLElement;

    public override onCreated(): void {
        super.onCreated();
        this._updateElement();
    }

    public override onDestroyed(): void {
        super.onDestroyed();
    }

    public override update(data: Schema["droppable"]): void {
        super.update(data);
        this._updateElement();
    }

    public override setType(type: Schema["droppable"]["type"]): void {
        super.setType(type);
        this._updateElement();
    }

    private _updateElement() {
        if (this._element) {
            this._element.remove();
        }
        if (this.data.enabled) {
            this._element = droppable(this.data.type);
            const parent = this.getInstanceComponent("render").getElement();
            parent.appendChild(this._element);
        }
    }
}
