/**
 * Abstract class for a border components
 */
import { IBorderComponent, Schema, IInstance } from "../../types/external";
import { IPage } from "../../types/internal";
import { AComponent } from "../AComponent";
import { CSSDomUpdate } from "../../types/external";
export default class BorderComponent extends AComponent<"border"> implements IBorderComponent {
    public name: "border" = "border";

    constructor(data: Schema["border"], instance: IInstance, page: IPage) {
        super(data, instance, page);
    }

    public override update(data: Schema["border"]): void {
        super.update(data);
        this._update();
    }

    /**
     * lifecycle
     */
    public override onCreated(): void {
        super.onCreated();
        this._update();
    }

    /**
     * Helper to get the border as CSS
     * @returns
     */
    private _getCSS(): CSSDomUpdate["css"] {
        return {
            borderWidth: `${this.data.width}px`,
            borderColor: `${this.data.color}`,
            borderRadius: `${this.data.radius}px`,
            borderStyle: `${this.data.style}`,
        };
    }

    /**
     * apply CSS
     */
    private _update() {
        const renderComponent = this.getInstanceComponent("render");
        if (renderComponent) {
            const element = renderComponent.getElement();
            const css = this._getCSS();
            this.page.getComponent("domupdate").addCSSUpdate({
                element,
                css,
            });
        }
    }

    override getDependencies() {
        return ["render"] as const;
    }
}
