/**
 * Screen background = background of the entire window, not just the page
 */
import { IPage, IPageScreenBackgroundComponent } from "../../types/internal";
import { APageComponent } from "../APageComponent";
import { PageSchema } from "../../types/external";

type Color = PageSchema["screenbackground"]["color"];
export default class PageScreenBackgroundComponent
    extends APageComponent<"screenbackground">
    implements IPageScreenBackgroundComponent
{
    public name: "screenbackground" = "screenbackground";

    constructor(data: PageSchema["screenbackground"], page: IPage) {
        super(data, page);
    }

    override onCreated() {
        super.onCreated();
        this.update();
    }

    /**
     * Redraw image/color
     */
    private async update() {
        let css = {
            backgroundSize: "100% 100%",
            backgroundRepeat: "no-repeat",
            backgroundImage: "none",
            backgroundColor: "transparent",
        };
        if (this.data.name) {
            const src = await this.getAssetManager().getPathForKey(this.data.name);
            css = {
                ...css,
                backgroundImage: `url('${src}')`,
            };
        } else if (this.data.color) {
            css = {
                ...css,
                backgroundColor: this.data.color,
            };
        }
        Object.assign(this.page.getActivityContainer().style, css);
    }

    public removeImage(): void {
        this.data.name = "";
        this.update();
    }

    public setColor(clr: Color): void {
        this.removeImage();
        this.data.color = clr;
        this.update();
    }

    public removeColor(): void {
        this.data.color = "";
        this.update();
    }

    public getColor(): Color {
        return this.data.color!;
    }

    public setImage(name: string) {
        this.removeColor();
        this.data.name = name;
        this.update();
    }

    public getImage() {
        return this.data.name!;
    }
}
