/**
 * velocity component for play mode
 *  every frame we move the instance by the velocity
 */

import { Schema, IInstance, Events } from "../../types/external";
import { IPage } from "../../types/internal";
import AVelocityComponent from "./AVelocityComponent";

export default class PlayVelocityComponent extends AVelocityComponent {
    private _listening: boolean = false;

    constructor(data: Schema["velocity"], instance: IInstance, page: IPage) {
        super(data, instance, page);
    }

    /**
     * lifecycle
     */
    public override onCreated(): void {
        super.onCreated();
        this.onEnterFrame = this.onEnterFrame.bind(this);
        this._updateListeners();
    }

    /**
     * in play mode we set the velocity and update the listeners
     * @param point
     */
    public override setVelocity(point: { x: number; y: number }): void {
        super.setVelocity(point);
        this._updateListeners();
    }

    /**
     * lifecycle
     */
    public override onDestroyed(): void {
        this._removeListeners();
        super.onDestroyed();
    }

    /**
     * in play mode we set the velocity and update the listeners
     * @param data
     */
    public override update(data: Schema["velocity"]): void {
        super.update(data);
        this._updateListeners();
    }

    /**
     * add/remove as necessary
     */
    private _updateListeners() {
        if (this.data.x !== 0 || this.data.y !== 0) {
            if (!this._listening) {
                this._addListeners();
            }
        } else {
            if (this._listening) {
                this._removeListeners();
            }
        }
    }

    private _addListeners() {
        this.page.events.on(Events.ENTER_FRAME, this.onEnterFrame);
        this._listening = true;
    }

    private _removeListeners() {
        this.page.events.off(Events.ENTER_FRAME, this.onEnterFrame);
        this._listening = false;
    }

    /**
     * on enter frame handler
     */
    private onEnterFrame() {
        if (this.data.x !== 0 || this.data.y !== 0) {
            // velocity exists
            const posComponent = this.getInstanceComponent("position");
            posComponent.increaseBy(this.data.x, this.data.y);
        }
    }
}
