import { IShape } from "../../types/external";
import { Point } from "../../types/external";
import {Circle as FCircle, Point as FPoint, Relations as FRelations} from "@flatten-js/core";
import { AxisAlignedRect, AAR } from "./AxisAlignedRect";
export abstract class AShape implements IShape {

    public abstract getImplementation(): Flatten.Polygon | FCircle;

    public abstract getCentre(): Point;

    public abstract drawIn(ctx: CanvasRenderingContext2D): void;

    public containsPoint(p: Point): boolean {
        // most of our shapes are AAR
        const aar = this.toAxisAlignedRect();
        if(aar){
            return AxisAlignedRect.containsPoint(aar, p);
        }
        else{
            return this.getImplementation().contains(new FPoint(p.x, p.y));
        }
    }

    // tolerance is not used yet, seems a bit complicated
    public containsShape(otherShape: AShape, tolerance = 0): boolean {
        return FRelations.inside(otherShape.getImplementation(), this.getImplementation());
    }

    public abstract transform(trans: Point, scale: Point, rot: number, origin: Point): AShape;

    public toAxisAlignedRect():AAR | undefined{
        return undefined;
    }

    public intersects(otherShape: AShape): boolean {
        const aar1 = this.toAxisAlignedRect();
        const aar2 = otherShape.toAxisAlignedRect();
        if(aar1 && aar2){
            // most of our shapes are AAR
            return AxisAlignedRect.intersects(aar1, aar2);
        }
        else{
            return FRelations.intersect(
                otherShape.getImplementation(),
                this.getImplementation(),
            );
        }
    }
    
    public abstract offset(p: Point): AShape;

    // used in jest only
    public abstract toJSON():{centre?: Point, radius?: number, vertices?: Point[]};
}
