/**
 * Edit mode identity
 */

import { Schema, IInstance, Events } from "../../types/external";
import { IPage } from "../../types/internal";
import AAnimationComponent from "./AAnimationComponent";
import { getInstanceAnimation } from "./InstanceAnimation";
import { IInstanceAnimation } from "../../types/internal";
import { AnimatableProps } from "../../types/external";
import { IncompleteAnimationDecorator } from "./IncompleteAnimationDecorator";
import { AnimationSettings } from "../../schema/schema";
import { AnimationOptions } from "../../types/external";
import { InstanceEventsMap } from "../../types/external";
import { AnimationSequenceByName, AnimationSequenceByProps } from "../../types/external";

export default class PlayAnimationComponent extends AAnimationComponent {
    private animation: IInstanceAnimation | undefined;

    private incompleteDecorator: IncompleteAnimationDecorator | undefined;

    constructor(data: Schema["animation"], instance: IInstance, page: IPage) {
        super(data, instance, page);
        this.onDropped = this.onDropped.bind(this);
        this.onClick = this.onClick.bind(this);
        this.onAccepted = this.onAccepted.bind(this);
        this.onEnterFrame = this.onEnterFrame.bind(this);
        this.onVisChanged = this.onVisChanged.bind(this);
        this.onComplete = this.onComplete.bind(this);
        this.onKilled = this.onKilled.bind(this);
    }

    override onCreated(): void {
        super.onCreated();
        this.incompleteDecorator = new IncompleteAnimationDecorator(this.instance);
        this._addListeners();

        // is there an incomplete animation?
        
        const restarted = this.incompleteDecorator?.restart();
        if(!restarted){
            // if not, play the animation that should be played when the instance is added
            this.playOnAction("onInstanceAdded");
        }
    }

    public override onDestroyed(): void {
        this._removeListeners();
        this.incompleteDecorator = undefined;
        this.destroyAnimation();
        super.onDestroyed();
    }

    public override stopAnimation(): void {
        this.destroyAnimation();
    }

    public override async playAnimationByNameAsync(name: string, settings?: Partial<AnimationSettings>, options?: Partial<AnimationOptions>): Promise<void>{
        return new Promise((resolve) => {
            const anim = this.playAnimationByName(name, settings, options);
            anim.on("complete", resolve);
        })
    }
    
    public override async playAnimationAsync(props: Partial<AnimatableProps>, settings?: Partial<AnimationSettings>, options?: Partial<AnimationOptions>): Promise<void>{
        return new Promise((resolve) => {
            const anim = this.playAnimation(props, settings, options);
            anim.on("complete", resolve);
        });
    }

    public override async sequenceAnimations(animations: (AnimationSequenceByName | AnimationSequenceByProps)[]): Promise<void> {
        const animListComponent = this.instance.getComponent("animationlist");

        const getProps = (animData: AnimationSequenceByName | AnimationSequenceByProps): AnimatableProps=>{
            if("name" in animData){
                return animListComponent!.getAnimationByName(animData.name);
            }
            else{
                return animData.props;
            }
        }

        for (const animData of animations) {
            const props = getProps(animData);
            await this.playAnimationAsync(props, animData.settings, animData.options);
        }
    }

    public override playAnimationByName(
        name: string,
        settings: Partial<AnimationSettings>,
        options?: Partial<AnimationOptions>,
    ): IInstanceAnimation {
        // find the one to play
        const animListComponent = this.instance.getComponent("animationlist");
        const anim = animListComponent!.getAnimationByName(name);
        if (anim) {
            this.playAnimation(anim, settings, options);
        }
        return this.animation!;
    }

    private destroyAnimation() {
        if (this.animation) {
            // kill first to emit "complete" event
            this.page.events.off(Events.ENTER_FRAME, this.onEnterFrame);
            this.animation.kill();
            this.animation.removeAllListeners();
            this.animation = undefined;
        }
    }

    private cleanUp(): void {
        // stop listening to enter frame
        this.page.events.off(Events.ENTER_FRAME, this.onEnterFrame);
        // remove the incomplete animation
        this.incompleteDecorator?.clear();
    }

    private onKilled(): void {
        this.cleanUp();
    }

    private onComplete(): void {
        this.cleanUp();
    }

    /**
     * Helper function to just animate to a position over time
     * @param pos 
     * @param duration 
     * @returns 
     */
    public override animateTo(pos:{x:number, y:number}, duration: number = 1): IInstanceAnimation{
        const props: AnimatableProps = {
            x: `x + t*(${pos.x} - x)`,
            y: `y + t*(${pos.y} - y)`
        }
        
        return this.playAnimation(props, {
            duration: typeof duration === "number" ? duration : 1
        });
    }

    /**
     * Play an animation from some props. Eg. {x: "x + 100*t"} and some options. Eg. {settings: {duration: 2}}
     */
    public override playAnimation(props: Partial<AnimatableProps>, settings: Partial<AnimationSettings>, options?: Partial<AnimationOptions>): IInstanceAnimation {
        this.destroyAnimation();

        settings = {
            duration: 1,
            delay: 0,
            repeat: 0,
            ...settings
        }
        
        this.animation = getInstanceAnimation(this.instance, props, settings, options);
        this.animation.on("complete", this.onComplete);
        this.animation.on("killed", this.onKilled);
        this.page.events.on(Events.ENTER_FRAME, this.onEnterFrame);
        return this.animation;
    }

    public override getAnimation(): IInstanceAnimation | undefined {
        return this.animation;
    }

    private _removeListeners(): void {
        this.instance.events.off(Events.INSTANCE_CLICK, this.onClick);
        this.instance.events.off(Events.INSTANCE_DROPPED, this.onDropped);
        this.instance.events.off(Events.INSTANCE_ACCEPTED, this.onAccepted);
        this.instance.events.c.visibility.off(Events.COMPONENT_UPDATE, this.onVisChanged);
        this.page.events.off(Events.ENTER_FRAME, this.onEnterFrame);
    }

    private onEnterFrame(data: {time: number}) {
        // tick
        if(this.animation){
            this.animation.setCurrentTime(data.time);
        
            //store progress so we can restart it
            const incompleteData = this.animation.getIncompleteAnimationData()!;
            this.incompleteDecorator?.store(incompleteData);
        }
    }

    /**
     * listen to the relevant events
     */
    private _addListeners(): void {
        if (this.data.onInstanceClick && this.data.onInstanceClick.name) {
            this.instance.events.on(Events.INSTANCE_CLICK, this.onClick);
        }
        if (this.data.onInstanceDropped && this.data.onInstanceDropped.name) {
            this.instance.events.on(Events.INSTANCE_DROPPED, this.onDropped);
        }
        if (this.data.onInstanceAccepted && this.data.onInstanceAccepted.name) {
            this.instance.events.on(Events.INSTANCE_ACCEPTED, this.onAccepted);
        }
        if(this.data.onInstanceVisible && this.data.onInstanceVisible.name){
            this.instance.events.c.visibility.on(Events.COMPONENT_UPDATE, this.onVisChanged);
        }
    }

    private onVisChanged(eventData: InstanceEventsMap[typeof Events.COMPONENT_UPDATE]):void{
        const payload = eventData.payload
        if(payload.key === "visibility" && payload.value === "visible"){
            this.playOnAction("onInstanceVisible");
        }
    }

    private onAccepted(): void {
        this.playOnAction("onInstanceAccepted");
    }

    private onDropped(): void {
        this.playOnAction("onInstanceDropped");
    }

    private onClick() : void{
        this.playOnAction("onInstanceClick");
    }

    private playOnAction(
        type: "onInstanceAccepted" | "onInstanceDropped" | "onInstanceClick" | "onInstanceAdded" | "onInstanceVisible",
    ): IInstanceAnimation | undefined {
        
        const data = this.data[type];
        const animName = data!.name;

        const settings: AnimationSettings = {
            duration: data!.duration,
            delay: data!.delay,
            repeat: data!.repeat,
        };

        return this.playAnimationByName(animName, settings);
    }
}
