import Salad from "../../salad";
import type {ISoundSequencer} from "@tscommon/@types/pm-npm-types/sound/soundsequencer";
import SoundSequencer from "@common/sound/soundsequencer/index"


class PMSoundSequencer implements Salad.ISoundSequencer{

    private static pmSoundSequencer: ISoundSequencer;

    constructor(){
        if(!PMSoundSequencer.pmSoundSequencer){
            //@ts-ignore
            PMSoundSequencer.pmSoundSequencer = new SoundSequencer();
            PMSoundSequencer.pmSoundSequencer.init();
        }
    }
    public stopSound(sound: string | Salad.ISound):void{
        PMSoundSequencer.pmSoundSequencer.stopSound(sound);
    }
    public playSound(params:Salad.ISound):Salad.ISound{
        return PMSoundSequencer.pmSoundSequencer.playSound(params);
    }
    public stop():void{
        PMSoundSequencer.pmSoundSequencer.stop();
    }
    public mute():void{
        PMSoundSequencer.pmSoundSequencer.mute();
    }
    public unmute():void{
        PMSoundSequencer.pmSoundSequencer.unmute();
    }
    public preloadSound(src: string, id: string, onLoad: (sound: Salad.ISound) => void): void{
        PMSoundSequencer.pmSoundSequencer.preloadSound(src, id, onLoad);
    }
}

export const getPMSoundSequencer = () => {
    return new PMSoundSequencer();
}