import { DrawingToolSetting } from "../../../../types/external";
import { ASimpleBrush } from "./ASimpleBrush";
import { DrawingArea } from "./types";

const eraserStrength = 0.666;

export class SimpleBrushEraser extends ASimpleBrush {
    private prevX: number;
    private prevY: number;

    constructor(drawingArea: DrawingArea, setting: DrawingToolSetting) {
        super(drawingArea, setting);
    }
    public start(x: number, y: number): void {
        this.prevX = x;
        this.prevY = y;
        this.ctx.strokeStyle = `rgba(0, 0, 0, ${eraserStrength})`;
    }
    public move(x: number, y: number): void {
        const size = this.getDrawingSize(y);
        // eraser smudges more
        this.smearFromTo(this.prevX, this.prevY, x, y, 0.9);
        this.ctx!.globalCompositeOperation = "destination-out";
        this.ctx.lineWidth = size;
        this.ctx.beginPath();
        this.ctx.moveTo(this.prevX, this.prevY);
        this.ctx.lineTo(x, y);
        this.ctx.stroke();
        this.ctx!.globalCompositeOperation = "source-over";
        this.prevX = x;
        this.prevY = y;
    }
    public end(): void {}
}
