import { IPage, IAssetManager, ITranslator } from "../types/internal";
import {
    IComponent,
    DependenciesFor,
    ComponentName,
    IInstance,
    ComponentsMap,
    Schema,
    KeyOfComponent,
    ComponentUpdate,
} from "../types/external";
import { proxied, HandlerFor } from "../utils/utils";
import { UpdateForComponent, Events } from "../types/external";

type Update<K extends ComponentName> = UpdateForComponent<K> & ComponentUpdate;

/**
 * Helper that makes an update object for a component
 * This contains all the info needed to update a component for an instance
 * @param instance
 * @param component
 * @param key
 * @param value
 * @returns
 */
const createEventDataForUpdate = <K extends ComponentName, T extends KeyOfComponent<K>>(
    instance: IInstance,
    component: AComponent<K>,
    key: T,
    value: Schema[K][T],
) => {

    const payload: UpdateForComponent<K>["payload"] = {
        key,
        value,
    };

    const updateForComponent: UpdateForComponent<K> = {
        component,
        payload
    };
    const update: Update<K> = updateForComponent as Update<K>;

    return {
        ...update,
        target: instance,
    };
};

/**
 * Abstract component class - any component that is created should extend this class
 */

export abstract class AComponent<K extends ComponentName> implements IComponent<K> {
    /**
     * When writing code, authors can listen to changes in this component
     * The name and the new value are provided.
     */
    public abstract name: K;

    /**
     * data for this component
     * eg. if this is the 'position' component, data = {x:10, y:10}
     * This is proxied so you can write data.x = 11 and a 'componentUpdated' event is dispatched
     */
    protected data: Schema[K];

    /**
     * The instance.
     * Access other components with instance.getComponent(<component name>)
     */
    public instance: IInstance;

    /**
     * the page
     */
    protected page: IPage;

    /**
     * Pass in the data, instance to which this component belongs, and the page
     * @param data
     * @param instance
     * @param page
     */
    constructor(data: Schema[K], instance: IInstance, page: IPage) {
        /**
         * We proxy the 'data' object so that when we 'set' we can trigger an event that the system can listen to
         * Eg. this.data.position.x = 10 will trigger an event indicating that the 'x' property has changed
         */
        const handler: HandlerFor<Schema[K] & object> = <T extends KeyOfComponent<K>>(key: T, value: Schema[K][T]) => {
            const eventData = createEventDataForUpdate(this.instance, this, key, value);
            page.events.emit(Events.COMPONENT_UPDATE, eventData);
            this.instance.events.emit(Events.COMPONENT_UPDATE, eventData);
            this.instance.events.c[this.name].emit(Events.COMPONENT_UPDATE, eventData);
        };
        this.data = proxied<Schema[K]>(data!, handler);
        this.instance = instance;
        this.page = page;
    }

    /**
     * Every component gets an asset resolver
     * @returns the asset resolver
     */
    protected getAssetManager(): IAssetManager {
        return this.page.getAssetManager();
    }

    protected getTranslator(): ITranslator {
        return this.page.getTranslator();
    }

    /**
     * Get another component from the instance
     * You are only allowed to get those that you listed in 'getDependencies'
     * @param name
     * @returns
     */
    protected getInstanceComponent<K extends ReturnType<this["getDependencies"]>[number]>(
        name: K,
    ): ComponentsMap[K] {
        return this.instance.getComponent(name);
    }

    /**
     * Get the data stored in this component
     * @returns {Schema[K]} - the data
     */
    public getData(): Schema[K] {
        return this.data;
    }

    /**
     * Update the data with an object of type Schema[K]
     * @param {Schema[K]} data
     */
    public update(data: Partial<Schema[K]>): void {

        type Key = KeyOfComponent<K>

        const keys: Key[] = Object.keys(data) as Key[];
        keys.forEach((k: Key) => {
            //these are proxied, so events will be emitted
            this.data[k] = data[k] as Schema[K][Key];
        });
    }

    /**
     * Which need to be loaded before this can be used?
     * Eg. draggable depends on 'render' and 'position'
     * They cannot depend on themselves
     **/
    public getDependencies(): DependenciesFor<K> {
        return [];
    }

    /**
     * internal methos to check if all dependencies are present
     */
    private _checkDependencies(): void {
        const componentNames = this.getDependencies();
        componentNames.forEach((name) => {
            const component = this.getInstanceComponent(name);
            if (!component) {
                throw new Error(
                    `Component ${this.name} depends on ${name} but it is not present in the instance`,
                );
            }
        });
    }

    /**
     * lifecycle - onCreated
     */
    public onCreated(): void {
        this._checkDependencies();
    }

    /**
     * lifecycle - onDestroyed
     */
    public onDestroyed(): void {
        // nothing yet
    }
}
