/**
 * Different ways of highlighting an element
 */
import {IInstance} from "@root/salad/types/external";
import { AnimatableProps} from "../../types/external";
import { AnimationSettings } from "@root/salad/schema/schema";
import { getReadyMadeAnimationByName } from "../animations/readyMadeAnimations";
import { IHighlighter, HighlighterOptions } from "./types";

abstract class AAnimationHighlighter implements IHighlighter {
    
    constructor(protected options: HighlighterOptions) {
        const animComp = options.instance.getComponent("animation");
        animComp.playAnimation(this.getProps(), this.getSettings());
    }

    protected abstract getProps(): AnimatableProps

    protected abstract getSettings(): AnimationSettings

    public destroy() {
        const animComp = this.options.instance.getComponent("animation");
        animComp.stopAnimation();
    }

}
class Shake extends AAnimationHighlighter {
   
    protected override getProps(): AnimatableProps {
        const shakeAnim = getReadyMadeAnimationByName("shake");
        return shakeAnim!.props;
    }

    protected override getSettings(): AnimationSettings {
        return {
            duration: 1,
            repeat: 3
        }
    }
}

class Pulse extends AAnimationHighlighter {

    protected override getProps(): AnimatableProps {
        const AMPLITUDE = 0.015;

        return {
            scaleX: `1 + ${AMPLITUDE} * sin(2 * pi * t)`,
            scaleY: `1 + ${AMPLITUDE} * sin(2 * pi * t)`
        }
    }

    protected override getSettings(): AnimationSettings {
        return {
            duration: 1,
            repeat: -1
        }
    }
}

export const map = {
    shake: Shake,
    pulse: Pulse
}
