/**
 * Image component - displays an image
 */

import { IVideoComponent, IInstance } from "../../types/external";
import { Schema } from "../../types/external";
import { IPage } from "../../types/internal";
import { AComponent } from "../AComponent";
import { videoContainer, video } from "../../utils/domElementFactory";

export default class VideoComponent extends AComponent<"video"> implements IVideoComponent {
    private container: HTMLElement;

    /**
     * a child of container, the video
     */
    private element: HTMLVideoElement;

    public name: "video" = "video";

    constructor(data: Schema["video"], instance: IInstance, page: IPage) {
        super(data, instance, page);
    }

    override getDependencies() {
        return ["render"] as const;
    }

    public override onDestroyed(): void {
        this._destroyVideo();
        super.onDestroyed();
    }

    public override onCreated() {
        super.onCreated();
        this._update();
    }

    private _destroyVideo() {
        if (this.element) {
            this.element.pause();
            this.element.removeAttribute("src");
            this.element.load();
            this.element.remove();
        }
    }

    public play():void{
        if (this.element) {
            this.element.play();
        }
    }

    public stop():void{
        if (this.element) {
            this.element.pause();
        }
    }

    private _addVideo() {
        const renderComp = this.getInstanceComponent("render");
        if (!this.container) {
            const parent = renderComp.getElement();
            this.container = videoContainer(parent);
        }
        this.element = video(this.container, {
            path:this.data.path,
            controls: this.data.controls,
            autoplay: this.data.autoplay
        });
    }

    private _update() {
        this._destroyVideo();
        if (this.data.path && this.data.enabled && this.data.path.trim().length >= 1) {
            this._addVideo();
        }
    }

    public override update(data: Schema["video"]): void {
        super.update(data);
        this._update();
    }

    public setPath(path: string) {
        this.data.path = path;
        this._update();
    }
}
