import Salad from "../../../index";
import { AActivityComponent } from "../AActivityComponent";
import {IActivityPagesComponent} from "../../../types/external";
import { ActivityOptions } from "../../../types/internal";

type ChangePageData = Salad.PageEventsMap[typeof Salad.Events.CHANGE_PAGE]

export class PlayActivityPagesComponent extends AActivityComponent implements IActivityPagesComponent{

    constructor(private activity: Salad.IActivity, private options?: ActivityOptions) {
        super();
    }

    private getPageIndexForPageName(name:string): number{
        return this.options!.pages.findIndex(
            (p) => p.schema!.identity!.displayName === name
        )
    }

    public getPageIndexForPageId(pageId:string): number{
        return this.options!.pages.findIndex(
            (p) => p.id === pageId
        )
    }

    /**
     * get the index of the page to navigate to
     * you can give an index or a string, which could be a name of a page or just 'next'
     * @param currentPageIndex
     * @param changeData
     * @returns
     */
    private getPageIndexForChange(currentPageIndex: number, changeData: ChangePageData): number | undefined {
        if ("name" in changeData) {
            // just find the page using the name
            const newIndex = this.getPageIndexForPageName(changeData.name);
            return newIndex >= 0 ? newIndex : undefined;
        }
        else if ("increment" in changeData) {
            // just increment the index
            return currentPageIndex + changeData.increment;
        }
        else if ("history" in changeData) {
            // go to a specific history state - eg. back/fd in the list
            const newPageId = this.activity.getComponent("history")!.peekUsingChange(changeData.history);
            return this.getPageIndexForPageId(newPageId)
        }
        return undefined;
    }
    
    public getCurrentPageIndex(){
        const pageId = this.activity.getComponent("history").getCurrentPageId();
        return this.getPageIndexForPageId(pageId);
    }

    /**
     * Apply a change to the page (navigate to another one)
     * @param changeData 
     * @returns 
     */
    public async changePage(changeData: ChangePageData): Promise<void>{
        const currentPageIndex = this.getCurrentPageIndex();
        const newIndex = this.getPageIndexForChange(currentPageIndex, changeData);
        if (newIndex !== undefined && newIndex >= 0 && newIndex < this.options!.pages.length) {
            const page = this.options!.pages[newIndex];
            // we found a page - adjust the history
            this.activity.getComponent("history").updateForChange(changeData, newIndex, page.id);
            // then go to it
            return await this.activity.gotoPageByIndex(newIndex);
        }
        else {
            throw new Error("Cannot find page");
        }
    }

}

