import { AActivityInfoComponent } from "./AActivityInfoComponent";

export class PlayActivityInfoComponent extends AActivityInfoComponent{

    protected override getHasIntroScreen(): boolean {
        return !!this.options.info && this.options.info.enabled && this.options.info.buttons.length >= 1;
    }

    protected override async openIntroScreenAndGetPageIndex(): Promise<number> | undefined {
        const modalHelper = this.options.modalHelper;
        const selectedData: { name: string } = await modalHelper?.openInfo(this.options.info!)!;
        const allPageNames = this.options.pages.map((p) => p.schema!.identity!.displayName);
        const index = allPageNames.indexOf(selectedData.name);
        return index >= 0 ? index : undefined;
    }
}

