/**
 * play music in the background
 */

import { IPage} from "../../types/internal";
import { APageComponent } from "../APageComponent";
import { PageSchema, IPageSoundComponent } from "../../types/external";

export default abstract class APageSoundComponent
    extends APageComponent<"sound">
    implements IPageSoundComponent
{
    public name: "sound" = "sound";

    protected muted?: boolean = false;

    constructor(data: PageSchema["sound"], page: IPage) {
        super(data, page);
    }

    public async playSound(path: string, options?: { loop?: boolean }): Promise<void> {
        // nothing in edit mode
    }
    public async play(options?: { loop: boolean }): Promise<void> {
        // nothing in edit mode
    }

    public setMuted(muted:boolean): void {
        this.muted = muted;
        if(muted){
            this.getSoundSequencer().mute();
        }
        else{
            this.getSoundSequencer().unmute();
        }
    }

    public setLoop(loop: boolean): void {
        this.data.loop = loop;
    }

    public getLoop(): boolean {
        return this.data.loop;
    }

    public setAutoPlay(autoPlay: boolean): void {
        this.data.autoPlay = autoPlay;
    }

    public getAutoPlay(): boolean {
        return this.data.autoPlay;
    }

    public setPath(path: string): void {
        this.data.path = path;
    }

    public getPath(): string {
        return this.data.path;
    }

    public async stop(): Promise<void> {
        // nothing in edit mode
    }

    public async stopSound(path: string): Promise<void> {
        // nothing in edit mode
    }

    public stopAllSounds(): void {
        // nothing in edit mode
    }
}
