/**
 * play music in the background
 */

import { IPage } from "../../types/internal";
import { PageSchema, IPageSoundComponent } from "../../types/external";
import APageSoundComponent from "./APageSoundComponent";
import { Events } from "../../types/external";

export default class PlayPageSoundComponent
    extends APageSoundComponent
    implements IPageSoundComponent
{
    constructor(data: PageSchema["sound"], page: IPage) {
        super(data, page);
    }

    public override onCreated(): void {
        super.onCreated();
        if (this.data.path && this.data.autoPlay) {
            this.play({
                loop: this.data.loop,
            });
        }
        // set up this component to match the activity settings
        const settings = this.page.getCurrentActivity().settings.getSettings();
        this.setMuted(settings?.muted || false);
    }

    public override onDestroyed(): void {
        super.onDestroyed();
        this.getSoundSequencer()?.stop();
    }

    /**
     * Play any sound
     * @param path 
     * @param options 
     * @returns 
     */
    public override async playSound(path: string, options?: { loop?: boolean }): Promise<void> {

        options = options || {loop: false};
        
        const id = await this.getAssetManager().getPathForKey(path);
        const ss = this.getSoundSequencer();
        const loop = options?.loop || false;

        this.page.events.emit(Events.PAGE_SOUND_START, {
            sound: path
        });

        // all sounds should have been preloaded using the AssetResolver.preload function

        ss.playSound({
            id,
            src: id,
            loop,
            ended: () => {
                this.page.events.emit(Events.PAGE_SOUND_END, {
                    sound: path
                });
            }
        });
    }

    /**
     * Play the sound you specified in the schema (the background sound)
     * @param options 
     * @returns 
     */
    public override async play(options?: { loop?: boolean }): Promise<void> {
        return this.playSound(this.data.path, options);
    }

    public override stopAllSounds(): void {
        this.getSoundSequencer()?.stop();
    }

    public override async stopSound(path: string): Promise<void> {
        const id = await this.getAssetManager().getPathForKey(path);
        const ss = this.getSoundSequencer();
        ss.stopSound(id);
        this.page.events.emit(Events.PAGE_SOUND_END, {
            sound: path
        });
    }

    public override async stop(): Promise<void> {
        const id = await this.getAssetManager().getPathForKey(this.data.path);
        const ss = this.getSoundSequencer();
        ss.stopSound(id);
    }
}
