import { lottie, destroyLottie } from "./lottieFactory";
import { getSizeOfLottie } from "./lottieUtils";

type PendingResolver = (value: string | PromiseLike<string>) => void

type LottieImage = {
    status: "loading",
    url: "";
    pending: PendingResolver[];
} | {
    status: "loaded",
    url: string;
    pending: PendingResolver[];
}

const svgToPng = async (url:string): Promise<string>=>{
    return new Promise((resolve)=>{
        const img = new Image();
        img.onload = () => {
            // Set up canvas
            const canvas = document.createElement('canvas');
            canvas.width = img.width;
            canvas.height = img.height;
            const ctx = canvas.getContext('2d');
            ctx!.drawImage(img, 0, 0);
            const pngUrl = canvas.toDataURL('image/png');
            // Cleanup and resolve
            resolve(pngUrl);
        };
        img.src = url;
    });
}

const lottieImageCache:{[key:string]: LottieImage} = {}

/**
 * Get the image url from a lottie file
 */
const getImgUrl = async (path: string): Promise<string>=>{
    const size = await getSizeOfLottie(path);

    const container = document.createElement("div");
    Object.assign(container.style, {
        width: size.width + "px",
        height: size.height + "px"
    })
    const item = await lottie(container, path, {
        autoplay: false,
        loop: false,
    });

    let resolver: (value: string | PromiseLike<string>) => void

    const onDrawnFrame = () => {
        requestAnimationFrame(async () => {
            const svgElement = item.renderer.svgElement;
            if (svgElement) {
                const svgData = new XMLSerializer().serializeToString(svgElement);
                // seem to get weird svg issues now - fix them
                const fixedSvgData = svgData
                    .replace(/ns\d+:href="#/g, 'xlink:href="#')
                    .replace(/xlink:href="#/g, 'href="#');
                //resolve(fixedSvgData);
                const svgUrl = "data:image/svg+xml;base64," + btoa(fixedSvgData);

                const pngUrl = await svgToPng(svgUrl);
                resolver(pngUrl);
                item.removeEventListener("drawnFrame", onDrawnFrame);
                destroyLottie(item);
            }
        })
    }

    return new Promise(async (resolve) => {
        resolver = resolve;
        item.addEventListener("drawnFrame", onDrawnFrame)
        item.goToAndStop(0, true);
    })
}

export const getLottieAsImageSrc = async(path: string): Promise<string> => {
    if(lottieImageCache[path]){
        if(lottieImageCache[path].status === "loaded"){
            // ok, loaded
            return lottieImageCache[path].url;
        }
        else if(lottieImageCache[path].status === "loading"){
            // in progress - add it
            const pending = lottieImageCache[path].pending;
            return new Promise<string>((resolve) => {
                pending.push(resolve);
            })
        }
        else{
            return "";
        }
    }
    else{
        //new one!
        lottieImageCache[path] = {
            status: "loading",
            url: "",
            pending: []
        }
        const svgUrl = await getImgUrl(path);
        lottieImageCache[path] = {
            ...lottieImageCache[path],
            status: "loaded",
            url: svgUrl
        };
        const pending = lottieImageCache[path].pending;
        pending.forEach((resolve) => {
            resolve(svgUrl);
        });
        return svgUrl;
    }
}

