/**
 * handles key presses and also virutal keyboard presses on tablets
 */

import { TypedEventEmitter } from "../../utils/TypedEventEmitter";

export interface IKeyboardHandler extends TypedEventEmitter<KeyboardEventMap> {
    destroy(): void;
    isKeyPressed(code: string): boolean;
}

export type VirtualKeyboardEvent = {
    code: string;
    key: string;
    first: boolean;
};

type KeyboardEventMap = {
    keyDown: VirtualKeyboardEvent;
    keyUp: VirtualKeyboardEvent;
};

class KeyboardHandler extends TypedEventEmitter<KeyboardEventMap> implements IKeyboardHandler {

    private pressedKeyCodes: Set<string> = new Set();

    constructor() {
        super();

        this.onKeyDown = this.onKeyDown.bind(this);
        this.onKeyUp = this.onKeyUp.bind(this);

        document.addEventListener("keydown", this.onKeyDown);
        document.addEventListener("keyup", this.onKeyUp);
    }

    public destroy(): void {
        document.removeEventListener("keydown", this.onKeyDown);
        document.removeEventListener("keyup", this.onKeyUp);
    }

    public isKeyPressed(code: string): boolean{
        return this.pressedKeyCodes.has(code);
    }

    private onKeyDown(e: KeyboardEvent): void {
        const {key, code} = e;
        const first = !this.pressedKeyCodes.has(code);
        this.pressedKeyCodes.add(code);
        this.emitEvent("keyDown", {key, code, first})
    }

    private onKeyUp(e: KeyboardEvent): void {
        const {key, code} = e;
        this.pressedKeyCodes.delete(code);
        this.emitEvent("keyUp", {key, code, first: true});
    }

    public emitEvent(type: keyof KeyboardEventMap, e: VirtualKeyboardEvent):void{
        this.emit(type, e);
    }
}

export const getKeyboardHandler = (): IKeyboardHandler => {
    return new KeyboardHandler();
};
