/**
 * Abstract class for a collision component
 */

import { Schema, ICollisionComponent, Point, IInstance } from "../../types/external";
import { IPage } from "../../types/internal";
import { AComponent } from "../AComponent";
import { ShapeData } from "../../types/external";
import { IShape, Size } from "../../types/external";
import { PolygonShape } from "../../utils/shapes/PolygonShape";
import { CircleShape } from "../../utils/shapes/CircleShape";
import { InstanceEventsMap, Events } from "../../types/external";

/**
 * Helper function - convert the data to a shape
 *
 * Eg. a polygon with points at 0,0, 1,0, 1,1, 0,1 and a size of 100,100
 * will be converted to a polygon with points at 0,0, 100,0, 100,100, 0,100
 *
 * Similarly a circle with radius 0.5 and a size of 100,100
 * will be converted to a circle with radius 50
 * @param data
 * @param size
 * @returns
 */
const dataToShape = (data: ShapeData, size: Size): IShape => {
    if (data.type === "polygon") {
        const pts = data.points.map((p: Point) => {
            return {
                x: p.x * size.width,
                y: p.y * size.height,
            };
        });
        return new PolygonShape(pts);
    } else {
        const centre = {
            x: size.width / 2,
            y: size.height / 2,
        };
        const r = Math.min(size.width, size.height) * data.radius;
        return new CircleShape(centre, r);
    }
};

export default class CollisionComponent
    extends AComponent<"collision">
    implements ICollisionComponent
{
    public name: "collision" = "collision";

    /**
     * the raw data in this class is also stored as a 'shape'- which is used for collisions
     */
    private _shape: IShape;

    constructor(data: Schema["collision"], instance: IInstance, page: IPage) {
        super(data, instance, page);
    }

    public getCentre(): Point {
        return this.getTransformedShape().getCentre();
    }

    public getIsStatic(): boolean{
        return this.data.static;
    }

    /**
     * lifecycle
     */
    public override onCreated(): void {
        super.onCreated();
        this.onComponentUpdated = this.onComponentUpdated.bind(this);
        this.instance.events.c.size.on(Events.COMPONENT_UPDATE, this.onComponentUpdated);
        this._updateShape();
    }

    /**
     * lifecycle
     */
    public override onDestroyed(): void {
        super.onDestroyed();
        this.instance.events.c.size.off(Events.COMPONENT_UPDATE, this.onComponentUpdated);
    }

    /**
     * does this instance contain the other instance?
     */
    public contains(otherInstance: IInstance, tolerance: number = 0): boolean {
        // check containment
        const containerShape = this.getTransformedShape();
        const instanceShape = otherInstance.getComponent("collision").getTransformedShape();
        return containerShape.containsShape(instanceShape, tolerance);
    }

    public getVectorToCentre(otherInstance: IInstance): Point {
        const myCenter = this.getCentre();
        const instanceCenter = otherInstance.getComponent("collision").getCentre();

        // check closeness
        const dx = myCenter.x - instanceCenter.x;
        const dy = myCenter.y - instanceCenter.y;

        return {
            x: dx,
            y: dy,
        };
    }

    /**
     * When the size of the instance changes, update the shape
     * @param eventData
     */
    private onComponentUpdated(eventData: InstanceEventsMap[typeof Events.COMPONENT_UPDATE]): void {
        this._updateShape();
    }

    public getShape(): IShape {
        return this._shape;
    }

    public setShapeData(shapeData: ShapeData): void {
        this.data.shape = shapeData;
        this._updateShape();
    }

    /**
     * Only ones in the same group can collide
     * @returns string
     */
    public getGroup(): string {
        return this.data.group;
    }

    public setGroup(group: string): void {
        this.data.group = group;
    }

    private _updateShape() {
        const sizeComp = this.getInstanceComponent("size");
        const size = sizeComp.getSize();
        this._shape = dataToShape(this.data.shape, size);
    }

    public override update(data: Schema["collision"]): void {
        super.update(data);
        this._updateShape();
    }

    private getTransformedShapeGivenTransforms(
        position: Point,
        scale: Point,
        rotation: number,
        origin: Point,
    ): IShape {
        return this._shape.transform(position, scale, rotation, origin);
    }

    public getFutureCentreAtNewPosition(futurePosition: Point): Point {
        const shape = this.getFutureTransformedShapeAtNewPosition(futurePosition);
        return shape.getCentre();
    }

    /**
     * Specify transforms and get the shape - useful for predicting future collisions
     * and stopping things moving if there will be one
     * @param position
     * @param scale
     * @param rotation
     * @param origin
     * @returns
     */
    public getFutureTransformedShapeAtNewPosition(futurePosition: Point): IShape {
        const transform = this.getInstanceComponent("transform");
        return this.getTransformedShapeGivenTransforms(
            futurePosition,
            transform.getScale(),
            transform.getRotation(),
            transform.getOriginPoint(),
        );
    }

    /**
     * Get the collision shape, based on the current position, scale and rotation
     * @returns
     */
    public getTransformedShape(): IShape {
        const transform = this.getInstanceComponent("transform");
        const position = this.getInstanceComponent("position");

        return this.getTransformedShapeGivenTransforms(
            position.getViewPosition(),
            transform.getScale(),
            transform.getRotation(),
            transform.getOriginPoint(),
        );
    }

    override getDependencies() {
        return ["render", "size", "position", "transform"] as const;
    }
}
