export interface IPointerEventData{
    point: Point;
    target: IInstance;
    targets: IInstance[];
    originalEvent?: MouseEvent | TouchEvent | PointerEvent; //optional
}

interface ICommonEventsMap {
    [Events.INSTANCE_CLICK]: IPointerEventData;

    [Events.INSTANCE_DROPPED]: {
        selectedInstance: IInstance;
    };
    [Events.INSTANCE_DBLCLICK]: IPointerEventData;
    [Events.INSTANCE_POINTERDOWN]: IPointerEventData;
    [Events.INSTANCE_POINTERDRAG]: IPointerEventData;
    [Events.INSTANCE_POINTERMOVE]: IPointerEventData;

    [Events.INSTANCE_ACCEPTED]: ICommonEventsMap[typeof Events.INSTANCE_DROPPED];

    [Events.INSTANCE_START_DRAG]: {
        selectedInstance: IInstance;
    };
    [Events.CONTENT_CHANGE]: {
        // the one you added to, or removed from. Eg a drop-zone
        target: IInstance;

        // the one you added to it or removed from it
        instance: IInstance;
        type: "add" | "remove";

        // the new contents
        contents: IInstance[];
    };
    [Events.COLLISION_START]: {
        instance1: IInstance;
        instance2: IInstance;
    };
    [Events.COLLISION_END]: ICommonEventsMap[typeof Events.COLLISION_START];
    [Events.INSTANCE_CREATED]: {
        target: IInstance;
    };
    [Events.INSTANCE_DESTROYED]: {
        target: IInstance;
    };
    [Events.INSTANCE_MOUSEOVER]: {
        target: IInstance;
    };
    [Events.INSTANCE_MOUSEOUT]: {
        target: IInstance;
    };
    [Events.KEY_DOWN]: {
        code: string;
        key: string;
        first: boolean;
    };
    [Events.KEY_UP]: ICommonEventsMap[typeof Events.KEY_DOWN];
    [Events.COMPONENT_UPDATE]: ComponentUpdate & { target: IInstance };
}

type CommonEventsMap = {
    [K in keyof ICommonEventsMap]: ICommonEventsMap[K];
} & CustomUserEventsMap;

export type PageSelection =
    | {
          // one selected instance
          type: "instance";
          selectedInstance: IInstance;
          selectedGroup: undefined;
      }
    | {
          // one selected group
          type: "group";
          selectedInstance: undefined;
          selectedGroup: IInstance[];
      }
    | {
          // none
          type: "none";
          selectedInstance: undefined;
          selectedGroup: undefined;
      };

