// helper
export interface ITypedEventEmitter<T> {
    on<E extends keyof T>(event: E, listener: (eventData: T[E]) => void): this;
    off<E extends keyof T>(event: E, listener?: (eventData: T[E]) => void): this;
    emit<E extends keyof T>(event: E, eventData?: T[E]): void;
    removeAllListeners(): void;
    listenerCount: {map: { [key:string]: number }, total: number};
}

