/**
 * components have the following external API, visible to people using the tool to write code
 */
export interface IComponent<K extends ComponentName> {
    name: K;

    /**
     * the instance that owns this component
     */
    instance: IInstance;

    /**
     * get all the data
     */
    getData(): Schema[K];

    /**
     * update all data
     * @param data
     */
    update(data: Partial<Schema[K]>): void;

    /**
     * Does this component have dependencies which must be created before this is created?
     */
    getDependencies(): DependenciesFor<K>;

    /**
     * life cycle
     */
    onCreated: () => void;
    onDestroyed: () => void;
}

