export interface ICollisionComponent extends IComponent<"collision"> {
    /*
      Pure data, in the model's world. Unaffected by transforms or positon
      For example Rect (0,0  0,1  1,1  1,0) - this means the element's collision area is a rectangle which matches the element's size
    */
    getShape(): IShape;
    setShapeData(shapeData: ShapeData): void;

    getCentre(): Point;

    /**
     * Get the shape in the model's world, and transform it by the position and transform components.
     * This is the shape in the page's world that is actually used for collision detection
     * Eg. Rect (0,0  0,1  1,1  1,0) -> Polygon(200,287  300,287  300,387  200,387)
     */
    getTransformedShape(): IShape;

    getIsStatic(): boolean;

    /**
     * Once moved to the new position, what is the new transformed shape?
     * Use this to determine whether we can move to that position or not
     * */
    getFutureTransformedShapeAtNewPosition(position: Point): IShape;

    getFutureCentreAtNewPosition(futurePosition: Point): Point;

    /**
     * Only objects in the same group can collide
     */
    getGroup(): string;
    setGroup(group: string): void;

    contains(otherInstance: IInstance, tolerance?: number): boolean;
    getVectorToCentre(otherInstance: IInstance): Point;
}

