/**
 * Class for the background component.
 * Holds an image and/or fill
 */

import { IAnimationListComponent, Schema, IInstance } from "../../types/external";
import { IPage } from "../../types/internal";
import { AComponent } from "../AComponent";
import { getReadyMadeAnimationByName } from "./readyMadeAnimations";

type AnimatableProps = Schema["animationlist"]["list"][string];

const builtIns:{[name:string] : AnimatableProps} = {
    "fadeIn":getReadyMadeAnimationByName("fadein")!.props,
    "fadeOut":getReadyMadeAnimationByName("fadeout")!.props,
    "shake": getReadyMadeAnimationByName("shake")!.props
}

export default class AnimationListComponent
    extends AComponent<"animationlist">
    implements IAnimationListComponent
{
    public name: "animationlist" = "animationlist";

    constructor(data: Schema["animationlist"], instance: IInstance, page: IPage) {
        super(data, instance, page);
    }

    public override update(data: Schema["animationlist"]): void {
        super.update(data);
    }

    /**
     * lifecycle
     */
    public override onCreated(): void {
        super.onCreated();
    }

    /**
     * lifecycle
     */
    public override onDestroyed(): void {
        super.onDestroyed();
    }

    public getAnimationByName(name: string): AnimatableProps {
        const list = this.data!.list;
        return list[name] || builtIns[name];
    }

}
