import AClockComponent from "./AClockComponent";
import Salad from "@root/salad";
import { clock } from "@root/salad/utils/domElementFactory";
import { getUI, IClockUI } from "./ClockUI";
import { ClockTimer, IClockTimer } from "./ClockTimer";
import { IInstanceAnimation } from "@root/salad/types/internal";
import { getReadyMadeAnimationByName } from "../animations/readyMadeAnimations";

const CLOCK_KEY = "__clock__";

export default class PlayClockComponent extends AClockComponent {
    
    private ui: IClockUI | undefined = undefined;
    private element: HTMLElement | undefined = undefined;
    private timer: IClockTimer = new ClockTimer();
    private animation:IInstanceAnimation | undefined = undefined;
    
    public override onCreated(): void {
        super.onCreated();
        this.onEnterFrame = this.onEnterFrame.bind(this);
        if(this.data.enabled){
            this.addUI();
            this.loadSavedTime();
            this.addEnterFrameListener();
        }
    }

    public override onDestroyed(): void {
        super.onDestroyed();
        if(this.ui){
            this.ui.destroy();
        }
        if(this.timer){
            this.timer.destroy();
        }
        this.destroyAnimation();
        this.removeEnterFrameListener();
    }

    private loadSavedTime():void{
        const activity = this.page.getCurrentActivity();
        const key = this.getKey();
        const value = activity.data.getForKey(key);
        if(value){
            const time = parseFloat(value as any);
            this.timer.setTime(time);
            this.updateUI();
        }
    }

    private getKey():string{
        return `${CLOCK_KEY}${this.data.name}`;
    }

    private addEnterFrameListener(){
        this.page.events.on(Salad.Events.ENTER_FRAME, this.onEnterFrame);
    }

    private removeEnterFrameListener(){
        this.page.events.off(Salad.Events.ENTER_FRAME, this.onEnterFrame);
    }

    private addUI():void{
        this.element = clock();
        const parent = this.instance.getComponent("render").getElement();
        parent.appendChild(this.element);
        this.ui = getUI(this.element, this.data.time, this.data.direction);
    }

    private updateUI():void{
        const time = this.timer.getTime();
        this.ui?.update(time);
    }

    private persist():void{
        const activity = this.page.getCurrentActivity();
        const key = this.getKey();
        activity.data.setValueForKey(key, this.timer.getTime());
    }

  
    private destroyAnimation():void{
        const animComp = this.instance.getComponent("animation");
        animComp.stopAnimation();
        this.animation = undefined;
    }

    private checkFinished():void{
        if(this.ui?.getIsFinished() && !this.animation){
            const animComp = this.instance.getComponent("animation");
            const shakeAnim = getReadyMadeAnimationByName("shake");
            this.animation = animComp.playAnimation(shakeAnim!.props, {
                duration: 1,
                repeat: 0
            }) as IInstanceAnimation;
        }
    }

    private onEnterFrame(eventData:Salad.PageEventsMap[typeof Salad.Events.ENTER_FRAME]){
        const changed = this.timer.update(eventData.time);
        if(changed){
            this.persist();
            this.updateUI();
            this.checkFinished();
        }
    }
}
