
export class ButtonPointerDrawer {
    constructor(private uiElement: HTMLElement) {}

    private static ARROW_WIDTH = 24;

    public clear(): void{
        Object.assign(this.uiElement.style, {
            display: "none",
            backgroundImage: "",
        })
    }

    /**
     * draw a trianglular arrow using the 'point'
     * @param point
     * @param style
     */
    public draw(point: { x: number; y: number }, color: string) {
        const angle = Math.atan2(point.y, point.x) + Math.PI / 2;

        const baseLength = ButtonPointerDrawer.ARROW_WIDTH;

        const baseDx = (Math.cos(angle) * baseLength) / 2;
        const baseDy = (Math.sin(angle) * baseLength) / 2;

        const p0 = {
            x: baseDx,
            y: baseDy,
        };

        const p1 = {
            x: -baseDx,
            y: -baseDy,
        };

        const p2 = {
            x: point.x,
            y: point.y,
        };

        const xs = [p0, p1, p2].map((p) => p.x);
        const ys = [p0, p1, p2].map((p) => p.y);

        const left = Math.min(...xs);
        const top = Math.min(...ys);

        const right = Math.max(...xs);
        const bottom = Math.max(...ys);

        const w = right - left;
        const h = bottom - top;

        const p0Translated = {
            x: p0.x - left,
            y: p0.y - top,
        };

        const p1Translated = {
            x: p1.x - left,
            y: p1.y - top,
        };

        const p2Translated = {
            x: p2.x - left,
            y: p2.y - top,
        };

        const svg = `
<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ${w} ${h}">
    <polygon 
        points="${p0Translated.x},${p0Translated.y} ${p1Translated.x},${p1Translated.y} ${p2Translated.x} ${p2Translated.y}" 
        fill="${color}"
        stroke="${color}" 
        stroke-width="0"/>
</svg>
`;

        const svgDataUri = "data:image/svg+xml;charset=UTF-8," + encodeURIComponent(svg);

        Object.assign(this.uiElement.style, {
            display: "block",
            backgroundImage: `url('${svgDataUri}')`,
            left: "50%",
            top: "50%",
            marginLeft: `${left}px`,
            marginTop: `${top}px`,
            width: `${w}px`,
            height: `${h}px`,
        });

        this.uiElement.classList.add("button-pointer-drawer");
    }
}
