/**
 * Class for the background component.
 * Holds an image and/or fill
 */

import { IBackgroundComponent, Schema, IInstance } from "../../types/external";
import { IPage } from "../../types/internal";
import { AComponent } from "../AComponent";
import { CSSDomUpdate } from "../../types/external";

export default class BackgroundComponent
    extends AComponent<"background">
    implements IBackgroundComponent
{
    public name: "background" = "background";

    constructor(data: Schema["background"], instance: IInstance, page: IPage) {
        super(data, instance, page);
    }

    public override update(data: Schema["background"]): void {
        super.update(data);
        this._update();
    }

    /**
     * lifecycle
     */
    public override onCreated(): void {
        super.onCreated();
        this._update();
    }

    public setFill(clr: Schema["background"]["fill"]): void {
        this.data.fill = clr;
        this._update();
    }

    public getFill(): Schema["background"]["fill"] {
        return this.data.fill;
    }

    public setImageRepeat(repeat: Schema["background"]["imageRepeat"]): void{
        this.data.imageRepeat = repeat;
        this._update();
    }
    public getImageRepeat(): Schema["background"]["imageRepeat"]{
        return this.data.imageRepeat;
    }
    public setImagePosition(position: Schema["background"]["imagePosition"]): void{
        this.data.imagePosition = position;
        this._update
    }

    public getImagePosition(): Schema["background"]["imagePosition"]{
        return this.data.imagePosition;
    }
    public setImageSize(size: Schema["background"]["imageSize"]): void{
        this.data.imageSize = size;
        this._update();
    }
    public getImageSize(): Schema["background"]["imageSize"]{
        return this.data.imageSize;
    }

    public setImage(path: Schema["background"]["image"]): void {
        this.data.image = path;
        this._update();
    }

    public getImage(): Schema["background"]["image"] {
        return this.data.image;
    }



    /**
     * lifecycle
     */
    public override onDestroyed(): void {}

    private async _update():Promise<void> {
        const renderComponent = this.getInstanceComponent("render");
        const element = renderComponent!.getElement();
        const css:CSSDomUpdate["css"] = {
            backgroundColor: this.data.fill || "transparent",
        }
        if(this.data.image){
            const resolvedPath = await this.getAssetManager().getPathForKey(this.data.image);
            css.backgroundImage = `url(${resolvedPath})`;
            css.backgroundRepeat = this.data.imageRepeat;
            css.backgroundPosition = this.data.imagePosition;
            css.backgroundSize = this.data.imageSize;
        }
        this.page.getComponent("domupdate").addCSSUpdate({
            element,
            css
        });
    }

    override getDependencies() {
        return ["render"] as const;
    }
}
