/**
 * Handles panning
 */
import { ICameraComponent, ICameraZoomer } from "../../types/external";
import { PageSchema } from "../../types/external";

type Box = PageSchema["camera"]["view"];

export class CameraZoomer implements ICameraZoomer {
    constructor(private cameraComp: ICameraComponent) {}

    /**
     * 1 means show camera width and height, 2 means show half the width and height
     * @param zoom
     */
    public setZoom(zoom: number, duration?:number): void {
        const view = this.getViewForZoom(zoom);
        this.cameraComp.moveToView(view, duration);
    }

    public getViewForZoom(zoom: number): Box{
        const view = this.cameraComp.getView();

        const cameraSize = this.cameraComp.getEffectiveSize();

        const newWidth = cameraSize.width / zoom;
        const newHeight = cameraSize.height / zoom;
        const newLeft = view.left + (view.width - newWidth) / 2;
        const newTop = view.top + (view.height - newHeight) / 2;

        return {
            left: Math.round(newLeft),
            top: Math.round(newTop),
            width: Math.round(newWidth),
            height: Math.round(newHeight),
        };
    }

    public getZoom(): number {
        const cameraSize = this.cameraComp.getEffectiveSize();
        const view = this.cameraComp.getView();
        const viewWidth = view.width;

        // height should be the same!
        return cameraSize.width / viewWidth;
    }

    public destroy(): void {
        
    }
}
