/**
 * when the velocity changes, change the rotation
 */

import { IMovementComponent } from "../../types/external";
import { IInstance, Schema } from "../../types/external";
import { IPage } from "../../types/internal";
import { AComponent } from "../AComponent";

export default abstract class AMovementComponent
    extends AComponent<"movement">
    implements IMovementComponent
{
    public name: "movement" = "movement";

    constructor(data: Schema["movement"], instance: IInstance, page: IPage) {
        super(data, instance, page);
    }

    public getWrap(): boolean {
        return this.data.wrap!;
    }

    public setWrap(wrap: boolean): void {
        this.data.wrap = wrap;
    }

    public getDestroy(): boolean {
        return this.data.destroy!;
    }

    public getMaxSpeed(): number {
        return this.data.maxspeed!;
    }

    public getMaxAngularSpeed(): number {
        return this.data.maxangularspeed!;
    }

    public getFriction(): number {
        return this.data.friction!;
    }

    public setFriction(f: number): void {
        this.data.friction = f;
    }

    public setDestroy(destroy: boolean): void{
        this.data.destroy = destroy;
    }

    public getOffsetAngle(): number {
        return this.data.offsetAngle!;
    }

    public setOffsetAngle(angle: number): void {
        this.data.offsetAngle = angle;
    }

    override getDependencies() {
        return ["render", "position", "velocity", "angularvelocity"] as const;
    }

    public override update(data: Schema["movement"]): void {
        super.update(data);
    }
}
