import { IPage } from "../../types/internal";
import { APageComponent } from "../APageComponent";
import { PageSchema, IPageHighlightComponent } from "../../types/external";
import { highlightCanvas } from "../../utils/domElementFactory";
import { makeHighlighter } from "./PageHighlighters";
import { IHighlighter } from "@root/salad/components/highlights/types";

export default class PlayPageHighlightComponent extends APageComponent<"highlight"> implements IPageHighlightComponent{
    
    public name: "highlight" = "highlight";
    private _element: HTMLCanvasElement;
    private _highlight: IHighlighter;

    constructor(data: PageSchema["highlight"], page: IPage) {
        super(data, page);
    }

    public override onCreated(): void {
        super.onCreated();
        this._element = highlightCanvas();
        const layerComp = this.getPageComponent("layers");
        layerComp.initLayer("highlight", this._element, {
            type: "unscaled",
        });
        if(this.data.type !== "none"){
            this._update();
        }
    }

    public override onDestroyed(): void {
        this._destroyHighlight();
        const layerComp = this.getPageComponent("layers");
        layerComp.removeLayer("highlight");
        super.onDestroyed();
    }

    private _update(): void {
        this._destroyHighlight();
        if(this.data.type !== "none"){
            this._highlight = makeHighlighter(this.data.type, this._element);
            //highlight and then set the highlight type to none so we dont save anything
            this.data.type = "none";
        }
    }

    public setHighlight(type: PageSchema["highlight"]["type"]): void {
        this.data.type = type;
        this._update();
    }

    private _destroyHighlight() {
        if (this._highlight) {
            this._highlight.destroy();
            this._highlight = null;
        }
    }

}
