import { IInstance } from "../../types/external";
import { AnimatableProps } from "../../types/external";
import {AnimationProps, IAnimationProps} from "./AnimationProps";
import { AInstanceAnimation } from "./AInstanceAnimation";
import { AnimationTime, IAnimationTime } from "./AnimationTime";
import { IIncompleteAnimationData } from "../../types/internal";
import { AnimationSettings } from "../../schema/schema";
import { AnimationOptions } from "../../types/external";
import { IInstanceAnimation } from "../../types/internal";
import { SaladJSONValue } from "../../types/external";
import { NumericAnimatedProps } from "../../schema/schema";

const getInitialPropsFromInstance = (instance: IInstance): NumericAnimatedProps => {
    const posComp = instance.getComponent("position");
    const transformComp = instance.getComponent("transform");
    const renderComp = instance.getComponent("render");
    const pos = posComp!.getPosition();
    const scale = transformComp!.getScale();

    return {
        x: pos.x,
        y: pos.y,
        scaleX: scale.x,
        scaleY: scale.y,
        rotation: transformComp!.getRotation(),
        opacity: renderComp!.getOpacity(),
    };
}

/**
 * Class to animate an instance
 */
class InstanceAnimation extends AInstanceAnimation{

    private timer: IAnimationTime;

    // if we have been killed
    private killed: boolean = false;

    // the props we are animating
    private animationProps: IAnimationProps;

    constructor(
        private instance: IInstance,
        private props: AnimatableProps,
        private settings: AnimationSettings,
        private options?: AnimationOptions,
    ) {
        super();

        // create the timer which handles delays, durations, repeat etc
        this.timer = new AnimationTime(settings);

        // get the initial props
        const initialProps = {
            ...getInitialPropsFromInstance(this.instance),
            ...options?.initialProps
        } 
        
        // create the animation props which handles updating the props on the instance
        this.animationProps = new AnimationProps(props, initialProps);
    }

    // finished
    private onCompleteHandler(): void {
        // one final update in case we jumped from 0.99 to 1.01 and skipped 1.0
        this.animationProps
            .updateCurrentPropsAtTime(1)
            .applyToInstance(this.instance);

        // and emit complete
        this.emit("complete");
        if (this.options?.onComplete) {
            this.options.onComplete();
        }
    }

    /**
     * Saved so that it can be resumed later
     * @returns 
     */
    public getIncompleteAnimationData(): (IIncompleteAnimationData & SaladJSONValue) | null {
        if(this.timer.isComplete()){
            return null;
        }
        else{
            const initialProps = this.animationProps.getInitialProps();
            return {
                props: this.props,
                settings: this.settings,
                delta: this.timer.getDelta(),
                options:   {
                    initialProps
                }
            };
        }
    }

    // kill this animation. Fires a killed event.
    public kill(): void {
        this.killed = true;
        this.emit("killed");
    }

    /** 
     * Set the delta of the animation. This is the time that has passed since the animation started
     * USed when restarting an animation
    */
    public setDelta(delta:number):void{
        this.timer.setDelta(delta);
    }
    
    
    /**
     * Tick the animation forward in time
     * @param time 
     * @returns 
     */
    public setCurrentTime(time: number): void {
        if(this.killed){
            // we have been killed, animation will have been stopped
            return;
        }

        this.timer.setCurrentTime(time)

        // now update the props if we need to
        if(this.timer.isComplete()){
            this.onCompleteHandler();
            return;
        }
        else if(!this.timer.isWaiting()){
            // wait until the delay is over
            if(this.timer.getHasRepeated()){
                this.animationProps.onRepeat();
            }
            
            // get the normalized time - from 0 to 1. This is the value of 't' in the animations
            const normalizedTime = this.timer.getNormalizedTime();
    
            // actually apply the props
            this.animationProps
                .updateCurrentPropsAtTime(normalizedTime)
                .applyToInstance(this.instance);
        }
    }
}

export const getInstanceAnimation = (
    instance: IInstance,
    props: AnimatableProps,
    settings: AnimationSettings,
    options?: AnimationOptions,
): IInstanceAnimation => {
    return new InstanceAnimation(instance, props, settings, options);
};
