import Salad from "../../index";
import { getPreloaderElement, IPreloaderElement } from "./PreloaderElement";

interface IActivityPreloader {
    preload(): Promise<void>;
}

type ActivityPreloaderOptions = {
    container: HTMLElement;
    assetManager: Salad.IAssetManager;
    pages: Salad.IPageData[];
    themeColor: string;
}

export class ActivityPreloader implements IActivityPreloader {
    private preloaderElement: IPreloaderElement | undefined;

    constructor(private options: ActivityPreloaderOptions) {
        this.onProgress = this.onProgress.bind(this);
    }

    private onProgress(progress: { value: number }) {
        this.preloaderElement!.update(progress.value)
    }

    private async preloadScripts() {
        const process = (scriptComp: {content?: string, transpiledCode?:string}) => {
            if(scriptComp.content){
                const transpiledCode = Salad.Utils.Code.transpileCode(scriptComp.content);
                scriptComp.transpiledCode = transpiledCode;
            }
        }
        this.options.pages.forEach((page: Salad.IPageData) => {
            if(page.schema.script){
                process(page.schema.script)
            }
            page.instances.forEach((instance: Salad.InstanceData) => {
                if(instance.schema.script){
                    process(instance.schema.script)
                }
            });
        });
    }

    private async preloadAssets() {
        this.options.assetManager.on("progress", this.onProgress);
        await this.options.assetManager.preload();
        this.options.assetManager.off("progress", this.onProgress);
        
    }

    // add a simple UI and wait for the asset resolver to load everything
    public async preload(): Promise<void> {
        this.preloaderElement = getPreloaderElement({themeColor: this.options.themeColor});
        this.options.container.appendChild(this.preloaderElement.element);

        await this.preloadScripts();
        await this.preloadAssets();

        this.preloaderElement.destroy();
        this.preloaderElement = undefined;
    }
}

export const getPreloader = (options: ActivityPreloaderOptions): IActivityPreloader => {
    return new ActivityPreloader(options);
};
