/**
 * UI buttons in play mode
 */
import { IPage } from "../../types/internal";
import { PageSchema } from "../../types/external";
import { getButton } from "./buttons/ButtonUtils";
import { ButtonName } from "../../types/internal";

export interface INavHandler {
    destroy(): void;
    setButtonEnabled(name: ButtonName, enabled: boolean): void;
    isButtonEnabled(name: ButtonName): boolean;
}

type PrevOrNextBehaviour = PageSchema["ui"]["prev"] | PageSchema["ui"]["next"]

class NavHandler implements INavHandler {
    // map name to actual button
    protected _button: HTMLElement;

    constructor(
        protected type: PrevOrNextBehaviour,
        protected buttonName: "prev" | "next",
        protected page: IPage,
    ) {
        this.onClick = this.onClick.bind(this);
        this.addButton();
    }

    private onClick(e: Event): void{
        e.stopPropagation();

        if (this.buttonName === "next") {
            if(this.type === "next"){
                this.page.navigation.gotoNextPage();
            }
            else if(this.type === "historynext"){
                this.page.navigation.historyForward();
            }
        }
        else if (this.buttonName === "prev") {
            if(this.type === "prev"){
                this.page.navigation.gotoPrevPage();
            }
            else if(this.type === "historyback"){
                this.page.navigation.historyBack();
            }
        }   
    }

    private addButton() {
        this._button = getButton(this.buttonName);
        const layerComp = this.page.getComponent("layers");
        layerComp.addChildToLayer(this._button, "ui");
        this._button.addEventListener("click", this.onClick);
    }

    public isButtonEnabled(name: ButtonName): boolean{
        if(this.buttonName !== name){
            return false;
        }
        const isDisabled = this._button.hasAttribute("disabled");
        return !isDisabled;
    }

    public setButtonEnabled(name: "prev" | "next", enabled: boolean): void {
        if(this.buttonName === name){
            if (enabled) {
                this._button.removeAttribute("disabled");
            }
            else {
                this._button.setAttribute("disabled", "disabled");
            }
        }
    }

    public destroy(): void {
        this._button.removeEventListener("click", this.onClick);
        this._button.remove();
    }
}


export const getHandler = (type: PrevOrNextBehaviour, buttonName: "prev" | "next", page: IPage): INavHandler => {
    return new NavHandler(type, buttonName, page);
};
