/**
 * Listen to all the relevant events on the page
 */

import { IActivity } from "../../types/internal";
import { ActivityMode } from "../../types/internal";
import { IActivityListeners } from "./AActivityListeners";
import { EditActivityListeners } from "./EditActivityListeners";
import { PlayActivityListeners } from "./PlayActivityListeners";

export const getListeners = (activity: IActivity, mode: ActivityMode): IActivityListeners => {
    return mode === "edit"
        ? new EditActivityListeners(activity)
        : new PlayActivityListeners(activity);
};
