/**
 * Abstract class for Lottie components
 */

import { ILottieComponent, ILottieAnimationItem, IInstance } from "../../types/external";
import { Schema } from "../../types/external";
import { IPage } from "../../types/internal";
import { AComponent } from "../AComponent";
import { lottieContainer } from "../../utils/domElementFactory";
import { CSSDomUpdate } from "../../types/external";

type ChildPosition = Schema["text"]["position"];

export default abstract class ALottieComponent
    extends AComponent<"lottie">
    implements ILottieComponent
{
    public name: "lottie" = "lottie";
    protected animationItemPromise: Promise<ILottieAnimationItem> | undefined;
    protected item: ILottieAnimationItem | undefined;
    protected _element: HTMLElement | undefined;

    constructor(data: Schema["lottie"], instance: IInstance, page: IPage) {
        super(data, instance, page);
    }

    override getDependencies() {
        return ["render"] as const;
    }

    override onCreated() {
        this.updateLottie();
    }

    /**
     * lifecycle
     */
    public override onDestroyed(): void {
        super.onDestroyed();
    }

    /**
     * On update, reset the lottie animation
     * @param data
     */
    override update(data: Schema["lottie"]): void {
        super.update(data);
        this.updateLottie();
    }

    public async setLoop(loop: boolean): Promise<void> {
        this.data.loop = loop;
    }

    public async playSegments(segment: [number, number]): Promise<void> {
        
    }

    public async play(frame?: number): Promise<void> {
        
    }

    public async stop(frame?: number): Promise<void> {
        
    }

    /**
     * Ppdate the source of the lottie animation
     * @param path
     */
    public updateSource(path: string) {
        if (this.data.path !== path) {
            this.data.path = path;
            this.updateLottie();
        }
    }

    public getPath(): string {
        return this.data.path;
    }

    public setChildPosition(pos: ChildPosition): void {
        this.data.position = pos;
        this._updatePosition();
    }

    public getChildPosition(): ChildPosition {
        return this.data.position;
    }

    private _updatePosition() {
        if(this._element){
            const css:CSSDomUpdate["css"] = {
                ...this.data.position   
            }
            this.page.getComponent("domupdate").addCSSUpdate({
                element: this._element,
                css
            })
        }
    }

    public getElement(): HTMLElement {
        return this._element!;
    }

    protected destroyLottie() {
        if (this._element) {
            this._element.remove();
            this._element = undefined;
        }
    }

    protected async updateLottie(): Promise<void>{
        this.destroyLottie();
        if (this.data.enabled) {
            const parent = this.getInstanceComponent("render").getElement();
            this._element = lottieContainer();
            parent.appendChild(this._element);
            await this.getOrMakeLottie();
            this._updatePosition();
        }
    }

    protected abstract getOrMakeLottie(): Promise<ILottieAnimationItem | undefined>;
}
