/**
 * Edit mode camera component
 * Shows a box illusrating the camera viewport
 */

import ACameraComponent from "./ACameraComponent";
import { Size, PageSchema } from "../../types/external";
import { IPage } from "../../types/internal";
import { cameraStartPositions } from "../../schema/pageSchema";
import { EditCameraBox, IEditCameraBox } from "./EditCameraBox";

type StartPosition = (typeof cameraStartPositions)[number];

export default class EditCameraComponent extends ACameraComponent {
    // used to show the camera viewport in edit mode
    private _cameraBox: IEditCameraBox;

    constructor(data: PageSchema["camera"], page: IPage) {
        super(data, page);
        this._cameraBox = new EditCameraBox(this.page);
        this.element.appendChild(this._cameraBox.element);
    }

    public override getEffectiveSize(): Size {
        const bgComp = this.page.getComponent("background");
        return bgComp.getSize();
    }

    public override onCreated(): void {
        super.onCreated();
        this.redrawBox();
    }

    public override setStartPosition(pos: StartPosition): void {
        super.setStartPosition(pos);
        this.redrawBox();
    }

    public override setSize(w: number | Size, h: number): void {
        super.setSize(w, h);
        this.redrawBox();
    }

    /**
     * redraw the camera box
     */
    protected redrawBox(): void {
        this._cameraBox.redraw();
    }
}
