/**
 * update the dom. Immediately in edit mode, using the render loop in play mode
 */
import { IPage, IDomUpdateComponent } from "../../types/internal";
import { PageSchema } from "../../types/external";
import { APageComponent } from "../APageComponent";
import { CSSDomUpdate } from "../../types/external";
import { applyCSS } from "./CSSApplication";
import { mergeCSS } from "./CSSMerge";

export abstract class ADomUpdateComponent extends APageComponent<"domupdate"> implements IDomUpdateComponent {
    
    public name: "domupdate" = "domupdate";
    protected updateMap: Map<HTMLElement, CSSDomUpdate> = new Map();
    protected appendCallbacks: (() => void)[] = [];
    
    constructor(data: PageSchema["domupdate"], page: IPage) {
        super(data, page);
    }
    
    public addCSSUpdate(update: CSSDomUpdate): void {
        const currentValue = this.updateMap.get(update.element);
        const merged = mergeCSS(currentValue?.css || {}, update.css);
        this.updateMap.set(update.element, {
            element: update.element,
            css: merged
        });
    }
    
    public addAppend(callback: () => void): void {
        this.appendCallbacks.push(callback);
    }
    
    protected flushCSS(): void {
        // Convert to array for faster iteration
        const updates = Array.from(this.updateMap);
        const updateCount = updates.length;
        for (let i = 0; i < updateCount; i++) {
            const [element, value] = updates[i];
            if (element) {
                applyCSS(element, value.css);
            }
        }    
        this.updateMap.clear();
    }
    
    protected flushAppend(): void {
        const callbacks = this.appendCallbacks;
        const count = callbacks.length;
        for (let i = 0; i < count; i++) {
            callbacks[i]();
        }
        this.appendCallbacks.length = 0;
    }
    
    public flush(): void {
        this.flushCSS();
        this.flushAppend();
    }
}