/**
 * Timers component.
 * Special component that manages timers and intervals
 */

import { ITimersComponent, IInstance, Schema } from "../../types/external";
import { IPage } from "../../types/internal";
import { AComponent } from "../AComponent";
import { Timer, Interval } from "./Timers";
import { IKillable } from "../../types/external";

export default class TimersComponent extends AComponent<"timers"> implements ITimersComponent {
    // list of timers
    _timers: Timer[] = [];

    // list of intervals
    _intervals: Interval[] = [];

    public name: "timers" = "timers";

    constructor(data: Schema["timers"], instance: IInstance, page: IPage) {
        super(data, instance, page);
    }

    public addTimeout(f: Function, duration: number): IKillable {
        const timer = new Timer(f, duration);
        this._timers.push(timer);
        return timer;
    }

    public addInterval(f: Function, duration: number): IKillable {
        const interval = new Interval(f, duration);
        this._intervals.push(interval);
        return interval;
    }

    //remove all
    public clearAll() {
        this._timers.forEach((timer: Timer) => {
            timer.kill();
        });
        this._timers = [];
        this._intervals.forEach((interval: Interval) => {
            interval.kill();
        });
        this._intervals = [];
    }

    public override onDestroyed(): void {
        this.clearAll();
        super.onDestroyed();
    }
}
