import { builtInFunctions } from "./BuiltInFunctions";

const functionCache = new Map<string, Function>();

export const getCompiledFunction = (expression: string): Function => {

    if (functionCache.has(expression)) {
        return functionCache.get(expression)!;
    }

    const __random_seed__ = Math.random();
    const jsCode = `
const __random_seed__ = ${__random_seed__};

${builtInFunctions}

// args
const { x, y, scaleX, scaleY, rotation, opacity } = arguments[1];
const t = arguments[0];

return ${expression};
`;

    const compiledFunction = new Function("evaluate", jsCode);
    functionCache.set(expression, compiledFunction);
    return compiledFunction;
};

