import AMovieClipComponent from "./AMovieClipComponent";
import Salad from "@root/salad";
export default class PlayMovieClipComponent extends AMovieClipComponent {

    private time:number | undefined = undefined;

    public override onCreated(): void {
        super.onCreated();
        this.onEnterFrame = this.onEnterFrame.bind(this);
        if(this.data.autoplay){
            this.addEnterFrameListener();
        }
        this.updateImage();
    }

    public override onDestroyed(): void {
        super.onDestroyed();
        this.removeEnterFrameListener();
    }

    private addEnterFrameListener(){
        this.page.events.on(Salad.Events.ENTER_FRAME, this.onEnterFrame);
    }

    private removeEnterFrameListener(){
        this.page.events.off(Salad.Events.ENTER_FRAME, this.onEnterFrame);
    }

    public override setSegmentStart(frame: number): void{
        this.data.segmentStart = frame;
        this.data.frame = Math.max(this.data.frame, frame);
        this.updateImage();
    }
    
    public override setSegmentEnd(frame: number): void{
        this.data.segmentEnd = frame;
        this.data.frame = Math.min(this.data.frame, frame);
        this.updateImage();
    }

    private onEnterFrame(eventData:Salad.PageEventsMap[typeof Salad.Events.ENTER_FRAME]){
        // first time we get a frame, set the time
        if(this.time === undefined){
            this.time = eventData.time;
        }

        // check if we need to update the frame - if the delta time is greater than the interval specified using fps
        const delta = eventData.time - this.time;
        const interval = 1000 / this.data.fps;
        if(delta >= interval){
            // update the frame so we can do the next one
            this.time = eventData.time;
            this.nextFrame();
        }
    }
}
