/**
 * Transitions allow the author to say that a page should fade out for example
 */

import { IPage } from "../../types/internal";
import { PageSchema } from "../../types/external";
import { gsap } from "gsap";
import { ConstructorOf } from "../../types/utils";

type AnimationType =
    | PageSchema["transitions"]["in"]["type"]
    | PageSchema["transitions"]["out"]["type"];

interface ITransition {
    play(): Promise<void>;
}

abstract class ATransition implements ITransition {
    constructor(
        protected duration: number,
        protected page: IPage,
    ) {}
    abstract play(): Promise<any>;

    reset(): void {
        // remove the effects of all transitions
        const el = this.page.getPageContainer();
        Object.assign(el, {
            opacity: 1,
            webkitFilter: "brightness(1)",
            filter: "brightness(1)",
        });
    }
}

class FadeInTransition extends ATransition implements ITransition {
    async play(): Promise<any> {
        const el = this.page.getPageContainer();
        el.style.opacity = "0";
        const options = {
            opacity: 1,
        };
        return gsap.to(el, options);
    }
}

class FadeOutTransition extends ATransition implements ITransition {
    async play(): Promise<any> {
        const el = this.page.getPageContainer();
        el.style.opacity = "1";
        const options = {
            opacity: 0,
        };

        return gsap.to(el, options);
    }
}

class FadeInFromBlackTransition extends ATransition implements ITransition {
    async play(): Promise<any> {
        const el = this.page.getPageContainer();
        return gsap.to(el, {
            webkitFilter: "brightness(1)",
            filter: "brightness(1)",
        });
    }
}

class FadeOutToBlackTransition extends ATransition implements ITransition {
    async play(): Promise<any> {
        const el = this.page.getPageContainer();
        return gsap.to(el, {
            webkitFilter: "brightness(0)",
            filter: "brightness(0)",
        });
    }
}

class NoneTransition extends ATransition implements ITransition {
    async play(): Promise<any> {
        // just reset it
        this.reset();
        return Promise.resolve();
    }
}

//TODO - not all done yet
const map: { [key in AnimationType]: ConstructorOf<ITransition, [number, IPage]> } = {
    fadein: FadeInTransition,
    fadeout: FadeOutTransition,
    fadeinfromblack: FadeInFromBlackTransition,
    fadeouttoblack: FadeOutToBlackTransition,
    none: NoneTransition,
};

// make a transtion
export const makeTransition = (type: AnimationType, duration: number, page: IPage): ITransition => {
    const Klass = map[type];
    return new Klass(duration, page);
};
