/**
 * This class is responsible for updating the props of the components at every frame of an animation
 */

import { AnimatableProps } from "../../types/external";
import { NumericAnimatedProps } from "../../schema/schema";
import Salad from "../../index";
import { getCompiledFunction } from "./CompiledAnimations";

export interface IAnimationProps{
    getInitialProps(): Partial<NumericAnimatedProps>
    updateCurrentPropsAtTime(time:number): this
    getCurrentProps(): Partial<NumericAnimatedProps>
    applyToInstance(instance: Salad.IInstance): void
    onRepeat(): void
}

export class AnimationProps implements IAnimationProps{
 
    /**
     * current props at the current value of 't' - x, y, scaleX, scaleY, rotation, opacity
     * use these to update the components themselves
     */
    private currentProps: Partial<NumericAnimatedProps> = {};
    
    // keys to update - perhaps just [x, y]
    private keysToUpdate: (keyof AnimatableProps)[];

    // eg. the user has written x-> 10 * sin(t/2) - compile it to a function so that we can easily execute it every frame
    private compiledFunctions: { [key in keyof AnimatableProps]: Function } = {};
    
    constructor(private props: AnimatableProps, private initialProps: Partial<NumericAnimatedProps>) {

        const keys = Object.keys(props) as (keyof AnimatableProps)[];

        // ones we are going to update (eg. if you only animate x position this will be ['x'])
        this.keysToUpdate = keys.filter((key) => {
            const val: string = this.props[key] as string;
            return typeof val === "string" && val.trim().length >= 1;
        }) as (keyof AnimatableProps)[];

        // compile the functions. Eg. x -> x + 50*t will animate 'x' from 100 to 150. Compile these strings into JS functions
        this.keysToUpdate.forEach((key) => {
            this.compiledFunctions[key] = getCompiledFunction(this.props[key] as string);
        });

        this.currentProps = {
            ...this.initialProps
        };
    }

    /**
     * When the animation repeats, we need to reset the current props to the initial props
     * Eg. in a jump animation after one jump has completed, we need to reset the initial props to the current props
     * so that the next jump starts from the current position not the very first position
     */
    public onRepeat(): void {
        this.updateCurrentPropsAtTime(1);
        this.initialProps = {
            ...this.initialProps,
            ...this.currentProps
        }
    }

    public getInitialProps(): Partial<NumericAnimatedProps> {
        return this.initialProps;
    }

    /**
     * execute the compiled functions to get the current props at a given time
     * @param time 
     * @returns 
     */
    public updateCurrentPropsAtTime(time:number): this {
        this.keysToUpdate.forEach((key) => {
            const fn = this.compiledFunctions[key]!;
            this.currentProps[key] = fn(time, this.initialProps);
        });
        return this;
    }

    /**
     * For testing only
     * @returns 
     */
    public getCurrentProps(): Partial<NumericAnimatedProps> {
        return this.currentProps;
    }

    
    /**
     * Get the value for a key. If the key is not present in the current props, return the initial props
     * Eg. if you are only animating 'x' then we return the new value of x and all the original values of y, scaleX, scaleY, etc.
     * @param key 
     * @returns 
     */
    private getValueForKey = (key: keyof AnimatableProps): number => {
        if (key in this.currentProps) {
            return this.currentProps[key] as number;
        }
        if (key in this.initialProps) {
            return this.initialProps[key] as number;
        }
        return 0;
    }

    /**
     * For each one, update the component
     * @param instance 
     */
    public applyToInstance(instance: Salad.IInstance): void {
        const posComp = instance.getComponent("position");
        const transformComp = instance.getComponent("transform");
        const renderComp = instance.getComponent("render");

        if (this.keysToUpdate.includes("x") || this.keysToUpdate.includes("y")) {
            const x = this.getValueForKey("x");
            const y = this.getValueForKey("y");
            const pos:Salad.Point = {
                x,
                y 
            };
            posComp!.setPosition(pos as Salad.Point);
        }

        if (this.keysToUpdate.includes("scaleX") || this.keysToUpdate.includes("scaleY")) {
            const scaleX = this.getValueForKey("scaleX");
            const scaleY = this.getValueForKey("scaleY");
            const scale = {
                x: scaleX,
                y: scaleY
            };
            transformComp!.setScale(scale);
        }

        if (this.keysToUpdate.includes("rotation")) {
            const rot = this.getValueForKey("rotation");
            transformComp!.setRotation(rot);
        }

        if (this.keysToUpdate.includes("opacity")) {
            const opacity = this.getValueForKey("opacity");
            renderComp!.setOpacity(opacity);
        }
    }

}


