import { getEventEmitter } from "./InstanceEventEmitter";
import {
    ComponentName,
    Schema,
    PartialSchema,
    IInstance,
    IInstanceEventEmitter,
    ComponentsMap,
} from "../types/external";
import { clone } from "../utils/utils";

class Instance implements IInstance {
    // event emitter
    private _events: IInstanceEventEmitter;

    // unique id
    private _id: string;

    // all the components for this instance
    private _componentsMap: Partial<ComponentsMap> = {};

    constructor(id: string) {
        this._events = getEventEmitter();
        this._id = id;
    }

    public destroy(): void {
        this._events.destroy();
        // override
    }

    public getName(): string {
        return this.getComponent("identity")!.getDisplayName();
    }

    public getId(): string {
        return this._id;
    }

    /**
     * Replace the entire components map
     * @param componentsMap
     */
    public setComponents(componentsMap: Partial<ComponentsMap>) {
        this._componentsMap = componentsMap;
    }

    /**
     * Get a map of all components
     * Eg. {render: RenderComponent, highlight: HighlightComponent}
     * @returns
     */
    public getComponents(): Partial<ComponentsMap> {
        return this._componentsMap;
    }

    // just a short version to save typing. Eg. this.getComponent("render") vs this.c.render
    public get c(): Partial<ComponentsMap> {
        return this._componentsMap;
    }

    /**
     * get a specific component
     * @param componentName
     * @returns
     */
    public getComponent<K extends ComponentName>(componentName: K): ComponentsMap[K] {
        return this._componentsMap[componentName] as ComponentsMap[K]; // we know it's not null
    }

    /**
     * get an event emitter
     */
    get events(): IInstanceEventEmitter {
        return this._events;
    }

    /**
     * Get the schema of the instance (the raw data)getData
     * @returns
     */
    public toSchema(): Schema {
        const schema: PartialSchema = {} satisfies PartialSchema;
        const components = this.getComponents();
        const keys: ComponentName[] = Object.keys(components) as ComponentName[];

        const setForKey = (k: ComponentName) => {
            const comp = components[k];
            schema[k] = comp!.getData();
        };

        keys.forEach(setForKey);
        return clone(schema) as Schema;
    }
}

/**
 * Makes a new (empty) instance
 * @param id
 * @returns
 */
export const getInstance = (id: string): IInstance => {
    return new Instance(id);
};
