/**
 * spawn component in play mode
 * on pointer down we spawn an instance
 */

import { Schema, ISpawnComponent, IInstance, Events } from "../../types/external";
import { IPage } from "../../types/internal";
import { InstanceEventsMap } from "../../types/external";
import { getSpawner } from "./Spawner";
import ASpawnComponent from "./ASpawnComponent";

export default class PlaySpawnComponent extends ASpawnComponent implements ISpawnComponent {

    constructor(data: Schema["spawn"], instance: IInstance, page: IPage) {
        super(data, instance, page);
        this.onPointerDown = this.onPointerDown.bind(this);
    }

    private onPointerDown(eventData: InstanceEventsMap[typeof Events.INSTANCE_POINTERDOWN]) {
        if (this.data.type !== "none") {
            // make a spawner
            getSpawner(this.data, this.instance, this.page).spawn(eventData.originalEvent);
        }
    }

    private _update() {
        if (this.data.type === "none") {
            this.removeListener();
        } else {
            this.addListener();
        }
    }

    private addListener() {
        this.instance.events.on(Events.INSTANCE_POINTERDOWN, this.onPointerDown);
    }

    private removeListener() {
        this.instance.events.off(Events.INSTANCE_POINTERDOWN, this.onPointerDown);
    }

    public override onCreated(): void {
        super.onCreated();
        this._update();
    }

    override onDestroyed() {
        super.onDestroyed();
        this.removeListener();
    }

    public override update(data: Schema["spawn"]): void {
        super.update(data);
        this._update();
    }
}
