/**
 * page layers component
 */
import { Size } from "../../../types/external";
import { IPage } from "../../../types/internal";
import { IPageLayer } from "./PageLayers";
import { PageSchema } from "../../../types/external";

type Box = PageSchema["camera"]["view"];

export abstract class APageLayer implements IPageLayer {
    constructor(
        public name: string,
        protected element: HTMLElement,
        protected page: IPage | undefined,
    ) {}

    public getElement(): HTMLElement {
        return this.element;
    }

    protected setLayerSize(size: Size): void {
        Object.assign(this.element.style, {
            width: `${Math.round(size.width)}px`,
            height: `${Math.round(size.height)}px`,
        });
    }

    /**
     * add a child
     * @param child
     */
    public add(child: HTMLElement) {
        this.element.appendChild(child);
    }

    /**
     * destroy the layer and remove all children
     */
    public destroy(): void {
        while (this.element.lastChild) {
            this.element.removeChild(this.element.lastChild!);
        }
        this.page = undefined;
    }

    // override this in each subclass to control how each layer is scaled and moved into the correct position
    public abstract showView(view: Box, globalScale: number): void;
}
