
import { IPage } from "../../types/internal";
import { PageSchema } from "../../types/external";
import { APageComponent } from "../APageComponent";
import {ISettingsComponent} from "../../types/internal";

export default class PageSettingsComponent
    extends APageComponent<"settings">
    implements ISettingsComponent
{
    public name: "settings" = "settings";

    constructor(data: PageSchema["settings"], page: IPage) {
        super(data, page);
    }

    public getSaveMethod(): "save" | "none"{
        return this.data.save;
    }

    public setSaveMethod(value: "save" | "none"): void{
        this.data.save = value;
    }

}
