/**
 * Position component
 */

import { IPositionComponent, IInstance } from "../../types/external";
import { Schema, Point } from "../../types/external";
import { IPage } from "../../types/internal";
import { AComponent } from "../AComponent";
import { PositionConstraints } from "./PositionConstraints";

export default class PositionComponent
    extends AComponent<"position">
    implements IPositionComponent
{
    public name: "position" = "position";

    constructor(data: Schema["position"], instance: IInstance, page: IPage) {
        super(data, instance, page);
    }

    override getDependencies() {
        return ["render"] as const;
    }

    override onCreated() {
        super.onCreated();
        this._updateElement();
    }

    /**
     * if there is a grid, round the position to the nearest grid point
     * @param size
     */
    public round(size: number): void {
        const pos = this.getPosition();
        this.setPosition({
            x: Math.round(pos.x / size) * size,
            y: Math.round(pos.y / size) * size,
        });
    }

    public getViewPosition(): Point {
        const pos = this.getPosition();
        const renderComponent = this.getInstanceComponent("render");
        if(renderComponent.getRenderLayer() === "hud"){
            const camera = this.page.getComponent("camera");
            const pos = this.getPosition();
            const view = camera.getView();
            return {
                x: pos.x + view.left,
                y: pos.y + view.top,
            };
        }
        else{
            return pos;
        }
    }

    public getGridPosition(round: boolean = false): Point{
        const grid = this.page.getComponent("grid");
        const size = grid.getGridSize();
        const pos = this.getPosition();
        if(round){
            return {
                x: Math.round(pos.x / size),
                y: Math.round(pos.y / size)
            };
        }
        else{
            return {
                x: pos.x / size,
                y: pos.y / size,
            };
        }
    }

    public setGridPosition(point: Point): void{
        const grid = this.page.getComponent("grid");
        const size = grid.getGridSize();
        this.setPosition({
            x: point.x * size,
            y: point.y * size,
        });
    }

    public goForward(distance: number): void {
        const directionFacing = this.instance.getComponent("transform").getDirectionFacing();
        this.increaseBy(
            distance * Math.cos((directionFacing * Math.PI) / 180),
            distance * Math.sin((directionFacing * Math.PI) / 180),
        );
    }

    public getPosition(): { x: number; y: number } {
        return {
            x: this.data.x,
            y: this.data.y,
        };
    }

    public override update(data: Schema["position"]) {
        super.update(data);
        this._updateElement();
    }

    /**
     * set the position.
     * @param point
     */
    public setPosition(point: Schema["position"]) {
        // this is where we want to move to
        let newPosition: Point | undefined = {
            ...this.data,
            ...point,
        } as Point;

        newPosition = new PositionConstraints(this.instance, this.page).applyConstraints(
            newPosition,
        );

        if (newPosition) {
            // actually update it
            this.data.x = newPosition.x;
            this.data.y = newPosition.y;
            this._updateElement();
        }
    }

    // increment the position by x/y
    public increaseBy(dx: number, dy: number): void {
        this.setPosition({
            x: this.data.x + dx,
            y: this.data.y + dy,
        });
    }

    /**
     * Get the position of 'p' relative to this object
     * Eg. If this.position is {150, 220} then the point {155, 230} is {5, 10} in local coordinates
     * @param p
     * @returns
     */
    public globalToLocal(p: Point): Point {
        const pos = this.getPosition();
        return {
            x: p.x - pos.x,
            y: p.y - pos.y,
        };
    }

    /**
     * eg. an instance is at 50,50 and has size 100,100
     * then 50, 50 -> 0,0
     * and 150,150 -> 1,1
     * @param p
     */
    public globalToLocalRelative(p: Point): Point {
        const pos = this.globalToLocal(p);
        const size = this.instance.getComponent("size").getSize();
        return {
            x: pos.x / size.width,
            y: pos.y / size.height,
        };
    }

    // put the element in the right place
    private _updateElement() {
        const renderComponent = this.getInstanceComponent("render");
        if (renderComponent) {
            const element = renderComponent.getElement();
            this.page.getComponent("domupdate").addCSSUpdate({
                element,
                css: {
                    left: `${this.data.x}px`,
                    top: `${this.data.y}px`,
                }
            })
        }
    }
}
