/**
 * Abstract camera component
 */
import { IPage } from "../../types/internal";
import { APageComponent } from "../APageComponent";
import { Point, Size, PageSchema, ICameraComponent } from "../../types/external";
import { cameraStartPositions } from "../../schema/pageSchema";
import { camera } from "../../utils/domElementFactory";
import { CameraTween, ICameraTween } from "./CameraTween";
import { CameraPanner } from "./CameraPanner";
import { CameraZoomer } from "./CameraZoomer";
import { ICameraPanner, ICameraZoomer } from "../../types/external";
import Salad from "../../index";

// where does the camera start (bottom-left, top-right, etc.)
type StartPosition = (typeof cameraStartPositions)[number];

const guard = (val: number, min: number, max: number) => Math.max(min, Math.min(max, val));

type Box = PageSchema["camera"]["view"];

export default abstract class ACameraComponent
    extends APageComponent<"camera">
    implements ICameraComponent
{
    public name: "camera" = "camera";

    // the tween that we use to move the camera
    private tween: ICameraTween | undefined;

    // an element which we just use to show the user the camera visible area
    protected element: HTMLElement;

    // handles panning around
    protected panner: ICameraPanner | undefined;

    // handles zooming
    protected zoomer: ICameraZoomer;

    constructor(data: PageSchema["camera"], page: IPage) {
        super(data, page);
        this.panner = new CameraPanner(this);
        this.zoomer = new CameraZoomer(this);
        this.element = camera();
    }

    public override onDestroyed(): void {
        super.onDestroyed();
        this.killTween();
        const layerComp = this.getPageComponent("layers");
        layerComp.removeLayer("camera");
        if(this.panner){
            this.panner.destroy();
            this.panner = undefined;
        }
    }

    /**
     * lifecycle
     * add a layer for the camera
     */
    public override onCreated(): void {
        super.onCreated();
        const layerComp = this.getPageComponent("layers");
        // add a layer for the camera
        layerComp.initLayer("camera", this.element, {
            type: "full",
        });
    }

    public override getDependencies() {
        return ["layout", "layers", "background"] as const;
    }

    /**
     * top-left, bottom-right etc
     * @returns
     */
    public getStartPosition(): StartPosition {
        return this.data.startPosition;
    }

    public setStartPosition(pos: StartPosition): void {
        this.data.startPosition = pos;
    }

    public getFollowName(): string {
        return this.data.follow.name;
    }

    public setFollowName(name: string): void {
        this.data.follow = {
            ...this.data.follow,
            name,
        };
    }

    /**
     * Zoom in and centre on an instance (if possible, never move the camera off the page)
     * @param instance 
     * @param zoom 
     */
    public zoomInOnInstance(instance: Salad.IInstance, zoom: number, duration?:number):void {
        const view = this.pan.getViewForCentreOnInstance(instance, zoom);
        this.moveToView(view, duration);
    }

    public zoomInOnInstanceName(name: string, zoom: number, duration?:number): void {
        const instance = this.page.getComponent("instances").getInstanceByName(name);
        if (instance) {
            this.zoomInOnInstance(instance, zoom, duration);
        }
    }
    
    public resetZoom(): void {
        this.zoom.setZoom(1);
    }

    /**
     * how fast does the camera scroll?
     * @param value
     */
    public setPanDuration(value: number): void {
        this.data.duration = value;
    }

    public getPanDuration(): number {
        return this.data.duration;
    }

    public setDeadZone(value: number): void {
        this.data.follow = {
            ...this.data.follow,
            deadZone: value,
        };
    }

    public getDeadZone(): number {
        return this.data.follow.deadZone;
    }

    public getSize(): Size {
        return this.data.size;
    }

    public getEffectiveSize(): Size {
        return this.data.size;
    }

    /**
     * Set the size (the viewable area)
     * If the first argument is a number, it will be the width, and the second argument will be the height
     * If the first argument is a Size object, it will use that
     * @param w
     * @param h
     */
    public setSize(w: number | Size, h: number): void {
        if (typeof w === "number") {
            this.data.size = {
                width: w,
                height: h,
            };
        } else {
            this.data.size = {
                width: w.width,
                height: w.height,
            };
        }
    }

    private killTween(): void {
        if (this.tween) {
            this.tween.destroy();
            this.tween = undefined;
        }
    }

    /**
     * Move using a tween
     * @param p
     */
    public moveToView(view: Box, duration?: number) {

        this.killTween();

        // use the duration specified or the default one in the schema
        duration = typeof duration === "number" ? duration : this.data.duration;

        if (duration === 0) {
            // just do it immediately
            this.setView(view);
        } else {
            // tween it, calling 'setView' each frame
            this.tween = new CameraTween(this, view, duration);
            this.tween.play();
        }
    }

    /**
     * Eg. camera width is 800, view width is 400 -> zoom must be ×2
     * @returns
     */
    public getZoom(): number {
        const scaleX = this.data.size.width / this.data.view.width;
        const scaleY = this.data.size.height / this.data.view.height;
        return (scaleX + scaleY) / 2;
    }

    public get pan() {
        return this.panner!;
    }

    public get zoom() {
        return this.zoomer;
    }

    /**
     * do we have any scrolling?
     * @returns
     */
    public hasXScroll(): boolean {
        const bgComp = this.getPageComponent("background");
        const bgSize = bgComp.getSize();
        return this.data.view.width < bgSize.width;
    }

    public hasYScroll(): boolean {
        const bgComp = this.getPageComponent("background");
        const bgSize = bgComp.getSize();
        return this.data.view.height < bgSize.height;
    }

    public canScrollLeft(): boolean {
        return this.data.view.left > 0;
    }

    public canScrollRight(): boolean {
        const bgComp = this.getPageComponent("background");
        const bgSize = bgComp.getSize();
        return this.data.view.left + this.data.view.width < bgSize.width;
    }

    public canScrollUp(): boolean {
        return this.data.view.top > 0;
    }

    public canScrollDown(): boolean {
        const bgComp = this.getPageComponent("background");
        const bgSize = bgComp.getSize();
        return this.data.view.top + this.data.view.height < bgSize.height;
    }

    /**
     * Eg. 0,0 means the top left of the current viewport, 1,1 means the bottom
     * @param instance
     * @returns
     */
    public getPositionRelativeToCamera(pos: Point): Point {
        const view = this.getView();

        return {
            x: (pos.x - view.left) / view.width,
            y: (pos.y - view.top) / view.height,
        };
    }

    /**
     * Set the viewport
     * @param p
     */
    public setView(box: Box) {

        const bgComp = this.getPageComponent("background");
        const bgSize = bgComp.getSize();
        const minLeft = 0;
        const maxLeft = bgSize.width - box.width;
        const minTop = 0;
        const maxTop = bgSize.height - box.height;

        const guardedView = {
            ...box,
            left: guard(box.left, minLeft, maxLeft),
            top: guard(box.top, minTop, maxTop),
        };
        this.data.view = {
            ...guardedView,
        };
    }

    /**
     * Get the offset in pixels
     * @returns
     */
    public getView(): Box {
        return this.data.view;
    }
}
