/**
 * Transitions allow the author to say that a page should fade out for example
 */

import { IPage, ITransitionsComponent } from "../../types/internal";
import { APageComponent } from "../APageComponent";
import { PageSchema } from "../../types/external";
import { makeTransition } from "./TransitionsFactory";

export default class TransitionsComponent
    extends APageComponent<"transitions">
    implements ITransitionsComponent
{
    public name: "transitions" = "transitions";

    constructor(data: PageSchema["transitions"], page: IPage) {
        super(data, page);
    }

    /**
     * Play
     * @param direction - in or out
     * @returns
     */
    public async playTransition(direction: keyof PageSchema["transitions"]) {
        const data = this.data[direction];
        const trans = makeTransition(data.type, data.duration, this.page);
        return trans.play();
    }

    public getTranstionIn(): PageSchema["transitions"]["in"]["type"] {
        return this.data.in.type;
    }

    public getTranstionOut(): PageSchema["transitions"]["out"]["type"] {
        return this.data.out.type;
    }

    public setTranstionIn(type: PageSchema["transitions"]["in"]["type"]): void {
        this.data.in = {
            ...this.data.in,
            type,
        };
    }

    public setTranstionOut(type: PageSchema["transitions"]["out"]["type"]): void {
        this.data.out = {
            ...this.data.out,
            type,
        };
    }
}
