/**
 * Image component - displays an image
 */

import { IImageComponent, IInstance } from "../../types/external";
import { Schema } from "../../types/external";
import { IPage } from "../../types/internal";
import { AComponent } from "../AComponent";
import { image } from "../../utils/domElementFactory";
import { CSSDomUpdate } from "../../types/external";

type ChildPosition = Schema["text"]["position"];

export default class ImageComponent extends AComponent<"image"> implements IImageComponent {
    // the actual image element
    private element: HTMLImageElement | undefined;

    public name: "image" = "image";

    constructor(data: Schema["image"], instance: IInstance, page: IPage) {
        super(data, instance, page);
    }

    override getDependencies() {
        return ["render"] as const;
    }

    public getElement(): HTMLImageElement | undefined {
        return this.element;
    }

    public override onDestroyed(): void {
        this._destroyImage();
        super.onDestroyed();
    }

    public override onCreated() {
        super.onCreated();
        this._update();
    }

    private _destroyImage() {
        if (this.element) {
            this.element.remove();
            this.element = undefined;
        }
    }

    private _updatePosition() {
        const css:CSSDomUpdate["css"] = {
            ...this.data.position   
        }
        this.page.getComponent("domupdate").addCSSUpdate({
            element: this.element!,
            css
        })
    }

    private async addImage(): Promise<void> {
        const parent = this.getInstanceComponent("render").getElement();
        if(!parent){
            return 
        }
        if(!this.element){
            this.element = image(parent);
        }
        const assetManager = this.getAssetManager();
        const src = await assetManager.getPathForKey(this.data.path);

        if(this.element){
            // it could have been destroyed in the meantime
            assetManager.loadImg(this.element, src);
            this._updatePosition();
            this._updateShadow();
        }
    }

    // some special stuff for builderstray
    private async _updateShadow(): Promise<void>{
        const parent = this.getInstanceComponent("render").getElement();
        if(!parent){
            return
        }
        const assetManager = this.getAssetManager();
        const resolvedPath = await assetManager.getPathForKey(this.data.path);
        if(this.data.shadow !== "none"){
            parent.classList.add("instance-shadow-" + this.data.shadow);
            parent.style.setProperty('--background-image', `url(${resolvedPath})`);
            parent.style.removeProperty('contain');
        }
        else{
            parent.classList.remove("instance-shadow-large");
            parent.classList.remove("instance-shadow-small");
            parent.style.setProperty('--background-image', `none`);
        }
    }

    private _update() {
        if (this.data.enabled) {
            this.addImage();
        }
        else{
            this._destroyImage();
        }
    }

    public override update(data: Schema["image"]): void {
        super.update(data);
        this._update();
    }

    public setPath(path: string) {
        this.data.path = path;
        this._update();
    }

    public getPath(): string {
        return this.data.path;
    }

    public setChildPosition(pos: ChildPosition): void {
        this.data.position = pos;
        this._updatePosition();
    }

    public getChildPosition(): ChildPosition {
        return this.data.position;
    }
}
