/**
 * Camera tween using gsap
 */

import { gsap } from "gsap";
import { ICameraComponent } from "../../types/external";
import { PageSchema } from "../../types/external";

type Box = PageSchema["camera"]["view"];

export interface ICameraTween {
    play(): void;
    destroy(): void;
}

const lerp = (from: number, to: number, t: number) => from + (to - from) * t;

export class CameraTween implements ICameraTween {
    private tween: ReturnType<typeof gsap.to> | undefined; 

    constructor(
        private component: ICameraComponent,
        private view: Box,

        //seconds
        private duration: number,
    ) {}
    public play(): void {
        // object that we tween, from time = 0 to time = 1
        const data = {
            time: 0,
        };

        const currentView = this.component.getView();

        // initial values
        const left0 = currentView.left;
        const top0 = currentView.top;
        const width0 = currentView.width;
        const height0 = currentView.height;

        const getView = (t: number) => {
            // get the new values at time 't' (lerp)
            return {
                ...currentView,
                left: lerp(left0, this.view.left, t),
                top: lerp(top0, this.view.top, t),
                width: lerp(width0, this.view.width, t),
                height: lerp(height0, this.view.height, t)
            };
        };

        const onUpdate = () => {
            const view = getView(data.time);
            this.component.setView(view);
        };

        const options = {
            time: 1,
            //seconds
            duration: this.duration,
            onUpdate,
        };

        this.tween = gsap.to(data, options);
    }
    public destroy(): void {
        if (this.tween) {
            this.tween.kill();
            this.tween = undefined;
        }
    }
}
