import EventEmitter from "events";
import UnlockAudioContextHelper from "./UnlockAudioContextHelper";

const base64regex = /^data:audio\/[a-z0-9]+;base64,/;

const isUndefined = val => typeof val === "undefined";
const isString = val => typeof val === "string";

function isBase64Audio(source) {
    return base64regex.test(source);
}

export default class {
    constructor(sequencer) {
        this.onSoundLoaded = this.onSoundLoaded.bind(this);
        this.unlockAudioContext = new UnlockAudioContextHelper();
        this.eventBus = new EventEmitter();
        this.sequencer = sequencer;
    }

    init() {
        this.queue = [];
        this.context = this.sequencer.options.context || null;
        this.decodeRequests = 0;
        this.soundBuffers = {};
        this.soundsPlaying = [];
        this.unlockWindows = [window];
        this._createAudioContext();
        this.dispatchEvent("ready");
        this.tick();
    }

    dispatchEvent(event, eventParams) {
        this.eventBus.emit(event, eventParams);
    }

    addEventListener(event, callback) {
        this.eventBus.on(event, callback);
    }

    _createAudioContext() {
        if (this.context === null) {
            window.AudioContext = window.AudioContext || window.webkitAudioContext;
            this.context = new AudioContext();
            console.log("Creating audio context");
        } else {
            console.log("Audio context already exists");
        }
        this.unlocked = false;
        this.context = this.context;
        this.addUnlockEventsToWindow(window);
        this.unlockAudioContext.setContext(this.context);
        this.gainNode = this.context.createGain();
        this.gainNode.connect(this.context.destination);
    }

    /**
     * Adds events to a window to detect a mouse down (or touch start) and play a silent sounds to unlock audio
     * @param unlockWindow
     */
    addUnlockEventsToWindow(unlockWindow) {
        this.unlockAudioContext.addUnlockEventsToWindow(unlockWindow);
    }
    tick() {
        const isFirefox = typeof InstallTrigger !== "undefined"; // Firefox 1.0+

        if (isFirefox) {
            // fire fox we use an oscillator rather than a setInterval for a ticker as its more reliable
            const source = this.context.createOscillator();
            source.connect(this.context.destination);
            const onEnded = () => {
                // Replace _(this.sequencer.tickers).each with forEach
                this.sequencer.tickers.forEach(function(ticker) {
                    ticker.call();
                }, this);
                this.tick();
            };
            source.onended = onEnded;
            const gainNode = this.context.createGain();
            source.connect(gainNode);
            gainNode.connect(this.context.destination);
            gainNode.gain.value = -1;
            source.start(this.context.currentTime);
            source.stop(this.context.currentTime + 0.001);
        } else {
            setInterval(() => {
                this.sequencer.tickers.forEach(ticker => {
                    if(ticker) {
                        ticker.call();
                    }
                });
            }, 10);
        }
    }
    onSoundLoaded(id, buffer) {
        if (this.sequencer.options.onTheFlyDecode) {
            this.soundBuffers[id] = buffer;
            this.dispatchEvent("fileload", {
                id
            });
        } else {
            this.decodeSound(
                {
                    buffer: buffer,
                    id: id,
                },
                function (params) {
                    this.soundBuffers[id] = params.decodedBuffer;
                    this.dispatchEvent("fileload", {
                        id
                    });
                },
            );
        }
    }
    preloadSound(source, id) {
        if (!id) {
            id = source;
        }
        if (isBase64Audio(source)) {
            const soundSrc = source.replace(base64regex, "");
            const arrayBuff = Base64Binary.decodeArrayBuffer(soundSrc);
            this.onSoundLoaded(id, arrayBuff);
        } else {
            const request = new XMLHttpRequest();
            request.open("GET", source, true);
            request.responseType = "arraybuffer";
            request.onload = () => {
                this.onSoundLoaded(id, request.response);
            };
            request.send();
        }
    }
    onError() {
        alert("Error decoding buffer");
    }
    scheduleSound(params) {
        this.queue.push(params);
        this.decodeSound(params);
        return params;
    }
    onDecodeComplete(fn) {
        if (this.decodeRequests === 0) {
            fn();
        } else {
            const onDecode = () => {
                this.removeEventListener("decode-complete", onDecode);
                fn();
            };
            this.addEventListener("decode-complete", onDecode);
        }
    }
    removeEventListener(event, callback) {
        this.eventBus.off(event, callback);
    }
    mute() {
        this.gainNode.gain.value = 0;
    }
    unmute() {
        this.gainNode.gain.value = 1;
    }
    decodeSound(params, onComplete) {
        if (
            !this.sequencer.options.onTheFlyDecode &&
            !params.buffer &&
            params.id &&
            this.soundBuffers[params.id]
        ) {
            // on the fly decoding is not enabled so the sound contains the decoded buffer already
            params.decodedBuffer = this.soundBuffers[params.id];
        }

        const onFinishDecode = () => {
            this.decodeRequests--;
            console.log(
                "Decoded audio: " + params.id + " decode requests count: " + this.decodeRequests,
            );
            if (onComplete) {
                onComplete.apply(this, [params]);
            }
            if (this.decodeRequests === 0) {
                this.dispatchEvent("decode-complete");
            }
        };

        if (isUndefined(params.decodedBuffer)) {
            this.decodeRequests++;

            if (!params.buffer && params.id && isUndefined(this.soundBuffers[params.id])) {
                console.log("Sound sequencer error: buffer does not exist for " + params.id);
                params.decodedBuffer = this.unlockAudioContext.getSilentBuffer();
                onFinishDecode();
            } else {
                let buffer = params.buffer ? params.buffer : this.soundBuffers[params.id];
                // we need to clone the buffer before decoding - now in all browsers, used to be just FireFox
                const dst = new ArrayBuffer(buffer.byteLength);
                new Uint8Array(dst).set(new Uint8Array(buffer));
                buffer = dst;

                this.context.decodeAudioData(
                    buffer,
                    (buffer) => {
                        params.decodedBuffer = buffer;
                        onFinishDecode();
                    },
                    (buffer) => {
                        console.log("Sound sequencer error: buffer decode error for " + params.id);
                        onFinishDecode();
                    },
                );
            }
        } else {
            // its already decoded - we just call complete function
            if (onComplete) {
                onComplete.apply(this, [params]);
            }
        }
    }
    playSound(params) {
        if (params.stopPrevious) {
            this.soundsPlaying.forEach((sound) => {
                if (sound.id === params.id) {
                    this.stopSound(sound);
                }
            })
        }
        this.decodeSound(params, () => {
            if (params.stopped) {
                return;
            }
            this.soundsPlaying.push(params);

            const source = this.context.createBufferSource(); // creates a sound source
            source.buffer = params.decodedBuffer; // tell the source which sound to play
            source.loop = params.loop;
            source.onended = () => {
                if (params.ended) {
                    params.ended();
                }
                this.soundsPlaying = this.soundsPlaying.filter(function(sound) {
                    return source !== sound.source;
                });
            };

            const delay = Math.max(0, params.delay) / 1000;
            source.start(this.context.currentTime + delay, params.offset);

            const gainNode = this.context.createGain();
            source.connect(gainNode);
            gainNode.connect(this.gainNode);
            if (!isUndefined(params.volume)) {
                gainNode.gain.value = params.volume;
            }
            params.context = this.context;
            params.gainNode = gainNode;
            params.source = source;
        });
        return params;
    }
    stopSound(sound, fadeOutTime) {
        if (isString(sound)) {
            const soundId = sound;
            sound = this.soundsPlaying.find(function (soundPlaying) {
                return soundPlaying.id === soundId;
            });
            if (!sound) {
                console.log("Cannot stop sound, soundId is not playing", soundId);
                return;
            }
        }
        if (sound.source) {
            try {
                if (fadeOutTime) {
                    const gainNode = sound.gainNode;
                    gainNode.gain.linearRampToValueAtTime(
                        0,
                        this.context.currentTime + fadeOutTime,
                    );
                    const _this = this;
                    setTimeout(
                        function () {
                            _this.stopSound(sound);
                        },
                        Math.ceil(fadeOutTime * 1000),
                    );
                } else {
                    // iOS8 sometimes crashes here
                    sound.source.stop(this.context.currentTime);
                }
            } catch (e) {
                console.error(e);
            }
        }
        sound.stopped = true;
    }
    stopSoundLooping(sound) {
        if (typeof sound === "string") {
            sound = this.soundsPlaying.find((soundPlaying) => {
                return soundPlaying.id === sound;
            })
        }
        if (sound) {
            if (sound.source) {
                sound.source.loop = false;
            }
            sound.loop = false;    
        }
    }
    start() {
        if (!this.started) {
            console.log("SOUND SEQUENCER STARTED");
            this.started = true;
            this.startTime = 0;
            const _this = this;
            _this.onDecodeComplete(function () {
                _this.startTime = new Date().getTime();
                _this.queue.forEach(function(queuedItem) {
                    queuedItem.sound = _this.playSound(queuedItem);
                });
            });
        }
    }
    stop() {
        console.log("SOUND SEQUENCER STOPPED");

        this.queue.forEach(function(queuedItem) {
            if (queuedItem.sound) {
                this.stopSound(queuedItem.sound);
            }
        }, this);
        
        this.queue = [];
        this.soundsPlaying.forEach(function(sound) {
            try {
                sound.source.stop(this.context.currentTime);
            } catch (e) {}
        }, this);

        this.started = false;
        this.stopTime = new Date().getTime();
    }
    getTimeSinceStarted() {
        if (this.started && this.startTime > 0) {
            return new Date().getTime() - this.startTime;
        } else {
            return 0; //this.stopTime - this.startTime;
        }
    }
}