import AGridComponent from "./AGridComponent";
import { Events } from "../../types/external";
import { PageEventsMap, IGridComponent } from "../../types/external";

export default class EditGridComponent extends AGridComponent implements IGridComponent {

    public override onCreated() {
        super.onCreated();
        this.onInstanceCreated = this.onInstanceCreated.bind(this);
        this.page.events.on(Events.INSTANCE_CREATED, this.onInstanceCreated);
    }

    public override onDestroyed(): void {
        super.onDestroyed();
        this.page.events.off(Events.INSTANCE_CREATED, this.onInstanceCreated);
    }

    /**
     * When any instance is created, snap to the grid
     * @param eventData
     */
    private onInstanceCreated(eventData: PageEventsMap[typeof Events.INSTANCE_CREATED]): void {
        if (this.data.snap) {
            const posComp = eventData.target.getComponent("position");
            posComp.round(this.getGridSize());
        }
    }
}
