import { DrawingToolSetting } from "../../types/external";
import { IAssetManager } from "@root/salad/types/internal";

const IMAGE_SIZE = 128;

export const getCursorInfoForTool = async (toolSetting: DrawingToolSetting, assetManager: IAssetManager): Promise<{path:string, offset:[number, number]}> => {

    const tool = toolSetting.tool;
    const handedness = toolSetting.options.handedness;

    // find the right origin for each cursor image
    const getOffset = (): [number, number] => {
        if(tool === "mouse") {
            return [0, 0];
        }
        // all images should be 128x128
        else if (tool === "rake") {
            // draw from near the middle
            return [35, 30];
        }
        else if (tool === "eraser") {
            return [32, 120];
        }
        else if (["pen", "pencil", "chalk", "stick"].includes(tool)) {
            // draw from the bottom-left
            return [8, 115];
        }
        // default - middle
        return [64, 64];
    };

    const getCursorPath = async(): Promise<string> => {
        if(tool === "mouse") {
            return "";
        }
        else{
            const imgName = handedness === "left" ? `${tool}_left` : tool;
            let key: string;
            let src: string;
            if (["rake", "eraser", "stick"].includes(tool)) {
                key = `cursor_${imgName}`;
                src = `/builderstray/tools/cursors/${imgName}.png`;
            }
            else {
                key = `cursor_${imgName}_${toolSetting.options.colorName}`;
                src = `/builderstray/tools/cursors/colors/${imgName}_${toolSetting.options.colorName}.png`;
            }

            if(!assetManager.hasKey(key)){
                assetManager.add(key, {
                    src,
                    type: "image",
                    contentType: "image/png"
                });
            }

            return key;
        }
    };

    const path = await getCursorPath();
    const offset = getOffset();

    if(handedness === "left") {
        offset[0] = IMAGE_SIZE - offset[0];
    }

    return {
        path,
        offset,
    };
};
