import Salad from "../index";
import { PlayActivityTransitionsComponent } from "./activitydecorators/transitions/PlayActivityTransitionsComponent";
import { PlayActivityUIComponent } from "./activitydecorators/ui/PlayActivityUIComponent";
import { PlayActivityHistoryComponent} from "./activitydecorators/history/PlayActivityHistoryComponent";
import { PlayActivitySettingsComponent } from "./activitydecorators/settings/PlayActivitySettingsComponent";
import { ActivityDataComponent } from "./activitydecorators/data/ActivityDataComponent";
import { ActivityCSSComponent } from "./activitydecorators/css/ActivityCSSComponent";
import { PlayActivityInfoComponent } from "./activitydecorators/info/PlayActivityInfoComponent";
import { ActivityLoggerComponent } from "./activitydecorators/log/ActivityLoggerComponent";
import { PlayActivityPagesComponent } from "./activitydecorators/pages/PlayActivityPagesComponent";
import { ActivityBackupComponent } from "./activitydecorators/backup/ActivityBackupComponent";
import { EditActivityHistoryComponent } from "./activitydecorators/history/EditActivityHistoryComponent";
import { EditActivityInfoComponent } from "./activitydecorators/info/EditActivityInfoComponent";
import { EditActivitySettingsComponent } from "./activitydecorators/settings/EditActivitySettingsComponent";
import { EditActivityTransitionsComponent } from "./activitydecorators/transitions/EditActivityTransitionsComponent";
import { EditActivityUIComponent } from "./activitydecorators/ui/EditActivityUIComponent";
import { EditActivityPagesComponent } from "./activitydecorators/pages/EditActivityPagesComponent";
import { ActivityScriptComponent } from "./activitydecorators/script/ActivityScriptComponent";
import { ActivityPreloaderComponent } from "./activitydecorators/preloader/ActivityPreloaderComponent";
import { ActivityFontsComponent } from "./activitydecorators/fonts/ActivityFontsComponent";
import { EditActivityPersistenceComponent } from "./activitydecorators/persistence/EditActivityPersistenceComponent";
import { PlayActivityPersistenceComponent } from "./activitydecorators/persistence/PlayActivityPersistenceComponent";
import { ActivityOptions } from "../types/internal";
import { ActivityMode, MapActivityComponentNameToClass, IActivityComponentFactory} from "../types/internal";
import { ActivityComponentsMap, ActivityComponentName } from "../types/internal";

const defaultMap:MapActivityComponentNameToClass = {
    data:           ActivityDataComponent,
    css:            ActivityCSSComponent,
    backup:         ActivityBackupComponent,
    logger:         ActivityLoggerComponent,
    script:         ActivityScriptComponent,
    preloader:      ActivityPreloaderComponent,
    fonts:          ActivityFontsComponent,
}

const editMap:MapActivityComponentNameToClass = {
    ...defaultMap,
    transitions:    EditActivityTransitionsComponent,
    ui:             EditActivityUIComponent,
    history:        EditActivityHistoryComponent,
    settings:       EditActivitySettingsComponent,
    info:           EditActivityInfoComponent,
    pages:          EditActivityPagesComponent,
    persistence:    EditActivityPersistenceComponent
}

const playMap:MapActivityComponentNameToClass = {
    ...defaultMap,
    transitions:    PlayActivityTransitionsComponent,
    ui:             PlayActivityUIComponent,
    history:        PlayActivityHistoryComponent,
    settings:       PlayActivitySettingsComponent,
    info:           PlayActivityInfoComponent,
    pages:          PlayActivityPagesComponent,
    persistence:    PlayActivityPersistenceComponent
}

class ActivityComponentFactory implements IActivityComponentFactory{

    constructor(private map: MapActivityComponentNameToClass){

    }
    
    public buildAllActivityComponents(activity: Salad.IActivity, options: ActivityOptions):ActivityComponentsMap{
        const keys = Object.keys(this.map) as ActivityComponentName[];
        const components = {} as ActivityComponentsMap;
        keys.forEach(key => {
            const Klass = this.map[key];
            //@ts-ignore
            components[key] = new Klass(activity, options);
        });
        return components;
    }
}

export const getComponentFactory = (mode: ActivityMode): IActivityComponentFactory => {
    const map = mode === "edit" ? editMap : playMap;
    return new ActivityComponentFactory(map);
}