/**
 * Simple cache for canvases, for re-use when we use the chalk tool for example
 */

import Salad from "../../../..";
import { generateNoiseWithColor } from "./ChalkNoise";

export class CanvasCache {
    private canvasCache: { [key: string]: HTMLCanvasElement[] } = {};

    constructor(
        private numCanvases: {
            drawing?: number;
            chalk?: number;
        },
    ) {}

    public get(
        name: "drawing" | "chalk",
        options: {
            w: number;
            h: number;
            fill?: string;
        },
    ): HTMLCanvasElement {
        //cache key
        const key = `${name}_${options.w}_${options.h}_${options.fill || ""}`;

        const numCanvases = this.numCanvases[name] || 0;

        if (this.canvasCache[key] && this.canvasCache[key].length >= numCanvases) {
            // array is 'full
            return Salad.Utils.getRandomChoice(this.canvasCache[key]);
        }
        else {
            // add another canvas and return it
            const canvas = document.createElement("canvas");
            canvas.width = options.w;
            canvas.height = options.h;

            if (options.fill) {
                generateNoiseWithColor(canvas, options.fill);
            }

            if (!this.canvasCache[key]) {
                this.canvasCache[key] = [];
            }
            this.canvasCache[key].push(canvas);

            return canvas;
        }
    }
}
