
import { Schema, IInstance } from "../../types/external";
import { IPage } from "../../types/internal";
import ASelectComponent from "./ASelectComponent";

export default class PlaySelectComponent extends ASelectComponent {
    constructor(data: Schema["select"], instance: IInstance, page: IPage) {
        super(data, instance, page);
        this.onChange = this.onChange.bind(this);
    }

    override update(data: Schema["select"]): void {
        // nothing
    }

    private onChange(event: Event): void {
        const target = event.target as HTMLSelectElement;
        this.data.selectedValue = target.value;
    }

    protected override _redrawUI(): void {
        super._redrawUI();
        if (this.data.enabled) {
            this._select!.addEventListener("change", this.onChange);
        }
    }
}
