/**
 * PageComponentFactory - builds all the components for a page
 */

import {
    IPage,
    ConstructorOfPageComponent,
    MapPageComponentNameToClass,
    IPageComponentFactory,
    PageComponentsMap,
} from "../types/internal";
import { PageComponentName, PageSchema, allPageComponentNames } from "../types/external";

class PageComponentFactory implements IPageComponentFactory {
    private mapComponentNameToClass: Partial<MapPageComponentNameToClass>;
    
    constructor(map: Partial<MapPageComponentNameToClass>) {
        this.mapComponentNameToClass = map;
    }
    public buildAllPageComponents(values: PageSchema, page: IPage): PageComponentsMap {
        const pageComponentsMap: Partial<PageComponentsMap> = {};

        const map = this.mapComponentNameToClass;

        allPageComponentNames.forEach(<K extends PageComponentName>(key: K) => {
            if (key in map) {
                const ClassRef: ConstructorOfPageComponent<K> = map[key] as ConstructorOfPageComponent<K>;
                if(ClassRef){
                    pageComponentsMap[key] = new ClassRef(values[key], page);
                }
            }
        });
        return pageComponentsMap as PageComponentsMap;
    }

    public merge(componentsMap: MapPageComponentNameToClass):void{
        Object.assign(this.mapComponentNameToClass, componentsMap);
    }
}

export const createPageComponentFactory = (map: Partial<MapPageComponentNameToClass>) => {
    return new PageComponentFactory(map);
}