import Salad from "../../../index";
import { IActivityComponent } from "../../../types/external";
import { AActivityComponent } from "../AActivityComponent";

type ChangePageData = Salad.PageEventsMap[typeof Salad.Events.CHANGE_PAGE]

export interface IActivityHistoryComponent extends IActivityComponent{
    getHistory(): Salad.ActivityHistory
    updateForChange(data: ChangePageData, pageIndex:number, pageId: string): void
    peekUsingChange(step: 1 | -1): string
    getCurrentPageId(): string
    destroy(): void
}

export class PlayActivityHistoryComponent extends AActivityComponent implements IActivityHistoryComponent{

    private history: Salad.ActivityHistory;

    constructor(private activity: Salad.IActivity, private options: Salad.ActivityOptions) {
        super();
        
        const pageIds = options.pages[0] ? [
            options.pages[0].id
        ] : [];


        this.history = options.history || {
            index: 0, // index in the pageIds array
            pageIds
        }
    }

    public getHistory(): Salad.ActivityHistory {
        return this.history;
    }

    /**
     * wipe the upcoming history and add a new page id
     * @param id 
     */
    private push(id: string) {
        // remove all the pages after the current index
        const newIds = this.history.pageIds.slice(0, this.history.index + 1);
        // add the new id
        newIds.push(id);
        // put the pointer at the end
        this.history.index = newIds.length - 1;
        this.history.pageIds = newIds;
    }

    public updateForChange(data: ChangePageData, pageIndex:number, pageId: string) {
        if ("name" in data || "increment" in data) {
            this.push(pageId);
        }
        else if ("history" in data) {
            this.history.index += data.history;
        }
    }

    /**
     * move the pointer to the next or previous page, but read-ahead and dont actually move yet
     * @param step 
     * @returns 
     */
    public peekUsingChange(step: 1 | -1): string {
        return this.history.pageIds[this.history.index + step];
    }

    /**
     * return the page id at the pointer position
     * @returns 
     */
    public getCurrentPageId(): string {
        return this.history.pageIds[this.history!.index];
    }

    /**
     * you can go back if there is a history and the index is not at the start
     * @returns 
     */
    private canGoBack(): boolean {
        return !!this.history && this.history!.index > 0;
    }

    /**
     * you can go forward if there is a history and the index is not at the end
     * @returns 
     */
    private canGoForward(): boolean {
        return !!this.history && this.history.index < this.history.pageIds.length - 1;
    }

    /**
     * setup the buttons so that the correct ones are enabled/disabled
     * @param newPage 
     * @param index 
     * @param numPages 
     */
    public override async onPageIn(newPage: Salad.IPage, index: number, numPages: number): Promise<void> {
        const uiComp = newPage.getComponent("ui");
        const prevMethod = uiComp.getPrevMethod();
        const nextMethod = uiComp.getNextMethod();

        if(prevMethod === "none") {
            uiComp.enable("prev", false);
        }
        else if(prevMethod === "historyback"){
            uiComp.enable("prev", this.canGoBack());
        }

        if(nextMethod === "none") {
            uiComp.enable("next", false);
        }
        else if (nextMethod === "historynext") {
            uiComp.enable("next", this.canGoForward());
        }
    }

}
