/**
 * we just store the last edit - nothing clever like a whole history of edits
 */

import { IPage } from "../../types/internal";
import { PageSchema } from "../../types/external";

type UndoAction = NonNullable<PageSchema["undo"]["action"]>;
type UndoType = UndoAction["payload"]["type"]; // position, size etc

type MapTypeToPayload = {
    [K in UndoType]: Extract<UndoAction["payload"], { type: K }>["data"];
}

export interface IUndoManager{
    destroy(): void;
    validateAction(action: UndoAction): boolean;
    applyAction(payload: UndoAction): void;
    getAction<T extends UndoType>(
        type: T,
        id: string,
        data: MapTypeToPayload[T]
    ): UndoAction;
}

export class UndoManager implements IUndoManager{
    constructor(private page?: IPage){

    }
    
    public getAction<T extends UndoType>(
        type: T,
        id: string,
        data: MapTypeToPayload[T]
    ): UndoAction {
        const payload = {
            type,
            data,
        };

        return {
            id,
            payload,
        } as UndoAction;
    }

    public validateAction(action: UndoAction): boolean{
        // does it still exist?
        const instance = this.page!.instances.getInstanceById(action!.id);
        return !!instance;
    }

    public applyAction(action: UndoAction): void{
        const payload = action.payload;
        const instance = this.page!.instances.getInstanceById(action!.id);
        if(instance){
            // choosw how to undo it
            if(payload?.type === "position"){
                const posComp = instance.getComponent("position")!;
                posComp.setPosition(payload.data.startPos);
            }
            else if(payload?.type === "rotation"){
                const tComp = instance.getComponent("transform")!;
                tComp.setRotation(payload.data.startRot);
            }
            else if(payload?.type === "size"){
                const sComp = instance.getComponent("size")!;
                sComp.setSize(payload.data.startSize.width, payload.data.startSize.height);
            }
        }
    }
    public destroy(){
        this.page = undefined;
    }
}
