import * as ExternalTypes from "./types/external";
import { HTMLDragger } from "./dragging/HTMLDragger";
import { PlayDragger } from "./dragging/PlayDragger";
import { EditDragger } from "./dragging/EditDragger";
import ts from "typescript";


export const getRandomNumber: typeof ExternalTypes.Utils.getRandomNumber = (min: number = 0, max: number = 1):number => {
    if(min > max){
        throw new Error("Invalid arguments")
    }
    return Math.random() * (max - min) + min;
}

export const getRandomInt: typeof ExternalTypes.Utils.getRandomInt = (min: number = 0, max: number = 1):number => {
    if(min > max || parseInt(min.toString()) !== min || parseInt(max.toString()) !== max){
        throw new Error("Invalid arguments")
    }
    return Math.floor(Math.random() * (max - min + 1)) + min;
};

export const getRandomColor: typeof ExternalTypes.Utils.getRandomColor =(opacity: number = 1): ExternalTypes.ColorString => {
    const r = ()=>Math.round(Math.random() * 255);
    opacity = Math.min(1, Math.max(0, opacity));
    if(opacity === 1){
        return `rgb(${r()}, ${r()}, ${r()})`   
    }
    else{
        return `rgba(${r()}, ${r()}, ${r()}, ${opacity})`
    }
};

export const getRandomPrimaryColor: typeof ExternalTypes.Utils.getRandomPrimaryColor = () => {
    const colorPalette:ExternalTypes.ColorString[] = [
        "#8E24AA",
        "#1E88E5",
        "#00897B",
        "#43A047",
        "#FDD835",
        "#FB8C00",
        "#E53935",
        "#F06292",
        "#6D4C41"
    ];
    const i = Math.floor(Math.random() * colorPalette.length);
    return colorPalette[i];
};

export const getRandomChoice: typeof ExternalTypes.Utils.getRandomChoice = <T>(arr: T[]): T => {
    const i = Math.floor(Math.random() * arr.length);
    return arr[i];
};

export const Geom: typeof ExternalTypes.Utils.Geom = {
    rectRectIntersect: (rect1: ExternalTypes.Rect, rect2: ExternalTypes.Rect): "none" | "touch" | "overlap" | "equal" => {
        const r1Right = rect1.left + rect1.width;
        const r1Bottom = rect1.top + rect1.height;
        const r2Right = rect2.left + rect2.width;
        const r2Bottom = rect2.top + rect2.height;
        if (rect1.left === rect2.left && rect1.top === rect2.top && rect1.width === rect2.width && rect1.height === rect2.height) {
            return 'equal';
        }
        // No overlap or touch
        else if (r1Right < rect2.left || rect1.left > r2Right || r1Bottom < rect2.top || rect1.top > r2Bottom) {
            return 'none';
        }
        // Overlap (if interiors intersect)
        else if (r1Right > rect2.left && rect1.left < r2Right && r1Bottom > rect2.top && rect1.top < r2Bottom) {
            return 'overlap';
        }
        // Touch on an edge or point only
        return 'touch';            
    }
}

export const Dragging: typeof ExternalTypes.Utils.Dragging = {
    /**
     * Make any element draggable and call dropHandler when you drop it on the page
     * @param el
     * @param page 
     * @param dropHandler 
     * @returns 
     */
    makeDraggable: (el: HTMLElement, page: ExternalTypes.IPageExternal, dropHandler:(pos: {x:number, y:number})=>void):any => {
        return new HTMLDragger(el, page, dropHandler);
    },

    /**
     * Make an instance draggable in play mode
     * @param page 
     * @param instance 
     * @returns 
     */
    getPlayDragger: (page: ExternalTypes.IPageExternal, instance:ExternalTypes.IInstance):any => {
        return new PlayDragger(page, instance);
    },

    /**
     * Make an instance draggable in edit mode
     * @param page 
     * @param instance 
     * @returns 
     */
    getEditDragger: (page: ExternalTypes.IPageExternal, instance:ExternalTypes.IInstance):any => {
        return new EditDragger(page, instance);
    }
}

export const Code = {
    transpileCode: (code:string): string=>{
        return ts.transpile(code);
    },
    getSyntaxErrors: (code:string) : {line:string | number, char: string | number, message:string}[]=>{
        const options = {
            compilerOptions: { 
                target: ts.ScriptTarget.ESNext
            },
            reportDiagnostics: true, // Collects syntax errors
        }
    
        const out = ts.transpileModule(code, options);

        return (out.diagnostics ||[]).map(diagnostic => {
            const message = ts.flattenDiagnosticMessageText(diagnostic.messageText, "\n");
            const messageInfo = diagnostic.file ? diagnostic.file.getLineAndCharacterOfPosition(diagnostic.start!) : { line: "?", character: "?"};
            return {
                line: messageInfo.line,
                char: messageInfo.character,
                message: `Error at ${messageInfo.line}:${messageInfo.character} - ${message}`
            };
        });
    }
}