import Salad from "../index"

export type RGBColor = {
    r: number;
    g: number;
    b: number;
};

export type RGBAColor = {
    r: number;
    g: number;
    b: number;
    a: number
};


// eg. #FF0000
const sixDigitHexRegExp = /^#?([a-f\d]{2})([a-f\d]{2})([a-f\d]{2})$/i;

// eg. #FF0000aa
const eightDigitHexRegExp = /^#?([a-f\d]{2})([a-f\d]{2})([a-f\d]{2})([a-f\d]{2})$/i;

// eg. rgb(255, 0, 0)
const rgbRegExp = /rgb\(([0-9]+),\s*([0-9]+),\s*([0-9]+)\)/;

// eg. rgba(255, 0, 0, 0.5)
const rgbaRegExp = /rgba\(([0-9]+),\s*([0-9]+),\s*([0-9]+),\s*([0-9.]+)\)/;

export const isValidColorString = (clr: string): boolean => {
    return (
        sixDigitHexRegExp.test(clr) ||
        eightDigitHexRegExp.test(clr) ||
        rgbRegExp.test(clr) ||
        rgbaRegExp.test(clr)
    );
}

const hexToRgba = (
    hex: `#${string}`,
): { r: number; g: number; b: number; a: number } | undefined => {
    var result = sixDigitHexRegExp.exec(hex);
    return result
        ? {
              r: parseInt(result[1], 16),
              g: parseInt(result[2], 16),
              b: parseInt(result[3], 16),
              a: 1,
          }
        : undefined;
};

export const getColorWithoutAlpha = (hex:`#${string}`): `#${string}`=>{
    if(sixDigitHexRegExp.test(hex)){
        return hex;
    }
    else{
        return hex.substring(0, 7) as `#${string}`
    }
}

const hexWithAToRgba = (hex: `#${string}`): { r: number; g: number; b: number; a: number } | undefined => {
    var result = eightDigitHexRegExp.exec(hex);
    return result
        ? {
              r: parseInt(result[1], 16),
              g: parseInt(result[2], 16),
              b: parseInt(result[3], 16),
              a: parseInt(result[4], 16) / 255,
          }
        : undefined;
};

const rgbStringToRgba = (
    str: string,
): { r: number; g: number; b: number; a: number } | undefined => {
    const match = str.match(rgbRegExp);
    return match
        ? {
              r: parseInt(match[1]),
              g: parseInt(match[2]),
              b: parseInt(match[3]),
              a: 1,
          }
        : undefined;
};

const rgbaStringToRgba = (
    str: string,
): { r: number; g: number; b: number; a: number } | undefined => {
    const match = str.match(rgbaRegExp);
    return match
        ? {
              r: parseInt(match[1]),
              g: parseInt(match[2]),
              b: parseInt(match[3]),
              a: parseFloat(match[4]) / 255,
          }
        : undefined;
};

export const stringToRGBAObject = (
    clr: Salad.ColorString,
): { r: number; g: number; b: number; a: number } | undefined => {
    if(!clr){
        return {
            r: 0,
            g: 0,
            b: 0,
            a: 0,
        }
    }
    if(sixDigitHexRegExp.test(clr)){
        return hexToRgba(clr as `#${string}`)
    }
    else if(eightDigitHexRegExp.test(clr)){
        return hexWithAToRgba(clr as `#${string}`)
    }
    else if(rgbRegExp.test(clr)){
        return rgbStringToRgba(clr)
    }
    else if(rgbaRegExp.test(clr)){
        return rgbaStringToRgba(clr)
    }
    return undefined;
};


/**
 * sets the opacity of a color of any format
 * @param clr 
 * @param alpha - from 0 to 1
 * @returns 
 */
export const setOpacity = <T extends Salad.ColorString>(clr: T, alpha: number): `#${string}` => {
    const obj = stringToRGBAObject(clr);
    const black = "#00000000" satisfies `#${string}`;
    if (obj) {
        const r = obj.r.toString(16).padStart(2, "0");
        const g = obj.g.toString(16).padStart(2, "0");
        const b = obj.b.toString(16).padStart(2, "0");
        const a = Math.round((alpha * 255)).toString(16).padStart(2, "0");
        return `#${r}${g}${b}${a}` as `#${string}`;
    } else {
        return black;
    }
};

/**
 * Mix using weight
 * Eg. weight = 1 means 100% of c1
 * @param c1
 * @param c2
 * @param weight
 * @returns
 */
const getWeightedColor = (c1: RGBColor, c2: RGBColor, weight: number): RGBColor => {
    return {
        r: Math.round(c1.r * weight + c2.r * (1 - weight)),
        g: Math.round(c1.g * weight + c2.g * (1 - weight)),
        b: Math.round(c1.b * weight + c2.b * (1 - weight)),
    };
};

const BLACK = {
    r: 0,
    g: 0,
    b: 0,
};

export const darkenRGB = (pixelClr: RGBColor, amount: number = 0.5) =>
    getWeightedColor(pixelClr, BLACK, amount);

export const rgbToInt = (clr: RGBColor): number => {
    return (clr.r << 16) + (clr.g << 8) + clr.b;
};
