
import { IPage, IPageKeyboardComponent } from "../../types/internal";
import { APageComponent } from "../APageComponent";
import { PageSchema } from "../../types/external";

export default abstract class APageKeyboardComponent
    extends APageComponent<"keyboard">
    implements IPageKeyboardComponent
{
    
    public name: "keyboard" = "keyboard";

    constructor(data: PageSchema["keyboard"], page: IPage) {
        super(data, page);
    }

    public getKeys():string{
        return this.data.keys;
    }

    public setKeys(value:string):void{
        this.data.keys = value;
    }

    public getShow(): PageSchema["keyboard"]["show"]{
        return this.data.show;
    }
    public setShow(show: PageSchema["keyboard"]["show"]):void{
        this.data.show = show;
    }

    public setPosition(value: PageSchema["keyboard"]["position"]):void{
        this.data.position = value;
    }

    public getPosition():PageSchema["keyboard"]["position"]{
        return this.data.position;
    }

}