/**
 * lottie component in edit mode - makes an actual lottie animation
 */

import {  Schema, IInstance } from "../../types/external";
import { IPage } from "../../types/internal";
import ALottieComponent from "./ALottieComponent";
import { getLottieAsImageSrc } from "../../utils/lottieImageCache";
import { ILottieAnimationItem } from "../../types/external";
export default class EditLottieComponent extends ALottieComponent {

    private img: HTMLImageElement | undefined;

    constructor(data: Schema["lottie"], instance: IInstance, page: IPage) {
        super(data, instance, page);
    }

    protected override destroyLottie() {
        super.destroyLottie();
        if (this.img) {
            this.img.remove();
            this.img = undefined;
        }
    }

    protected override async getOrMakeLottie(): Promise<ILottieAnimationItem | undefined> {
        const resolvedPath = await this.getAssetManager().getPathForKey(this.data.path);
        const src = await getLottieAsImageSrc(resolvedPath);
        this.img = document.createElement("img");
        Object.assign(this.img.style, {
            width: "100%",
            height: "100%",
            objectFit: "contain",
        });
        this.img.src = src;
        this._element!.appendChild(this.img);
        return undefined;
    }

}
