import { IFontImport } from './types';

export class FontImport implements IFontImport{

    constructor(private fonts: {[key:string]:{base64:string}}){
        
    }

    public async importFonts(): Promise<void>{
        for(const fontName in this.fonts){
            const font = this.fonts[fontName];
            const fontFace = new FontFace(fontName, `url(${font.base64})`);
            try{
                await fontFace.load();
                // @ts-ignore
                document.fonts.add(fontFace);
            }
            catch(e){

            }
        }
    }
}