
import Salad from "../index";
import { TypedEventEmitter } from "../utils/TypedEventEmitter";
import { ITypedEventEmitter } from "../types/external";

export interface IActivityEventEmitter extends ITypedEventEmitter<Salad.ActivityEventsMap> {
    destroy(): void;
}

export class ActivityEventEmitter
    extends TypedEventEmitter<Salad.ActivityEventsMap>
    implements IActivityEventEmitter
{
    constructor() {
        super();
    }

    /**
     * Remove all listeners
     */
    public destroy(): void {
    this.removeAllListeners();
    }
}
