/**
 * layout component
 * This handles
 */

import { IPage } from "../../types/internal";
import { Point, PageSchema, Events, IPageLayoutComponent} from "../../types/external";
import { APageComponent } from "../APageComponent";
import { getEventPosition } from "../../utils/utils";
import { PageComponentUpdate } from "../../types/external";

type SaladDomRect = {
    top:number,
    left:number,
    width:number,
    height:number
}

const getFullScreenRect = (): SaladDomRect => {
    return {
        top: 0,
        left: 0,
        width: window.innerWidth,
        height: window.innerHeight
    };
}

const getRect = (element: HTMLElement): SaladDomRect => {
    if ((window as any).isJestEnvironment) {
        const width = parseInt(element.style.width);
        const height = parseInt(element.style.height);
        const top = parseInt(element.style.top);
        const left = parseInt(element.style.left);
        return {
            top,
            left,
            width,
            height
        };
    }
    else{
        const rect = element.getBoundingClientRect();
        return {
            top: rect.top,
            left: rect.left,
            width: rect.width,
            height: rect.height,
        };
    }
}

export default class PageLayoutComponent
    extends APageComponent<"layout">
    implements IPageLayoutComponent
{
    public name: "layout" = "layout";

    private _globalScale: number;

    private _parentRect: SaladDomRect;
    private _containerRect: SaladDomRect;

    constructor(data: PageSchema["layout"], page: IPage) {
        super(data, page);
    }

    public override getDependencies() {
        return ["camera", "layers"] as const;
    }

    override onCreated() {
        super.onCreated();
        this.performLayout = this.performLayout.bind(this);
        this._onPageComponentUpdated = this._onPageComponentUpdated.bind(this);
        this.page.events.on(Events.PAGE_RESIZE, this.performLayout);
        this.page.events.c.camera.on(Events.PAGE_COMPONENT_UPDATED, this._onPageComponentUpdated);
        this.performLayout();
    }

    public getGlobalScale():number{
        return this._globalScale;
    }

    /**
     *
     * @param clientPos
     * @returns {Point} page position
     */
    public getPagePositionForClientPosition(clientPos: Point): Point {
        const rect = this._containerRect;
        clientPos.x -= rect.left;
        clientPos.y -= rect.top;
        const pagePos =  {
            x: clientPos.x / this._globalScale,
            y: clientPos.y / this._globalScale,
        };
        const camComp = this.getPageComponent("camera");
        const view = camComp.getView();
        return {
            x: pagePos.x + view.left,
            y: pagePos.y + view.top,
        };
    }

    /**
     * Get the x/y position of a touch event on the page - For example if we have moved the camera to 100,100 then a
     * click at the point 250, 250 is really at 350, 350
     * Take into account the page scale as well, if we have scaled by a factor 2 then a click at 100,200 is really 200, 400
     * @param e
     * @returns
     */
    public getPagePositionForEvent(e: PointerEvent | TouchEvent | MouseEvent): Point  {
        let pos = getEventPosition(e);
        return this.getPagePositionForClientPosition({
            x: pos.x,
            y: pos.y,
        });
    }
  
    private _onPageComponentUpdated(eventData: PageComponentUpdate): void {
        this.performLayout();
    }

    /**
     * App was resized
     */
    private performLayout() { 
        // layout everything so it fits in the parent, and store it
        const camComp = this.getPageComponent("camera");
        const view = camComp.getView();
        const parent = this.page.getActivityContainer();
        const container = this.page.getPageContainer();
        
        this._parentRect = document.fullscreenElement ? getFullScreenRect() : getRect(parent);

        const parentWidth = this._parentRect.width;
        const parentHeight = this._parentRect.height;
        const scaleX = parentWidth / view.width;
        const scaleY = parentHeight / view.height;

        // set the global scale to the minimum of the two scales so it fits in the parent
        this._globalScale = Math.min(scaleX, scaleY);

        const newWidth = Math.round(view.width * this._globalScale);
        const newHeight = Math.round(view.height * this._globalScale);

        //update the actual container of our app (center it)
        Object.assign(container.style, {
            width: `${newWidth}px`,
            height: `${newHeight}px`,
            left: `${(parentWidth - newWidth) / 2}px`,
            top: `${(parentHeight - newHeight) / 2}px`,
        });

        // also scale all layers inside
        const layersComp = this.getPageComponent("layers");
        layersComp.showView(view, this._globalScale);
        this._containerRect = getRect(container);
        
    }

    override onDestroyed(): void {
        this.page.events.off(Events.PAGE_RESIZE, this.performLayout);
        this.page.events.off(Events.PAGE_COMPONENT_UPDATED, this._onPageComponentUpdated);
        super.onDestroyed();
    }
}
