import { IPage } from "../../types/internal";
import { APageComponent } from "../APageComponent";
import { PageSchema, IPageUndoComponent } from "../../types/external";
import { Point, Size } from "../../types/external";
import {UndoManager, IUndoManager} from "./UndoManager";

type UndoAction = PageSchema["undo"]["action"];

export default class EditPageUndoComponent
    extends APageComponent<"undo">
    implements IPageUndoComponent
{
    public name: "undo" = "undo";
    private undoManager: IUndoManager;

    constructor(data: PageSchema["undo"], page: IPage) {
        super(data, page);
        this.undoManager = new UndoManager(page)
    }

    public override onCreated(): void {
        super.onCreated();
    }

    public canUndo():boolean{
        return this.data.enabled && this.undoManager.validateAction(this.data.action!);
    }

    public clear(): void{
        this.data.enabled = false;
        this.data.action = undefined;
    }

    public onRotateEnd(id:string, startRot:number, endRot:number):void{
        this.data.action = this.undoManager.getAction("rotation", id, {startRot, endRot});
        this.data.enabled = true;
    }
    
    public onDragEnd(id:string, startPos:Point, endPos:Point):void{
        this.data.action = this.undoManager.getAction("position", id, {startPos, endPos});
        this.data.enabled = true;
    }

    public onResizeEnd(id:string, startSize:Size, endSize:Size):void{
        this.data.action = this.undoManager.getAction("size", id, {startSize, endSize});
        this.data.enabled = true;
    }

    public undo():void{
        if(this.canUndo()){
            const action: NonNullable<UndoAction> = this.data.action! as NonNullable<UndoAction>;
            this.undoManager.applyAction(action);
        }
        this.clear();
    }

    public override onDestroyed(){
        super.onDestroyed();
        this.undoManager.destroy();
    }

}
