/**
 * Page script - authors can write typescript on the page
 */

import { IPage, IPageScriptComponent } from "../../types/internal";
import { APageComponent } from "../APageComponent";
import { PageSchema } from "../../types/external";

export default class ScriptComponent
    extends APageComponent<"script">
    implements IPageScriptComponent
{
    public name: "script" = "script";

    constructor(data: PageSchema["script"], page: IPage) {
        super(data, page);
    }

    /**
     * Store whether we have run the "script" component at least once
     * Eg. for a script that only runs once such as "clone" me 20 times
     * that you don't want to run every time a file is loaded
     * @returns boolean
     */
    public getHasRunOnce(): boolean {
        return this.data.ranOnce;
    }

    public setHasRunOnce(ran: boolean = true): void {
        this.data.ranOnce = ran;
    }

    /**
     * Content = the actual code
     * @returns 
     */
    public getContent(): string {
        return this.data.content;
    }

    public setContent(content: string): void {
        this.data.content = content;
    }

    public getTranspiledCode(): string | undefined {
        return this.data.transpiledCode;
    }

}
