/**
 * Edit mode camera component
 * Shows a box illusrating the camera viewport
 */

import { cameraElement } from "../../utils/domElementFactory";
import { IPage } from "../../types/internal";
import { startPositionToViewportCSS } from "./CameraViewportCSS";

export interface IEditCameraBox {
    element: HTMLElement;
    redraw(): void;
}

export class EditCameraBox implements IEditCameraBox {
    public element: HTMLElement;

    constructor(private page: IPage) {
        this.element = cameraElement();
    }
    public redraw() {
        const cameraComp = this.page.getComponent("camera");
        const data = cameraComp.getData();
        const bgComp = this.page.getComponent("background");
        const bgSize = bgComp.getSize();
        // only show if the viewport is smaller than the whole page
        const showBox = data.size.width < bgSize.width || data.size.height < bgSize.height;
        const startPosition = cameraComp.getStartPosition();

        // this is the CSS to show the camera box
        const position = startPositionToViewportCSS(startPosition);

        Object.assign(this.element.style, {
            width: `${data.size.width}px`,
            height: `${data.size.height}px`,
            display: showBox ? "block" : "none",
            position: "absolute",
            ...position,
        });
    }
}
