import Salad from "../../../index";
import { AActivityComponent } from "../AActivityComponent";
import { IActivityUIComponent } from "../../../types/external";

export class PlayActivityUIComponent extends AActivityComponent implements IActivityUIComponent{

    constructor() {
        super();
    }

    public override async onPageIn(newPage: Salad.IPage, index: number, numPages: number): Promise<void> {
        const navComp = newPage.getComponent("ui");
        const prevMethod = navComp.getPrevMethod();
        const nextMethod = navComp.getNextMethod();
        // setup the buttons so that the correct ones are enabled/disabled

        const uiComp = newPage.getComponent("ui");

        if(prevMethod === "none") {
            uiComp.enable("prev", false);
        }
        else if (prevMethod === "prev") {    
            uiComp.enable("prev", index >= 1);
        }

        if(nextMethod === "none") {
            uiComp.enable("next", false);
        }
        else if (nextMethod === "next") {
            uiComp.enable("next", numPages >= 2 && index < numPages - 1);
        }
    }

}
