export const getDefaultComponentFactory = (mode: ActivityMode) => {
    return mode === "edit" ? createComponentFactory(editMap) : createComponentFactory(playMap);
}

export const getComponentFactoryForKeys = (keys: ComponentName[], mode: ActivityMode) => {
    let map:MapComponentNameToClass = {};
    keys.forEach((key) => {
        map = {
            ...map,
            [key]: mode === "edit" ? editMap[key] : playMap[key]
        }
    });
    return createComponentFactory(map);
}