/**
 * Page instances component
 */
import {
    IInstancesComponent,
} from "../../types/internal";

import AInstancesComponent from "./AInstancesComponent";
import { PageEventsMap, IInstance, Events, PageSchema } from "../../types/external";
import { IPage } from "../../types/internal";

export default class PlayInstancesComponent extends AInstancesComponent implements IInstancesComponent{

    private instanceScriptQueue: (() => void)[] = [];
    private pageLoaded = false;

    constructor(data: PageSchema["instances"], page: IPage){
        super(data, page);
        this.onInstanceCreated = this.onInstanceCreated.bind(this);
    }

    public override onCreated(): void {
        super.onCreated();
        this.page.events.on(Events.INSTANCE_CREATED, this.onInstanceCreated);
    }

    public override onDestroyed(): void {
        super.onDestroyed();
        this.page.events.off(Events.INSTANCE_CREATED, this.onInstanceCreated);
    }

    /**
     * when a new instance is added, run its script
     * @param eventData
     */
    private onInstanceCreated(eventData: PageEventsMap[typeof Events.INSTANCE_CREATED]) {
        const codeRunnerComp = this.page.getComponent("coderunner");
        const runScript = () => {
            codeRunnerComp!.runInstanceCreatedScript(eventData.target as IInstance, this.page);
        };
        if (this.pageLoaded) {
            runScript();
        } else {
            this.instanceScriptQueue.push(runScript);
        }
    }


     /**
     * after the page is created, run its script
     * @param eventData
     */
    public override runScripts():void {
        const codeRunnerComp = this.page.getComponent("coderunner");
        codeRunnerComp!.runPageCreatedScript(this.page);
        // flush any pending
        this.instanceScriptQueue.forEach((runScript) => {
            runScript();
        });
        this.pageLoaded = true;
    }

}
