/**
 * events component
 */
import { IPage } from "../../../types/internal";
import { IInstance } from "../../../types/external";
import { Point } from "../../../types/external";
import { Pointer, IPointer } from "./Pointer";
import { getMouseHoverManager, IMouseHoverManager } from "../MouseHoverManager";
import { Events } from "../../../types/external";
import { isCustom } from "../customEvents";
import { IHitTestManager, getHitTestManager } from "./HitTestManager";

export interface IPointerHandler {
    getCurrentPos(): Point;
    getTargetInstancesUnderPoint(p: Point): IInstance[];
    destroy(): void;
}

export abstract class APointerEventHandler implements IPointerHandler {
    // store last instance that was clicked on, in order to send it as the target of a "drag" event
    private currentInstance: IInstance | undefined;

    // store pointer position
    protected _pointer: IPointer = new Pointer();

    // handle mouse over and mouse out
    private hoverManager: IMouseHoverManager = getMouseHoverManager();

    private hitTestManager: IHitTestManager;

    constructor(
        protected page: IPage,
    ) {
        const el = this.page.getPageContainer();

        this.onPointerMove = this.onPointerMove.bind(this);
        this.onPointerDown = this.onPointerDown.bind(this);
        this.onPointerUp = this.onPointerUp.bind(this);
        this.onPointerClick = this.onPointerClick.bind(this);
        this.onMouseOver = this.onMouseOver.bind(this);
        this.onMouseOut = this.onMouseOut.bind(this);

        // always add these
        el.addEventListener("pointerdown", this.onPointerDown);
        el.addEventListener("pointerup", this.onPointerUp);
        el.addEventListener("click", this.onPointerClick);

        this.hitTestManager = getHitTestManager(this.page);

        this.hoverManager.on("mouseover", this.onMouseOver);
        this.hoverManager.on("mouseout", this.onMouseOut);

        /**
         * pointermove is used when dragging in edit or play mode so it is in this base class
         * these are triggered on touch devices too so we dont need to add touchmove
         */

        el.addEventListener("pointermove", this.onPointerMove);
    }

    /**
     * Get the normalised mouse pos, taking into account the touch location(s) and the offset of the containing div
     * @param e
     * @returns
     */
    protected getPagePositionForEvent(e: PointerEvent | TouchEvent | MouseEvent): Point {
        return this.page.getComponent("layout")!.getPagePositionForEvent(e);
    }

    // at any time you can get the position of the pointer
    public getCurrentPos() {
        return this._pointer.getCurrentPos();
    }

    /**
     * get the instances under the mouse. In order of z-index (top-most first), lower ones come last
     * Take into account getRespondsToMouseEvents
     * @param {Point} p - page position not container position/client position
     * @returns
     */
    public getTargetInstancesUnderPoint(p: Point): IInstance[] {
        return this.hitTestManager.getTargetInstancesUnderPoint(p);
    }

    private onMouseOut(instance: IInstance) {
        this.page.events.emit(Events.INSTANCE_MOUSEOUT, {
            target: instance,
        });
        instance.events.emit(Events.INSTANCE_MOUSEOUT, {
            target: instance,
        });
    }

    private onMouseOver(instance: IInstance) {
        this.page.events.emit(Events.INSTANCE_MOUSEOVER, {
            target: instance,
        });
        instance.events.emit(Events.INSTANCE_MOUSEOVER, {
            target: instance,
        });
    }

    /**
     * Pointer down
     * @param e
     */
    private onPointerDown(e: PointerEvent | TouchEvent) {
        if(isCustom(e)){
            return;
        }
        
        const point: Point = this.getPagePositionForEvent(e);
        //Find the ones that are under the mouse
        const targets = this.getTargetInstancesUnderPoint(point);

        // reset the pointer
        this._pointer.start(point);

        // trigger event on the page
        this.page.events.emit(Events.PAGE_POINTERDOWN, {
            point,
            targets: targets,
            originalEvent: e,
        });
        if (targets.length >= 1) {
            // trigger on the first (top-most) instance and the page
            this.currentInstance = targets[0];
            const payload = {
                point,
                targets: targets,
                target: this.currentInstance,
                originalEvent: e,
            };
            this.page.events.emit(Events.INSTANCE_POINTERDOWN, payload);
            this.currentInstance.events.emit(Events.INSTANCE_POINTERDOWN, payload);
        }
    }

    /**
     * Moved the mouse
     * @param e
     */
    private onPointerMove(e: PointerEvent) {
        const point = this.getPagePositionForEvent(e);

        const size = this.page.getComponent("background").getSize();

        if(point.x < 0 || point.y < 0 || point.x > size.width || point.y > size.height) {
            this.currentInstance = undefined;
        }

        const targets = this.getTargetInstancesUnderPoint(point);

        // how far they moved
        const delta = this._pointer.getDelta(point);

        // move the pointer
        this._pointer.move(point);

        const isDown = this._pointer.isDown();

        // and emit the correct event
        const pageEventType = isDown ? Events.PAGE_POINTERDRAG : Events.PAGE_POINTERMOVE;
        const instanceEventType = isDown ? Events.INSTANCE_POINTERDRAG : Events.INSTANCE_POINTERMOVE;

        const payload = {
            point,
            targets,
            target: this.currentInstance as IInstance,
            delta,
            originalEvent: e,
        };

        this.page.events.emit(pageEventType, payload);

        if (this.currentInstance) {
            this.currentInstance.events.emit(instanceEventType, payload);
        }
        else {
            this.hoverManager.update(targets.length >= 1 ? targets[0] : undefined);
        }
    }

    /**
     * Click event
     * @param e
     * @returns
     */
    private onPointerClick(e: PointerEvent | MouseEvent) {
        // if moved even a tiny bit, it's a drag, not a click
        if (this._pointer.isDrag()) {
            return;
        }
        const point = this.getPagePositionForEvent(e);
        const targets = this.getTargetInstancesUnderPoint(point);
        // emit event 'pageClick' on the page
        this.page.events.emit(Events.PAGE_CLICK, {
            point,
            targets,
        });
        if (targets.length >= 1) {
            // also emit 'instanceClick' on the uppermost target and the page
            const target = targets[0];
            const payload = {
                point,
                targets,
                target,
                originalEvent: e
            };
            this.page.events.emit(Events.INSTANCE_CLICK, payload);
            target.events.emit(Events.INSTANCE_CLICK, payload);
        }
    }

    /**
     * Pointer up
     * @param e
     */
    private onPointerUp(e: PointerEvent) {
        this.currentInstance = undefined;
        this.page.events.emit(Events.PAGE_POINTERUP, {
            targets: [],
            originalEvent: e,
        });

        //TODO - why in a timeout?
        setTimeout(() => {
            this._pointer.stop();
        });
    }

    // remove all listeners
    public destroy(): void {
        const el = this.page.getPageContainer();
        el.removeEventListener("pointerdown", this.onPointerDown);
        el.removeEventListener("pointerup", this.onPointerUp);
        el.removeEventListener("click", this.onPointerClick);
        el.removeEventListener("pointermove", this.onPointerMove);

        this.hoverManager.off("mouseover", this.onMouseOver);
        this.hoverManager.off("mouseout", this.onMouseOut);
        this.hoverManager.destroy();

        this.hitTestManager.destroy();
    }
}
