/**
 * modals - ModalsComponent.
 */
import { IModalsComponent, IInstance, Schema, Events } from "../../types/external";
import { IPage } from "../../types/internal";
import { AComponent } from "../AComponent";
export default class PlayModalsComponent extends AComponent<"modals"> implements IModalsComponent {
    public name: "modals" = "modals";

    constructor(data: Schema["modals"], instance: IInstance, page: IPage) {
        super(data, instance, page);
        this.onAccepted = this.onAccepted.bind(this);
        this.onClick = this.onClick.bind(this);
        this.onDrop = this.onDrop.bind(this);
    }

    override getDependencies() {
        return ["render"] as const;
    }

    public override onCreated(): void {
        super.onCreated();
        this._addListeners();
    }

    public override onDestroyed(): void {
        super.onDestroyed();
        this._removeListeners();
    }

    private async showInfo(name: string) {
        const modal = this.page.getComponent("modalslist").getModalByName(name);
        if (modal) {
            this.page.modals.open(modal);
        }
    }

    private onClick() {
        const data = this.data.onInstanceClick;
        this.showInfo(data.name);
    }

    private onDrop() {
        const data = this.data.onInstanceDropped;
        this.showInfo(data.name);
    }

    private onAccepted() {
        const data = this.data.onInstanceAccepted;
        this.showInfo(data.name);
    }

    private _removeListeners() {
        this.instance.events.off(Events.INSTANCE_CLICK, this.onClick);
        this.instance.events.off(Events.INSTANCE_DROPPED, this.onDrop);
        this.instance.events.off(Events.INSTANCE_ACCEPTED, this.onAccepted);
    }

    private _addListeners() {
        if (this.data.onInstanceClick && !!this.data.onInstanceClick.name) {
            this.instance.events.on(Events.INSTANCE_CLICK, this.onClick);
        }
        if (this.data.onInstanceDropped && !!this.data.onInstanceDropped.name) {
            this.instance.events.on(Events.INSTANCE_DROPPED, this.onDrop);
        }
        if (this.data.onInstanceAccepted && !!this.data.onInstanceAccepted.name) {
            this.instance.events.on(Events.INSTANCE_ACCEPTED, this.onAccepted);
        }
    }
}
