/**
 * A single page
 */

import {
    IPage,
    IAssetManager,
    IPageEventEmitter,
    PageComponentsMap,
    IComponentFactory,
    InstanceData,
    IPageComponentFactory, IInstancesComponent,
    ITranslator,
    ISoundSequencer
} from "../types/internal";
import { PageEventEmitter } from "./PageEventEmitter";
import { mergeDefaultsIntoSchema } from "../utils/utils";
import { defaultSchema } from "../defaultSchema";
import { defaultPageSchema } from "../defaultPageSchema";
import {
    PageComponentName, PartialPageSchema, IPageDataComponent,
    IPageLayoutComponent,
    IPageSoundComponent, IPageCollisionsComponent,
    IPageHighlightComponent,
    Schema, PageSchema, Point, IPageTimersComponent,
    IPageNavigationDecorator,
    IPageUndoComponent,
    IPageModalsDecorator,
    IModalHelper,
    IPageScriptsDecorator,
    ICameraComponent,
    IPageDrawingDecorator,
    IDragNDropComponent,
    IPageBackgroundComponent,
    IEventsComponent,
    IGridComponent
} from "../types/external";

import { PageNavigationDecorator } from "./pagedecorators/PageNavigationDecorator";
import { PageModalsDecorator } from "./pagedecorators/PageModalsDecorator";
import { PageDrawingDecorator } from "./pagedecorators/PageDrawingDecorator";
import { PageScriptsDecorator } from "./pagedecorators/PageScriptsDecorator";
import Salad from "../index";

class Page implements IPage {
    /**
     * the html that will contain this page
     */
    private _pageContainer: HTMLElement;

    /**
     * The parent of the container
     * Used to scale the container when its parent changes size
     */
    private _activityContainer: HTMLElement;

    /**
     * All the page components
     */
    private _components: PageComponentsMap;

    /**
     * event emitter
     */
    private _events: IPageEventEmitter;

    /**
     * Responsible for making the components
     */
    private _componentFactory: IComponentFactory;
    private _pageComponentFactory: IPageComponentFactory;

    /**
     * Some defaults to "fill in the blanks" if any component values are missing
     */
    private _defaultSchema: Schema;
    private _defaultPageSchema: PageSchema;

    /**
     * A function to get an asset resolver
     */
    private _assetsManager: IAssetManager;

    
    private _soundSequencer: ISoundSequencer;

    private _translator: ITranslator = {
        translate(key: string):string {
            return key;
        },
    };

    // unique id
    private _id: string;

    /**
     * Decorators
     */
    private _navigation: IPageNavigationDecorator = new PageNavigationDecorator(this);
    private _modals: IPageModalsDecorator = new PageModalsDecorator(this);
    private _drawing: IPageDrawingDecorator = new PageDrawingDecorator(this);
    private _scripts: IPageScriptsDecorator = new PageScriptsDecorator(this);

    constructor(id:string, activityContainer: HTMLElement, pageContainer: HTMLElement) {
        this._id = id;
        this._activityContainer = activityContainer;
        this._pageContainer = pageContainer;

        this._events = new PageEventEmitter();

        // set up some defaults (these can be changed - for example in the tests)
        this._defaultSchema = defaultSchema;
        this._defaultPageSchema = defaultPageSchema;
    }

    public getSoundSequencer(): ISoundSequencer {
        return this._soundSequencer;
    }

    public setSoundSequencer(seq: ISoundSequencer): this {
        this._soundSequencer = seq;
        return this;
    }

    /**
     * Populate with instances
     * @returns this - for chaining
     */
    public loadInstancesData(instances: InstanceData[]): this {
        if(!this._components){
            throw new Error("loadPageData must be called before loadInstancesData")
        }
        const insComp = this.getComponent("instances")!;
        insComp.addInstancesData(instances);
        insComp.runScripts();
        return this;
    }

    /**
     * Create the page components
     * @param schema
     * @returns
     */
    public loadPageData(schema: PartialPageSchema): this {
        const merged = mergeDefaultsIntoSchema<PageSchema>(this._defaultPageSchema, schema);
        this._components = this._pageComponentFactory.buildAllPageComponents(merged, this);
        Object.values(this._components).forEach((c) => {
            c.onCreated();
        });
        return this;
    }

    public setAssetManager(manager: IAssetManager): this {
        this._assetsManager = manager;
        return this;
    }

    public setModalHelper(helper: IModalHelper): this {
        this.modals.setHelper(helper);
        return this;
    }

    public setDefaultSchema(defaultSchema: Schema): this {
        this._defaultSchema = defaultSchema;
        return this;
    }

    public getDefaultSchema(): Schema {
        return this._defaultSchema;
    }

    public setDefaultPageSchema(defaultPageSchema: PageSchema): this {
        this._defaultPageSchema = defaultPageSchema;
        return this;
    }

    public getId(): string {
        return this._id;
    }

    public setFactories(
        componentFactory: IComponentFactory,
        pageComponentFactory: IPageComponentFactory,
    ): this {
        this._componentFactory = componentFactory;
        this._pageComponentFactory = pageComponentFactory;
        return this;
    }

    public getComponent<K extends PageComponentName>(name: K): PageComponentsMap[K] {
        return this._components[name];
    }

    /**
     * Get the container HTML element for this Page.
     * @returns {HTMLElement}
     */
    public getPageContainer(): HTMLElement {
        return this._pageContainer;
    }

    /**
     * get the parent element
     * Used for adding events to the parent
     */
    public getActivityContainer(): HTMLElement {
        return this._activityContainer;
    }

    /**
     * Return how to make components
     * Used by the instance builder
     */
    public getComponentFactory(): IComponentFactory {
        return this._componentFactory;
    }

    /**
     * A way to get the 'real' path from the name of an asset
     * Eg. 'dinosaur1' -> '/images/sdk/dinos/dinosaur1'
     * @returns an asset resolver
     */
    public getAssetManager(): IAssetManager {
        return this._assetsManager;
    }

    public getTranslator(): ITranslator{
        return this._translator;
    }

    public setTranslator(t: ITranslator): this{
        this._translator = t;
        return this;
    }

    public get data(): IPageDataComponent {
        return this.getComponent("data");
    }
    
    public get modals(): IPageModalsDecorator {
        return this._modals;
    }

    public get navigation(): IPageNavigationDecorator {
        return this._navigation;
    }

    public get scripts(): IPageScriptsDecorator {
        return this._scripts;
    }

    public get drawing(): IPageDrawingDecorator {
        return this._drawing;
    }

    public get instances(): IInstancesComponent {
        return this.getComponent("instances")!;
    }

    public get timers(): IPageTimersComponent {
        return this.getComponent("timers")!;
    }

    public get camera() : ICameraComponent{
        return this.getComponent("camera")!;
    }

    public get sound(): IPageSoundComponent {
        return this.getComponent("sound")!;
    }

    public get collisions(): IPageCollisionsComponent {
        return this.getComponent("collisions")!;
    }

    public get highlight(): IPageHighlightComponent {
        return this.getComponent("highlight")!;
    }

    public get layout(): IPageLayoutComponent{
        return this.getComponent("layout");
    }

    public get undo(): IPageUndoComponent{
        return this.getComponent("undo");
    }

    public get grid():IGridComponent{
        return this.getComponent("grid")!;
    }

    public get dragndrop(): IDragNDropComponent{
        return this.getComponent("dragndrop")!;
    }

    public get background(): IPageBackgroundComponent{
        return this.getComponent("background")!;
    }

    public get eventsComponent(): IEventsComponent {
        return this.getComponent("events")!;
    }

    /**
     * Get the events component, use this to dispatch page events
     */
    public get events(): IPageEventEmitter {
        return this._events;
    }

    /**
     * Get the page schema
     * Calls 'getData' on every component
     */
    public getPageData(): PageSchema {
        const schema: PartialPageSchema = {};
        const keys: PageComponentName[] = Object.keys(this._components!) as PageComponentName[];
        keys.forEach((k) => {
            const comp = this._components![k];
            schema[k] = comp?.getData();
        });
        return schema as PageSchema;
    }

    /**
     * Get instances data
     * @returns the data
     */
    public getInstancesData(): InstanceData[] {
        return this.getComponent("instances")!.getInstanceData();
    }

    /**
     * Destroy the whole page.
     * Remove all instances and event listeners
     */
    public destroy() {
        // stop the timer and render loop
        this.getComponent("ticker")?.stop();

        //remove all instances
        this.instances.destroyAllInstances();

        //stop events
        this.events.destroy();

        this.getComponent("timers")?.clearAll();

        // destroy components
        Object.values(this._components!).forEach((c) => {
            c.onDestroyed();
        });

        this.events.removeAllListeners();
    }

    public getPointerPosition(): Point | undefined {
        return this.getComponent("events")!.getPointerPosition();
    }

    public getCurrentActivity(): Salad.IActivity{
        const activity = Salad.Factory.getCurrentActivity();
        return activity;
    }
}

export const getPage = (id:string = Salad.Utils.getUUID(), activityContainer?: HTMLElement | undefined, pageContainer?: HTMLElement | undefined) => {
    if(!activityContainer){
        const parent = document.createElement("div")
        activityContainer = document.createElement("div")
        parent.appendChild(activityContainer)            
    }
    if(!pageContainer){
        pageContainer = document.createElement("div")
        activityContainer.appendChild(pageContainer)
    }
    return new Page(id, activityContainer, pageContainer);
};
