/**
 * Different ways of highlighting an element
 */
import { PageSchema } from "../../types/external";
import { ConstructorOf } from "@root/salad/types/utils";
import { IHighlighter, HighlighterOptions } from "@root/salad/components/highlights/types";
import {map as confettiMap} from "@root/salad/components/highlights/ConfettiHighlighters";

type HighlightType = Exclude<PageSchema["highlight"]["type"], "none">

const highlighterMap:{[name in HighlightType]: ConstructorOf<IHighlighter, [HighlighterOptions]>} = {
    ...confettiMap
}

export const makeHighlighter = (type: HighlightType, canvas?: HTMLCanvasElement): IHighlighter => {
    const Klass = highlighterMap[type];
    if (Klass) {
        return new Klass({
            canvas,
            element: canvas
        });
    }
    return undefined;
};
