export const getAnimForDriveKeys = (
    instance: IInstance,
    key: string,
    duration:number, 
    amount:number,
    spec: { up: string; left: string; right: string; down: string },
): { anim: AnimatableProps; settings: AnimationSettings } => {
    let anim: AnimatableProps = {}
    let settings: AnimationSettings = {
        duration,
    };
    if (key === spec.right) {
        anim = {
            rotation: `rotation + ${amount}*t`,
        };
    } else if (key === spec.left) {
        anim = {
            rotation: `rotation - ${amount}*t`,
        };
    } else if (key === spec.up) {
        const directionFacing = instance.getComponent("transform").getDirectionFacing();
        const dx = 100 * Math.cos((directionFacing * Math.PI) / 180);
        const dy = 100 * Math.sin((directionFacing * Math.PI) / 180);
        anim = {
            x: `x + ${dx}*t`,
            y: `y + ${dy}*t`,
        };
    } else if (key === spec.down) {
        const directionFacing = instance.getComponent("transform").getDirectionFacing();
        const dx = 100 * Math.cos((directionFacing * Math.PI) / 180);
        const dy = 100 * Math.sin((directionFacing * Math.PI) / 180);
        anim = {
            x: `x - ${dx}*t`,
            y: `y - ${dy}*t`,
        };
    }
    return {
        anim,
        settings,
    };
};
