import APageKeyboardComponent from "./APageKeyboardComponent";
import { IPage } from "../../types/internal";
import { PageSchema } from "../../types/external";
import { keyboard } from "../../utils/domElementFactory";
import { getButtons, IKeyboardButtons } from "./KeyboardButtons";
import {getVisibility} from "./KeyboardVisibility";
export default class PlayPageKeyboardComponent extends APageKeyboardComponent {

    private element: HTMLElement;
    private _buttons: IKeyboardButtons | undefined = undefined;

    constructor(data: PageSchema["keyboard"], page: IPage){
        super(data, page);
        this.element = keyboard();
    }

    public override onCreated(): void {
        const shouldAddKeys = getVisibility(this).getShouldShowKeyboard();
        if(shouldAddKeys){
            const layerComp = this.getPageComponent("layers");
            // add a layer for the camera
            layerComp.initLayer("keyboard", this.element, {
                type: "ui",
            });
            const keys = this.data.keys
                .split(",")
                .map((key) => key.trim());
            this._buttons = getButtons(this.element, this.data.position, this.page, keys);
        }
    }

    public override onDestroyed():void{
        if(this._buttons){
            this._buttons.destroy();
            this._buttons = undefined;
        }
        const layerComp = this.getPageComponent("layers");
        layerComp.removeLayer("keyboard");
        super.onDestroyed();
    }
}
