/**
 * Abstract class for Button components
 */

import { IButtonComponent, IInstance } from "../../types/external";
import { Schema } from "../../types/external";
import { IPage } from "../../types/internal";
import { AComponent } from "../AComponent";
import { button, buttonUI, buttonContainer } from "../../utils/domElementFactory";
import { ButtonPointerDrawer } from "./ButtonPointerDrawer";
import { getColorForTheme } from "./ButtonThemes";
import { CSSDomUpdate } from "../../types/external";

type ChildPosition = Schema["text"]["position"];

export default abstract class AButtonComponent
    extends AComponent<"button">
    implements IButtonComponent
{
    public name: "button" = "button";

    /**
     * container
     */
    protected _element: HTMLElement | undefined;

    /**
     * button element
     */
    protected _button: HTMLButtonElement;

    /**
     * pointer
     */
    protected _ui: HTMLElement;

    constructor(data: Schema["button"], instance: IInstance, page: IPage) {
        super(data, instance, page);
    }

    override getDependencies() {
        return ["render"] as const;
    }

    override onCreated() {
        super.onCreated();
        if (this.data.enabled) {
            this.addElement();
            this._updateValue();
        }
    }

    public setState(state: Schema["button"]["state"]): void{
        this.data.state = state;
        this._redrawUI();
    }

    public getState(): Schema["button"]["state"]{
        return this.data.state;
    }

    public getEnabled(): boolean{
        return this.data.enabled;
    }

    /**
     * lifecycle
     */
    public override onDestroyed(): void {
        super.onDestroyed();
        this._destroyElement();
    }

    public setText(s: string): void {
        this.data.text = s;
        this._updateValue();
    }

    private _updateValue() {
        this._button.innerText = this.data.text;
    }

    public getText(): string {
        return this.data.text;
    }

    private _redrawUI(): void {
        // apply theme
        if(this.data.state === "disabled"){
            this._button.setAttribute("disabled", "disabled");
        }
        else{
            this._button.removeAttribute("disabled");
        }

        this._ui.classList.add(
            "drawer",
            "drawer-theme_" + this.data.type
        );
        
        const buttonDrawer = new ButtonPointerDrawer(this._ui);
        
        if(this.data.arrow.x === 0 && this.data.arrow.y === 0){
            buttonDrawer.clear();
        }
        else{
            this.instance.getComponent("render").setLayoutPaint(false);
            const color = getColorForTheme(this.data.type);
            buttonDrawer.draw(this.data.arrow, color);
        }
    }

    protected addElement(): void {
        const parent = this.getInstanceComponent("render").getElement();
        this._element = buttonContainer(parent);
        this._ui = buttonUI(this._element);
        this._button = button(this._element);
        this._button.classList.add(
            "theme_" + this.data.type,
            "role_" + this.data.role
        );

        this._redrawUI();
        this._updatePosition();
    }

    protected _destroyElement(): void {
        if (this._element) {
            while (this._element.firstChild) {
                this._element.removeChild(this._element.firstChild);
            }
            this._element.remove();
            this._element = undefined;
        }
    }

    /**
     * On update, reset the lottie animation
     * @param data
     */
    override update(data: Schema["button"]): void {
        super.update(data);
        this._destroyElement();
        if (this.data.enabled) {
            this.addElement();
            this._updateValue();
        }
    }

    public setChildPosition(pos: ChildPosition): void {
        this.data.position = pos;
        this._updatePosition();
    }

    public getChildPosition(): ChildPosition {
        return this.data.position;
    }

    private _updatePosition() {
        const css:CSSDomUpdate["css"] = {
            ...this.data.position   
        }
        this.page.getComponent("domupdate").addCSSUpdate({
            element: this._element!,
            css
        });
    }

    public getElement(): HTMLElement {
        return this._element!;
    }
}
