import Salad from "../..";

type AnimatableProps = Partial<Salad.Schema["animationlist"]["list"][string]>;

const readyMadeAnimationNames = [
    "move_right",
    "move_down",
    "rotate",
    "oscillate_left_right",
    "oscillate_up_down",
    "grow",
    "shrink",
    "walk",
    "jump",
    "fadein",
    "fadeout",
    "blink",
    "pulse",
    "circle",
    "shake",
] as const;

export type ReadyMadeAnimationName = (typeof readyMadeAnimationNames)[number];

const definitions: {
    [key in ReadyMadeAnimationName]: {
        label: string;
        name: key;
        props: AnimatableProps;
    };
} = {
    move_right: {
        name: "move_right",
        label: "Move right",
        props: {
            x: "x + t*250",
        },
    },
    move_down: {
        name: "move_down",
        label: "Move down",
        props: {
            y: "y + t*250",
        },
    },
    rotate: {
        name: "rotate",
        label: "Rotate",
        props: {
            rotation: "t * 360",
        },
    },
    oscillate_left_right: {
        name: "oscillate_left_right",
        label: "Oscillate left/right",
        props: {
            x: "x + sin(t * 2 * PI) * 100",
        },
    },
    oscillate_up_down: {
        name: "oscillate_up_down",
        label: "Oscillate up/down",
        props: {
            y: "y + sin(t * 2 * PI) * 100",
        },
    },
    grow: {
        name: "grow",
        label: "Grow",
        props: {
            scaleX: "1 + t",
            scaleY: "1 + t",
        },
    },
    shrink: {
        name: "shrink",
        label: "Shrink",
        props: {
            scaleX: "1 - t",
            scaleY: "1 - t",
        },
    },
    pulse: {
        name: "pulse",
        label: "Pulse",
        props: {
            scaleX: "1 + (sin(t * 12 * PI) * 0.1 - 0.05)",
            scaleY: "1 + (sin(t * 12 * PI) * 0.1 - 0.05)",
        },
    },
    walk: {
        name: "walk",
        label: "Walk",
        props: {
            x: "x + 100 * t",
            rotation: "20*sin(t * 6 * PI)",
        },
    },
    jump: {
        name: "jump",
        label: "Jump",
        props: {
            x: "x + 50 * t",
            y: "y - 100*sin(t * PI)",
        },
    },
    fadein: {
        name: "fadein",
        label: "Fade in",
        props: {
            opacity: "t",
        },
    },
    fadeout: {
        name: "fadeout",
        label: "Fade out",
        props: {
            opacity: "1 - t",
        },
    },
    circle: {
        name: "circle",
        label: "Circle",
        props: {
            x: "(x - 60) + 60*cos(2*pi*t)",
            y: "y + 60*sin(2*pi*t)",
        },
    },
    blink: {
        name: "blink",
        label: "Blink",
        props: {
            opacity: "1 - step(frac(t * 10))",
        },
    },
    shake: {
        name: "shake",
        label: "Shake",
        props: {
            x: "x + 4 * noise(t)",
            y: "y + 4 * noise(1 - t)",
        },
    },
};

export const getAllReadyMadeAnimations = () => {
    return definitions;
};

export const getReadyMadeAnimationNamesAndLabels = () => {
    return Object.entries(definitions).map(([key, value]) => {
        return { name: key, label: value.label };
    });
};

export const getReadyMadeAnimationByName = (animationName: ReadyMadeAnimationName): {
    label: string;
    name: typeof animationName;
    props: AnimatableProps;
} => {
    if (animationName in definitions) {
        return definitions[animationName as keyof typeof definitions];
    }
    return undefined;
};
