/**
 * Wait for instances to load
 * Give this class a list of ids and it will wait for them to load and emit an event when they are all loaded
 */

import { IInstance } from "../types/external";
import { IPage } from "../types/internal";
import { PageEventsMap, Events } from "../types/external";
import { TypedEventEmitter } from "./TypedEventEmitter";
import { ITypedEventEmitter } from "../types/external";

type EventMap = {
    loaded: IInstance[];
};

export interface IGetInstancesAsync extends ITypedEventEmitter<EventMap> {
    getHasLoaded(): boolean;
    destroy(): void;
    load(): void;
}

export class GetInstancesAsync extends TypedEventEmitter<EventMap> implements IGetInstancesAsync {

    private loadedInstances: IInstance[] = [];

    constructor(
        private page: IPage,
        private ids: string[],
    ) {
        super();
        this.onInstanceCreated = this.onInstanceCreated.bind(this);
    }

    public getHasLoaded(): boolean {
        return this.loadedInstances.length === this.ids.length;
    }

    public load(): void {
        // handle ones that already exist

        this.ids.forEach((id: string) => {
            const instance = this.page.instances.getInstanceById(id);
            if(instance) {
                this.addInstance(instance);
            }
        });

        const loaded = this.checkAllLoaded();
        if (loaded) {
            this.emit("loaded", this.loadedInstances);
        }
        else{
            // wait
            this.page.events.on(Events.INSTANCE_CREATED, this.onInstanceCreated);
        }
    }

    private addInstance(instance: IInstance): void {
        if (instance && !this.loadedInstances.includes(instance)) {
            this.loadedInstances.push(instance);
        }
    }

    private checkAllLoaded(): boolean {
        const allLoaded = this.getHasLoaded();
        if (allLoaded) {
            // got them all!
            this.page.events.off(Events.INSTANCE_CREATED, this.onInstanceCreated);
            this.emit("loaded", this.loadedInstances);
        }
        return allLoaded;
    }

    private onInstanceCreated(eventData: PageEventsMap[typeof Events.INSTANCE_CREATED]): void {
        const instance = eventData.target;
        const id = instance.getId();
        if (this.ids.includes(id)) {
            // relevant one
            this.addInstance(instance);
            this.checkAllLoaded();
        }
    }

    public destroy(): void {
        this.page.events.off(Events.INSTANCE_CREATED, this.onInstanceCreated);
    }
}
