export type ConstructorOf<C, Args extends any[]> = {
    new (...args: Args): C;
};

interface IPointLike {
    x: number;
    y: number;
}

/**
 * or smoothing out some movement
 * @param points
 * @param n 
 * @returns 
 */
export const averageOfLastN = <T extends IPointLike>(points: T[], n: number): IPointLike => {
    let sumX = 0;
    let sumY = 0;

    const numToPick = Math.min(n, points.length);

    for (let i = 0; i < numToPick; i++) {
        const j = points.length - 1 - i;
        sumX += points[j].x;
        sumY += points[j].y;
    }

    const x = sumX / numToPick;
    const y = sumY / numToPick;

    return { x, y };
};

/**
 * For debugging
 */
export const addToBody = (() => {
    const size = 350;
    let numCanvases = 0;

    const add = (...els: HTMLElement[]) => {
        els.forEach((el, i) => {
            Object.assign(el.style, {
                "z-index": 1000 + i,
                transform: `scale(${size / el.clientWidth})`,
                "transform-origin": "top left",
                width: `${size}px`,
                height: `${size}px`,
                position: "fixed",
                border: "1px solid black",
                top: 60,
                left: `${200 + size * numCanvases}px`,
            });
            document.body.appendChild(el);
            numCanvases++;
        });
    };
    return add;
})();

type ExtractKeys<T, K extends keyof T> = {
    [P in K]: T[P];
};

export const extractKeys = <T, K extends keyof T>(obj: T, keys: K[]): ExtractKeys<T, K> => {
    const result = {} as ExtractKeys<T, K>;
    keys.forEach((key) => {
        result[key] = obj[key];
    });
    return result;
};
