/**
 * navigation component in play mode - go to a page when you click
 */
import { INavigationComponent, IInstance, Schema, Events } from "../../types/external";
import { IPage } from "../../types/internal";
import ANavigationComponent from "./ANavigationComponent";
import Salad from "../../index";
export default class PlayNavigationComponent
    extends ANavigationComponent
    implements INavigationComponent
{
    constructor(data: Schema["navigation"], instance: IInstance, page: IPage) {
        super(data, instance, page);
        this.onClick = this.onClick.bind(this);
    }

    /**
     * Go to a specific page
     */
    private onClick() {
        const to = this.data.page;
        const reset = this.data.reset;
        const launchURL = this.data.launchURL;
        const resetActivity = this.data.resetActivity;
        if(resetActivity){
            this.page.navigation.resetActivity();
        }
        else if (reset) {
            this.page.navigation.resetPage();
        }
        else if(to){
            if(to === "+1"){
                this.page.navigation.gotoNextPage();
            }
            else if(to === "-1"){
                this.page.navigation.gotoPrevPage();
            }
            else if(to === "forward"){
                this.page.navigation.historyForward();
            }
            else if(to === "back"){
                this.page.navigation.historyBack();
            }
            else{
                this.page.navigation.gotoPageName(to);
            }
        }
        else if(launchURL){
            this.page.navigation.launchURL(launchURL);
        }
    }

    public override onCreated(): void {
        super.onCreated();
        if (this.data.page || this.data.reset || this.data.launchURL || this.data.resetActivity) {
            this.instance.events.on(Events.INSTANCE_CLICK, this.onClick);
        }
    }

    public override onDestroyed(): void {
        this.instance.events.off(Events.INSTANCE_CLICK, this.onClick);
    }
}
