/**
 * Render in edit mode - handles hiding/showing
 */

import AVisibilityComponent from "./AVisibilityComponent";

export default class EditorVisibilityComponent extends AVisibilityComponent {

    public override toggleEditorVisibility(): void {
        this.setEditorVisibility(!this.data.editorVisible);
    }

    public override onCreated(): void {
        super.onCreated();
        this.updateEditorVisibility();
    }

    /**
     * This will hide/show using 'visibility' not 'display'
     */
    private updateEditorVisibility() {
        const element = this.instance.getComponent("render").getElement();
        if (this.data.editorVisible) {
            element.classList.remove("editor-hidden");
        } else {
            element.classList.add("editor-hidden");
        }
    }

    public getCanCollide():boolean{
        // nothing collides in edit mode
        return false
    }

    public override setEditorVisibility(visible: boolean): void {
        this.data.editorVisible = visible;
        this.updateEditorVisibility();
    }
}
