/**
 * transform component. Handles rotation, scale, and origin
 */

import { IInstance, Events } from "../../../types/external";
import { IPage } from "../../../types/internal";
import { IFireListener } from "./AKeyListener";
import { Schema } from "../../../types/external";

type FireType = Schema["gamecontrol"]["fire"]["type"];

export class FireListener implements IFireListener {
    constructor(
        private instance: IInstance,
        private page: IPage,
        private instanceName: string,
        private type: FireType,
    ) {
        this.onKeyDown = this.onKeyDown.bind(this);
        this.onClick = this.onClick.bind(this);
        this.initListeners();
    }
    public destroy(): void {
        this.page.events.off(Events.KEY_DOWN, this.onKeyDown);
        this.instance.events.off(Events.INSTANCE_CLICK, this.onClick);
    }
    private onClick(): void {
        const component = this.instance.getComponent("gamecontrol");
        component.fire(this.instanceName);
    }
    private onKeyDown(eventData: { code: string }): void {
        if (eventData.code === "Space") {
            const component = this.instance.getComponent("gamecontrol");
            component.fire(this.instanceName);
        }
    }
    private initListeners(): void {
        if (this.type === "space") {
            this.page.events.on(Events.KEY_DOWN, this.onKeyDown);
        } else {
            this.instance.events.on(Events.INSTANCE_CLICK, this.onClick);
        }
    }
}
