import { APointerEventHandler } from "./APointerEventHandler";
import { IPointerHandler } from "./APointerEventHandler";
import { Events } from "../../../types/external";
import Salad from "../../../index";

export class EditPointerEventHandler extends APointerEventHandler implements IPointerHandler {
    constructor(page: Salad.IPage) {
        super(page);
        this.onPointerDblClick = this.onPointerDblClick.bind(this);
        const el = this.page.getPageContainer();
        el.addEventListener("dblclick", this.onPointerDblClick);
    }

    /**
     * dblclick is used when editing a textarea in Edit mode only.
     * @param e
     */
    private onPointerDblClick(e: PointerEvent | MouseEvent) {
        const point = this.getPagePositionForEvent(e);
        const targets = this.getTargetInstancesUnderPoint(point);
        this.page.events.emit(Events.PAGE_DBLCLICK, {
            point,
            targets,
        });
        if (targets.length >= 1) {
            const target = targets[0];
            const payload = {
                point,
                targets,
                target,
                originalEvent: e,
            };
            this.page.events.emit(Events.INSTANCE_DBLCLICK, payload);
            target.events.emit(Events.INSTANCE_DBLCLICK, payload);
        }
    }

    public override destroy(): void {
        super.destroy();
        const el = this.page.getPageContainer();
        el.removeEventListener("dblclick", this.onPointerDblClick);
    }
}
