import { Schema, IDraggableComponent, IInstance } from "../../types/external";
import { IPage } from "../../types/internal";
import { AComponent } from "../AComponent";
import { IDragger } from "../../dragging/types";

export default abstract class ADraggableComponent
    extends AComponent<"draggable">
    implements IDraggableComponent
{
    // does the actual dragging
    protected dragger: IDragger | undefined;

    public name: "draggable" = "draggable";

    constructor(data: Schema["draggable"], instance: IInstance, page: IPage) {
        super(data, instance, page);
        this.onPageSizeChange = this.onPageSizeChange.bind(this);
    }

    override getDependencies() {
        return ["position", "transform", "render", "data"] as const;
    }

    public isDraggable(): boolean{
        return !!this.dragger;
    }

    public getSnapsBackOnFail(): boolean {
        return this.data.snapBackOnFail;
    }

    public getDeleteOnFail(): boolean {
        return this.data.deleteOnFail;
    }

    public override onDestroyed(): void {
        super.onDestroyed();
        this._removeDraggable();
    }

    public getEnabled(): boolean {
        return this.data.enabled;
    }

    public activate(): void {
        // only used in edit mode
    }

    public startDragging(e: MouseEvent | TouchEvent): void {}

    public deactivate(): void {
        // only used in edit mode
    }

    public resetPosition(): void {}

    protected _removeDraggable(): void {
        if (this.dragger) {
            this.dragger.destroy();
            this.dragger = undefined;
        }
    }

    public disable() {
        this.data.enabled = false;
    }

    public enable() {
        this.data.enabled = true;
    }

    protected abstract createDragger(): void;

    protected onPageSizeChange() {
        if (this.dragger) {
            this.dragger.updateRect();
        }
    }
}
