/**
 * Grid component
 * Helps authors align items on a grid
 */

import { IPage } from "../../types/internal";
import { APageComponent } from "../APageComponent";
import { PageSchema, IGridComponent } from "../../types/external";
export default abstract class AGridComponent extends APageComponent<"grid"> implements IGridComponent {
    public name: "grid" = "grid";

    constructor(data: PageSchema["grid"], page: IPage) {
        super(data, page);
    }

    override getDependencies() {
        return ["instances"] as const;
    }

    public getGridSize(): number {
        return this.data.size;
    }

    public setGridSize(size: number) {
        this.data.size = size;
    }

    public getSnapToGrid(): boolean {
        return this.data.snap;
    }

    public setSnapToGrid(snap: boolean): void {
        this.data.snap = snap;
    }
}
