/**
 * UI buttons in play mode
 */
import { IPage, IUIComponent } from "../../types/internal";
import { PageSchema } from "../../types/external";
import AUIComponent from "./AUIComponent";
import { getHandler as getScrollHandler } from "./UINavigationHandlers";
import { getHandler as getNavHandler, INavHandler } from "./NavHandler";
import { IUIScroll } from "./types";
import { ButtonName } from "../../types/internal";

export default class PlayUIComponent extends AUIComponent implements IUIComponent {
    
    private _scrollHandler: IUIScroll | undefined;
    private _prevHandler: INavHandler | undefined;
    private _nextHandler: INavHandler | undefined;

    private nextPageHandler: () => void | undefined;
    private prevPageHandler: () => void | undefined;

    constructor(data: PageSchema["ui"], page: IPage) {
        super(data, page);
    }

    /**
     * lifecycle
     * make a layer and the UI
     */
    public override onCreated() {
        super.onCreated();
        // register the ui layer with the layer component
        const layerComp = this.getPageComponent("layers");
        layerComp.initLayer("ui", this._element, {
            type: "ui",
        });
        this.init();
    }

    public override setNextPageHandler(handler: () => void): void {
        this.nextPageHandler = handler;
    }

    public override setPrevPageHandler(handler: () => void): void {
        this.prevPageHandler = handler;
    }

    public override getPageHandler(name: "prev" | "next"): () => void | undefined {
        return name === "prev" ? this.prevPageHandler : this.nextPageHandler;
    }

    /**
     * lifecycle
     * stop listening
     */
    public override onDestroyed(): void {
        const layerComp = this.getPageComponent("layers");
        layerComp.removeLayer("ui");

        super.onDestroyed();
        if (this._scrollHandler) {
            this._scrollHandler.destroy();
            this._scrollHandler = undefined;
        }
        if (this._prevHandler) {
            this._prevHandler.destroy();
            this._prevHandler = undefined;
        }
        if (this._nextHandler) {
            this._nextHandler.destroy();
            this._nextHandler = undefined;
        }
    }

    public override isEnabled(name: ButtonName): boolean {
        return this._scrollHandler?.isButtonEnabled(name) || this._prevHandler?.isButtonEnabled(name) || this._nextHandler?.isButtonEnabled(name) || false;
    }

    // enable/disable a button (eg. the prev/next buttons)
    public enable(name: ButtonName, enabled: boolean): void {
        // just loop through the handlers and call the method on all of them
        if (this._scrollHandler) {
            this._scrollHandler.setButtonEnabled(name, enabled);
        }
        if (this._prevHandler) {
            this._prevHandler.setButtonEnabled(name, enabled);
        }
        if (this._nextHandler) {
            this._nextHandler.setButtonEnabled(name, enabled);
        }
    }

    private init() {
        if (this._scrollHandler) {
            this._scrollHandler.destroy();
            this._scrollHandler = undefined;
        }
        if (this.data.scroll !== "none") {
            this._scrollHandler = getScrollHandler(this.data.scroll, this.page);
        }
        if (this._prevHandler) {
            this._prevHandler.destroy();
            this._prevHandler = undefined;
        }
        if (this._nextHandler) {
            this._nextHandler.destroy();
            this._nextHandler = undefined;
        }
        if (this.data.prev !== "none") {
            this._prevHandler = getNavHandler(this.data.prev, "prev", this.page);
        }
        if (this.data.next !== "none") {
            this._nextHandler = getNavHandler(this.data.next, "next", this.page);
        }
    }
}
