import { Polygon } from "../../types/external";

export type AAR = {
    minX:number,
    minY:number,
    maxX:number,
    maxY:number
};

export const isAxisAlignedRect = (poly: Polygon): boolean => {
    if (poly.length !== 4) {
        return false;
    }
    
    let minX = poly[0].x;
    let maxX = poly[0].x;
    let minY = poly[0].y;
    let maxY = poly[0].y;
    
    for (let i = 1; i < 4; i++) {
        const x = poly[i].x;
        const y = poly[i].y;
        
        if (x < minX){
            minX = x;
        }
        else if (x > maxX){
            maxX = x;
        }
        
        if (y < minY){
            minY = y;
        }
        else if (y > maxY){
            maxY = y;
        }
    }
    
    // Track if we've seen min and max values
    let hasMinX = false;
    let hasMaxX = false;
    let hasMinY = false;
    let hasMaxY = false;
    
    for (let i = 0; i < 4; i++) {
        if (poly[i].x === minX){
            hasMinX = true;
        }
        else if (poly[i].x === maxX){
            hasMaxX = true;
        }
        else{
            return false;
        }
        
        if (poly[i].y === minY){
            hasMinY = true;
        }
        else if (poly[i].y === maxY){
            hasMaxY = true;
        }
        else {
            return false;
        }
    }

    return hasMinX && hasMaxX && hasMinY && hasMaxY;
}

export const toAxisAlignedRect = (poly: Polygon): AAR | undefined => {

    if (!isAxisAlignedRect(poly)) {
        return undefined;
    }
    
    // Find min/max directly rather than using map and spread
    let minX = poly[0].x;
    let maxX = poly[0].x;
    let minY = poly[0].y;
    let maxY = poly[0].y;
    
    for (let i = 1; i < 4; i++) {
        const x = poly[i].x;
        const y = poly[i].y;
        
        if (x < minX) minX = x;
        else if (x > maxX) maxX = x;
        
        if (y < minY) minY = y;
        else if (y > maxY) maxY = y;
    }
    
    return { minX, minY, maxX, maxY };
}

export class AxisAlignedRect{
    public static containsPoint(aar: AAR, p: {x:number, y:number}): boolean{
        return p.x >= aar.minX && p.x <= aar.maxX && p.y >= aar.minY && p.y <= aar.maxY;
    }
    public static intersects(aar1: AAR, aar2: AAR): boolean{
        return aar1.minX <= aar2.maxX &&
            aar1.maxX >= aar2.minX &&
            aar1.minY <= aar2.maxY &&
            aar1.maxY >= aar2.minY;
    }
}
