import { IPage } from "../../types/internal";
import { IPageScriptsDecorator } from "../../types/external";

export class PageScriptsDecorator implements IPageScriptsDecorator {
    private _fns: {[name:string] : Function} = {}
    constructor(private page: IPage) {

    }
    public get fns(){
        return this._fns;
    }

    public addFn(name: string, fn: Function): void{
        this._fns[name] = fn;
    }

    public getFn(name: string): Function{
        return this._fns[name];
    }

}
