/**
 * page layers component
 */
import { IPage, IPageLayersComponent, PageLayerProps } from "../../types/internal";
import { APageComponent } from "../APageComponent";
import { PageSchema } from "../../types/external";
import { IPageLayer, getPageLayer } from "./pagelayers/PageLayers";

export default class PageLayersComponent
    extends APageComponent<"layers">
    implements IPageLayersComponent
{
    // array of layers
    private _pageLayers: Map<string, IPageLayer> = new Map<string, IPageLayer>();

    public name: "layers" = "layers";

    constructor(data: PageSchema["layers"], page: IPage) {
        super(data, page);
    }

    public getLayerByName(name: string): IPageLayer | undefined {
        return this._pageLayers.get(name);
    }

    /**
     * loop through all layers and update their position and size
     * @param scale
     * @param offset
     */
    public showView(view: PageSchema["camera"]["view"], globalScale: number): void {
        this._pageLayers.forEach((layer) => {
            layer.showView(view, globalScale);
        })
    }

    /**
     * create a new layer
     * @param name
     * @param element
     * @param props
     * @returns
     */
    public initLayer(name: string, element: HTMLElement, props: PageLayerProps, parentLayerName?:string): void {
        if (this._pageLayers.get(name)) {
            throw new Error("layer exists");
        } 
        
        const getContainer = ()=>{
            if(parentLayerName){
                const layer =  this._pageLayers.get(parentLayerName);
                return layer?.getElement();
            }
            else{
                return this.page.getPageContainer();
            }
        }
        
        const container = getContainer();
        if (!container) {
            throw new Error("container not found");
        }
        
        else {
            const layer = getPageLayer(name, element, this.page, props);
            this._pageLayers.set(name, layer);
            container.appendChild(element);
        }
    }

    public addChildToLayer(child: HTMLElement, layerName: string): void {
        const dom = this.page.getComponent("domupdate");
        const layer = this._pageLayers.get(layerName);
        if (layer) {
            dom.addAppend(()=>{
                layer.add(child);
            })
        } else {
            throw new Error("layer not found");
        }
    }

    public removeLayer(name:string):void{
        const layer = this._pageLayers.get(name);
        if(layer){
            const el = layer.getElement();
            if (el.parentElement) {
                el.parentElement.removeChild(el);
            }
            layer.destroy();
            this._pageLayers.delete(name);
        }
    }

    /**
     * empty all layers and remove them all
     */
    public override onDestroyed(): void {
        super.onDestroyed();
        const names = Array.from(this._pageLayers.keys());
        names.forEach((name) => {
            this.removeLayer(name);
        })
        this._pageLayers = new Map<string, IPageLayer>();
    }
}
