import { IDrawing } from "./types";
import { SimpleCanvasDrawing } from "./simple/SimpleCanvasDrawing";
import { IAssetManager } from "../../types/internal";
/**
 * Get a drawing object
 * Pass in the surface because the tools behave slightly differently
 * @param surface
 * @param canvas
 * @param options
 * @returns
 */
export const getDrawing = (
    surface: "paper" | "empty",
    canvas: HTMLCanvasElement,
    options?: { perspectiveScale: number },
    assetManager?: IAssetManager
): IDrawing => {
    return new SimpleCanvasDrawing(surface, {
        canvas,
        options,
    }, assetManager);
};
