/**
 * Handles selection of instances
 * Instances can be selecetd individually or in groups
 * This is only done in edit mode
 */

import { IPage, IPageSelectionComponent } from "../../types/internal";
import { APageComponent } from "../APageComponent";
import { PageSchema, PageEventsMap, IInstance, PageSelection } from "../../types/external";
import { Events } from "../../types/external";

export default class PageSelectionComponent
    extends APageComponent<"selection">
    implements IPageSelectionComponent
{
    private selection: PageSelection = {
        type: "none",
        selectedInstance: undefined,
        selectedGroup: undefined,
    };

    public name: "selection" = "selection";

    constructor(data: PageSchema["selection"], page: IPage) {
        super(data, page);
    }

    public override getDependencies() {
        return ["instances"] as const;
    }

    /**
     * lifecycle
     * listen to events
     */
    public override onCreated(): void {
        super.onCreated();
        this.onInstanceClick = this.onInstanceClick.bind(this);
        this.onPageClick = this.onPageClick.bind(this);
        this.onInstanceDestroyed = this.onInstanceDestroyed.bind(this);

        this.page.events.on(Events.PAGE_CLICK, this.onPageClick);
        this.page.events.on(Events.INSTANCE_DESTROYED, this.onInstanceDestroyed);
        this.page.events.on(Events.INSTANCE_CLICK, this.onInstanceClick);
    }

    /**
     * lifecycle
     * remove listeners
     */
    public override onDestroyed(): void {
        super.onDestroyed();
        this.page.events.off(Events.PAGE_CLICK, this.onPageClick);
        this.page.events.off(Events.INSTANCE_CLICK, this.onInstanceClick);
        this.page.events.off(Events.INSTANCE_DESTROYED, this.onInstanceDestroyed);
    }

    /**
     * Set one as selected
     * @param instance
     */
    public selectInstance(instance: IInstance): void {
        this.unselectAll();
        instance.getComponent("selected").setSelected(true);
        this.selection = {
            type: "instance",
            selectedInstance: instance,
            selectedGroup: undefined,
        };
        this.emitChange();
    }


    /**
     * unselect all
     */
    public unselectAll(): void {
        this.getAllInstances().forEach((instance: IInstance) => {
            const selectedComponent = instance.getComponent("selected");
            selectedComponent.setSelected(false);
        });
        this.selection = {
            type: "none",
            selectedInstance: undefined,
            selectedGroup: undefined,
        };
        this.emitChange();
    }

    /**
     * create a group from a number of instances
     * @param instances
     */
    public selectGroupUsingInstances(instances: IInstance[]): void {
        const selectedGroup: IInstance[] = [];
        this.getAllInstances().forEach((instance: IInstance) => {
            const isPartOfGroup = instances.includes(instance);
            instance.getComponent("selected").setGrouped(isPartOfGroup);
            if (isPartOfGroup) {
                selectedGroup.push(instance);
            }
        });
        this.selection = {
            type: "group",
            selectedInstance: undefined,
            selectedGroup: selectedGroup,
        };
        this.emitChange();
    }

    /**
     * using the HTML elements, create a group
     * For example when the user draws a rectangle
     * @param elements
     */
    public selectGroupUsingElements(elements: HTMLElement[]): void {
        const comp = this.getPageComponent("instances");
        const instances: IInstance[] = elements.map(comp.getInstanceForElement.bind(comp));
        this.selectGroupUsingInstances(instances);
    }

    /**
     * toggle selected/unselected
     * @param instance
     */
    public toggleSelectedInstance(instance: IInstance): void {
        if (this.selection.type === "instance") {
            // one selected
            const prevSelectedInstance = this.selection.selectedInstance;
            if (instance === prevSelectedInstance) {
                this.unselectAll();
            } else {
                // convert to group
                this.unselectAll();
                this.selectGroupUsingInstances([prevSelectedInstance, instance]);
            }
        } else if (this.selection.type === "group" && this.selection.selectedGroup.length >= 1) {
            // group selected
            if (this.selection.selectedGroup.includes(instance)) {
                this.removeFromGroup(instance);
            } else {
                this.addToGroup(instance);
            }
        } else {
            this.selectInstance(instance);
        }
    }

    // helper function
    private getAllInstances(): IInstance[] {
        return this.getPageComponent("instances").getAllInstances();
    }

    // tell the UI to start/stop enabling moveable and selecto
    private emitChange(): void {
        this.page.events.emit(Events.SELECTION_CHANGE, {
            selection: this.selection,
        });
    }

    // append to group
    private addToGroup(instance: IInstance) {
        const instances = this.selection.type === "group" ? this.selection.selectedGroup : [];
        this.selectGroupUsingInstances([...instances, instance]);
    }

    private removeFromGroup(instance: IInstance): void {
        if (this.selection.type === "group") {
            const newGroup = this.selection.selectedGroup.filter((i) => i !== instance);
            this.selectGroupUsingInstances(newGroup);
        }
    }

    /**
     * when you delete something, just unset everything
     */
    private onInstanceDestroyed() {
        this.unselectAll();
    }

    /**
     * if you click on an instance, select it (thus removing any group)
     * @param eventData
     */
    private onInstanceClick(eventData: PageEventsMap[typeof Events.INSTANCE_CLICK]) {
        const selectedInstance = eventData.target as IInstance;
        const currentSelectionInstance = this.selection.type === "instance" ? this.selection.selectedInstance : undefined;
        const currentSelectionGroup = this.selection.type === "group" ? this.selection.selectedGroup : undefined;
        const isAddition = eventData.originalEvent && (eventData?.originalEvent.shiftKey || eventData?.originalEvent.ctrlKey);
        const addToGroup = isAddition && (!!currentSelectionInstance || !!currentSelectionGroup);
        if(addToGroup){
            this.unselectAll();
            const newSelection = currentSelectionGroup ? [
                ...currentSelectionGroup,
                selectedInstance
            ] : [
                currentSelectionInstance,
                selectedInstance
            ];
            this.selectGroupUsingInstances(newSelection as IInstance[]);
        }
        else{
            this.selectInstance(selectedInstance);
        }
        this.emitChange();
    }

    /**
     *
     * @param instance
     */
    public unselectIfSelected(instance: IInstance): void {
        if (this.selection.type === "instance" && this.selection.selectedInstance === instance) {
            this.unselectAll();
        } else if (
            this.selection.type === "group" &&
            this.selection.selectedGroup.includes(instance)
        ) {
            this.removeFromGroup(instance);
        }
    }

    /**
     * they clicked off the instances
     * just unselect everything
     * @param eventData
     */
    private onPageClick(eventData: PageEventsMap[typeof Events.PAGE_CLICK]) {
        if (eventData.targets.length === 0) {
            this.unselectAll();
        }
    }

    public getSelection(): PageSelection {
        return this.selection;
    }
}
