/**
 * Register all the handlers here
 * What happens when you drop an instance?
 */

import { IDropHandler } from "./types";
import { IInstance } from "../../types/external";
import { MaterialDropHandler } from "./MaterialDropHandler";
import { DroppableHandler } from "./DroppableHandler";
import { IPage } from "../../types/internal";

// in this order
const Klasses = [
    MaterialDropHandler,
    DroppableHandler
];

export const getAllHandlers = (page: IPage, draggedInstance: IInstance): IDropHandler[] => {
    return Klasses.map((Klass) => {
        return new Klass(page, draggedInstance, page.instances.getAllInstances());
    });
};
