/**
 * Image component - displays an image
 */

import { IContainmentComponent, IInstance } from "../../types/external";
import { Schema } from "../../types/external";
import { IPage } from "../../types/internal";
import { AComponent } from "../AComponent";
import { IShape } from "../../types/external";
import { Point } from "../../types/external";
import {dataToShape, getRect} from "./dataToShape";

type Shape = Schema["containment"]["shape"];

export default class ContainmentComponent
    extends AComponent<"containment">
    implements IContainmentComponent
{
    public name: "containment" = "containment";

    private _shape: IShape | undefined;

    constructor(data: Schema["containment"], instance: IInstance, page: IPage) {
        super(data, instance, page);
    }

    override getDependencies() {
        return ["collision"] as const;
    }

    public setShape(shape: Shape): void {
        this.data.shape = shape;
        this._updateShape();
    }

    public getShape(): Shape {
        return this.data.shape;
    }

    public getImplementedShape(): IShape {
        return this._shape!;
    }

    private _updateShape(): void {
        if(this.data.shape && this.data.shape.type === "page") {
            const size = this.page.getComponent("background").getSize();
            this._shape = getRect(size.width, size.height);
        }
        else if (this.data.shape && this.data.shape.type !== "none") {
            this._shape = dataToShape(this.data.shape);
        }
        else {
            this._shape = undefined
        }
    }

    public canMoveTo(newPosition: Point): boolean {
        if (this._shape) {
            const collisionComp = this.instance.getComponent("collision");
            const newShape = collisionComp.getFutureTransformedShapeAtNewPosition(newPosition);
            return this._shape.containsShape(newShape);
        } else {
            // no containment, so return true
            return true;
        }
    }

    public override onCreated(): void {
        super.onCreated();
        this._updateShape();
    }

    public override update(data: Schema["containment"]): void {
        super.update(data);
        this._updateShape();
    }
}
