import { IPage } from "../../types/internal";
import { Point, IInstance } from "../../types/external";
import { translatePoint, drawPoint } from "../../utils/PolygonUtils";

const GRID_COLOR = "rgba(0, 0, 0, 0.1)";

const COLLISION_COLOR = "rgba(200, 0, 0, 0.333)";
const BOUNDS_COLOR = "rgba(50, 50, 50, 0.333)";
const CONTAINMENT_COLOR = "rgba(0, 0, 200, 0.333)";

const getCssForGrid = (size: number, clr: string = GRID_COLOR) => {
    return {
        "background-image": `repeating-linear-gradient(${clr} 0 1px, transparent 1px 100%), repeating-linear-gradient(90deg, ${clr} 0 1px, transparent 1px 100%)`,
        "background-size": `${size}px ${size}px`,
        "background-position": `0 0`,
    };
};

export interface IDebugDrawer {
    clear(): void;
    redraw(): void;
}

abstract class ADebugDrawer implements IDebugDrawer {
    protected page: IPage;
    protected element: HTMLElement;

    constructor(page: IPage, element: HTMLElement) {
        this.page = page;
        this.element = element;
    }

    public abstract clear(): void;
    public abstract redraw(): void;
}

export class CollisionsDrawer extends ADebugDrawer implements IDebugDrawer {
    
    constructor(page: IPage, element: HTMLCanvasElement) {
        super(page, element);
    }

    public clear(): void {
        const elt = this.element as HTMLCanvasElement;
        const ctx = elt.getContext("2d")!;
        ctx!.clearRect(0, 0, elt.width, elt.height);
    }

    /**
     * draw the collision shapes
     */
    public redraw(): void {
        const elt = this.element as HTMLCanvasElement;
        const ctx = elt.getContext("2d")!;

        ctx!.clearRect(0, 0, elt.width, elt.height);
        ctx!.fillStyle = COLLISION_COLOR;
        this._redrawCollisionShapes();
        ctx!.fillStyle = "rgba(0, 200, 0, 0.5)";
        this._redrawOrigins();
    }

    /**
     * Put a blob on the origins
     */
    private _redrawOrigins() {

        const insComp = this.page.getComponent("instances");
        const instances = insComp.getAllInstances();

        const elt = this.element as HTMLCanvasElement;

        const ctx = elt.getContext("2d")!;

        const originPoints = instances.map((instance: IInstance) => {
            const origin = instance.getComponent("transform").getOriginPoint();
            const pos = instance.getComponent("position").getPosition();
            return translatePoint(origin, pos);
        });
        const _drawPoint = (p: Point) => {
            drawPoint(p, ctx!);
        };
        originPoints.forEach(_drawPoint);
    }

    /**
     * draw the collision shapes (circles, polygons, etc.)
     */
    private _redrawCollisionShapes() {
        const insComp = this.page.getComponent("instances");
        const instances = insComp.getAllInstances();

        const elt = this.element as HTMLCanvasElement;

        const ctx = elt.getContext("2d");
        const shapes = instances.map((instance: IInstance) => {
            return instance.getComponent("collision").getTransformedShape();
        });
        shapes.forEach((shape) => {
            shape.drawIn(ctx!);
        });
    }
}

/**
 * draw the grid
 */
export class GridDrawer extends ADebugDrawer implements IDebugDrawer {
    public clear(): void {
        Object.assign(this.element.style, {
            "background-image": "none",
        });
    }

    /**
     * draw the grid
     */
    public redraw(): void {
        const gridComp = this.page.getComponent("grid");
        const size = gridComp.getGridSize();
        Object.assign(this.element.style, {
            ...getCssForGrid(size),
            width: "100%",
            height: "100%",
        });
    }
}

export class BoundingCircle extends ADebugDrawer implements IDebugDrawer {
    constructor(page: IPage, element: HTMLCanvasElement) {
        super(page, element);
    }

    public clear(): void {
        const elt = this.element as HTMLCanvasElement;
        const ctx = elt.getContext("2d")!;
        ctx!.clearRect(0, 0, elt.width, elt.height);
    }

    /**
     * draw the collision shapes
     */
    public redraw(): void {
        const elt = this.element as HTMLCanvasElement;
        const ctx = elt.getContext("2d")!;

        ctx!.clearRect(0, 0, elt.width, elt.height);
        ctx!.fillStyle = BOUNDS_COLOR;
        this._redrawBoxes();
    }

    private _redrawBoxes() {
        const insComp = this.page.getComponent("instances");
        const instances = insComp.getAllInstances();

        const elt = this.element as HTMLCanvasElement;

        const ctx = elt.getContext("2d");
      
        const circles = instances.map((instance: IInstance) => {
            const pos = instance.getComponent("position").getPosition();
            const transComp = instance.getComponent("transform");
            return transComp.getMaximalBoundingCircle(pos);
        });
        circles.forEach((circle) => {
            ctx!.beginPath();
            ctx!.arc(circle.centre.x, circle.centre.y, circle.radius, 0, 2 * Math.PI);
            ctx!.fill();
        });
    }
}

export class ContainmentDrawer extends ADebugDrawer implements IDebugDrawer {
    clear(): void {
        const elt = this.element as HTMLCanvasElement;
        const ctx = elt.getContext("2d");
        ctx!.clearRect(0, 0, elt.width, elt.height);
    }
    redraw(): void {
        const elt = this.element as HTMLCanvasElement;
        const ctx = elt.getContext("2d");

        ctx!.clearRect(0, 0, elt.width, elt.height);
        ctx!.fillStyle = CONTAINMENT_COLOR;

        const insComp = this.page.getComponent("instances");
        const instances = insComp.getAllInstances();

        const shapes = instances
            .map((instance: IInstance) => {
                const shape = instance.getComponent("containment").getImplementedShape();
                return shape;
            })
            .filter((s) => !!s);

        shapes.forEach((shape) => {
            shape.drawIn(ctx!);
        });
    }
}
