

export class KeyCodes{
    public static getCode(k: string): string {
        // Handle single letters (both uppercase and lowercase)
        if (k.length === 1 && ((k >= 'a' && k <= 'z') || (k >= 'A' && k <= 'Z'))) {
            // The code is always the same for both 'a' and 'A' (KeyA)
            return `Key${k.toUpperCase()}`;
        }
        
        // Handle special cases
        switch (k) {
            case "ArrowUp":
            case "ArrowDown":
            case "ArrowLeft": 
            case "ArrowRight":
            case "Space":
                return k;
            case "rightArrow": return "ArrowRight";
            case "leftArrow": return "ArrowLeft";
            case "upArrow": return "ArrowUp";
            case "downArrow": return "ArrowDown";
            default: return k;
        }
    }
    
    public static getKey(k: string): string {
        // Get the key value (which might differ from code)
        switch (k) {
            case "Space": return " ";
            case "rightArrow": return "ArrowRight";
            case "leftArrow": return "ArrowLeft";
            case "upArrow": return "ArrowUp";
            case "downArrow": return "ArrowDown";
            default: return k; // Return the key as is (preserves case for letters)
        }
    }
    
    public static getDisplayText(k: string): string {
        // For special keys, we might want to show a symbol instead of the full name
        const map = {
            "ArrowUp": "↑",
            "ArrowDown": "↓",
            "ArrowLeft": "←",
            "ArrowRight": "→",
            " ": "Space",
            "Space": "Space",
        } as const;

        return (k in map ? map[k as keyof typeof map] : k);
    }
}
