/**
 * UI buttons in play mode
 */

import { IPage } from "../../types/internal";
import { PageSchema } from "../../types/external";
import { ConstructorOf } from "../../types/utils";
import { LRUDButtonScroll, LRButtonScroll, UDButtonScroll } from "./buttons/ButtonUIScroll";
import { MouseUIScroll } from "./scroll/MouseUIScroll";
import { IUIScroll } from "./types";

type Constructor = ConstructorOf<IUIScroll, [PageSchema["ui"]["scroll"], IPage]>;

const mapScrollTypeToHandler: {
    [type in Exclude<PageSchema["ui"]["scroll"], "none">]: Constructor;
} = {
    mouse: MouseUIScroll,
    leftrightupdown: LRUDButtonScroll,
    leftright: LRButtonScroll,
    updown: UDButtonScroll,
};

export const getHandler = (type: keyof typeof mapScrollTypeToHandler, page: IPage): IUIScroll => {
    const Klass = mapScrollTypeToHandler[type];
    return new Klass(type, page);
};
