/**
 * Draggable in play mode
 */

import { IDraggableComponent } from "../../types/external";
import { Schema, Point, IInstance } from "../../types/external";
import { IPage } from "../../types/internal";
import ADraggableComponent from "./ADraggableComponent";
import Salad from "../..";

const ORIGINAL_POSITION_KEY = "__originalPosition";

export default class PlayDraggableComponent
    extends ADraggableComponent
    implements IDraggableComponent
{

    constructor(data: Schema["draggable"], instance: IInstance, page: IPage) {
        super(data, instance, page);
    }

    override onCreated(): void {
        super.onCreated();
        this.storeOriginalPosition()
        if (this.data.enabled) {
            this.enable();
        }
    }

    private storeOriginalPosition(): void {
        // store _originalPosition - used to snap back to where it started
        const pos = this.getInstanceComponent("position");
        const data = this.getInstanceComponent("data");
        let originalPos = data.getForKey(ORIGINAL_POSITION_KEY);
        if(!originalPos){
            originalPos = pos.getPosition();
            data.setValueForKey(ORIGINAL_POSITION_KEY, originalPos);
        }
    }

    override onDestroyed(): void {
        super.onDestroyed();
        this.disable();
    }

    /**
     * Note - event target has to be set correctly on 'e'
     * @param e
     */
    public override startDragging(e: MouseEvent | TouchEvent): void {
        //eg. call moveable dragstart function
        this.dragger!.startDraggingUsingEvent(e);
    }

    /**
     * put it back where it started
     */
    public override resetPosition(): void {
        const originalPos = this.getInstanceComponent("data")!.getForKey(ORIGINAL_POSITION_KEY);
        if (originalPos) {
            this.getInstanceComponent("position").setPosition(originalPos as Point);
        }
    }

    public override disable() {
        super.disable();
        this._removeDraggable();
    }

    protected createDragger(): void {
        this.dragger = Salad.Utils.Dragging.getPlayDragger(this.page, this.instance);
    }

    public override enable() {
        super.enable();

        //clean up the old draggable and events
        this._removeDraggable();
        // make new one
        this.createDragger();
    }
}
