// timers
export class Timer {
    private _id: number;
    constructor(fn: Function, duration: number) {
        this._id = setTimeout(fn, duration);
    }
    kill() {
        clearTimeout(this._id);
    }
}

export class Interval {
    private _id: number;
    constructor(fn: Function, duration: number) {
        this._id = setInterval(fn, duration);
    }
    kill() {
        clearInterval(this._id);
    }
}
