/**
 * Highlight in play mode
 */

import { Schema, IInstance } from "../../types/external";
import AHighlightComponent from "./AHighlightComponent";
import { IPage } from "../../types/internal";
import { Events } from "../../types/external";
import { IHighlighter } from "./types";
import { makeHighlighter } from "./Highlighters";

export default class PlayHighlightComponent extends AHighlightComponent {
    /**
     * this does the actual highlighting
     */
    private _highlight: IHighlighter;
    
    constructor(data: Schema["highlight"], instance: IInstance, page: IPage) {
        super(data, instance, page);
        this.onClick = this.onClick.bind(this);
        this.onAccepted = this.onAccepted.bind(this);
    }

    public override update(data: Schema["highlight"]): void {
        super.update(data);
        this._update();
    }

    /**
     * make the actual highlight
     */
    private _update(): void {
        this._destroyHighlight();
        if(this.data.type !== "none"){
            const layer = this.page.getComponent("layers").getLayerByName("highlight");
            const canvas = layer.getElement() as HTMLCanvasElement;
            this._highlight = makeHighlighter(this.data.type, this.instance, canvas);
            //highlight and then set the highlight type to none so we dont save anything
            this.data.type = "none";
        }
    }  

    /**
     * lifecycle
     */
    public override onCreated(): void {
        super.onCreated();
        this._addListeners();
        if(this.data.type !== "none"){
            this._update();
        }
    }
    /**
     * lifecycle
     */
    public override onDestroyed(): void {
        this._destroyHighlight();
        this._removeListeners();
        super.onDestroyed();
    }

    private onClick(): void {
        this.setHighlight(this.data.onInstanceClick);
    }

    private onAccepted(): void {
        this.setHighlight(this.data.onInstanceAccepted);
    }

    private _addListeners(): void {
        if (this.data.onInstanceClick && this.data.onInstanceClick !== "none") {
            this.instance.events.on(Events.INSTANCE_CLICK, this.onClick);
        }
        if (this.data.onInstanceAccepted && this.data.onInstanceAccepted !== "none") {
            this.instance.events.on(Events.INSTANCE_ACCEPTED, this.onAccepted);
        }
    }

    private _removeListeners(): void {
        this.instance.events.off(Events.INSTANCE_CLICK, this.onClick);
        this.instance.events.off(Events.INSTANCE_ACCEPTED, this.onAccepted);
    }

    /**
     * in play mode we can change the highlight type and it actually makes the highlight too
     * @param type
     */
    public override setHighlight(type: Schema["highlight"]["type"]): void {
        super.setHighlight(type);
        this._update();
    }

    private _destroyHighlight() {
        if (this._highlight) {
            this._highlight.destroy();
            this._highlight = null;
        }
    }
}
