/**
 * Abstract class for a text component
 */

import { ITextComponent, IInstance } from "../../types/external";
import { Schema } from "../../types/external";
import { IPage } from "../../types/internal";
import { AComponent } from "../AComponent";
import { textArea, textContainer } from "../../utils/domElementFactory";
import { InstanceEventsMap, Events } from "../../types/external";
import { textTypes } from "../../schema/schema";
import { getLayoutHelper } from "./TextLayout";

type ChildPosition = Schema["text"]["position"];
export default abstract class ATextComponent extends AComponent<"text"> implements ITextComponent {
    // the container element
    protected element: HTMLElement | undefined;

    // the element you type in
    protected textElement: HTMLTextAreaElement | undefined;

    //a div that floats on top to prevent editing and to allow easy dragging
    protected cover: HTMLElement | undefined;

    public name: "text" = "text";

    constructor(data: Schema["text"], instance: IInstance, page: IPage) {
        super(data, instance, page);
        this.onComponentUpdated = this.onComponentUpdated.bind(this);
        this.onInput = this.onInput.bind(this);
    }

    public fitTextSize(): void {
        const sizeComp = this.instance.getComponent("size");
        const w = this.textElement!.scrollWidth;
        const h = this.textElement!.scrollHeight;
        sizeComp.setSize(w, h);
    }

    public getText(): string {
        return this.data.value;
    }

    public setText(value: string): void {
        this.data.value = value;
        this._updateValue();
    }

    public focus():void{
        this.textElement!.focus();
        const length = this.textElement.value.length;
        this.textElement.setSelectionRange(length, length);
    }

    public setMaxLength(length: number): void{
        this.data.maxlength = length;
        this._updateMaxLen();
    }

    /**
     * set the type - eg. speech bubble, plain text etc
     * @param type
     */
    public setType(type: Schema["text"]["type"]): void {
        this.data.type = type;
        this._updateTypeUI();
    }

    public getType(): Schema["text"]["type"] {
        return this.data.type;
    }

    /**
     * get the container
     * @returns
     */
    public getElement(): HTMLElement {
        return this.element!;
    }

    public getTextArea(): HTMLTextAreaElement {
        return this.textElement!;
    }

    override getDependencies() {
        return ["render"] as const;
    }

    /**
     * Destroy the html elements
     */
    protected _destroyElement(): void {
        if (this.textElement) {
            this.textElement.removeEventListener("input", this.onInput);
            this.textElement.remove();
            this.textElement = undefined;
        }
        if (this.cover) {
            this.cover.remove();
            this.cover = undefined;
        }
        if (this.element) {
            this.element.remove();
            this.element = undefined;
        }
    }

    /**
     * lifecycle
     */
    public override onDestroyed(): void {
        super.onDestroyed();
        this._destroyElement();
        this.instance.events.off(Events.COMPONENT_UPDATE, this.onComponentUpdated);
    }

    /**
     * lifecycle
     */
    public override onCreated() {
        if (this.data.enabled) {
            this.addElement();
            this._updateValue();
            this._updateTypeUI();
            this._updateMaxLen();
            this._updateMaxLen();
            this._updatePosition();
        }
        this._listenToSizeChange();
    }

    private _listenToSizeChange() {
        if (this.data.enabled) {
            this.instance.events.on(Events.COMPONENT_UPDATE, this.onComponentUpdated);
        } else {
            this.instance.events.off(Events.COMPONENT_UPDATE, this.onComponentUpdated);
        }
    }

    /**
     * When the size of the instance changes, update the shape
     * @param eventData
     */
    protected onComponentUpdated(eventData: InstanceEventsMap[typeof Events.COMPONENT_UPDATE]): void {
        if(eventData.component.name === "size"){
            this._updateTypeUI();
        }
    }

    /**
     * user typed
     * @param event
     */
    private onInput(event: Event): void {
        this.data.value = (event.target as HTMLInputElement).value;
    }

    protected updateCover(){
        // disable the text area
        if(this.getisEditable()){   
            if(this.cover){
                this.cover.remove();
                this.cover = undefined;
            }
        }
        else{
            if(!this.cover){
                this.cover = this.getCover();
            }
        }   
    }

    protected abstract getCover(): HTMLElement;

    protected abstract getisEditable(): boolean;

    /**
     * add html elements
     */
    protected addElement(): void {
        const parent = this.getInstanceComponent("render").getElement();
        this.element = textContainer(parent);
        this.textElement = textArea(this.element, this.data);
        this.textElement.addEventListener("input", this.onInput);
        this.updateCover();
    }

    /**
     * Updated the data
     * @param data
     */
    public override update(data: Schema["text"]): void {
        super.update(data);
        this._destroyElement();
        if (this.data.enabled) {
            this.addElement();
            this._updateValue();
            this._updateTypeUI();
            this._updateMaxLen();
            this._updatePosition();
        }
        this._listenToSizeChange();
    }

    public setEditable(editable: boolean): void {
        if (this.data.editable !== editable) {
            this.data.editable = editable;
            this._destroyElement();
            this.addElement();
            this._updateValue();
            this._updateTypeUI();
            this._updatePosition();
        }
    }

    private _updatePosition() {
        Object.assign(this.element!.style, {
            ...this.data.position,
        });
    }

    private _updateMaxLen():void {
        if(this.textElement){
            this.textElement.maxLength = this.data.maxlength;
        }
    }

    private _updateTypeUI(): void {
        textTypes.forEach((type) => {
            this.element!.classList.remove("component-text-" + type);
        });
        if (this.data.type !== "plain") {
            this.element!.classList.add("component-text-" + this.data.type);
        }
        const layoutHelper = getLayoutHelper(this, this.instance);
        layoutHelper.redraw();
    }

    /**
     * change the text
     */
    private _updateValue() {
        const translator = this.getTranslator();
        const value = this.data.translationKey ? translator.translate(this.data.translationKey) : this.data.value;
        this.textElement!.value = value;
        const fontSize = this.data.textFormat.fontSize || 20;
        const defaultFonts = ATextComponent.DEFAULT_FONT_STACK;
        
        const fontFamily = this.data.textFormat.fontFamily || defaultFonts[0];
        const fontStack = [
            fontFamily,
            ...defaultFonts
        ].join(", ");

        const textAlign = this.data.textFormat.textAlign || "left";
        const color = this.data.textFormat.color || "black";

        Object.assign(this.textElement!.style, {
            fontSize: fontSize + "px",
            fontFamily: fontStack,
            textAlign: textAlign,
            fontWeight: 700,
            color,
        });
        this.textElement!.setAttribute("placeholder", this.data.placeholder);
        this.textElement!.style.setProperty("font-family", fontStack, "important");
    }

    private static DEFAULT_FONT_STACK = [
        "Nunito",
        "'Helvetica Neue'",
        "Arial",
        "Helvetica",
        "sans-serif"
    ]

    public setChildPosition(pos: ChildPosition): void {
        this.data.position = pos;
        this._updatePosition();
    }

    public getChildPosition(): ChildPosition {
        return this.data.position;
    }
}
