/**
 * This file contains the factories for creating the page components.
 */

import PlayCameraComponent from "./camera/PlayCameraComponent";
import EditCameraComponent from "./camera/EditCameraComponent";
import PageLayersComponent from "./layers/PageLayersComponent";
import PageDataComponent from "./data/PageDataComponent";
import EditPageSoundComponent from "./sound/EditPageSoundComponent";
import PlayPageSoundComponent from "./sound/PlayPageSoundComponent";
import PageBackgroundComponent from "./background/PageBackgroundComponent";
import PlayInstancesComponent from "./instances/PlayInstancesComponent";
import EditInstancesComponent from "./instances/EditInstancesComponent";
import DebugComponent from "./debug/DebugComponent";
import TransitionsComponent from "./transitions/TransitionsComponent";
import ScriptComponent from "./script/ScriptComponent";
import PageLayoutComponent from "./layout/PageLayoutComponent";
import PlayTickerComponent from "./ticker/PlayTickerComponent";
import EditTickerComponent from "./ticker/EditTickerComponent";
import PageTimersComponent from "./timers/PageTimersComponent";
import EditPageCollisionsComponent from "./collisions/EditPageCollisionsComponent";
import PlayPageCollisionsComponent from "./collisions/PlayPageCollisionsComponent";
import EditUIComponent from "./ui/EditUIComponent";
import PlayUIComponent from "./ui/PlayUIComponent";
import EditGridComponent from "./grid/EditGridComponent";
import PlayGridComponent from "./grid/PlayGridComponent";
import PageIdentityComponent from "./identity/PageIdentityComponent";
import PageScreenBackgroundComponent from "./screenbackground/PageScreenBackgroundComponent";
import EditDomUpdateComponent from "./domupdate/EditDomUpdateComponent";
import PlayDomUpdateComponent from "./domupdate/PlayDomUpdateComponent";
import PageModalsListComponent from "./modalslist/PageModalsListComponent";
import PageSelectionComponent from "./selection/PageSelectionComponent";
import EditEventsComponent from "./events/EditEventsComponent";
import CodeRunnerComponent from "./coderunner/CodeRunnerComponent";
import PlayEventsComponent from "./events/PlayEventsComponent";
import PlayPageDrawingComponent from "./drawing/PlayPageDrawingComponent";
import EditPageDrawingComponent from "./drawing/EditPageDrawingComponent";
import DragNDropComponent from "./dragndrop/DragNDropComponent";
import { createPageComponentFactory } from "./PageComponentFactory";
import { ActivityMode } from "../types/internal";
import { PageComponentName } from "../types/external";
import { MapPageComponentNameToClass } from "../types/internal";
import PageSettingsComponent from "./settings/PageSettingsComponent";
import EditPageUndoComponent from "./undo/EditPageUndoComponent";
import PlayPageUndoComponent from "./undo/PlayPageUndoComponent";
import EditPageKeyboardComponent from "./keyboard/EditPageKeyboardComponent";
import PlayPageKeyboardComponent from "./keyboard/PlayPageKeyboardComponent";
import PlayPageHighlightComponent from "./highlight/PlayPageHighlightComponent";
import EditPageHighlightComponent from "./highlight/EditPageHighlightComponent";

const defaultMap = {
    background: PageBackgroundComponent,
    script: ScriptComponent,
    data: PageDataComponent,
    layers: PageLayersComponent,
    debug: DebugComponent,
    screenbackground: PageScreenBackgroundComponent,
    modalslist: PageModalsListComponent,
    dragndrop: DragNDropComponent,
    timers: PageTimersComponent,
    identity: PageIdentityComponent,
    selection: PageSelectionComponent,
    coderunner: CodeRunnerComponent,
    transitions: TransitionsComponent,
    settings: PageSettingsComponent,
    layout: PageLayoutComponent,
};

const editMap = {
    ...defaultMap,
    collisions: EditPageCollisionsComponent,
    sound: EditPageSoundComponent,
    instances: EditInstancesComponent,
    camera: EditCameraComponent,
    domupdate: EditDomUpdateComponent,
    ticker: EditTickerComponent,
    grid: EditGridComponent,
    drawing: EditPageDrawingComponent,
    events: EditEventsComponent,
    highlight: EditPageHighlightComponent,
    ui: EditUIComponent,
    undo: EditPageUndoComponent,
    keyboard: EditPageKeyboardComponent
};

const playMap = {
    ...defaultMap,
    collisions: PlayPageCollisionsComponent,
    instances: PlayInstancesComponent,
    sound: PlayPageSoundComponent,
    domupdate: PlayDomUpdateComponent,
    ticker: PlayTickerComponent,
    camera: PlayCameraComponent,
    grid: PlayGridComponent,
    drawing: PlayPageDrawingComponent,
    highlight: PlayPageHighlightComponent,
    events: PlayEventsComponent,
    ui: PlayUIComponent,
    undo: PlayPageUndoComponent,
    keyboard: PlayPageKeyboardComponent
};

export const getDefaultPageComponentFactory = (mode: ActivityMode) => {
    return (mode === "edit") ? createPageComponentFactory(editMap) : createPageComponentFactory(playMap);
}

export const getPageComponentFactoryForKeys = (keys: PageComponentName[], mode: ActivityMode) => {
    keys = [
        "domupdate", // always add domupdate, the rest depend on it
        ...keys
    ]
    let map:MapPageComponentNameToClass = {};
    keys.forEach((key) => {
        map = {
            ...map,
            [key]: mode === "edit" ? editMap[key] : playMap[key]
        }
    });
    return createPageComponentFactory(map);
}