/**
 * when the velocity changes, change the rotation
 * and apply friction
 */

import { IInstance, Schema } from "../../types/external";
import { IPage } from "../../types/internal";
import { InstanceEventsMap, Events } from "../../types/external";
import AMovementComponent from "./AMovementComponent";

export default class PlayMovementComponent extends AMovementComponent {
    constructor(data: Schema["movement"], instance: IInstance, page: IPage) {
        super(data, instance, page);
        this.onComponentUpdate = this.onComponentUpdate.bind(this);
        this.onEnterFrame = this.onEnterFrame.bind(this);
    }

    public override update(data: Schema["movement"]): void {
        super.update(data);
    }

    private onEnterFrame() {
        if (this.data.friction !== 1) {
            const velComponent = this.getInstanceComponent("velocity");
            const speed = velComponent!.getSpeed();
            if (speed !== 0) {
                velComponent!.setSpeed(speed * this.data.friction);
            }
        }
        if (this.data.angularfriction !== 1) {
            const angVelComponent = this.getInstanceComponent("angularvelocity");
            const angVel = angVelComponent!.getAngularVelocity();
            angVelComponent!.setAngularVelocity(angVel * this.data.angularfriction);
        }
    }

    private makeRotationMatchVelocity() {
        const velocityComp = this.instance.getComponent("velocity");
        const transComponent = this.instance.getComponent("transform");
        const speed = velocityComp!.getSpeed();
        if (speed > 0) {
            const velocity = velocityComp!.getVelocity();
            const angle = Math.atan2(velocity.y, velocity.x);
            const newRotation = (angle * 180) / Math.PI - this.data.offsetAngle;
            transComponent!.setRotation(newRotation);
        }
    }

    private makeVelocityMatchRotation() {
        const velocityComp = this.instance.getComponent("velocity");
        const transComponent = this.instance.getComponent("transform");
        const angle = ((transComponent!.getRotation() + this.data.offsetAngle) * Math.PI) / 180;
        const speed = velocityComp!.getSpeed();
        const newVelocity = {
            x: speed * Math.cos(angle),
            y: speed * Math.sin(angle),
        };
        velocityComp!.setVelocity(newVelocity);
    }

    private onComponentUpdate(eventData: InstanceEventsMap[typeof Events.COMPONENT_UPDATE]) {
        if (
            eventData.component.name === "velocity" &&
            this.data.match === "rotationmatchesvelocity"
        ) {
            // velocity has changed, make angle match
            this.makeRotationMatchVelocity();
        } else if (
            eventData.component.name === "transform" &&
            eventData.payload &&
            eventData.payload.key === "rotation" &&
            this.data.match === "velocitymatchesrotation"
        ) {
            // angle has changed, make velocity match
            this.makeVelocityMatchRotation();
        }
    }

    public override onCreated(): void {
        super.onCreated();
        if (this.data.friction !== 1 || this.data.angularfriction !== 1) {
            this.page.events.on(Events.ENTER_FRAME, this.onEnterFrame);
        }
        if (this.data.match !== "none") {
            this.instance.events.on(Events.COMPONENT_UPDATE, this.onComponentUpdate);
            if (this.data.match === "rotationmatchesvelocity") {
                this.makeRotationMatchVelocity();
            } else if (this.data.match === "velocitymatchesrotation") {
                this.makeVelocityMatchRotation();
            }
        }
    }

    public override onDestroyed(): void {
        super.onDestroyed();
        this.page.events.off(Events.ENTER_FRAME, this.onEnterFrame);
        this.instance.events.off(Events.COMPONENT_UPDATE, this.onComponentUpdate);
    }
}
