/**
 * events component
 */
import { ITypedEventEmitter, IInstance } from "../../types/external";
import { TypedEventEmitter } from "../../utils/TypedEventEmitter";

export type HoverEventMap = {
    mouseover: IInstance;
    mouseout: IInstance;
};

export interface IMouseHoverManager extends ITypedEventEmitter<HoverEventMap> {
    update(instanceOver: IInstance | undefined): void;
    destroy(): void;
}

export class MouseHoverManager
    extends TypedEventEmitter<HoverEventMap>
    implements IMouseHoverManager
{
    private currentInstance: IInstance | undefined = undefined;

    constructor() {
        super();
    }

    public update(instanceOver: IInstance | undefined): void {
        if (this.currentInstance === instanceOver) {
            // nothing changed. Either the same one is hovered or they are both undefined
        } else {
            // something changed
            if (this.currentInstance && !instanceOver) {
                // defined -> undefined
                this.emit("mouseout", this.currentInstance);
            } else if (!this.currentInstance && instanceOver) {
                // undefined -> defined
                this.emit("mouseover", instanceOver);
            } else {
                // defined -> defined, but different
                this.emit("mouseout", this.currentInstance);
                this.emit("mouseover", instanceOver);
            }
        }
        this.currentInstance = instanceOver;
    }

    public destroy(): void {
        this.currentInstance = undefined;
    }
}

export const getMouseHoverManager = (): IMouseHoverManager => {
    return new MouseHoverManager();
};
