/**
 * Class that represents a droppable component, that you can drop other objects into
 */

import ADroppableComponent from "./ADroppableComponent";
import { IInstance } from "../../types/external";
import { Schema } from "../../types/external";
import { IPage } from "../../types/internal";
import { droppableCounter } from "../../utils/domElementFactory";
import { getDroppableContent, IDroppableContent, DroppableEventMap } from "./DroppableContent";
import { PageEventsMap, Events } from "../../types/external";
import { GetInstancesAsync, IGetInstancesAsync } from "../../utils/GetInstancesAsync";
import { DropSuccessDecorator } from "./DropSuccessDecorator";

export default class PlayDroppableComponent extends ADroppableComponent {
    // show the number of contents
    private _counter: HTMLElement;

    // the contents
    private _content: IDroppableContent;

    private _instanceLoader: IGetInstancesAsync;

    constructor(data: Schema["droppable"], instance: IInstance, page: IPage) {
        super(data, instance, page);
    }

    private _addContent() {
        this._content = getDroppableContent();
        this._content.on("change", this.onContentChange);

        if (this.data.contents.length >= 1) {
            this._instanceLoader = new GetInstancesAsync(this.page, this.data.contents);
            this._instanceLoader.on("loaded", (instances: IInstance[]) => {
                this._instanceLoader.removeAllListeners();
                this._content.setList(instances);
                this._updateCount();
            });
            this._instanceLoader.load();
        }
    }

    /**
     * show the number of things inside
     */
    private _addCounter() {
        if (this.data.displayCount !== "none") {
            const parent = this.getInstanceComponent("render").getElement();
            this._counter = droppableCounter(parent);
            this._updateCount();
        }
    }

    /**
     * lifecycle
     */
    public override onDestroyed(): void {
        super.onDestroyed();
        if (this._instanceLoader) {
            this._instanceLoader.removeAllListeners();
            this._instanceLoader.destroy();
        }
        if (this._content) {
            this._content.off("change", this.onContentChange);
            this._content.destroy();
        }
        if (this._counter) {
            this._counter.remove();
        }
    }

    /**
     * lifecycle
     */
    public override onCreated() {
        super.onCreated();
        this.onContentChange = this.onContentChange.bind(this);
        if (this.data!.enabled) {
            this._addContent();
            this._addCounter();
        }
    }

    /**
     * when the content changes we emit and event.
     * you could listen to these to see what the user dropped
     * @param eventData
     */
    private onContentChange(eventData: DroppableEventMap["change"]): void {
        this.data.contents = this._content.getIds();

        const contentEventData: PageEventsMap[typeof Events.CONTENT_CHANGE] = {
            type: eventData.type,
            contents: eventData.instances,
            instance: eventData.instance,
            target: this.instance,
        };

        this.page.events.emit(Events.CONTENT_CHANGE, contentEventData);
        this.instance.events.emit(Events.CONTENT_CHANGE, contentEventData);

        this._updateCount();
    }

    public override addContent(instance: IInstance): void {
        this._content.add(instance);
        new DropSuccessDecorator(this.instance, instance).snapIntoPosition();
    }

    /**
     * show the number of things inside
     */
    private _updateCount() {
        if (this.data.displayCount !== "none") {
            this._counter.innerText = "" + this.data.contents.length;
        }
    }

    public override removeContent(instance: IInstance): void {
        if (this._content) {
            this._content.remove(instance);
        }
    }

    /**
     * Reached capacity?
     * @returns
     */
    private isFull(): boolean {
        const currentCount = this._content.getNames().length;
        return currentCount >= this.data.capacity;
    }

    /**
     * Will this droppable accept the draggable?
     *
     * @param droppedInstance
     * @returns boolean
     */
    public override getWillAcceptInstance(droppedInstance: IInstance): boolean {
        const currentNames = this._content.getNames();

        let instanceToEject: IInstance | undefined = undefined;

        if (this.data.enabled) {
            //ok, it is possible...
            if (this.isFull()) {
                // if full but we can eject then find the one to eject
                if (this.data.eject) {
                    const firstName = currentNames[0];
                    instanceToEject = this.page.instances.getInstanceByName(firstName) as IInstance;
                }
                else {
                    // else we are not allowed at all
                    return false;
                }
            }

            // Ok, next, check if we can actually accept this. Eg. some might only accept certain instances
            const acceptanceFn = this.getAcceptanceFunction();
            if (!acceptanceFn(droppedInstance)) {
                return false;
            }

            //ok, we might accept this - check if it is in the right place
            const success = new DropSuccessDecorator(this.instance, droppedInstance).getSuccess();

            if (!success) {
                return false;
            }
            // ok, we can accept it but first check if we should kick other ones out
            if (instanceToEject) {
                // eject it
                this.removeContent(instanceToEject);
                instanceToEject.getComponent("draggable").resetPosition();
            }
            // and return true
            return true;
        } else {
            return false;
        }
    }
}
