/**
 * Is this element selected - edit mode
 */

import { ISelectedComponent, Schema, IInstance } from "../../types/external";
import { IPage } from "../../types/internal";
import { AComponent } from "../AComponent";

export default class EditSelectedComponent
    extends AComponent<"selected">
    implements ISelectedComponent
{
    public name: "selected" = "selected";

    constructor(data: Schema["selected"], instance: IInstance, page: IPage) {
        super(data, instance, page);
    }

    /**
     * in edit mode when an object becomes part of the group we indicate it with styling
     * note that there is no concept of a group of elements that can be moved/eeited together
     * there is always at most one group, consisting of all elements that are grouped
     * @param grouped
     */
    public setGrouped(grouped: boolean): void {
        const renderComponent = this.getInstanceComponent("render")!;
        const elt = renderComponent.getElement();
        if (grouped) {
            elt.classList.add("editor-grouped");
        } else {
            elt.classList.remove("editor-grouped");
        }
    }

    /**
     * in edit mode when an object is selected we initiate the draggable, otherwise destroy it
     * @param selected
     */
    public setSelected(selected: boolean): void {
        const draggableComponent = this.getInstanceComponent("draggable");
        if (draggableComponent) {
            if (selected) {
                draggableComponent.activate();
            } else {
                draggableComponent.deactivate();
            }
        }
    }

    override getDependencies() {
        return ["render", "draggable"] as const;
    }
}
