/**
 * transform component. Handles rotation, scale, and origin
 */

import { IInstance, Events } from "../../../types/external";
import { IPage } from "../../../types/internal";
import { IInputKeyListener } from "./AKeyListener";
import { getAnimForKeys } from "./Utils";

export class ArrowKeyListener implements IInputKeyListener {
    constructor(
        private instance: IInstance,
        private page: IPage,
        private duration: number,
        private amount: number,
    ) {
        this.onKeyDown = this.onKeyDown.bind(this);
        this.initListeners();
    }
    public destroy(): void {
        this.page.events.off(Events.KEY_DOWN, this.onKeyDown);
    }
    private onKeyDown(eventData: { key: string }): void {
        let { anim, settings } = getAnimForKeys(eventData.key, this.duration, this.amount, {
            up: "ArrowUp",
            down: "ArrowDown",
            left: "ArrowLeft",
            right: "ArrowRight",
        });
        if (anim) {
            this.instance.getComponent("animation").playAnimation(anim, settings);
        }
    }
    private initListeners(): void {
        this.page.events.on(Events.KEY_DOWN, this.onKeyDown);
    }
}
