import { DrawingToolSetting } from "../../../types/external";
import { IDrawing } from "../types";
import { getTool } from "./tools/SimpleCanvasTools";
import { DrawingArea } from "./tools/types";
import { ISimpleBrush } from "./tools/types";
import {IAssetManager} from "../../../types/internal";
export class SimpleCanvasDrawing implements IDrawing {
    /**
     * The current brush
     */
    private _brush: ISimpleBrush | undefined;

    /**
     * current tool setting
     */
    private _toolSetting: DrawingToolSetting;

    constructor(
        private surface: "paper" | "empty",
        private drawingArea: DrawingArea,
        private assetManager?: IAssetManager,
    ) {
        //@ts-ignore
        this.drawingArea.canvas.getContext("2d").willReadFrequently = true;
    }

    /**
     *
     * @param setting
     */
    public updateCurrentToolSettings(setting: Partial<DrawingToolSetting>): void {
        this._toolSetting = {
            ...this._toolSetting,
            ...setting,
        };
    }

    /**
     * wipe it
     */
    public clear() {
        const ctx = this.drawingArea.canvas.getContext("2d");
        ctx!.clearRect(0, 0, this.drawingArea.canvas.width, this.drawingArea.canvas.height);
    }

    /**
     * get the new brush
     * @returns
     */
    private getNewBrush(): ISimpleBrush {
        return getTool(this.surface, this.drawingArea, this._toolSetting);
    }

    public destroy(): void {
        this.clear();
    }

    /**
     * Get base64
     * @returns
     */
    public getData(): string {
        return this.drawingArea.canvas.toDataURL();
    }

    /**
     * Load base64 in
     * @param base64
     */
    public async setData(key: string): Promise<void> {
        this.clear();
        if (key) {
            const image = new Image();
            image.onload = () => {
                const ctx = this.drawingArea.canvas.getContext("2d");
                ctx!.drawImage(
                    image,
                    0,
                    0,
                    this.drawingArea.canvas.width,
                    this.drawingArea.canvas.height,
                );
            }
            const src = await this.assetManager.getPathForKey(key);
            this.assetManager.loadImg(image, src);
        }
    }

    /**
     * mouse down
     * @param x
     * @param y
     */
    public onDown(x: number, y: number) {
        this._brush = this.getNewBrush();
        this._brush.start(x, y);
    }

    /**
     * mouse dragged - eg. draw a line
     * @param x
     * @param y
     */
    public onDrag(x: number, y: number) {
        this._brush!.move(x, y);
    }

    /**
     * mouse up
     */
    public onUp() {
        if (this._brush) {
            this._brush.end();
            this._brush = undefined;
        }
    }
}
