/**
 * Text component in edit mode.
 * Authors can edit the text by double clicking on it.
 */

import { Schema, IInstance, Events } from "../../types/external";
import { IPage } from "../../types/internal";
import ATextComponent from "./ATextComponent";
import { PageEventsMap } from "../../types/external";
import { cover } from "../../utils/domElementFactory";
export default class EditTextComponent extends ATextComponent {

    private _editing: boolean = false;

    constructor(data: Schema["text"], instance: IInstance, page: IPage) {
        super(data, instance, page);
    }

    private addEditListeners() {
        this.instance.events.on(Events.INSTANCE_DBLCLICK, this.onDblClick);
        this.page.events.on(Events.PAGE_CLICK, this.onPageClick);
    }

    private removeEditListeners() {
        this.instance.events.off(Events.INSTANCE_DBLCLICK, this.onDblClick);
        this.page.events.off(Events.PAGE_CLICK, this.onPageClick);
    }

    protected getCover(){
        return cover(this.element!);
    }

    protected override addElement(): void {
        super.addElement();
        this.addEditListeners();
    }

    protected override _destroyElement(): void {
        super._destroyElement();
        this.removeEditListeners();
    }

    protected override getisEditable(): boolean {
        return this._editing;
    }

    private onDblClick() {
        this._editing = true;
        this.updateCover();
        this.textElement!.focus();
        setTimeout(() => {
            this.textElement!.focus();
        });
    }

    private onPageClick(eventData: PageEventsMap[typeof Events.PAGE_CLICK]) {
        if (this._editing && !eventData.targets.includes(this.instance)) {
            this._editing = false;
            this.updateCover();
        }
    }

    override onCreated(): void {
        this.onDblClick = this.onDblClick.bind(this);
        this.onPageClick = this.onPageClick.bind(this);
        super.onCreated();
    }
}
