import { Events } from "../../types/external";
import * as Utils from "../../utils";

const stringifyObjectForCode = (Obj: any) => {
    let s = "";
    const keys = Object.keys(Obj);    
    keys.forEach((key) => {
        const entry = Obj[key as keyof typeof Obj];
        if(typeof entry === 'function'){
            s += `${key}: ${entry.toString()},\n`
        }
        else if(typeof entry === 'object'){
            s += `${key}: { ${stringifyObjectForCode(entry)} },\n`
        }
    })
    return s;
}

const UtilsStr = `
const Utils = {
    ${stringifyObjectForCode(Utils)}
};`

const NAMESPACE = `
${UtilsStr}
Salad = {
    Events: ${JSON.stringify(Events)},
    Utils: Utils,
}
`;

const CALL_FUNCTION_ONCE = `
if(typeof(onFirstCreated) === 'function'){
    onFirstCreated.apply(this, arguments)
}
`;

const CALL_FUNCTION = `
if(typeof(onCreated) === 'function'){
    onCreated.apply(this, arguments)
}
`;

export class CodeGenerator {
    getFunctionToExecute(transpiledContent:string | undefined, hasRunOnce: boolean): Function {
        if (!transpiledContent) {
            return new Function("getFunctionToExecute", "");
        }

        let jsCode = transpiledContent;

        jsCode = `
${NAMESPACE}
${jsCode}
${hasRunOnce ? "" : CALL_FUNCTION_ONCE}
${CALL_FUNCTION}
        `;

        jsCode = jsCode.replace(/\r/g, "");

        //make a function with the code in
        return new Function("getFunctionToExecute", jsCode);
    }
}

