import { IPage } from "../../types/internal";
import { IInstance } from "../../types/external";
import { DrawingToolSetting, IPageDrawingDecorator } from "../../types/external";
import { Events } from "../../types/external";
import { getCursorInfoForTool } from "./PageDrawingCursors";

export class PageDrawingDecorator implements IPageDrawingDecorator {
    private drawingSettings: DrawingToolSetting | undefined = undefined;

    constructor(private page: IPage) {}

    /**
     * @returns true if the page or any instance on the page has drawing enabled
     */
    public getNeedsDrawingTools(): boolean {
        const enabledOnPage = this.page.getComponent("drawing").getEnabled();
        if(enabledOnPage) {
            return true;
        }
        const instanceWithDrawingEnabled = this.page.instances.findInstanceByFilter(
            (instance: IInstance) => {
                return instance.getComponent("drawing").getEnabled();
            },
        );
        return !!instanceWithDrawingEnabled;
    }

    public getTools():string{
        return this.page.getComponent("drawing").getTools();
    }

    public getCurrentDrawingSetting(): DrawingToolSetting {
        return this.drawingSettings!;
    }

    /**
     * The user chose a tool to draw with.
     * Store it and inform everyone interested
     * @param toolSetting
     */
    public setDrawingSettings(toolSetting: DrawingToolSetting): void {
        this.drawingSettings = toolSetting;
        this.page.events.emit(Events.DRAWING_TOOL_CHANGE, {
            toolSetting,
        });
    }

    public clearCursor(): void {
        // TODO
    }

    public async setCursorForTool(instance: IInstance): Promise<void>{
        const toolSetting = this.getCurrentDrawingSetting();
        const cursorInfo = await getCursorInfoForTool(toolSetting, this.page.getAssetManager());
        instance.getComponent("cursor").setCursor(cursorInfo.path, cursorInfo.offset);
    }
}
