import { Schema, IDraggableComponent, IInstance, Events } from "../../types/external";
import { IPage } from "../../types/internal";
import ADraggableComponent from "./ADraggableComponent";
import { draggableIndicator } from "../../utils/domElementFactory";
import Salad from "../..";
export default class EditDraggableComponent
    extends ADraggableComponent
    implements IDraggableComponent
{
    private _element: HTMLElement;

    constructor(data: Schema["draggable"], instance: IInstance, page: IPage) {
        super(data, instance, page);
    }

    public override onCreated(): void {
        super.onCreated();
        this.page.events.on(Events.PAGE_RESIZE, this.onPageSizeChange);
        this._updateElement();
    }

    override onDestroyed() {
        super.onDestroyed();
        this._removeDraggable();
        this.page.events.off(Events.PAGE_RESIZE, this.onPageSizeChange);
    }

    public override resetPosition(): void {
        // not used in edit mode
    }

    public override startDragging(e: MouseEvent | TouchEvent): void {
        // not used in edit mdoe
    }

    protected createDragger(): void {
        this.dragger = Salad.Utils.Dragging.getEditDragger(this.page, this.instance);
    }

    public override update(data: Schema["draggable"]): void {
        super.update(data);
        this._updateElement();
    }

    /**
     * in edit mode we use activate/deactivate to create/destroy the dragger
     */
    public override activate(): void {
        this.createDragger();
    }

    public override deactivate(): void {
        this._removeDraggable();
    }

    public override disable() {
        super.disable();
        this._updateElement();
    }

    public override enable() {
        super.enable();
        this._updateElement();
    }

    private _updateElement() {
        if (this._element) {
            this._element.remove();
        }
        if (this.data.enabled) {
            this._element = draggableIndicator();
            const parent = this.getInstanceComponent("render").getElement();
            parent.appendChild(this._element);
        }
    }
}
