/**
 * size component (width, height)
 */

import { ISizeComponent, IInstance, Schema, Size } from "../../types/external";
import { IPage } from "../../types/internal";
import { AComponent } from "../AComponent";
import { CSSDomUpdate } from "../../types/external";
export default class SizeComponent extends AComponent<"size"> implements ISizeComponent {
    public name: "size" = "size";

    constructor(data: Schema["size"], instance: IInstance, page: IPage) {
        super(data, instance, page);
    }

    override getDependencies() {
        return ["render"] as const;
    }

    public getSize(): Size {
        return {
            width: this.data.width,
            height: this.data.height,
        };
    }

    public override update(data: { width?: number; height?: number }): void {
        const lockAspectRatio = this.instance.getComponent("transform").getLockAspectRatio();
        if (lockAspectRatio > 0) {
            // force the aspect ratio to be locked
            // in the UI you can only change one at a time anyway
            if (typeof data.height === "undefined" && typeof data.width !== "undefined") {
                data.height = data.width / lockAspectRatio;
            } else if (typeof data.width === "undefined" && typeof data.height !== "undefined") {
                data.width = data.height * lockAspectRatio;
            }
        }
        super.update(data);
        this.updateElementSize();
    }

    public getGridSize(round?: boolean): {width: number, height: number}{
        const grid = this.page.getComponent("grid");
        const size = grid.getGridSize();
        if(round){
            return {
                width: Math.round(this.data.width / size),
                height: Math.round(this.data.height / size),
            };
        }
        else{
            return {
                width: this.data.width / size,
                height: this.data.height / size,
            };
        }
    }

    public setGridSize(w: number, h: number): void{
        const grid = this.page.getComponent("grid");
        const size = grid.getGridSize();
        this.setSize(w * size, h * size);
    }

    public setSize(width: number, height: number) {
        this.data = {
            ...this.data,
            width,
            height,
        };
        this.updateElementSize();
    }

    /**
     * update the size of the element
     */
    private updateElementSize() {
        const element = this.getInstanceComponent("render").getElement();
        const css:CSSDomUpdate["css"] = {
            width: `${this.data.width}px`,
            height: `${this.data.height}px`,
        }
        
        this.page.getComponent("domupdate").addCSSUpdate({
            element,
            css
        });
    }

    override onCreated() {
        super.onCreated();
        this.updateElementSize();
    }
}
