/**
 * Events in play mode - startListeningToDomEvents and KeyEvents
 */

import { IPage } from "../../types/internal";
import { PageSchema, Events } from "../../types/external";
import AEventsComponent from "./AEventsComponent";
import { IKeyboardHandler, getKeyboardHandler, VirtualKeyboardEvent } from "./KeyboardHandler";
import { PlayPointerEventHandler } from "./pointer/PlayPointerEventHandler";
import { getResizeEventHandler } from "./ResizeEventHandler";
export default class PlayEventsComponent extends AEventsComponent {
    public name: "events" = "events";
    private keyboardHandler: IKeyboardHandler;

    constructor(data: PageSchema["events"], page: IPage) {
        super(data, page);
        this.onKeyDown = this.onKeyDown.bind(this);
        this.onKeyUp = this.onKeyUp.bind(this);
        this.keyboardHandler = getKeyboardHandler();
    }

    public override getDependencies() {
        return ["coderunner"] as const;
    }

    private onKeyDown(e: VirtualKeyboardEvent): void {
        this.page.events.emit(Events.KEY_DOWN, {
            code: e.code,
            key: e.key,
            first: e.first,
        });
    }

    private onKeyUp(e: VirtualKeyboardEvent): void {
        this.page.events.emit(Events.KEY_UP, {
            code: e.code,
            key: e.key,
            first: e.first,
        });
    }

    public override isKeyPressed(code: string): boolean {
        return this.keyboardHandler.isKeyPressed(code);
    }

    /**
     * lifecycle
     */
    public override onDestroyed(): void {
        super.onDestroyed();

        this.keyboardHandler.off("keyDown", this.onKeyDown);
        this.keyboardHandler.off("keyUp", this.onKeyUp);
        this.keyboardHandler.destroy();
    }

    /**
     * in play mode we listen to dom events and key events, and we also run scripts
     */
    public override onCreated(): void {
        super.onCreated();

        /**
         * start listening to dom events like instance click
         * and key events like keydown/up
         */

        this.pointerEventHandler = new PlayPointerEventHandler(this.page);
        this.resizeEventHandler = getResizeEventHandler(this.page);

        this.keyboardHandler.on("keyDown", this.onKeyDown);
        this.keyboardHandler.on("keyUp", this.onKeyUp);

    }
}
