/**
 * events component
 */
import { IPage } from "../../../types/internal";
import { IInstance } from "../../../types/external";
import { Point } from "../../../types/external";

export interface IHitTestManager {
    getTargetInstancesUnderPoint(p: Point): IInstance[];
    destroy(): void;
}

export class HitTestManager implements IHitTestManager {
    
    private page: IPage | undefined;

    constructor(page: IPage) {
        this.page = page;
    }

    public getTargetInstancesUnderPoint(p: Point): IInstance[] {

        const hit: IInstance[] = [];
        const instances = this.page!.instances.getAllInstances();
        instances.forEach((instance: IInstance) => {

            const renderComp = instance.getComponent("render");
            if (renderComp.getRespondsToMouseEvents()) {
                const posComp = instance.getComponent("position");
                const pos = posComp.getViewPosition();
                // perf optimisation - get the bounding circle of the instance - this is the smallest circle that definitely contains the instance regardless of rotation
                const transComp = instance.getComponent("transform");
                const circle = transComp.getMaximalBoundingCircle(pos);
                const dx = p.x - circle.centre.x;
                const dy = p.y - circle.centre.y;
                if(dx ** 2 + dy ** 2 <= circle.radius ** 2){
                    // if the point is within the bounding circle, check if it is within the actual shape
                    const collComp = instance.getComponent("collision");
                    const shape = collComp.getTransformedShape();
                    const inside = shape.containsPoint(p);
                    if (inside) {
                        hit.push(instance);
                    }
                }
            }
        });

        // sort them so the top-most one comes first (this is the one you actually clicked on)
        hit.sort((a: IInstance, b: IInstance) => {
            const zA = a.getComponent("render")!.getZIndex();
            const zB = b.getComponent("render")!.getZIndex();
            return zA === zB ? 0 : zA < zB ? 1 : -1;
        });

        return hit;
    }

    public destroy(): void {
        this.page = undefined;
    }

}

export const getHitTestManager = (page: IPage): IHitTestManager => {
    return new HitTestManager(page);
}