/**
 * Listen to all the relevant events on the page
 */

import { IPage } from "../../types/internal";
import { IActivity } from "../../types/internal";
import { PageEventsMap } from "../../types/external";
import { Events } from "../../types/external";

export interface IActivityListeners {
    destroy(): void;
    listenToPage(page: IPage): void;
    stopListening(page: IPage): void;
}

// save a thumbnail every 5 seconds


export abstract class AActivityListeners implements IActivityListeners {
    constructor(protected activity: IActivity) {
        this.onChangePage = this.onChangePage.bind(this);
        this.onResetPage = this.onResetPage.bind(this);
        this.onResetActivity = this.onResetActivity.bind(this);
    }

    public abstract listenToPage(page: IPage): void;

    public abstract stopListening(page: IPage): void;

    protected onChangePage(eventData: PageEventsMap[typeof Events.CHANGE_PAGE]): void {
        this.activity.changePage(eventData);
    }

    /**
     * reset the whole activity
     */
    protected onResetActivity(): void {
        this.activity.reset();
    }

    /**
     * reset the current page
     */
    protected onResetPage(): void {
        this.activity.resetPage();
    }

    public destroy(): void {
        // nothing yet
    }
}
