import { IMovieClipComponent, IInstance } from "../../types/external";
import { Schema } from "../../types/external";
import { IPage } from "../../types/internal";
import { AComponent } from "../AComponent";

export default abstract class AMovieClipComponent extends AComponent<"movieclip"> implements IMovieClipComponent {
    
    public name: "movieclip" = "movieclip";

    constructor(data: Schema["movieclip"], instance: IInstance, page: IPage) {
        super(data, instance, page);
    }

    override getDependencies() {
        return ["image", "render"] as const;
    }

    private updateSegmentFrame(): void {
        if(this.data.frame > this.data.segmentEnd){
            this.data.frame = this.data.segmentStart;
        }
        else if(this.data.frame < this.data.segmentStart){
            this.data.frame = this.data.segmentStart;
        }
        this.data.frame = (this.data.frame) % this.data.paths.length;
    }

    protected updateImage(): void {
        if(this.data.enabled){
            this.updateSegmentFrame();
            const imageComponent = this.getInstanceComponent("image");
            imageComponent.setPath(this.data.paths[this.data.frame]);
        }
    }

    public override update(data: Schema["image"]): void {
        super.update(data);
        this.updateImage();
    }

    public nextFrame(): void {
        this.data.frame = this.data.frame + 1;
        this.updateImage();
    }

    public setPaths(paths: string[]): void{
        this.data.paths = paths.map((path) => path.trim());
        this.updateImage();
    }

    public setSegmentStart(frame: number): void{
        this.data.segmentStart = frame;
        this.updateImage();
    }
    
    public setSegmentEnd(frame: number): void{
        this.data.segmentEnd = frame;
        this.updateImage();
    }

    public setFrame(frame: number): void{
        this.data.frame = frame;
        this.updateImage();
    }

    public getFrame(): number{
        return this.data.frame;
    }
}
