/**
 * Different kinds of layers.
 * Some fill the whole screen, some are UI layers and match the camera
 */

import { PageLayerProps } from "../../../types/internal";
import { IPage } from "../../../types/internal";
import { FullPageLayer } from "./FullPageLayer";
import { UIPageLayer } from "./UIPageLayer";
import { PageSchema } from "../../../types/external";
import { ConstructorOf } from "@root/salad/types/utils";
import { APageLayer } from "./APageLayer";
import { UnscaledPageLayer } from "./UnscaledPageLayer";
import { HUDPageLayer } from "./HUDPageLayer";
import { ContainerPageLayer } from "./ContainerPageLayer";

type Box = PageSchema["camera"]["view"];

export interface IPageLayer {
    name: string;
    getElement(): HTMLElement;
    add(child: HTMLElement): void;
    showView(view: Box, globalScale: number): void;
    destroy(): void;
}

const map:{[_type in PageLayerProps["type"]]: ConstructorOf<APageLayer, [string, HTMLElement, IPage]>} = {
    ui: UIPageLayer,
    full: FullPageLayer,
    unscaled: UnscaledPageLayer,
    hud: HUDPageLayer, 
    container: ContainerPageLayer // contains other ones
}

export const getPageLayer = (
    name: string,
    element: HTMLElement,
    page: IPage,
    props: PageLayerProps,
) => {

    const Klass = map[props.type];
    if (Klass) {
        return new Klass(name, element, page);
    }
    else{
        throw new Error(`Unknown layer type: ${props.type}`);
    }
};
