/**
 * A single page
 */

import { IPage } from "../../types/internal";
import { ModalOutput, IModalHelper } from "../../types/external";
import { IPageModalsDecorator } from "../../types/external";
import { PageSchema } from "../../types/external";

type Modal = PageSchema["modalslist"]["modals"][string];

export class PageModalsDecorator implements IPageModalsDecorator {
    /**
     * A way to open modals
     */
    private _helper: IModalHelper;

    constructor(private page: IPage) {}

    public setHelper(helper: IModalHelper): void {
        this._helper = helper;
    }

    public async open(modal: Modal): Promise<ModalOutput> {
        // pause the game?
        const comp = this.page.getComponent("ticker");
        const isRunning = comp.getIsRunning();
        if (isRunning && modal.pauseGame) {
            comp.stop();
        }
        const output = await this._helper.openModal(modal);
        if (output && output.type === "next") {
            this.page.navigation.gotoNextPage();
        }
        // unpause the game?
        if (isRunning && modal.pauseGame) {
            comp.start();
        }
        return output;
    }

    public async alert(msg: string, buttons?:Modal["buttons"], pauseGame?: Modal["pauseGame"]): Promise<void> {
        const blocks:Modal["blocks"] = [
            {
                type: "text",
                text: msg,
            }
        ]

        const modal: Modal = {
            blocks,
            buttons,
            pauseGame
        }

        this.open(modal);
    }

    public async openByName(name: string): Promise<ModalOutput | undefined>  {
        const modal = this.page.getComponent("modalslist").getModalByName(name);
        if (modal) {
            this.page.modals.open(modal);
        }
        return undefined;
    }
}
