
import { ITickerComponent } from "../../types/internal";

let DEBUG = false;

// @ts-ignore
window.__showDebug = ()=>{
    DEBUG = true;
}

export interface ILogger{
    destroy():void;
    createUI():void;
    logTime(t:number):void;
}
export class Logger implements ILogger{
    
    private logger: HTMLElement | undefined = undefined;
    private pauseButton: HTMLElement | undefined = undefined;
    private playButton: HTMLElement | undefined = undefined;
    private container: HTMLElement | undefined = undefined;
    private component: ITickerComponent;

    private timing:{lastSampleTime:number, numFramesSinceLastSample:number, fps:number, totalSamples:number, averageFps:number} = {
        lastSampleTime: 0,
        numFramesSinceLastSample: 0,
        fps: 0,
        averageFps: 0,
        totalSamples: 0
    }

    constructor(component: ITickerComponent){
        this.component = component;
    }

    private addContainer(){
        if(!DEBUG){
            return;
        }
        if(!this.container){
            this.container = document.createElement("div");
            Object.assign(this.container.style, {
                position: "fixed",
                top: "12px",
                right: "130px",
                width: "250px",
                height: "32px",
                display: "flex",
                gap: "8px",
            })
            document.body.appendChild(this.container);
        }
    }
    
    public createUI(){
        if(!DEBUG){
            return;
        }
        this.addContainer();

        if(!this.pauseButton){
            this.pauseButton = document.createElement("button");
            this.pauseButton.innerText = "Pause";
            this.container?.appendChild(this.pauseButton);
            this.pauseButton.addEventListener("click", ()=>{
                this.component.stop();
            })
        }
        if(!this.playButton){
            this.playButton = document.createElement("button");
            this.playButton.innerText = "Play";
            this.container?.appendChild(this.playButton);
            this.playButton.addEventListener("click", ()=>{
                this.component.start();
            })
        }
    }

    public logTime(t:number){
        if(!DEBUG){
            return;
        }
        this.addContainer();
        if(!this.logger){
            this.logger = document.createElement("div");
            Object.assign(this.logger.style, {
                flex: 1
            })
            this.container?.appendChild(this.logger);
        }
        
        if(t - this.timing.lastSampleTime > 1000){
            //Sample!
            this.sampleAt(t);
            this.timing.numFramesSinceLastSample = 0;
            this.timing.totalSamples++;
        }   
        else{
            this.timing.numFramesSinceLastSample++;
        }
    }

    private sampleAt(t:number){
        const delta = t - this.timing.lastSampleTime;
        const sampledFps = this.timing.numFramesSinceLastSample / (delta / 1000);
        this.timing.lastSampleTime = t;
        this.timing.fps = sampledFps;
        this.timing.averageFps = (this.timing.totalSamples * this.timing.averageFps + sampledFps) / (this.timing.totalSamples + 1);
        const fpsText = Math.round(this.timing.fps);
        const avgText = Math.round(this.timing.averageFps);
        this.logger!.innerText = `fps ${fpsText} avg ${avgText}`;
    }

    public destroy(){
        if(this.container){
            while(this.container.firstChild){
                this.container.removeChild(this.container.firstChild);
            }
            document.body.removeChild(this.container);
            this.container = undefined;
        }    
    }
}
