export const video = (parent: HTMLElement, options: {
    path: string;
    controls: boolean;
    autoplay: boolean;
}): HTMLVideoElement => {
    const el = document.createElement("video");
    if(options.controls) {
        el.setAttribute("controls", "controls");
    }
    if(options.autoplay) {
        el.setAttribute("autoplay", "autoplay");
    }
    el.setAttribute("width", "100%");
    el.setAttribute("height", "100%");
    el.setAttribute("src", options.path);
    const source = document.createElement("source");
    source.setAttribute("src", options.path);
    el.appendChild(source);
    parent.append(el);
    return el;
};

