/**
 * abstract class for drawing on an instance
 */

import { IDrawingComponent, Schema, IInstance } from "../../types/external";
import { IPage } from "../../types/internal";
import { AComponent } from "../AComponent";

export default abstract class ADrawingComponent
    extends AComponent<"drawing">
    implements IDrawingComponent
{
    public name: "drawing" = "drawing";

    constructor(data: Schema["drawing"], instance: IInstance, page: IPage) {
        super(data, instance, page);
    }

    public getEnabled(): boolean {
        return this.data.enabled;
    }

    public getContext(): CanvasRenderingContext2D | undefined {
        return undefined;
    }

    public getElement(): HTMLCanvasElement | undefined {
        return undefined;
    }

    public setEnabled(enabled: boolean): void {
        this.data.enabled = enabled;
    }

    override getDependencies() {
        return ["render", "position", "size"] as const;
    }
}
