import { IPage } from "../../types/internal";
import { Events } from "../../types/external";
import { KeyCodes } from "./KeyCodes";

export interface IKeyboardButtons{
    destroy():void
}

class KeyboardButtons implements IKeyboardButtons {
    private buttons: HTMLButtonElement[] = [];
    private container: HTMLElement;
    
    constructor(
        private el: HTMLElement, 
        private position: "top" | "bottom",
        private page: IPage, 
        private keys: string[]
    ) {
        this.onDown = this.onDown.bind(this);
        this.onUp = this.onUp.bind(this);
        this.render();
    }
    
    private getEventData(key: string):{key: string, code: string, first: boolean}{
        return {
            key: KeyCodes.getKey(key),
            code: KeyCodes.getCode(key),
            first:true
        }
    }

    private onDown(e: PointerEvent):void{
        const target = e.target;
        const id = (target as HTMLElement).id
        const key = id.split("-")[1];
        this.page.events.emit(Events.KEY_DOWN, this.getEventData(key));
    }

    private onUp(e: PointerEvent):void{
        const target = e.target;
        const id = (target as HTMLElement).id
        const key = id.split("-")[1];
        this.page.events.emit(Events.KEY_UP, this.getEventData(key));
    }

    private render(): void{
        this.container = document.createElement("div");
        this.container.classList.add("keyboard-buttons");
        this.container.classList.add(`keyboard-buttons-${this.position}`);
        this.el.append(this.container);
        this.keys.forEach(k=>{
            const button = document.createElement("button")
            button.innerText = KeyCodes.getDisplayText(k);
            this.el.append(button);
            this.buttons.push(button);
            button.id = "button-" + k;
            button.addEventListener("pointerdown", this.onDown);
            button.addEventListener("pointerup", this.onUp);
            this.container.append(button);
        })
    }
    public destroy():void{
        this.buttons.forEach(b=>{
            b.removeEventListener("pointerdown", this.onDown);
            b.removeEventListener("pointerup", this.onUp);
        })
        this.buttons = [];
    }
}

export const getButtons = (el: HTMLElement, position: "top" | "bottom", page: IPage, keys: string[]): IKeyboardButtons => {
    return new KeyboardButtons(el, position, page, keys);
};