import { CSSDomUpdate } from "../../types/external";

type CSSDomTransform = CSSDomUpdate["css"]["transform"]

type FinalCSS = Omit<CSSDomUpdate["css"], "transform"> & {
    transform?: string
}

// check if updates actually changed anything
const mapElementToStyles: WeakMap<HTMLElement, Record<string, any>> = new WeakMap();

// store the transform state for each element
const mapElementToTransform: WeakMap<HTMLElement, CSSDomTransform> = new WeakMap();

const applyTransform = (element: HTMLElement, transform: CSSDomTransform): string => {
    // Get or initialize transform state
    let state:CSSDomTransform = mapElementToTransform.get(element);
    if (!state) {
        state = {
            rotate: "0deg",
            scaleX: 1,
            scaleY: 1,
            skew: "0deg",
            translateZ: "0px"
        };
        mapElementToTransform.set(element, state);
    }
    
    // Only update properties that are explicitly set
    for (const key in transform) {
        //@ts-ignore
        if (transform[key] !== undefined) {
            //@ts-ignore
            state[key] = transform[key];
        }
    }
    
    // Generate transform string from complete state
    return `rotate(${state.rotate || 0}) scale(${state.scaleX || 1}, ${state.scaleY || 1}) skew(${state.skew || 0}) translateZ(${state.translateZ || 0})`;
}

export const applyCSS = (element: HTMLElement, css: CSSDomUpdate["css"]): void => {
    const finalCSS: FinalCSS = {} as FinalCSS;
                
    // Handle regular CSS properties
    for (const key in css) {
        if (key !== 'transform') {
            //@ts-ignore
            finalCSS[key] = css[key];
        }
    }
    
    // Handle transform independently
    if (css.transform) {
        finalCSS.transform = applyTransform(element, css.transform);
    }
    
    let styleCache = mapElementToStyles.get(element);
    if (!styleCache) {
        styleCache = {};
        mapElementToStyles.set(element, styleCache);
    }
                 
    for (const key in finalCSS) {
        //@ts-ignore
        const newValue = finalCSS[key];
        if (styleCache[key] !== newValue) {
            element.style[key as any] = newValue;
            styleCache[key] = newValue;
        }
    }
}
