/**
 * A class that manages collsions
 * Dispatches events when collisions start and end
 */

import { ITypedEventEmitter, IInstance, CollisionHashKey } from "../../types/external";
import { TypedEventEmitter } from "../../utils/TypedEventEmitter";
import { unique } from "../../utils/utils";
import { IHasId } from "../../types/external";

export type CollisionData = {
    instance1: IInstance;
    instance2: IInstance;
};

export const getCollisionHashKeyForInstances = (
    instance1: IHasId,
    instance2: IHasId,
): CollisionHashKey => {
    const id1 = instance1.getId();
    const id2 = instance2.getId();
    if (id1 < id2) {
        return `${id1}:${id2}`;
    }
    return `${id2}:${id1}`;
};

export type CollisionHash = {
    [id: CollisionHashKey]: CollisionData & {
        collides: boolean;
    };
};

export type CollisionEventMap = {
    collisionStart: { data: CollisionData };
    collisionEnd: { data: CollisionData };
};

export interface ICollisionsManager extends ITypedEventEmitter<CollisionEventMap> {
    update(hash: CollisionHash): void;
    destroy(): void;
    getCurrentCollisions(): CollisionHashKey[];
    getCollides(key: CollisionHashKey): boolean;
}

class CollisionsManager extends TypedEventEmitter<CollisionEventMap> implements ICollisionsManager {
    private _hash: CollisionHash = {};

    constructor() {
        super();
    }

    /**
     * Update the hash, and figure out what changed.
     * Dispatch events for collisions that started and ended
     * @param newHash
     */
    public update(newHash: CollisionHash): void {
        // find the changes

        const keys: CollisionHashKey[] = Object.keys(this._hash) as CollisionHashKey[];
        const newKeys: CollisionHashKey[] = Object.keys(newHash) as CollisionHashKey[];

        const allKeys = unique([...keys, ...newKeys]);

        const end: CollisionData[] = [];
        const start: CollisionData[] = [];

        allKeys.forEach((k: CollisionHashKey) => {
            if (this._hash[k] && this._hash[k].collides && !newHash[k]) {
                // deleted a collision - was colliding but now isn't
                end.push(this._hash[k]);
            } else if (!this._hash[k] && newHash[k] && newHash[k].collides) {
                // added new collision - wasn't colliding but now is
                start.push(newHash[k]);
            } else if (this._hash[k] && newHash[k]) {
                // collision still exists and has changed
                if (this._hash[k].collides && !newHash[k].collides) {
                    end.push(this._hash[k]);
                } else if (!this._hash[k].collides && newHash[k].collides) {
                    start.push(newHash[k]);
                }
            }
        });

        //do the end events first
        end.forEach((collisionEndData) => {
            this.emit("collisionEnd", {
                data: collisionEndData,
            });
        });
        start.forEach((collisionStartData) => {
            this.emit("collisionStart", {
                data: collisionStartData,
            });
        });

        this._hash = newHash;
    }

    public getCollides(key: CollisionHashKey): boolean{
        const value = this._hash[key] && this._hash[key].collides;
        return !!value;
    }

    public getCurrentCollisions(): CollisionHashKey[] {
        return Object.keys(this._hash) as CollisionHashKey[];
    }

    public destroy(): void {
        this._hash = {};
    }
}

export const getCollisionsManager = (): ICollisionsManager => {
    return new CollisionsManager();
};
