/**
 * Render component for play mode
 */

import AVisibilityComponent from "./AVisibilityComponent";
import { IInstance, Events } from "../../types/external";
import { IPage } from "../../types/internal";
import { Schema } from "../../types/external";
export default class PlayVisibilityComponent extends AVisibilityComponent {
    constructor(data: Schema["visibility"], instance: IInstance, page: IPage) {
        super(data, instance, page);
        this.onClick = this.onClick.bind(this);
    }

    public override onCreated(): void {
        super.onCreated();
        this.updateVisibility();
        this._addListeners();
    }

    public override onDestroyed(): void {
        super.onDestroyed();
        this._removeListeners();
    }

    public override toggleEditorVisibility(): void {
        // ignore in play mode
    }

    public override setEditorVisibility(_: boolean): void {
        // ignore in play mode
    }

    public override updateVisibility(): void {
        const element = this.instance.getComponent("render").getElement();
        element.classList.remove("visibility-hidden", "visibility-none");
        if (this.data.visibility === "hidden") {
            element.classList.add("visibility-hidden");
        }
        if (this.data.visibility === "none") {
            element.classList.add("visibility-none");
        }
    }

    protected _addListeners(): void {
        if (this.data.onInstanceClick) {
            this.instance.events.on(Events.INSTANCE_CLICK, this.onClick);
        }
    }

    protected _removeListeners() {
        this.instance.events.off(Events.INSTANCE_CLICK, this.onClick);
    }

    public getCanCollide():boolean{
        const visComp = this.instance.getComponent("visibility");
        const vis = visComp.getVisibility();
        return vis !== "none";
    }

    private onClick(): void {
        if (this.data.onInstanceClick) {
            this.update({
                visibility: this.data.onInstanceClick,
            });
        }
    }
}
