/**
 * Handles the camera following a specific instance
 */

import { IPage } from "../../types/internal";
import { ICameraComponent } from "../../types/external";
import { PageSchema } from "../../schema/pageSchema";
import { IInstance } from "../../types/external";
import { PageEventsMap, Events } from "../../types/external";

export interface ICameraFollow {
    /**
     * Wait for the instance to appear and then monitor it
     * @param data
     */
    init(data: PageSchema["camera"]["follow"]): void;

    /**
     * clean up
     */
    destroy(): void;
}

export class CameraFollow implements ICameraFollow {
    /**
     * What we are following
     */
    private followingInstance: IInstance | undefined = undefined;
    private followingName: string | undefined = undefined;

    /**
     * store the dead zone. Eg. 0.1 (dead zone is 10% of the width and height)
     */
    private deadZone: number | undefined = undefined;

    constructor(
        private cameraComp: ICameraComponent,
        private page: IPage,
    ) {
        this.deadZone = cameraComp.getDeadZone();
        this.onInstanceCreated = this.onInstanceCreated.bind(this);
        this.onInstanceDestroyed = this.onInstanceDestroyed.bind(this);
        this.onComponentUpdated = this.onComponentUpdated.bind(this);
    }

    /**
     * Wait for the instance to appear and then monitor it
     * @param data
     */
    public init(data: PageSchema["camera"]["follow"]): void {
        this.followingName = data.name;
        const instance = this.page.instances.getInstanceByName(this.followingName);
        if (instance) {
            // it exists already
            this.followingInstance = instance;
            this.addComponentMoveListeners();
        } else {
            // wait for it to be added
            this.page.events.on(Events.INSTANCE_CREATED, this.onInstanceCreated);
        }
        this.page.events.on(Events.INSTANCE_DESTROYED, this.onInstanceDestroyed);
    }

    private updateOnTargetMove(): void {
        const instanceCentre = this.followingInstance!.getComponent("collision").getCentre();
        const relativePosition = this.cameraComp.getPositionRelativeToCamera(instanceCentre);

        // see if we have gone outside the dead zone (https://unity-connect-prd.storage.googleapis.com/20190924/learn/images/9359554c-4cd3-4a3b-a2f4-d55bf4089159_03.jpg)

        let dx = 0,
            dy = 0;

        if (relativePosition.x > 1 - this.deadZone!) {
            // eg. if deadzone = 0.2 and we are at 0.8, do nothing
            // if we are at 0.81, move the camera to the right by 0.01
            dx = relativePosition.x - (1 - this.deadZone!);
        } else if (relativePosition.x < this.deadZone!) {
            // eg. if deadzone = 0.2 and we are at 0.2, do nothing
            // if we are at 0.19, move the camera to the left by 0.01
            dx = relativePosition.x - this.deadZone!;
        }

        // same in the y direction
        if (relativePosition.y > 1 - this.deadZone!) {
            dy = relativePosition.y - (1 - this.deadZone!);
        } else if (relativePosition.y < this.deadZone!) {
            dy = relativePosition.y - this.deadZone!;
        }

        // move immediately
        if (dx !== 0 || dy !== 0) {
            const view = this.cameraComp.getView();
            this.cameraComp.pan.by(dx * view.width, dy * view.height, 0);
        }
    }

    /**
     * Listen to when it moves
     * check if we havent just moed the camera
     *
     */
    private onComponentUpdated(eventData: PageEventsMap[typeof Events.COMPONENT_UPDATE]) {
        this.updateOnTargetMove();
    }

    private onInstanceCreated(eventData: PageEventsMap[typeof Events.INSTANCE_CREATED]) {
        if (eventData.target.getName() === this.followingName) {
            // got it!
            this.followingInstance = eventData.target;
            // listen to when it moves
            this.addComponentMoveListeners();
        }
    }

    private onInstanceDestroyed(eventData: PageEventsMap[typeof Events.INSTANCE_DESTROYED]) {
        if (eventData.target.getName() === this.followingName) {
            // it got removed
            this.removeComponentMoveListeners();
            this.followingInstance = undefined;
        }
    }

    private removeComponentMoveListeners(): void {
        if (this.followingInstance) {
            this.followingInstance.events.c.position.off(Events.COMPONENT_UPDATE, this.onComponentUpdated);
        }
    }

    private addComponentMoveListeners(): void {
        this.followingInstance!.events.c.position.on(Events.COMPONENT_UPDATE, this.onComponentUpdated);
        this.updateOnTargetMove();
    }

    public destroy(): void {
        this.removeComponentMoveListeners();
        this.page.events.off(Events.INSTANCE_CREATED, this.onInstanceCreated);
        this.page.events.off(Events.INSTANCE_DESTROYED, this.onInstanceDestroyed);
    }
}
