import { getEventPosition } from "../utils/utils";
import { ADragger} from "./ADragger";
import { DraggerOptions, MoveableEventData } from "./types";
import { getMoveable } from "./MoveableFactory";
import { IPageExternal } from "../types/external";

const css = (element: HTMLElement, styles: Record<string, any>) => {
    Object.assign(element.style, styles);
};

/**
 * A dragger for any old HTML element
 *  - Clone the element as a helper (this is similar to a jquery draggable helper).
 *  - When you drop it on the page it will create an instance on the page
 */
export class HTMLDragger extends ADragger {
    // the one you mousedown'd on
    private target: HTMLElement;

    // like jquery, this is the cloned thing that you drag
    private helper: HTMLElement | undefined;

    private dropHandler:any

    constructor(
        target: HTMLElement,
        page: IPageExternal,
        dropHandler:(pos:{x:number, y:number})=>void,
    ) {
        super(page);
        this.target = target;
        this.dropHandler = dropHandler;
        this.onMouseDown = this.onMouseDown.bind(this);

        // make the helper when they mousedown - this has to be a mousedown event to work with moveablejs
        target.addEventListener("mousedown", this.onMouseDown);
        target.addEventListener("touchstart", this.onMouseDown);
    }

    private makeHelper(): HTMLElement {
        // clone and make the same size
        const clone = this.target.cloneNode(true) as HTMLElement;
        css(clone, {
            width: `${this.target.clientWidth}px`,
            height: `${this.target.clientHeight}px`,
            "z-index": 100000,
        });
        return clone;
    }

    /**
     * add helper to the DOM and start dragging it
     * @param e
     */
    private onMouseDown(e: MouseEvent | TouchEvent): void {
        if ("button" in e && e.button === 2) {
            return;
        }

        //make the helper and start dragging it
        this.helper = this.makeHelper();
        document.body.appendChild(this.helper);

        // center it on the mouse
        const xy = getEventPosition(e);

        const x = xy!.x - this.helper.clientWidth / 2;
        const y = xy!.y - this.helper.clientHeight / 2;

        this.helper.addEventListener("pointerdown", (e) => {
            e.preventDefault();
            e.stopImmediatePropagation();
        });

        css(this.helper, {
            transform: `translate(${x}px, ${y}px)`,
            position: "absolute",
            top: 0,
            left: 0,
        });

        // options to drag the helper
        const options: DraggerOptions = {
            onClick: () => {},
            onDragStart: (e: { set: (p: [number, number]) => void }) => {
                // put it in the right place
                e.set([x, y]);
                this.moveable!.updateRect();
            },
            onDragEnd: (e: MoveableEventData["dragEnd"]) => {
                // destroy the helper
                this.destroyMoveable();

                const position = this.page
                    .layout!
                    .getPagePositionForEvent(e.inputEvent);

                if(this.dropHandler){
                    this.dropHandler(position)
                }
            
                document.body.removeChild(this.helper!);
                this.helper = undefined;
            },
            onDrag: (e: MoveableEventData["drag"]) => {
                css(this.helper!, {
                    transform: `translate(${e.beforeTranslate[0]}px, ${e.beforeTranslate[1]}px)`,
                });
                this.moveable!.updateRect();
            },
        };
        // make the moveable instance
        this.moveable = getMoveable(this.helper, document.body, this.getMoveableOptions(), options);

        // finally, force a start drag to start it dragging
        this.startDraggingUsingEvent(e);
    }
}
