/**
 * page timers - add/remove timeouts and intervals
 */

import { IPage } from "../../types/internal";
import { APageComponent } from "../APageComponent";
import { PageSchema } from "../../types/external";
import { Timer, Interval } from "../../components/timers/Timers";
import { IPageTimersComponent } from "../../types/external";

export default class PageTimersComponent
    extends APageComponent<"timers">
    implements IPageTimersComponent
{
    // array of 'setTimeout' timers
    private _timers: Timer[] = [];

    // array of 'setInterval' timers
    private _intervals: Interval[] = [];

    public name: "timers" = "timers";

    constructor(data: PageSchema["timers"], page: IPage) {
        super(data, page);
    }

    public addTimeout(f: Function, duration: number): Timer {
        const timer = new Timer(f, duration);
        this._timers.push(timer);
        return timer;
    }

    public addInterval(f: Function, duration: number): Interval {
        const interval = new Interval(f, duration);
        this._intervals.push(interval);
        return interval;
    }

    public clearAll(): void {
        this._timers.forEach((timer: Timer) => {
            timer.kill();
        });
        this._timers = [];
        this._intervals.forEach((interval: Interval) => {
            interval.kill();
        });
        this._intervals = [];
    }

    public override onDestroyed(): void {
        this.clearAll();
        super.onDestroyed();
    }
}
