import { MoveableOptions } from "moveable";
import { IInstance, IPageExternal } from "../types/external";
import { IMoveable, IDragger } from "./types";

// abstract class for all draggers
export abstract class ADragger implements IDragger {
    // the moveable instance
    protected moveable: IMoveable | undefined;

    constructor(
        protected page: IPageExternal,
        protected instance?: IInstance | undefined
    ) {}

    // play/edit mode can use different options
    protected getMoveableOptions(): MoveableOptions {
        return {
            draggable: true,
            renderDirections: [],
        };
    }

    protected destroyMoveable() {
        if (this.moveable) {
            this.moveable.off();
            this.moveable.destroy();
            this.moveable = undefined;
        }
    }

    public destroy() {
        this.destroyMoveable();
    }

    /**
     * Force start dragging.
     * We need this because when you spawn a new instance we need to start dragging immediately,
     * (and it is not the one that you clicked on)
     * @param e
     */
    public startDraggingUsingEvent(e: MouseEvent | TouchEvent): void {
        this.moveable!.dragStart(e);
    }

    /**
     * eg. when the window changes size, redraw the rect
     */
    public updateRect(): void {
        if (this.moveable) {
            this.moveable.updateRect();
        }
    }
}
