export interface IPreloaderElement{
    destroy(): void;
    update(progress: number): void;
    element: HTMLElement
}

export class PreloaderElement implements IPreloaderElement{
    
    private _element: HTMLElement;
    private _bar: HTMLElement;
    private _text: HTMLElement;

    constructor(options?:{themeColor: string}){
    
        const container = document.createElement("div");
        container.classList.add("activity-preloader-container");
        Object.assign(container.style, {
            backgroundColor: options?.themeColor || "rgba(200, 200, 200, 0.5)"
        })

        const progress = document.createElement("div");
        progress.classList.add("activity-preloader-progress");
        container.appendChild(progress);

        this._text = document.createElement("div");
        this._text.classList.add("activity-preloader-text");
        this._text.id = "activity-preloader-text";
        this._text.innerText = "Loading...";

        this._bar = document.createElement("div");
        this._bar.classList.add("activity-preloader-bar");
        this._bar.id = "activity-preloader-bar";

        progress.appendChild(this._bar);
        progress.appendChild(this._text);

        this._element = container;
    }

    get element(): HTMLElement{
        return this._element;
    }

    public destroy(): void{
        this._element.remove();
    }

    public update(progress: number): void{
        this._text.innerText = `Loading... ${Math.floor(progress * 100)}%`;
        this._bar.style.width = `${progress * 100}%`;
    }
}

export const getPreloaderElement = (options?: {themeColor: string}): IPreloaderElement => {
    return new PreloaderElement(options);
}