/**
 * UI buttons in play mode
 */
import { IPage } from "../../../types/internal";
import { PageSchema, Events } from "../../../types/external";
import { PageEventsMap } from "../../../types/external";
import { IUIScroll } from "../types";

export class MouseUIScroll implements IUIScroll {
    constructor(
        protected type: PageSchema["ui"]["scroll"],
        protected page: IPage,
    ) {
        this.onDrag = this.onDrag.bind(this);
        this.page.events.on(Events.PAGE_POINTERDRAG, this.onDrag);
    }

    private onDrag(eventData: PageEventsMap[typeof Events.PAGE_POINTERDRAG]) {
        // check you are not actually dragging a draggable
        const draggableTargets = eventData.targets.filter(target => {
            const dragComp = target.getComponent("draggable");
            return dragComp && dragComp.getEnabled();
        });
        if (draggableTargets.length === 0) {
            this.page.getComponent("camera").pan.by(-eventData.delta!.dx, -eventData.delta!.dy, 0);
        }
    }

    public destroy(): void {
        this.page.events.off(Events.PAGE_POINTERDRAG, this.onDrag);
    }

    public isButtonEnabled(name: string): boolean{
        return false;
    }

    public setButtonEnabled(name: string, enabled: boolean): void {
        // do nothing
    }
}
