/**
 * UI buttons in play mode
 */
import { IPage } from "../../../types/internal";
import { PageSchema, Events } from "../../../types/external";
import { getButton } from "./ButtonUtils";
import { IUIScroll } from "../types";

type ButtonName = "left" | "right" | "up" | "down";

type Buttons = { [name in ButtonName]: HTMLElement };

abstract class AButtonScroll implements IUIScroll {
    // map name to actual button
    protected _buttons: Buttons = {} as Buttons;

    constructor(
        protected type: PageSchema["ui"]["scroll"],
        protected page: IPage,
    ) {
        this.onCameraUpdate = this.onCameraUpdate.bind(this);
        this.onClick = this.onClick.bind(this);
        this.page.events.on(Events.PAGE_COMPONENT_UPDATED, this.onCameraUpdate);
        this.addButtons();
        this.onCameraUpdate();
    }

    protected abstract getButtonNames(): ButtonName[];

    private onClick(e: Event) {
        e.stopPropagation();

        const button = e.currentTarget as HTMLElement;

        //find the name from the target
        const keys: ButtonName[] = Object.keys(this._buttons) as ButtonName[];
        const name = keys.find((name) => {
            return this._buttons[name] === button;
        });

        if (name === "left") {
            this.page.getComponent("camera").pan.left();
        } else if (name === "right") {
            this.page.getComponent("camera").pan.right();
        } else if (name === "up") {
            this.page.getComponent("camera").pan.up();
        } else if (name === "down") {
            this.page.getComponent("camera").pan.down();
        }
    }

    protected addButtons() {
        this._buttons = {} as Buttons;
        const buttonNames = this.getButtonNames();
        const layerComp = this.page.getComponent("layers");

        buttonNames.forEach((name) => {
            const button = getButton(name);
            this._buttons[name] = button;
            layerComp.addChildToLayer(button, "ui");
            button.addEventListener("click", this.onClick);
        });
    }

    public isButtonEnabled(name: ButtonName): boolean{
        return !this._buttons[name].hasAttribute("disabled");
    }

    /**
     * when the camera moves, update the buttons
     */
    protected onCameraUpdate(): void {
        const cameraComp = this.page.getComponent("camera");
        this.setButtonEnabled("left", cameraComp.canScrollLeft());
        this.setButtonEnabled("right", cameraComp.canScrollRight());
        this.setButtonEnabled("up", cameraComp.canScrollUp());
        this.setButtonEnabled("down", cameraComp.canScrollDown());
    }

    public setButtonEnabled(name: ButtonName, enabled: boolean): void {
        const button = this._buttons[name];
        if (button) {
            if (enabled) {
                button.removeAttribute("disabled");
            } else {
                button.setAttribute("disabled", "disabled");
            }
        }
    }

    public destroy(): void {
        const buttons = Object.values(this._buttons);

        buttons.forEach((button: HTMLElement) => {
            button.removeEventListener("click", this.onClick);
            button.remove();
        });

        this._buttons = {} as Buttons;
    }
}

export class LRUDButtonScroll extends AButtonScroll {
    constructor(type: PageSchema["ui"]["scroll"], page: IPage) {
        super(type, page);
    }
    protected override getButtonNames(): ButtonName[] {
        return ["left", "right", "up", "down"];
    }
}

export class LRButtonScroll extends AButtonScroll {
    constructor(type: PageSchema["ui"]["scroll"], page: IPage) {
        super(type, page);
    }
    protected override getButtonNames(): ButtonName[] {
        return ["left", "right"];
    }
}

export class UDButtonScroll extends AButtonScroll {
    constructor(type: PageSchema["ui"]["scroll"], page: IPage) {
        super(type, page);
    }
    protected override getButtonNames(): ButtonName[] {
        return ["up", "down"];
    }
}
