/**
 * Render in edit mode - handles hiding/showing
 */

import ARenderComponent from "./ARenderComponent";

export default class EditRenderComponent extends ARenderComponent {
    
    public override getRespondsToMouseEvents(): boolean {
        const visComp = this.instance.getComponent("visibility");
        return visComp.getEditorVisibility();
    }

    public override onCreated(): void {
        super.onCreated();
        this._element!.classList.add("editor-border");
    }

    protected override updateLayoutPaint(): void {
        this._element?.classList.remove("layout-paint");
    }
}
