import { IPageEventEmitter } from "../types/internal";
import { PageEventsMap } from "../types/external";
import { TypedEventEmitter } from "../utils/TypedEventEmitter";
import { PageComponentName, allPageComponentNames } from "../types/external";
import { IndividualPageComponentUpdate } from "../types/internal";

class PageComponentEventEmitter extends TypedEventEmitter<IndividualPageComponentUpdate>  {
    constructor() {
        super();
    }

    public destroy(): void {
        this.removeAllListeners();
    }
}

export class PageEventEmitter
    extends TypedEventEmitter<PageEventsMap>
    implements IPageEventEmitter
{
    
    c:{
        [k in PageComponentName]: PageComponentEventEmitter;
    }

    constructor() {
        super();
        this.c = {} as any;
        for (const key of allPageComponentNames) {
            this.c[key] = new PageComponentEventEmitter();
        }
    }

    /**
     * Remove all listeners
     */
    public destroy(): void {
        this.removeAllListeners();
    }
}
