import { IPageKeyboardComponent } from "../../types/internal";

export interface IKeyboardVisibility{
    getShouldShowKeyboard():boolean;
}

class KeyboardVisibility implements IKeyboardVisibility{
    constructor(private comp: IPageKeyboardComponent){

    }

    public getShouldShowKeyboard():boolean{
        const keys = this.comp?.getKeys();
        if(!keys || keys.length === 0){
            return false;
        }
        const show = this.comp?.getShow();
        if(show === "always"){
            return true;
        }
        else if(show === "never"){
            return false;
        }
        else if(show === "tablet"){
            return false; //AppVariables.getBoolean("tablet");
        }
        return false;
    }
}

export const getVisibility = (comp: IPageKeyboardComponent)=>{
    return new KeyboardVisibility(comp);
}
