import Salad from "../../../index";
import { IActivityCSSComponent } from "../../../types/external";
import { AActivityComponent } from "../AActivityComponent";
import { ActivityOptions } from "../../../types/internal";

export class ActivityCSSComponent extends AActivityComponent implements IActivityCSSComponent{

    constructor(private activity: Salad.IActivity, private options: ActivityOptions) {
        super();
        options.container.classList.remove("moveable-edit");
        options.container.classList.remove("moveable-play");
        options.container.classList.add("moveable-" + options.mode);
    }

}
