/**
 * An activity is a collection of pages that are displayed in a sequence.
 * And a way to navigate between them.
 * With transitions between them.
 */

import Salad from "../index";
import { getListeners } from "./listeners/ActivityListeners";
import { IActivityListeners } from "./listeners/AActivityListeners";
import { getComponentFactory} from "./ComponentFactories";
import { IPage, IActivityComponentFactory, ActivityComponentName,
    ActivityComponentsMap, ActivityOptions } from "../types/internal";

import { IActivitySettingsComponent,
    IActivityDataComponent, IActivityHistoryComponent, IActivityScriptComponent,
    IStatsCreator, IActivityLoggerComponent } from "../types/external";

import {IActivityEventEmitter, ActivityEventEmitter} from "./ActivityEventEmitter";
import { clone } from "../utils/utils";
import { getPageFactory } from "./PageFactory";

type ChangePageData = Salad.PageEventsMap[typeof Salad.Events.CHANGE_PAGE]

class Activity implements Salad.IActivity{

    // Page currently displayed
    private currentPage: IPage | undefined = undefined;

    // listen to different things in edit and play mode
    private listeners: IActivityListeners | undefined = undefined;

    // set of components
    private _components: ActivityComponentsMap;

    // event emitter
    private _events: IActivityEventEmitter;

    constructor(private options: ActivityOptions) {
        // remove any Vue reactivity
        this.options.backup = clone(this.options.backup);
        this.options.data = clone(this.options.data);
        this.options.history = clone(this.options.history);
        this.options.script = clone(this.options.script);
        this.options.info = clone(this.options.info);
        this.options.pages = clone(this.options.pages);
        this.options.settings = clone(this.options.settings);

        // add the container for the pages
        if(!this.options.pageContainer){
            this.options.pageContainer = document.createElement("div");
            this.options.container.appendChild(this.options.pageContainer);
        }

        // set up ids so css works
        this.options.container.id = "salad_container";
        this.options.pageContainer.id = "salad_page_container";

        Object.assign(this.options.pageContainer.style, {
            position: "relative",
            overflow: this.options.mode === "edit" ? "visible" : "hidden",
        })

        this._events = new ActivityEventEmitter();
    }

    private makeComponents(): void {
        this.destroyComponents();
        const factory:IActivityComponentFactory = getComponentFactory(this.options.mode);
        this._components = factory.buildAllActivityComponents(this, this.options);
    }

    public getComponent<K extends ActivityComponentName>(name: K): ActivityComponentsMap[K]{
        return this._components[name]!;
    }

    public getComponents(): ActivityComponentsMap{
        return this._components;
    }

    public get events(): IActivityEventEmitter {
        return this._events;
    }

    public get logger(): IActivityLoggerComponent {
        return this.getComponent("logger")!;
    }

    public async start(): Promise<void> {
        // start!
        this.listeners = getListeners(this, this.options.mode);
        this.makeComponents();
        // start the components
        await this.getComponent("fonts").loadFonts();
        await this.getComponent("preloader").preload();
        await this.getComponent("info").open();
    }

    public log(msg:any):void{
        this.getComponent("logger")!.log(msg);
    }

    public getCurrentPage(): IPage | undefined{
        return this.currentPage;
    }

    private async onPageOut(): Promise<void> {
        for(const c of Object.values(this._components)){
            await c.onPageOut(this.currentPage!);
        }
    }

    private async onPageIn(index:number): Promise<void> {
        for(const c of Object.values(this._components)){
            await c.onPageIn(this.currentPage!, index, this.options.pages.length);
        }
    }

    /**
     * Go to a page. Do not use this to navigate between pages in the activity.
     * Use "changePage" instead, which will handle the history properly
     * @param {number} index
     */
    public async gotoPageByIndex(index: number): Promise<void> {
        await this.onPageOut();
        this.destroyCurrentPage();
        const pageFactory = getPageFactory(this.options.pages[index], this.options);
        this.currentPage = pageFactory.createPage();
        pageFactory.setup();
        await this.onPageIn(index);
        this.listeners!.listenToPage(this.currentPage);
        this._events.emit(Salad.Events.ACTIVITY_PAGE_CHANGE, {
            page: this.currentPage
        });
    }

    public get history(): IActivityHistoryComponent{
        return this.getComponent("history")!;
    }

    public get settings(): IActivitySettingsComponent{
        return this.getComponent("settings")!;
    }

    public get stats(): IStatsCreator{
        return this.options.api.stats;
    }

    public get data(): IActivityDataComponent{
        return this.getComponent("data")!;
    }

    public get script(): IActivityScriptComponent{
        return this.getComponent("script")!;
    }
    /**
     * Remove handlers, destroy page
     */
    public destroyCurrentPage() {
        if (this.currentPage) {
            
            // first save any changes and emit an event to anyone listenning
            this.save();

            // stop listening
            this.listeners!.stopListening(this.currentPage);

            // destroy
            this.currentPage.destroy();

            // emit - this is only really used in the jest tests at the moment
            this._events.emit(Salad.Events.ACTIVITY_PAGE_DESTROYED, {
                page: this.currentPage
            });
            this.currentPage = undefined;
        }
    }

    public async reset(): Promise<void> {
        return this.getComponent("backup").resetActivity();
    }

    public async resetPage(): Promise<void> {
        return this.getComponent("backup").resetPage();
    }

    /**
     * If this page supports "saving"
     * Then save everything 'locally' inside options, so that if we navigate back to this page we can restore it to how it should be
     * and emit an event to save everything globally in a pinia store or whatever the client happens to be using.
     * The latter is only really used in edit mode when the Vue UI needs to update immediately.
     */
    public save(): void {
        const saved = this.getComponent("persistence").save();
        if(saved){
            // emit to save the data globally
            this._events.emit(Salad.Events.ACTIVITY_CHANGE_DATA);
        }
    }

    /**
     * Change the page. You must use this to navigate between pages in the activity.
     * changeData can be a string, a number or an object. 
     * This method will handle the history properly.
     */
    public async changePage(changeData: ChangePageData): Promise<void> {
        return this.getComponent("pages").changePage(changeData);
    }

    private destroyComponents(): void {
        if(this._components){
            const keys = Object.keys(this._components) as ActivityComponentName[];
            keys.forEach((k) => {
                this._components[k].destroy();
            });
        }
    }

    /**
     * Destroy the activity, currently this just destroys the current page
     */
    public destroy(): void {
        this.destroyCurrentPage();
        this._events.destroy();
        this.listeners!.destroy();
        this.options.pageContainer.remove();
        this.destroyComponents();
    }
}


export const createActivity = async (options: ActivityOptions): Promise<Salad.IActivity> => {
    return new Activity(options);
}