/**
 * handles the logic for restarting an animation after loading a file
 * And also saving the progress so that it can be restarted
 */

import { IInstance } from "../../types/external";
import { IIncompleteAnimationData } from "../../types/internal";
import { IInstanceAnimation } from "../../types/internal";
import { SaladJSONValue } from "../../types/external";

const INCOMPLETE_ANIMATION_KEY = "__incompleteAnimation";

export class IncompleteAnimationDecorator {

    constructor(private instance: IInstance) {}

    public store(dataToPersist: IIncompleteAnimationData & SaladJSONValue){
        const dataComp = this.instance.getComponent("data");
        dataComp.setValueForKey(INCOMPLETE_ANIMATION_KEY, dataToPersist);
    }

    public restart(): boolean{
        const dataComp = this.instance.getComponent("data");
        const incompleteAnimationData = dataComp?.getForKey(INCOMPLETE_ANIMATION_KEY) as IIncompleteAnimationData & SaladJSONValue;
        if(incompleteAnimationData){
            const animComp = this.instance.getComponent("animation")!;
            const props = incompleteAnimationData.props;
            const settings = incompleteAnimationData.settings;
            const options = incompleteAnimationData.options;

            // play the animation
            const anim = animComp.playAnimation(props, settings, options) as IInstanceAnimation;

            // set the delta to take us to the right place
            anim.setDelta(incompleteAnimationData.delta);
            return true;
        }
        return false;
    }

    public clear(): void {
        const dataComp = this.instance.getComponent("data");
        dataComp.setValueForKey(INCOMPLETE_ANIMATION_KEY, null);
    }

}
