import { IPage } from "../../types/internal";
import { IPageNavigationDecorator } from "../../types/external";
import { Events } from "../../types/external";

export class PageNavigationDecorator implements IPageNavigationDecorator {
    constructor(private page: IPage) {}

    public setNextPageHandler(fn: () => void) {
        const uiComp = this.page.getComponent("ui");
        uiComp.setNextPageHandler(fn);
    }
    public setPrevPageHandler(fn: () => void) {
        const uiComp = this.page.getComponent("ui");
        uiComp.setPrevPageHandler(fn);
    }
    public gotoNextPage(): void {
        const uiComp = this.page.getComponent("ui");
        const handler = uiComp.getPageHandler("next");
        if (handler) {
            handler();
        } else {
            this.page.events.emit(Events.CHANGE_PAGE, {
                increment: 1,
            });
        }
    }

    public launchURL(url: string): void {
        window.open(url, "_blank");
    }

    public gotoPrevPage(): void {
        const uiComp = this.page.getComponent("ui");
        const handler = uiComp.getPageHandler("prev");
        if (handler) {
            handler();
        } else {
            this.page.events.emit(Events.CHANGE_PAGE, {
                increment: -1,
            });
        }
    }
    public gotoPageName(to: string): void {
        this.page.events.emit(Events.CHANGE_PAGE, {
            name: to,
        });
    }

    public resetActivity(): void {
        this.page.events.emit(Events.RESET_ACTIVITY, {});
    }

    public resetPage(): void {
        this.page.events.emit(Events.RESET_PAGE, {});
    }
    
    public historyBack(): void {
        this.page.events.emit(Events.CHANGE_PAGE, {
            history: -1,
        });
    }
    
    public historyForward(): void {
        this.page.events.emit(Events.CHANGE_PAGE, {
            history: +1,
        });
    }
}
