/**
 * when the velocity changes, change the rotation
 */

import { IInstance, Schema } from "../../types/external";
import { IPage } from "../../types/internal";
import AGroupComponent from "./AGroupComponent";
import Salad from "../..";
import {InstanceEventsMap, Events} from "../../types/external";

export default class PlayGroupComponent extends AGroupComponent {
    
    constructor(data: Schema["group"], instance: IInstance, page: IPage) {
        super(data, instance, page);
        this.onComponentUpdated = this.onComponentUpdated.bind(this);
    }

    public override onCreated(): void {
        super.onCreated();
        if(this.data.value.length > 0){
            this.startListening();
        }
    }

    private getOffset(instance1: IInstance, instance2: IInstance): {x:number, y:number}{
        const position1 = instance1.getComponent("position").getPosition();
        const position2 = instance2.getComponent("position").getPosition();
        return {
            x: position2.x - position1.x,
            y: position2.y - position1.y
        }
    }

    private onComponentUpdated(eventData: InstanceEventsMap[typeof Events.COMPONENT_UPDATE]): void {
        const newPosition = this.instance.getComponent("position").getPosition();
        this.data.value.forEach((group) => {
            const instance = this.page.instances.getInstanceByName(group.name);
            if(instance){
                if(!group.offset){
                    group.offset = this.getOffset(this.instance, instance);
                }
                instance.getComponent("position").setPosition({
                    x: newPosition.x + group.offset.x,
                    y: newPosition.y + group.offset.y
                });
            }
        })
    }

    private startListening(): void{
        this.instance.events.c.position.on(Salad.Events.COMPONENT_UPDATE, this.onComponentUpdated);
    }

    private stopListening(): void{
        this.instance.events.c.position.off(Events.COMPONENT_UPDATE, this.onComponentUpdated);
    }

    public override onDestroyed(): void {
        super.onDestroyed();
        this.stopListening();
    }

    public override update(data: Schema["group"]): void {
        super.update(data);
        if(this.data.value.length > 0){
            this.startListening();
        }
        else{
            this.stopListening();
        }
    }

}
