/**
 * Abstract class for identity component.
 * This contains, for example the display name of the instance
 */

import { IAnimationComponent, IInstance } from "../../types/external";
import { Schema } from "../../types/external";
import { IPage } from "../../types/internal";
import { AComponent } from "../AComponent";
import { AnimatableProps } from "../../types/external";
import { EmptyInstanceAnimation } from "./EmptyInstanceAnimation";
import { AnimationSettings } from "../../schema/schema";
import { IInstanceAnimation } from "../../types/internal";
import { AnimationOptions } from "../../types/external";
import { AnimationSequenceByName, AnimationSequenceByProps } from "../../types/external";

export default abstract class AAnimationComponent
    extends AComponent<"animation">
    implements IAnimationComponent
{
    public name: "animation" = "animation";

    constructor(data: Schema["animation"], instance: IInstance, page: IPage) {
        super(data, instance, page);
    }

    override getDependencies() {
        return ["render"] as const;
    }

    protected getElement(): HTMLElement {
        return this.getInstanceComponent("render")!.getElement();
    }

    public playAnimation(
        props: Partial<AnimatableProps>,
        options?: Partial<AnimationSettings>,
    ): IInstanceAnimation {
        return new EmptyInstanceAnimation(); // in edit mode there are no animations but we need to return something
    }

    public animateTo(pos:{x:number, y:number}, duration?: number): IInstanceAnimation {
        return new EmptyInstanceAnimation(); // in edit mode there are no animations
    }

    public playAnimationByName(name: string, options?: Partial<AnimationSettings>): IInstanceAnimation {
        return new EmptyInstanceAnimation(); // in edit mode there are no animations
    }

    public override update(data: Schema["animation"]): void {
        super.update(data);
    }

    public getAnimation(): IInstanceAnimation | undefined {
        return new EmptyInstanceAnimation(); // in edit mode there are no animations
    }

    public stopAnimation(): void {
        // do nothing
    }

    public async playAnimationByNameAsync(name: string, settings?: Partial<AnimationSettings>, options?: Partial<AnimationOptions>): Promise<void>{
        return Promise.resolve();
    }
    
    public async playAnimationAsync(props: Partial<AnimatableProps>, settings?: Partial<AnimationSettings>, options?: Partial<AnimationOptions>): Promise<void>{
        return Promise.resolve();
    }

    public async sequenceAnimations(animations: (AnimationSequenceByName | AnimationSequenceByProps)[]): Promise<void> {
        return Promise.resolve();
    }
}
