/**
 * angular velocity component for play mode
 * Every frame we rotate the instance by the angular velocity
 */
import { Schema, IInstance, Events } from "../../types/external";
import { IPage } from "../../types/internal";
import AAngularVelocityComponent from "./AAngularVelocityComponent";

export default class PlayAngularVelocityComponent extends AAngularVelocityComponent {
    private _listening: boolean = false;

    constructor(data: Schema["angularvelocity"], instance: IInstance, page: IPage) {
        super(data, instance, page);
    }

    public override onCreated(): void {
        this.onEnterFrame = this.onEnterFrame.bind(this);
        this._updateListeners();
    }

    public override onDestroyed(): void {
        super.onDestroyed();
        this.page.events.off(Events.ENTER_FRAME, this.onEnterFrame);
    }

    /**
     * add/remove as necessary
     */
    private _updateListeners() {
        if (this.data.value !== 0) {
            if (!this._listening) {
                this._addListeners();
            }
        } else {
            if (this._listening) {
                this._removeListeners();
            }
        }
    }

    public override setAngularVelocity(value: number): void {
        super.setAngularVelocity(value);
        this._updateListeners();
    }

    /**
     * in play mode we set the velocity and update the listeners
     * @param data
     */
    public override update(data: Schema["angularvelocity"]): void {
        super.update(data);
        this._updateListeners();
    }

    private _addListeners() {
        this.page.events.on(Events.ENTER_FRAME, this.onEnterFrame);
        this._listening = true;
    }

    private _removeListeners() {
        this.page.events.off(Events.ENTER_FRAME, this.onEnterFrame);
        this._listening = false;
    }

    private onEnterFrame() {
        if (this.data.value !== 0) {
            const transformComponent = this.getInstanceComponent("transform");
            const r = transformComponent!.getRotation();
            transformComponent!.setRotation(r + this.data!.value!);
        }
    }
}
