// helper function
export const getSizeOfLottie = async (
    src: string,
): Promise<{ width: number; height: number } | undefined> => {
    try {
        let json: any;
        if (src.startsWith("{")) {
            json = JSON.parse(src);
        }
        else{
            try{
                const data = await fetch(src);
                const blob = await data.blob();
                const text = await blob.text();
                json = JSON.parse(text);
            }
            catch(e){
                console.log("failed to fetch lottie");
                console.log(e);
                return {
                    width: 256,
                    height: 256,
                }
            }
        }
        if (json && typeof json.w === "number" && json.w > 0 && typeof json.h === "number" && json.h > 0) {
            return {
                width: json.w,
                height: json.h,
            };
        }
    }
    catch (e) {
        console.log("failed to parse lottie");
    }
    return undefined;
};