/**
 * DataComponent - stores any keys and values
 */

import { IDataComponent, IInstance } from "../../types/external";
import { Schema } from "../../types/external";
import { IPage } from "../../types/internal";
import { AComponent } from "../AComponent";

export default class DataComponent extends AComponent<"data"> implements IDataComponent {
    public name: "data" = "data";

    constructor(data: Schema["data"], instance: IInstance, page: IPage) {
        super(data, instance, page);
    }

    public getAll(): Schema["data"]["value"] {
        return this.data.value;
    }

    /**
     *
     * @param key get value for key
     * @returns
     */
    public getForKey(key: string): Schema["data"]["value"][string] {
        return this.data.value[key];
    }

    /**
     * set value for key
     * @param key
     * @param value
     */
    public setValueForKey(key: string, value: Schema["data"]["value"][string]): void {
        this.data.value[key] = value;
    }

    public override update(data: Schema["data"]): void {
        this.data.value = data.value;
    }
}
