/**
 * Class that builds components from a schema and a map of component classes
 */

import {
    Schema,
    ComponentName,
    IInstance,
    ComponentsMap,
    allComponentNames,
} from "../types/external";

import type { DeepPartial } from "../utils/utils";

import {
    IPage,
    ConstructorOfComponent,
    MapComponentNameToClass,
    IComponentFactory,
} from "../types/internal";


class ComponentFactory implements IComponentFactory {
    private mapComponentNameToClass: MapComponentNameToClass;

    constructor(map: MapComponentNameToClass) {
        this.mapComponentNameToClass = map;
    }

    /**
     * Given a schema, instance and page, build all components
     * @param values
     * @param instance
     * @param page
     * @returns
     */
    public buildAllComponents<T extends DeepPartial<Schema>>(
        values: T,
        instance: IInstance,
        page: IPage,
    ): Partial<ComponentsMap> {
        const componentsMap: Partial<ComponentsMap> = {};

        const map = this.mapComponentNameToClass;

        allComponentNames.forEach(<K extends ComponentName>(key: K) => {
            if (key in map) {
                const ClassRef: ConstructorOfComponent<K> = map[key] as ConstructorOfComponent<K>;
                if(ClassRef){
                    componentsMap[key] = new ClassRef(values[key] as Schema[K] , instance, page);
                }
            }
        });

        return componentsMap;
    }
    
    public merge(componentsMap: MapComponentNameToClass):void{
        Object.assign(this.mapComponentNameToClass, componentsMap);
    }
}

export const createComponentFactory = (map: MapComponentNameToClass) =>{
    return new ComponentFactory(map);
}
