import { DrawingToolSetting } from "../../../../types/external";
import { ASimpleBrush } from "./ASimpleBrush";
import { DrawingRect, DrawingArea } from "./types";
import { getPointRect, expandRect } from "./utils";
import { CanvasCache } from "./CanvasCache";

const clrCanvas = (canvas: HTMLCanvasElement) =>
    canvas.getContext("2d")!.clearRect(0, 0, canvas.width, canvas.height);

export class SimpleBrushPen extends ASimpleBrush {
    private drawingCanvas: HTMLCanvasElement;
    private drawingCtx: CanvasRenderingContext2D;
    private prevX: number;
    private prevY: number;
    private rect: DrawingRect;

    private points: { x: number; y: number }[] = [];

    public static canvasCache = new CanvasCache({
        drawing: 1,
    });

    constructor(drawingArea: DrawingArea, setting: DrawingToolSetting) {
        super(drawingArea, setting);

        // draw in a temp canvas

        this.drawingCanvas = SimpleBrushPen.canvasCache.get("drawing", {
            w: this.canvas.width,
            h: this.canvas.height,
        });

        this.drawingCtx = this.drawingCanvas!.getContext("2d")!;
        if(this.settings.options.color){
            this.drawingCtx!.strokeStyle = this.settings.options.color;
        }
        this.drawingCtx!.lineJoin = "round";
        this.drawingCtx!.lineCap = "round";
        this.drawingCtx!.lineWidth = this.settings.options.size;

        Object.assign(this.drawingCanvas.style, {
            width: "100%",
            height: "100%",
            top: 0,
            left: 0,
            position: "absolute",
            boxSizing: "border-box",
            transform: this.canvas.style.transform,
        });
        this.canvas.parentElement?.appendChild(this.drawingCanvas);
    }

    public start(x: number, y: number): void {
        this.rect = getPointRect(x, y, this.drawingCtx.lineWidth / 2);
        this.prevX = x;
        this.prevY = y;
        this.drawingCtx.beginPath();
    }

    /**
     * copy a rect - there is no need to copy the entire canvas
     */
    private copy() {
        const x = Math.floor(this.rect.left);
        const w = Math.ceil(this.rect.right) - x;
        const y = Math.floor(this.rect.top);
        const h = Math.ceil(this.rect.bottom) - y;
        this.ctx!.drawImage(this.drawingCanvas, x, y, w, h, x, y, w, h);
    }

    public move(x: number, y: number): void {
        this.smearFromTo(this.prevX, this.prevY, x, y);

        const MIN_NUM_STEPS = 1;
        const MAX_NUM_STEPS = 8;
        const distToSteps = 0.1;
        const dx = this.prevX - x;
        const dy = this.prevY - y;
        const dist = Math.sqrt(dx * dx + dy * dy);
        const numSteps = Math.max(
            MIN_NUM_STEPS,
            Math.min(MAX_NUM_STEPS, Math.floor(dist * distToSteps)),
        );

        // append points
        for (let i = 1; i <= numSteps; i++) {
            const t = i / numSteps;
            const p = {
                x: this.prevX + (x - this.prevX) * t,
                y: this.prevY + (y - this.prevY) * t,
            };
            this.points.push(p);
        }

        clrCanvas(this.drawingCanvas);

        // draw the points
        this.drawingCtx.beginPath();
        this.drawingCtx.moveTo(this.points[0].x, this.points[0].y);
        this.points.forEach((p) => {
            this.drawingCtx.lineTo(p.x, p.y);
        });

        // stroke everything
        this.drawingCtx.stroke();
        expandRect(this.rect, x, y, this.drawingCtx.lineWidth / 2);
        this.prevX = x;
        this.prevY = y;
    }

    public end(): void {
        this.copy();
        clrCanvas(this.drawingCanvas);
        this.drawingCanvas.remove();
    }
}
