import Lottie, { AnimationItem, AnimationConfigWithData, AnimationConfigWithPath } from "lottie-web";
import Salad from "../index";

type MakeLottieOptions = {
    autoplay: boolean;
    loop: boolean;
};

export const destroyLottie = (item: Salad.ILottieAnimationItem & AnimationItem) => {
    if (item && item.goToAndStop) {
        item.goToAndStop(0);
    }
    item.removeEventListener("data_ready");
    item.removeEventListener("data_failed");
    item.removeEventListener("error");
    item.removeEventListener("data_ready");
    item.removeEventListener("drawnFrame");
    item.removeEventListener("complete");
    item.removeEventListener("DOMLoaded");
    item.destroy();
}

export const lottie = async (
    container: HTMLElement,
    path: string,
    options: MakeLottieOptions,
): Promise<Salad.ILottieAnimationItem & AnimationItem> => {

    const sharedParams: Omit<AnimationConfigWithData, "animationData"> & Omit<AnimationConfigWithPath, "path">= {
        container,
        renderer: "svg",
        autoplay: options.autoplay,
        loop: options.loop,
        rendererSettings: {
            preserveAspectRatio: "xMidYMid meet",
            progressiveLoad: true,
            hideOnTransparent: true
        }
    }

    let params:  AnimationConfigWithData | AnimationConfigWithPath ;

    if (path.startsWith("{")) {
        params = {
            ...sharedParams,
            animationData: JSON.parse(path),
        }
    }
    else{
        params = {
            ...sharedParams,
            path,
        }
    }
    
    const item = Lottie.loadAnimation(params);

    // performance optimization
    item.setSubframe(false);

    return new Promise((resolve, reject) => {

        const tidyUp = () => {
            item.removeEventListener("DOMLoaded", onLoaded);
            item.removeEventListener("data_failed", onDataFailed);
            item.removeEventListener("error", onError);
        }

        // you can specify a default frame to go to when the lottie is loaded
        const onLoaded = () => {
            setTimeout(() => {
                resolve(item);
                tidyUp();
            }, 0)
        }

        const onDataFailed = () => {
            console.warn("failed to load lottie");
            reject();
            tidyUp();
        }

        const onError = () => {
            console.warn("failed to load lottie");
            reject();
            tidyUp();
        }

        item.addEventListener("DOMLoaded", onLoaded);
        item.addEventListener("data_failed", onDataFailed);
        item.addEventListener("error", onError);
    });
};
