import Salad from "../../../index";
import { AActivityComponent } from "../AActivityComponent";
import { IActivityPersistenceComponent } from "../../../types/external";
import { ActivityOptions } from "../../../types/internal";

export abstract class AActivityPersistenceComponent extends AActivityComponent implements IActivityPersistenceComponent{
    
    constructor(protected activity: Salad.IActivity, protected options?: ActivityOptions) {
        super();
    }

    protected _save(): void {
        const page = this.activity.getCurrentPage()!;
        const pagesComp = this.activity.getComponent("pages");
        const index = pagesComp.getPageIndexForPageId(page.getId());

        // get the data
        const instances = page.getInstancesData();
        const schema = page.getPageData();
        
        // save the data locally
        this.options.pages[index] = {
            ...this.options.pages[index],
            instances,
            schema
        }
    }

    protected abstract shouldSave(): boolean;

    public save(): boolean {
        if(this.shouldSave()){
            this._save();
            return true;
        }
        return false;
    }

}
