/**
 * Different ways of highlighting an element
 */
import { Schema } from "../../types/external";
import { ConstructorOf } from "@root/salad/types/utils";
import {IInstance} from "@root/salad/types/external";
import { IHighlighter, HighlighterOptions } from "./types";
import {map as confettiMap} from "./ConfettiHighlighters"
import {map as animationMap} from "./AnimationHighlighters"

class Glow implements IHighlighter {

    constructor(protected options: HighlighterOptions) {
        Object.assign(options.element.style, {
            "box-shadow": this.getCSS()
        })
    }

    private getCSS() {
        const colors = ["#48abe0", "#ebecca", "#8a2be2", "#ff1493"];
        return colors.map((color, i) => {
            const offset = i + 1;
            return `0 0 ${offset * 2}px ${offset * 1.5}px ${color}`;
        }).join(", ");
    }
    
    public destroy() {
        delete this.options.element.style.boxShadow;
    }
}

type HighlightType = Exclude<Schema["highlight"]["type"], "none">



const highlighterMap:{[name in HighlightType]: ConstructorOf<IHighlighter, [HighlighterOptions]>} = {
    ...confettiMap,
    ...animationMap,
    glow: Glow
}

export const makeHighlighter = (type: HighlightType, instance: IInstance, canvas?: HTMLCanvasElement): IHighlighter => {
    const Klass = highlighterMap[type];
    if (Klass) {
        const renderComponent = instance.getComponent("render");
        const element = renderComponent.getElement();
        return new Klass({
            element,
            canvas,
            instance
        });
    }
    return undefined;
};
