/**
 * when the velocity changes, change the rotation
 */

import { IInstance, Schema } from "../../types/external";
import { IPage } from "../../types/internal";
import AMovementComponent from "./AMovementComponent";
import { movementIndicator } from "../../utils/domElementFactory";
import { CSSDomUpdate } from "../../types/external";
export default class EditMovementComponent extends AMovementComponent {
    private _element: HTMLElement | undefined;

    constructor(data: Schema["movement"], instance: IInstance, page: IPage) {
        super(data, instance, page);
    }

    public override onCreated(): void {
        super.onCreated();
        if (this.data.offsetAngle !== 0) {
            this._updateElement();
        }
    }

    public override setOffsetAngle(angle: number): void {
        super.setOffsetAngle(angle);
        this._updateElement();
    }

    public override update(data: Schema["movement"]): void {
        super.update(data);
        this._updateElement();
    }

    private _updateElement(): void {
        if (this.data.offsetAngle !== 0) {
            if (!this._element) {
                this._element = movementIndicator();
                const parent = this.getInstanceComponent("render").getElement();
                parent.appendChild(this._element);
            }
            const css: CSSDomUpdate["css"] = {
                transform: {
                    rotate: `${this.data.offsetAngle}deg`,
                }
            }
            this.page.getComponent("domupdate").addCSSUpdate({
                element: this._element,
                css
            });
        }
        else {
            if (this._element) {
                this._element.remove();
                this._element = undefined;
            }
        }
    }
}
