/**
 * transform component. Handles rotation, scale, and origin
 */

import { IInstance } from "../../../types/external";
import { IPage } from "../../../types/internal";
import { ArrowKeyListener } from "./ArrowKeyListener";
import { ArrowKeyRotListener } from "./ArrowKeyRotListener";
import { ArrowDriveKeyListener } from "./ArrowDriveKeyListener";
import { FireListener } from "./FireListener";
import { WASDKeyListener } from "./WASDKeyListener";
import { WASDDriveKeyListener } from "./WASDDriveKeyListener";
import { Schema } from "../../../types/external";
import { ConstructorOf } from "../../../types/utils";

export interface IInputKeyListener {
    destroy(): void;
}

export interface IFireListener {
    destroy(): void;
}

type GameControl = Schema["gamecontrol"];

const mapTypeToInputClass: {
    [type in Exclude<GameControl["input"]["type"], "none">]: ConstructorOf<
        IInputKeyListener,
        [IInstance, IPage, number, number]
    >;
} = {
    arrow: ArrowKeyListener,
    wasd: WASDKeyListener,
    arrowrot: ArrowKeyRotListener,
    arrowdrive: ArrowDriveKeyListener,
    wasddrive: WASDDriveKeyListener,
};

export const getInputKeyListener = (
    instance: IInstance,
    page: IPage,
    data: Schema["gamecontrol"]["input"],
): IInputKeyListener | undefined => {
    const Klass = mapTypeToInputClass[data.type];
    return new Klass(instance, page, data.duration, data.amount);
};

export const getFireListener = (
    instance: IInstance,
    page: IPage,
    data: Schema["gamecontrol"]["fire"],
): IInputKeyListener | undefined => {
    return new FireListener(instance, page, data.name, data.type);
};
