/**
 * sounds component.
 * In play mode we play a sound when the instance is clicked
 */
import ASoundsComponent from "./ASoundsComponent";
import { Events } from "../../types/external";
import { Schema } from "../../types/external";
import { IPage } from "../../types/internal";
import { IInstance } from "../../types/external";
import { InstanceEventsMap } from "../../types/external";

export default class PlaySoundsComponent extends ASoundsComponent {

    constructor(data: Schema["sounds"], instance: IInstance, page: IPage) {
        super(data, instance, page);
        this.onInstanceClick = this.onInstanceClick.bind(this);
        this.onInstanceDropped = this.onInstanceDropped.bind(this);
        this.onInstanceAccepted = this.onInstanceAccepted.bind(this);
        this.onVisChanged = this.onVisChanged.bind(this);
    }

    private onInstanceClick() {
        const soundToPlay = this.data?.onInstanceClick;
        this.page.getComponent("sound")?.playSound(soundToPlay);
    }

    private onInstanceDropped() {
        const soundToPlay = this.data?.onInstanceDropped;
        this.page.getComponent("sound")?.playSound(soundToPlay);
    }

    private onInstanceAccepted() {
        const soundToPlay = this.data?.onInstanceAccepted;
        this.page.getComponent("sound")?.playSound(soundToPlay);
    }

    private onVisChanged(eventData: InstanceEventsMap[typeof Events.COMPONENT_UPDATE]) {
        const payload = eventData.payload
        if(payload.key === "visibility" && payload.value === "visible"){
            const soundToPlay = this.data?.onInstanceVisible;
            this.page.getComponent("sound")?.playSound(soundToPlay);
        }
    }

    protected _addListeners(): void {
        if (this.data?.onInstanceClick) {
            this.instance.events.on(Events.INSTANCE_CLICK, this.onInstanceClick);
        }
        if (this.data?.onInstanceDropped) {
            this.instance.events.on(Events.INSTANCE_DROPPED, this.onInstanceDropped);
        }
        if (this.data?.onInstanceAccepted) {
            this.instance.events.on(Events.INSTANCE_ACCEPTED, this.onInstanceAccepted);
        }
        if(this.data?.onInstanceVisible){
            this.instance.events.c.visibility.on(Events.COMPONENT_UPDATE, this.onVisChanged);
        }
    }

    protected _removeListeners(): void {
        this.instance.events.off(Events.INSTANCE_CLICK, this.onInstanceClick);
        this.instance.events.off(Events.INSTANCE_DROPPED, this.onInstanceDropped);
        this.instance.events.off(Events.INSTANCE_DROPPED, this.onInstanceAccepted);
        this.instance.events.c.visibility.off(Events.COMPONENT_UPDATE, this.onVisChanged);
    }

    public override onCreated(): void {
        super.onCreated();
        this._addListeners();
    }

    public override onDestroyed(): void {
        super.onDestroyed();
        this._removeListeners();
    }
}
