/**
 * Page background component
 *
 */

import { IPage } from "../../types/internal";
import { APageComponent } from "../APageComponent";
import { background } from "../../utils/domElementFactory";
import { Size, PageSchema, IPageBackgroundComponent } from "../../types/external";

type Color = PageSchema["background"]["color"];
export default class PageBackgroundComponent
    extends APageComponent<"background">
    implements IPageBackgroundComponent
{
    // html container
    private _element: HTMLElement;

    public name: "background" = "background";

    constructor(data: PageSchema["background"], page: IPage) {
        super(data, page);
    }

    /**
     * lifecycle
     * create the background element and register a layer
     */
    override onCreated() {
        super.onCreated();
        this._element = background();
        this.update();
        const layerComp = this.getPageComponent("layers");
        layerComp.initLayer("background", this._element, {
            type: "full",
        });
    }

    override onDestroyed() {
        const layerComp = this.getPageComponent("layers");
        layerComp.removeLayer("background");
        super.onDestroyed();
    }

    public override getDependencies() {
        return ["layout", "layers"] as const;
    }

    /**
     * Update the HTML to show the background color/image
     */
    private async update() {
        let css: Partial<CSSStyleDeclaration> = {
            backgroundSize: "100% 100%",
            backgroundRepeat: "no-repeat",
            backgroundImage: "none",
            backgroundColor: "transparent",
        };
        if (this.data.name) {
            const src = await this.getAssetManager().getPathForKey(this.data.name);
            css = {
                ...css,
                backgroundImage: `url('${src}')`,
            };
        } else if (this.data.color) {
            css = {
                ...css,
                backgroundColor: this.data.color,
            };
        }
        Object.assign(this._element.style, css);
    }

    public setImage(name: string) {
        this.removeColor();
        this.data.name = name;
        this.update();
    }

    public removeImage(): void {
        this.data.name = "";
        this.update();
    }

    public removeColor(): void {
        this.data.color = "";
        this.update();
    }

    public setColor(clr: Color): void {
        this.removeImage();
        this.data.color = clr;
        this.update();
    }

    public getColor(): Color {
        return this.data.color!;
    }

    public getImage(): string {
        return this.data.name!;
    }

    public getElement(): HTMLElement {
        return this._element;
    }

    public getSize(): Size {
        return this.data.size!;
    }

    public setSize(w: number, h: number): void {
        this.data.size = {
            width: w,
            height: h,
        };
        this.update();
    }
}
