/**
 * make text areas look nice - eg. speech bubbles have adjusted size so the text fits inside the bubble
 */

import { ITextComponent, IInstance } from "../../types/external";
import { Schema } from "../../schema/schema";
import { ConstructorOf } from "../../types/utils";
abstract class ATextLayoutHelper {
    constructor(
        protected component: ITextComponent,
        protected instance: IInstance,
    ) {}
    public abstract redraw(): void;
}

class SpeechLayoutHelper extends ATextLayoutHelper {
    private static SPEECH_ASPECT_RATIO = 300 / 226; // width:height of the actual bubble

    // fit a rectangle inside the speed bubble, 54% of the width, 28% from the left etc
    private static SPEECH_INNER_WIDTH_PERCENT = 58;
    private static SPEECH_INNER_LEFT_PERCENT = 24;

    private static SPEECH_INNER_HEIGHT_PERCENT = 57;
    private static SPEECH_INNER_TOP_PERCENT = 16;

    public redraw(): void {
        const size = this.instance.getComponent("size").getSize();
        const textElement = this.component.getTextArea();
        const ar = size.width / size.height;
        let width:number, height:number, left:number, top: number;
        if (ar >= SpeechLayoutHelper.SPEECH_ASPECT_RATIO) {
            // wider
            height = size.height;
            width = size.height * SpeechLayoutHelper.SPEECH_ASPECT_RATIO;
            left = (size.width - width) / 2;
            top = 0;
        } else {
            height = size.width / SpeechLayoutHelper.SPEECH_ASPECT_RATIO;
            width = size.width;
            top = (size.height - height) / 2;
            left = 0;
        }

        const innerWidth = (width * SpeechLayoutHelper.SPEECH_INNER_WIDTH_PERCENT) / 100;
        const innerLeft = left + (width * SpeechLayoutHelper.SPEECH_INNER_LEFT_PERCENT) / 100;

        const innerHeight = (height * SpeechLayoutHelper.SPEECH_INNER_HEIGHT_PERCENT) / 100;
        const innerTop = top + (height * SpeechLayoutHelper.SPEECH_INNER_TOP_PERCENT) / 100;

        Object.assign(textElement.style, {
            width: `${innerWidth}px`,
            height: `${innerHeight}px`,
            marginLeft: `${innerLeft}px`,
            marginTop: `${innerTop}px`,
        });
    }
}

class PlainLayoutHelper extends ATextLayoutHelper {
    public redraw(): void {
        const textElement = this.component.getTextArea();
        Object.assign(textElement.style, {
            width: `100%`,
            height: `100%`,
        });
    }
}

export const getLayoutHelper = (component: ITextComponent, instance: IInstance) => {
    const type = component.getType();

    const map: {
        [key in Schema["text"]["type"]]: ConstructorOf<
            ATextLayoutHelper,
            [ITextComponent, IInstance]
        >;
    } = {
        speech_left: SpeechLayoutHelper,
        speech_right: SpeechLayoutHelper,
        plain: PlainLayoutHelper,
        boxed: PlainLayoutHelper,
    };

    const Klass = map[type];
    return new Klass(component, instance);
};
