const isSuspendedOrInterrupted = (audioContext: AudioContext) : boolean => {
    return audioContext.state === "suspended" || (audioContext.state as any) === "interrupted";
}

export default class UnlockAudioContextHelper {

    private unlockWindows: HTMLElement[] = [];
    private audioContext:AudioContext = null;
    private silentBuffer: AudioBuffer = null;

    constructor() {
        this.playSilentSound = this.playSilentSound.bind(this);
    }

    addUnlockEventsToWindow(window: HTMLElement) {
        this.unlockWindows.push(window);
        if (this.audioContext && isSuspendedOrInterrupted(this.audioContext)) {
            this.addInteractionEventsToElement(window);
        }
    }

    private createInteractionEvents() {
        this.unlockWindows.forEach((element) => {
            this.addInteractionEventsToElement(element);
        });
    }

    private removeInteractionEvents() {
        this.unlockWindows.forEach((element) => {
            this.removeInteractionEventsFromElement(element);
        });
    }

    setContext(audioContext: AudioContext) {
        this.audioContext = audioContext;
        this.audioContext.onstatechange = () => {
            if (isSuspendedOrInterrupted(this.audioContext)) {
                this.audioContext.resume();
                setTimeout(() => {
                    // perhaps it needs to be unlocked again...
                    if (isSuspendedOrInterrupted(this.audioContext)) {
                        this.createInteractionEvents();
                    }
                }, 500);
            }
            if (this.audioContext.state === "running") {
                this.removeInteractionEvents();
            }
        };
        if (isSuspendedOrInterrupted(this.audioContext)) {
            this.createInteractionEvents();
        }
    }
    
    private addInteractionEventsToElement(element: HTMLElement) {
        element.addEventListener("mousedown", this.playSilentSound);
        element.addEventListener("touchstart", this.playSilentSound);
    }

    private removeInteractionEventsFromElement(element: HTMLElement) {
        element.removeEventListener("mousedown", this.playSilentSound);
        element.removeEventListener("touchstart", this.playSilentSound);
    }

    public getSilentBuffer() {
        if (!this.silentBuffer) {
            this.silentBuffer = this.audioContext.createBuffer(1, 1, 22050);
        }
        return this.silentBuffer;
    }

    private playSilentSound() {
        const source = this.audioContext.createBufferSource();
        source.buffer = this.getSilentBuffer();
        source.connect(this.audioContext.destination);
        source.start();
    }

}