/**
 * page layers component
 */
import { APageLayer } from "./APageLayer";
import { PageSchema } from "../../../types/external";

type Box = PageSchema["camera"]["view"];

export class UnscaledPageLayer extends APageLayer {
    public showView(view: Box, globalScale: number): void {
        const scaledSize = {
            width: Math.round(view.width * globalScale),
            height: Math.round(view.height * globalScale)
        }
        this.setLayerSize(scaledSize);
        if(this.element.tagName.toLowerCase() === "canvas"){
            const el = this.element as HTMLCanvasElement;
            el.width = scaledSize.width;
            el.height = scaledSize.height;
        }
    }
}
