/**
 * A dragger for play mode
 *
 * Ignore rotation and resizing - you can't do it
 *  - enforce the collision shape
 *  - emit instanceClick
 *  - bring to the top
 *  - apply axis restrictions
 *  - apply containment restrictions
 *  - apply foreshortening
 */

import { IInstance } from "../types/external";
import { IPage } from "../types/internal";
import { Point } from "../types/external";
import { applyAxis } from "../components/draggable/AxisHelpers";
import { PageEventsMap, Events, IPageExternal } from "../types/external";
import { ADragger } from "./ADragger";
import { getMoveable } from "./MoveableFactory";
import { DraggerOptions, MoveableEventData } from "./types";
export class PlayDragger extends ADragger {

    private hasMoved = false;
    private _useGlobalScale = false;

    constructor(page: IPageExternal, instance: IInstance) {
        super(page, instance);

        const renderComponent = this.instance!.getComponent("render");
        const target = renderComponent!.getElement();

        const positionComponent = this.instance!.getComponent("position");
        const draggableComponent = this.instance!.getComponent("draggable");
        const draggableData = draggableComponent!.getData();

        let startPos: Point | undefined = undefined;

        // get the options
        const dragOptions: DraggerOptions = {
            onClick: (e: MoveableEventData["click"]) => {
                // figure out where they clicked

                const clientPos = {
                    x: e!.clientX,
                    y: e!.clientY,
                };

                const point = this.page
                    .layout!
                    .getPagePositionForClientPosition(clientPos);

                const eventData: PageEventsMap[typeof Events.INSTANCE_CLICK] = {
                    target: this.instance!,
                    targets: [this.instance!],
                    point,
                    originalEvent: e!.inputEvent,
                };
                // just dispatch the events we need. This is annoying but moveable swallows these events.
                this.page.events.emit(Events.INSTANCE_CLICK, eventData);
                this.instance!.events.emit(Events.INSTANCE_CLICK, eventData);
            },
            onDragStart: (e: MoveableEventData["dragStart"]) => {
                // find out if they clicked on the collision shape, if not stop.
                const clientPos = {
                    x: e!.clientX,
                    y: e!.clientY,
                };
                const p = this.page
                    .layout
                    .getPagePositionForClientPosition(clientPos);

                const collComp = this.instance!.getComponent("collision");
                const shape = collComp!.getTransformedShape();
                const inside = shape.containsPoint(p);

                this.hasMoved = false;

                if (!inside) {
                    console.log("e", e)
                    e!.stop();
                } else {
                    startPos = positionComponent!.getPosition();

                    if (draggableData!.bringToFront) {
                        renderComponent!.bringToFront();
                    }
                    this.page.events.emit(Events.INSTANCE_START_DRAG, {
                        selectedInstance: this.instance!,
                    });
                    this.instance!.events.emit(Events.INSTANCE_START_DRAG, {
                        selectedInstance: this.instance!,
                    })
                }
            },
            onDragEnd: () => {
                if(this.hasMoved) {
                    // dispatch the relevant events
                    this.page.dragndrop.dropInstance(this.instance!);
                }
                startPos = undefined;
                this._useGlobalScale = false;
            },
            onDrag: (e: MoveableEventData["drag"]) => {

                let scale = 1;
                if(this._useGlobalScale){
                    /**
                     * not sure why but when we force start dragging (when we spawn a new instance) we need to use the global scale.
                     * if we don't do this, the instance will move too fast.
                     * otherwise (if we are just dragging normally) we can use 1
                     */
                    scale = this.page.layout.getGlobalScale() || 1;
                }

                this.hasMoved = true;
                const dx = e!.beforeTranslate[0] / scale;
                const dy = e!.beforeTranslate[1] / scale;
                
                // update the position component.
                let newPosition = {
                    x: startPos!.x + dx,
                    y: startPos!.y + dy
                };

                //apply dragging axis
                newPosition = applyAxis(
                    positionComponent!.getPosition(),
                    newPosition,
                    draggableData!.axis,
                );

                // when you setPosition you might get a new position due to 'containment'
                positionComponent!.setPosition(newPosition);

                // it might have failed due to containment, so get it again
                newPosition = positionComponent!.getPosition();

                // apply fore-shortening. Eg this is used in maths city when you move the watering can far away
                if (draggableData && draggableData.foreShorten && draggableData.foreShorten > 0) {
                    const transComponent = this.instance!.getComponent("transform");
                    const bgSize = this.page.background!.getSize();
                    // from 0 to 1
                    const fraction1 = newPosition.y / bgSize.height;
                    // from -1 to 1
                    const fraction2 = 2 * (fraction1 - 0.5);

                    const scale = 1 + (draggableData.foreShorten * fraction2) / 100;
                    transComponent!.setScale({ x: scale, y: scale });
                }
            },
        };

        //make the moveable instance
        this.moveable = getMoveable(
            target,
            this.page.getPageContainer(),
            this.getMoveableOptions(),
            dragOptions,
        );
    }

    public override startDraggingUsingEvent(e: MouseEvent | TouchEvent): void {
        this._useGlobalScale = true;
        super.startDraggingUsingEvent(e);
    }
}
