import { DrawingToolSetting } from "../../../../types/external";
import { ASimpleBrush } from "./ASimpleBrush";
import { DrawingArea } from "./types";
import { averageOfLastN } from "../../../../types/utils";

export class SimpleBrushRake extends ASimpleBrush {
    private lastMousePositions: { x: number; y: number }[] = [];

    //must be odd for it to look correct
    private static numProngsOnRake = 7;

    // gap between each one
    private static distanceBetweenProngs = 16;

    constructor(drawingArea: DrawingArea, setting: DrawingToolSetting) {
        super(drawingArea, setting);
    }

    private getAngle(pos: { x: number; y: number }): number {
        // remove wobbling by averaging the last 3 mouse positions
        const smoothing = 3;
        if (!this.lastMousePositions || this.lastMousePositions.length <= 1) {
            return Math.PI / 4;
        } else {
            const averaged = averageOfLastN(this.lastMousePositions, smoothing);
            const dx = pos.x - averaged.x;
            const dy = pos.y - averaged.y;
            return Math.atan2(dy, dx);
        }
    }

    public start(x: number, y: number): void {
        this.lastMousePositions.push({ x, y });
    }

    public move(x: number, y: number): void {
        const angle = this.getAngle({ x, y }) + Math.PI / 2;
        const offset = {
            x: Math.cos(angle) * SimpleBrushRake.distanceBetweenProngs,
            y: Math.sin(angle) * SimpleBrushRake.distanceBetweenProngs,
        };
        const lastPos = this.lastMousePositions[this.lastMousePositions.length - 1];
        for (let i = 0; i < SimpleBrushRake.numProngsOnRake; i++) {
            const index = i - Math.floor(SimpleBrushRake.numProngsOnRake / 2);
            const p0 = {
                x: lastPos.x + index * offset.x,
                y: lastPos.y + index * offset.y,
            };
            const p1 = {
                x: x + index * offset.x,
                y: y + index * offset.y,
            };

            this.smearFromTo(p0.x, p0.y, p1.x, p1.y);
        }
        this.lastMousePositions.push({ x, y });
    }

    public end(): void {}
}
