/**
 * script component - stores typescript code that the author can write
 */

import { IScriptComponent, IInstance, Schema } from "../../types/external";
import { IPage } from "../../types/internal";
import { AComponent } from "../AComponent";

export default class ScriptComponent extends AComponent<"script"> implements IScriptComponent {
    public name: "script" = "script";

    constructor(data: Schema["script"], instance: IInstance, page: IPage) {
        super(data, instance, page);
    }

    public override update(data: Schema["script"]) {
        super.update(data);
    }

    public getHasRunOnce(): boolean {
        return this.data.ranOnce;
    }

    public setHasRunOnce(ran: boolean = true): void {
        this.data.ranOnce = ran;
    }

    public getContent(): string {
        return this.data.content;
    }

    public setContent(value: string): void {
        this.data.content = value;
    }

    public getTranspiledCode(): string | undefined {
        return this.data.transpiledCode;
    }

}
