import Salad from "../../salad";
import isEqual from "fast-deep-equal";
import deepmerge from "@fastify/deepmerge"

function replaceByClonedSource(options:any) {
    return function (target:any[], source:any[]) {
        return source
    }
}
const _deepmerge = deepmerge({
        mergeArray: replaceByClonedSource
    });

export type DeepPartial<T> = T extends object
    ? {
          [P in keyof T]?: DeepPartial<T[P]>;
      }
    : T;

/**
 * Returns a new object, Note - this does not change its arguments
 * items in schema overwite the same items in defaults
 * 
 * @param defaults
 * @param schema
 * @returns
 */
export const mergeDefaultsIntoSchema = <T>(defaults: T, schema: DeepPartial<T>): T => {
    return _deepmerge(defaults, schema as Partial<T>) as T;
};

export type HandlerFor<Obj extends object> = <K extends keyof Obj>(key: K, value: Obj[K]) => void;

export const proxied = <Obj extends object>(data: Obj, handler: HandlerFor<Obj>) => {
    const set = <K extends keyof Obj>(target: Obj, key: K, value: Obj[K]) => {
        const valHasChanged = !isEqual(target[key], value)
        target[key] = value;
        if (valHasChanged) {
            handler(key, value);
        }
        return true;
    };
    return new Proxy<Obj>(data, {
        set: set as ProxyHandler<Obj>["set"],
    });
};

export type Rect = {
    x: number;
    y: number;
    width: number;
    height: number;
};

export const isASubsetOfB = <T = string>(a: ReadonlyArray<T>, b: ReadonlyArray<T>): boolean => {
    return aIncludesB(b, a);
};

export const aIncludesB = <T = string>(a: ReadonlyArray<T>, b: ReadonlyArray<T>): boolean => {
    return a.filter((k) => b.includes(k)).length === b.length;
};

export const equals = <T = string>(a: ReadonlyArray<T>, b: ReadonlyArray<T>): boolean => {
    return isASubsetOfB(a, b) && isASubsetOfB(b, a);
};

export const unique = <T = string>(arr: ReadonlyArray<T>): T[] => {
    return Array.from(new Set(arr));
};

export const disableSelect = (element: HTMLElement) => {
    Object.assign(element.style, {
        "user-select": "none",
        "-webkit-user-select": "none",
        "-moz-user-select": "none",
        "-ms-user-select": "none"
    });
};

export const disableDomElement = (element: HTMLElement) => {
    Object.assign(element.style, {
        "user-select": "none",
        "-webkit-user-select": "none",
        "-moz-user-select": "none",
        "-ms-user-select": "none"
    });
    disableDraggingOfDomElement(element);
};

//TODO nothing works in chrome - impossible to make it unselectable
export const disableTextArea = (element: HTMLTextAreaElement) => {
    Object.assign(element.style, {
        "user-select": "none",
        "-webkit-user-select": "none",
        "-webkit-tap-highlight-color": "transparent",
        "-webkit-touch-callout": "none",
        "-moz-user-select": "none",
        "-ms-user-select": "none"
    });

    element.setAttribute("disabled", "disabled");
    element.setAttribute("unselectable", "on");
    element.addEventListener('focus', (e) => (e.target as HTMLElement).blur());
};

export const disableDraggingOfDomElement = (element: HTMLElement) => {
    element.setAttribute("draggable", "false");
};

type EventPosition = {
    x: number;
    y: number;
};

export const getEventPosition = (
    e: PointerEvent | TouchEvent | MouseEvent,
): EventPosition => {
    let xy = {
        pageX: 0,
        pageY: 0,
        clientX: 0,
        clientY: 0,
    }
    
    if ("TouchEvent" in window && e instanceof TouchEvent) {
        if (e.changedTouches && e.changedTouches.length >= 1) {
            xy = e.changedTouches[0];
        } else if (e.touches && e.touches.length >= 1) {
            xy = e.touches[0];
        }
    } else if ("PointerEvent" in window && e instanceof PointerEvent) {
        if ((e as any).originalEvent) {
            e = (e as any).originalEvent as PointerEvent;
        }
        xy = {
            pageX: e.pageX,
            pageY: e.pageY,
            clientX: e.clientX,
            clientY: e.clientY,
        };
    } else if ("MouseEvent" in window && e instanceof MouseEvent) {
        xy = {
            pageX: e.pageX,
            pageY: e.pageY,
            clientX: e.clientX,
            clientY: e.clientY,
        };
    }
    return {
        x: xy.pageX || xy.clientX,
        y: xy.pageY || xy.clientY,
    };
};

export const stringToNumberArray = (valueStr: string): number[] | undefined => {
    const numbers = valueStr.split(",").map((n) => {
        const num = parseFloat(n);
        if (isNaN(num)) {
            return null;
        }
        return num;
    });
    if (numbers.some((n) => n === null)) {
        return undefined;
    }
    return numbers as number[];
};

export const stringToPointsArray = (valueStr: string): Salad.Point[] | undefined => {
    const points = valueStr.split(",").map((p) => {
        p = p.trim();
        const [xStr, yStr] = p.split(" ");
        const x = parseFloat(xStr);
        const y = parseFloat(yStr);
        if (isNaN(x) || isNaN(y)) {
            return null;
        }
        return {
            x,
            y,
        };
    });
    if (points.some((p) => p === null)) {
        return undefined;
    }
    else{
        return points as Salad.Point[];
    }
};


export const clone = <T>(val: T): T => {
    if(!val){
        return val;
    }
    return JSON.parse(JSON.stringify(val)) as T;
};

/**
 * split into blocks of size n
 * @param arr 
 * @param n 
 * @returns 
 */
export const splitIntoN = <T>(arr: T[], n: number): T[][] => {
    if (arr.length % n !== 0) {
        throw new Error("mismatch");
    }
    const result:T[][] = [];
    for (let i = 0; i < arr.length; i += n) {
        const block = arr.slice(i, i + n) as T[]
        result.push(block);
    }
    return result;
};

const wIsOnRHSOfv = (v: { x: number; y: number }, w: { x: number; y: number }): boolean => {
    const cross = v.x * w.y - w.x * v.y;
    return cross < 0;
};

export const p2IsOnRHSOfLineSegment = (
    p0: { x: number; y: number },
    p1: { x: number; y: number },
    p2: { x: number; y: number },
): boolean => {
    const v = {
        x: p1.x - p0.x,
        y: p1.y - p0.y,
    };
    const w = {
        x: p2.x - p0.x,
        y: p2.y - p0.y,
    };
    return wIsOnRHSOfv(v, w);
};

export const canUseKeyboard = (): boolean => {
    const dialogsOpen = document.querySelectorAll(".ui-dialog:is(:visible)").length >= 1;
    const activeElement = document.activeElement;

    const inputFocus = activeElement instanceof HTMLInputElement;
    const textFocus = activeElement instanceof HTMLTextAreaElement;
    const divFocus = activeElement instanceof HTMLDivElement && activeElement.isContentEditable;

    return !(dialogsOpen || inputFocus || textFocus || divFocus);
};

export const findCommonPrefixes = (labels: string[], minLengthOfPrefix:number = 3, maxLengthOfPrefix:number = 8, maxNumber: number = 4): string[] => {

    const prefixCountMap: {[key:string]:number} = {}
  
    // Build the prefix count map
    for (const label of labels) {
        for (let i = 1; i <= label.length; i++) {
            const prefix = label.slice(0, i);
            prefixCountMap[prefix] = (prefixCountMap[prefix] || 0) + 1
        }
    }

    let prefixes = Object.keys(prefixCountMap)

    //remove duplicates
    prefixes = Array.from(new Set(prefixes));

    // they must exist twice
    prefixes = Object.keys(prefixCountMap).filter(prefix => prefixCountMap[prefix] >= 2);

    // remove any that are prefixes of others. Eg. if apple is in our list, we don't want app
    prefixes = prefixes.filter(prefix => {
        return !prefixes.some(otherPrefix => otherPrefix !== prefix && otherPrefix.startsWith(prefix));
    });

    // get the right length
    prefixes = prefixes.filter(prefix => {
        return prefix.length >= minLengthOfPrefix && prefix.length <= maxLengthOfPrefix
    });

    // Sort by count (descending) and length (descending) - count is more important but we want long ones
    prefixes = prefixes.sort((p1:string, p2:string) => {
        const count1 = prefixCountMap[p1];
        const count2 = prefixCountMap[p2];
        if(count1 > count2){
            return -1;
        }
        else if(count1 < count2){
            return 1;
        }
        else{
            if(p1.length > p2.length){
                return -1;
            }
            else if(p1.length < p2.length){
                return 1;
            }
        }
        return 0;
    });
  
    // Take the top maxNumber
    prefixes = prefixes.slice(0, maxNumber);
  
    return prefixes;
  }
  
/**
 * Returns the array in which if you traverse it you never get an item that has dependencies that haven't been visited yet
 * @param dependencyMap 
 * @returns 
 */
export const resolveDependencies = <T extends string>(dependencyMap: Map<T, Set<T>>): T[] => {
    const orderedComponentNames: T[] = [];
    const allKeys = Array.from(dependencyMap.keys());
    
    const reverseDependencies = new Map<T, Set<T>>();

    allKeys.forEach((key:T) => {
        
        // Track reverse dependencies
        for (const dep of dependencyMap.get(key)!) {
            if(!dependencyMap.has(dep)){
                throw new Error("Dependency not found: " + dep);
            }
            if (!reverseDependencies.has(dep)){
                reverseDependencies.set(dep, new Set());
            }
            reverseDependencies.get(dep)!.add(key);
        }
    });

    // Queue components with no dependencies first
    const processQueue: T[] = allKeys.filter((name: T) => dependencyMap.get(name)!.size === 0);

    let infiniteLoopTrap = 0;

    const processedKeys = new Set<T>();

    while (processQueue.length > 0 && infiniteLoopTrap < 1000) {
        const key = processQueue.shift()!;

        orderedComponentNames.push(key);
        processedKeys.add(key);

        // Resolve reverse dependencies
        if (reverseDependencies.has(key)) {
            const dependents = reverseDependencies.get(key)!;
            for (const dependent of dependents!) {
                const depsForDependent = dependencyMap.get(dependent)!;
                depsForDependent.delete(key);
                if (depsForDependent.size === 0) {
                    processQueue.push(dependent);
                }
            }
        }
        infiniteLoopTrap++;
    }

    if (infiniteLoopTrap >= 1000) {
        console.error("Infinite loop detected in resolveDependencies");
    }

    if (orderedComponentNames.length !== allKeys.length) {
        const keys = Array.from(dependencyMap.keys());
        const obj:any = {} as any;
        keys.forEach(key => {
            obj[key] = Array.from(dependencyMap.get(key)!.values());
        });
        const unProcessed = allKeys.filter((x) => !processedKeys.has(x));
        throw new Error("Failed to process: " + unProcessed + "\nprocessedKeys: " + processedKeys + "\ndependencyMap: " + JSON.stringify(obj));
    }

    return orderedComponentNames;
}


export const setCaretPosition = (textarea: HTMLTextAreaElement, line: number, char: number):void => {
    // Split the content into lines
    const lines = textarea.value.split('\n');

    line = Math.max(0, Math.min(line, lines.length - 1));
    
    let position = 0;
    for (let i = 0; i < line; i++) {
        position += lines[i].length + 1; // +1 for the newline character
    }
    position += Math.min(char, lines[line].length);
    textarea.focus();
    textarea.setSelectionRange(position, position);
}
