/**
 * Edit mode identity
 */

import { Schema, IInstance } from "../../types/external";
import { IPage } from "../../types/internal";
import { identity } from "../../utils/domElementFactory";
import AIdentityComponent from "./AIdentityComponent";

export default class EditIdentityComponent extends AIdentityComponent {
    /**
     * An html element that is shown in edit mode only and displays the name to authors
     */
    private _element: HTMLSpanElement;

    constructor(data: Schema["identity"], instance: IInstance, page: IPage) {
        super(data, instance, page);
    }

    override onCreated(): void {
        super.onCreated();
        this._addElement();
    }

    public override onDestroyed(): void {
        super.onDestroyed();
        this._element.remove();
    }

    override update(data: Schema["identity"]): void {
        super.update(data);
        this.updateValue();
    }

    public override setDisplayName(name: string): void {
        super.setDisplayName(name);
        this.updateValue();
    }

    // where we will display the name
    private _addElement() {
        const parent = this.getInstanceComponent("render").getElement();
        this._element = identity(parent);
        this.updateValue();
    }

    /**
     * show the text to the user
     */
    private updateValue() {
        if (this._element) {
            this._element.innerText = this.getDisplayName();
            const id = this.instance.getId();
            this._element.setAttribute("title", id)
        }
    }
}
