/**
 * Abstract class for identity component.
 * This contains, for example the display name of the instance
 */

import { IIdentityComponent, IInstance } from "../../types/external";
import { Schema } from "../../types/external";
import { IPage } from "../../types/internal";
import { AComponent } from "../AComponent";

export default abstract class AIdentityComponent
    extends AComponent<"identity">
    implements IIdentityComponent
{
    public name: "identity" = "identity";
    constructor(data: Schema["identity"], instance: IInstance, page: IPage) {
        super(data, instance, page);
    }

    public setDisplayName(name: string): void {
        this.data.displayName = name;
    }
    public getDisplayName(): string {
        return this.data.displayName;
    }
    override getDependencies() {
        return ["render"] as const;
    }
}
