/**
 * An object that can spawn new instances
 * You can specify the type of instance to spawn (clone, or make a new one)
 */

import { Schema, IInstance } from "../../types/external";
import { IPage } from "../../types/internal";
import { makeCustom } from "../../pageComponents/events/customEvents";
export interface ISpawner {
    spawn(e: MouseEvent | TouchEvent): void;
}

class Spawner implements ISpawner {
    constructor(
        private _data: Schema["spawn"],
        private _instance: IInstance,
        private _page: IPage,
    ) {}

    public spawn(e: MouseEvent | TouchEvent): void {
        // make the new instance
        let instance: IInstance | undefined = this.getSpawnedInstance();
        if (instance) {
            // put it in the right place. Use the position rather than the centre
            const pos = this._instance.getComponent("position").getPosition();
            instance.getComponent("position").setPosition(pos);

            // add the draggable component - the one we made might not have it
            
            // we need to make a new event with the right target
            const el = instance.getComponent("render").getElement();

            let Klass = ("TouchEvent" in window && e instanceof TouchEvent) ? TouchEvent : MouseEvent;
            
            var eventWithTarget = new Klass(e.type, {
                view: window,
                bubbles: true,
                cancelable: true,

                //@ts-ignore
                clientX: e.clientX,
                //@ts-ignore
                clientY: e.clientY,
                //@ts-ignore
                pageX: e.clientX,
                //@ts-ignore
                pageY: e.clientY,
                //@ts-ignore
                x: e.clientX,
                //@ts-ignore
                y: e.clientY,

                //@ts-ignore
                touches: e.touches,
            });

            makeCustom(eventWithTarget);

            // we need to dispatch the event on the target and then the draggable will work (using moveablejs)
            el.dispatchEvent(eventWithTarget);

            //start drag!
            const dragComp = instance.getComponent("draggable");
            dragComp.startDragging(eventWithTarget);
        }
    }

    /**
     * Clone 'me', but remove the spawn component!
     * @returns
     */
    private getSchemaForClone(): Schema | undefined {
        const suffix = this._data.suffix || "";
        const schema = this._instance.toSchema();
        schema.identity.displayName += suffix;
        return schema
    }

    private getSchemaForName(instanceName: string): Schema | undefined {
        const instance = this._page.instances.getInstanceByName(instanceName);
        if (!instance) {
            console.warn(`Instance ${instanceName} not found`);
            return undefined;
        }
        const suffix = this._data.suffix || "";
        const schema = instance.toSchema();
        schema.identity.displayName += suffix;
        return schema;
    }

    private getSpawnedInstance(): IInstance | undefined {
        let schema: Schema | undefined = undefined;
        if (this._data.type === "clone") {
            schema = this.getSchemaForClone();
        }
        else if (this._data.type === "instance") {
            schema = this.getSchemaForName(this._data.name);
        }
        if (schema) {
            schema.spawn = {
                ...schema.spawn,
                type: "none",
                spawnParent: this._instance.getId()
            }
            schema.draggable = {
                ...schema.draggable,
                enabled: true
            }
            return this._page.instances.addInstanceUsingSchema(schema);
        }
        else{
            return undefined;
        }
    }
}

// factory method to get a Spawner
export const getSpawner = (data: Schema["spawn"], instance: IInstance, page: IPage): ISpawner => {
    return new Spawner(data, instance, page);
};
