import { ButtonName } from "../../../types/internal";
import { svg } from "../../../utils/svgElementFactory";

export function htmlStringToElement(htmlString: string): HTMLElement {
    var tempDiv = document.createElement("div");
    tempDiv.innerHTML = htmlString;
    return tempDiv.firstChild as HTMLElement;
}

const addIcon = (parent: HTMLElement, iconId: ButtonIcon): void => {
    //@ts-ignore
    svg(parent, iconId, "white", {width: 32, height: 32});
};

const getIconButton = (className: string, icon: ButtonIcon): HTMLElement => {
    const button = document.createElement("button");
    button.classList.add("layer-ui-button", `layer-ui-button-${className}`);
    addIcon(button, icon);
    return button;
};

type ButtonIcon = "chunkyArrowRight" | "chunkyArrowLeft" | "chunkyArrowUp" | "chunkyArrowDown" | "";

const namesToIcons:{[key in ButtonName]: ButtonIcon} = {
    left: "chunkyArrowLeft",
    right: "chunkyArrowRight",
    up: "chunkyArrowUp",
    down: "chunkyArrowDown",
    prev: "chunkyArrowLeft",
    next: "chunkyArrowRight",
    scroll: "", // no icon
} as const;

export const getButton = (name: ButtonName):HTMLElement => {
    let icon = namesToIcons[name as keyof typeof namesToIcons];
    return getIconButton(name, icon);
};
