/**
 * DataComponent - stores any keys and values
 */

import { ICursorComponent, IInstance } from "../../types/external";
import { IPage } from "../../types/internal";
import { AComponent } from "../AComponent";
import { Schema } from "../../types/external";

export default class CursorComponent extends AComponent<"cursor"> implements ICursorComponent {
    public name: "cursor" = "cursor";

    constructor(data: Schema["cursor"], instance: IInstance, page: IPage) {
        super(data, instance, page);
    }

    public clearCursor(): void {
        const el = this.instance.getComponent("render").getElement();

        Object.assign(el.style, {
            cursor: `auto`,
        });
    }

    public override getDependencies() {
        return ["render"] as const;
    }

    public override onCreated(): void {
        super.onCreated();
        this.updateCursor();
    }

    public override update(data: Schema["cursor"]): void {
        super.update(data);
        this.updateCursor();
    }

    private async updateCursor(): Promise<void> {

        const CSS_VALUES = ['default', 'auto', 'move', 'grab', 'pointer'];

        const el = this.instance.getComponent("render").getElement();
        if(!this.data.path){
            this.clearCursor();
            return;
        }
        else if(CSS_VALUES.includes(this.data.path)){
            Object.assign(el.style, {
                cursor: this.data.path,
            });
        }
        else{
            const offsetArr = this.data.offset || [0, 0];
            const path = await this.getAssetManager().getPathForKey(this.data.path);
            Object.assign(el.style, {
                cursor: `url(${path}) ${offsetArr[0]} ${offsetArr[1]}, auto`,
            });
        }
    }

    public setCursor(path: string, offset?: [number, number]): void {
        this.data.path = path;
        this.data.offset = offset;
        this.updateCursor();
    }
}
