/**
 * Camera in play mode
 *
 */
import ACameraComponent from "./ACameraComponent";
import { CameraFollow, ICameraFollow } from "./CameraFollow";
import { IPage } from "../../types/internal";
import { PageSchema } from "../../types/external";

export default class PlayCameraComponent extends ACameraComponent {
    private _follow: ICameraFollow | undefined;

    constructor(data: PageSchema["camera"], page: IPage) {
        super(data, page);
    }

    /**
     * life cycle
     */
    public override onCreated(): void {
        super.onCreated();
        // if they said (e.g.) 'start at the bottom-right', then set that up now
        this.applyStartPosition();
        // if they said 'follow the hero around the screen', then set that up now
        this.applyFollow();
    }

    public override onDestroyed(): void {
        super.onDestroyed();
        if (this._follow) {
            this._follow.destroy();
            this._follow = undefined;
        }
    }

    private applyFollow() {
        if (this.data.follow && !!this.data.follow.name) {
            if (!this._follow) {
                this._follow = new CameraFollow(this, this.page);
            }
            this._follow.init(this.data.follow);
        }
    }

    private applyStartPosition(): void {
        const bgComp = this.getPageComponent("background");
        const bgSize = bgComp.getSize();
        // make sure that if we want to start at the bottom right, we actually do
        if (this.data.startPosition === "top-left") {
            this.setView({
                left: 0,
                top: 0,
                width: this.data.size.width,
                height: this.data.size.height,
            });
        } else if (this.data.startPosition === "top-right") {
            this.setView({
                left: bgSize.width - this.data.size.width,
                top: 0,
                width: this.data.size.width,
                height: this.data.size.height,
            });
        } else if (this.data.startPosition === "bottom-left") {
            this.setView({
                left: 0,
                top: bgSize.height - this.data.size.height,
                width: this.data.size.width,
                height: this.data.size.height,
            });
        } else if (this.data.startPosition === "bottom-right") {
            this.setView({
                left: bgSize.width - this.data.size.width,
                top: bgSize.height - this.data.size.height,
                width: this.data.size.width,
                height: this.data.size.height,
            });
        } else if (this.data.startPosition === "center") {
            this.setView({
                left: (bgSize.width - this.data.size.width) / 2,
                top: (bgSize.height - this.data.size.height) / 2,
                width: this.data.size.width,
                height: this.data.size.height,
            });
        } else{
            // default
            this.setView({
                left: 0,
                top: 0,
                width: this.data.size.width,
                height: this.data.size.height,
            });
        }
    }
}
