import { Point } from "../../../types/external";

export interface IPointer {
    start(pos: Point): void;
    move(pos: Point): void;
    stop(): void;
    isDown(): boolean;
    isDrag(): boolean;
    getDelta(pos: Point): { dx: number; dy: number } | undefined;
    getCurrentPos(): Point;
}

export class Pointer implements IPointer {
    // set on mouse down
    private startPos: Point | undefined = undefined;

    // set on mouse down and move move
    private currentPos: Point | undefined = undefined;

    // distance moved in the last step
    private deltaSqr: number = 0;

    private static MIN_DISTSQR_FOR_DRAG = 50;

    constructor() {}

    public start(pos: Point): void {
        this.startPos = pos;
        this.currentPos = pos;
        this.deltaSqr = 0;
    }

    public move(pos: Point): void {
        this.currentPos = pos;
        if (this.startPos) {
            const dx = this.startPos.x - pos.x;
            const dy = this.startPos.y - pos.y;
            this.deltaSqr = dx * dx + dy * dy;
        }
    }

    public getDelta(pos: Point): { dx: number; dy: number } | undefined {
        if (this.startPos) {
            const dx = pos.x - this.startPos.x;
            const dy = pos.y - this.startPos.y;
            return { dx, dy };
        }
        return undefined;
    }

    public stop(): void {
        this.startPos = undefined;
        this.currentPos = undefined;
        this.deltaSqr = 0;
    }

    public isDown(): boolean {
        return !!this.startPos;
    }

    /**
     * ignore clicks if there is a tiny bit of movement
     * @returns
     */
    public isDrag(): boolean {
        return !!this.startPos && this.deltaSqr > Pointer.MIN_DISTSQR_FOR_DRAG;
    }

    public getCurrentPos(): Point {
        return this.currentPos!;
    }
}
