/**
 * Useful functions for working with polygons
 */

import { Point, Polygon } from "../types/external";

export const getCentre = (poly: Polygon): Point => {
    const zero: Point = {
        x: 0,
        y: 0,
    };
    const sum = poly.reduce((accum: Point, current: Point, _: number) => {
        return {
            x: accum.x + current.x,
            y: accum.y + current.y,
        } as Point;
    }, zero);

    return {
        x: sum.x / poly.length,
        y: sum.y / poly.length,
    };
};

export const getRect = (w: number, h: number): Polygon => {
    return [
        {
            x: 0,
            y: 0,
        },
        {
            x: w,
            y: 0,
        },
        {
            x: w,
            y: h,
        },
        {
            x: 0,
            y: h,
        },
    ];
};

export const negate = (p: Point): Point => {
    return {
        x: -p.x,
        y: -p.y,
    };
};


/**
 * 
 * @param p 
 * @param angle - in degrees
 * @param origin 
 * @returns 
 */
export const rotatePoint = (p: Point, angle: number, origin: Point): Point => {
    const cos = Math.cos((angle * Math.PI) / 180);
    const sin = Math.sin((angle * Math.PI) / 180);
    const trans = translatePoint(p, negate(origin));

    const r = {
        x: trans.x * cos - trans.y * sin,
        y: trans.x * sin + trans.y * cos,
    };
    return translatePoint(r, origin);
};

export const scalePoint = (p: Point, scale: Point, origin: Point): Point => {
    const trans = translatePoint(p, negate(origin));
    const r = {
        x: trans.x * scale.x,
        y: trans.y * scale.y,
    };
    return translatePoint(r, origin);
};

export const translatePoint = (pt: Point, translation: Point): Point => {
    if (typeof translation.x === "number") {
        return {
            x: pt.x + translation.x,
            y: pt.y + translation.y,
        };
    }
    return pt;
};

export const applyRotate = (p: Polygon, angle: number, origin: Point): Polygon => {
    return p.map((pt) => {
        return rotatePoint(pt, angle, origin);
    });
};

export const applyScale = (p: Polygon, scale: Point, origin: Point): Polygon => {
    return p.map((pt) => {
        return scalePoint(pt, scale, origin);
    });
};

export const applyTranslate = (p: Polygon, translation: Point): Polygon => {
    return p.map((pt) => {
        return translatePoint(pt, translation);
    });
};

export const applyTransforms = (
    p: Polygon,
    translation: Point,
    scale: Point,
    rotation: number,
    origin: Point,
): Polygon => {
    return applyTranslate(applyRotate(applyScale(p, scale, origin), rotation, origin), translation);
};

export const drawPolygon = (poly: Polygon, ctx: CanvasRenderingContext2D) => {
    ctx.beginPath();
    poly.forEach((pt: Point, i: number) => {
        if (i === 0) {
            ctx.moveTo(pt.x, pt.y);
        } else {
            ctx.lineTo(pt.x, pt.y);
        }
    });
    ctx.lineTo(poly[0].x, poly[0].y);
    ctx.closePath();
    ctx.fill();
};

export const drawCircle = (center: Point, r: number, ctx: CanvasRenderingContext2D) => {
    ctx.beginPath();
    ctx.arc(center.x, center.y, r, 0, 2 * Math.PI);
    ctx.closePath();
    ctx.fill();
};

export const drawPoint = (p: Point, ctx: CanvasRenderingContext2D) => {
    const RADIUS = 3;
    ctx.beginPath();
    ctx.arc(p.x, p.y, RADIUS, 0, 2 * Math.PI);
    ctx.closePath();
    ctx.fill();
};
