/**
 * Page drawing - the user draws on the actual page
 */
import { IPage, IPageDrawingComponent } from "../../types/internal";
import { APageComponent } from "../APageComponent";
import { PageSchema, Events } from "../../types/external";
import { drawing, pageDrawingCanvas } from "../../utils/domElementFactory";
import { PageEventsMap } from "../../types/external";
import { getDrawing } from "./DrawingFactory";
import { IDrawing } from "./types";

export default class PlayPageDrawingComponent
    extends APageComponent<"drawing">
    implements IPageDrawingComponent
{
    // elements they draw in
    private _canvas: HTMLCanvasElement;
    private _element: HTMLElement;

    // the actual drawing
    private drawing: IDrawing;

    public override name: "drawing" = "drawing";

    constructor(data: PageSchema["drawing"], page: IPage) {
        super(data, page);
        this.onPagePointerDown = this.onPagePointerDown.bind(this);
        this.onPagePointerDrag = this.onPagePointerDrag.bind(this);
        this.onPagePointerUp = this.onPagePointerUp.bind(this);
        this.resizeDrawingArea = this.resizeDrawingArea.bind(this);
        this.onToolSettingsChange = this.onToolSettingsChange.bind(this);
    }

    private addCanvas(){
        this._canvas = pageDrawingCanvas(this._element);
    }

    public override onCreated(): void {
        this._element = drawing();
        if (this.data.enabled) {
            this.addCanvas();
            this.drawing = getDrawing("paper", this._canvas, {
                perspectiveScale: 1,
            }, this.getAssetManager());
            const layerComp = this.getPageComponent("layers");
            layerComp.initLayer("drawing", this._element, {
                type: "full",
            });
            this.resizeDrawingArea();
            this.page.events.on(Events.DRAWING_TOOL_CHANGE, this.onToolSettingsChange);
            this.activate();
        }
    }

    public getContext(): CanvasRenderingContext2D | undefined {
        if(!this._canvas) {
            this.addCanvas();
        }
        return this._canvas?.getContext("2d")!;
    }

    public override onDestroyed(): void {
        super.onDestroyed();
        this.deactivate();
        //stop listening and destroy

        const layerComp = this.getPageComponent("layers");
        layerComp.removeLayer("drawing");

        this.page.events.off(Events.DRAWING_TOOL_CHANGE, this.onToolSettingsChange);
        if (this.drawing) {
            this.drawing.destroy();
        }
    }

    public getTools(): string {
        return this.data.tools;
    }

    public override getDependencies() {
        return ["layers"] as const;
    }

    public getElement(): HTMLElement {
        return this._element;
    }

    public activate(): void {
        if (this.drawing && this.data.enabled) {
            this.page.events.on(Events.PAGE_POINTERDOWN, this.onPagePointerDown);
        }
    }

    public deactivate(): void {
        if (this.drawing) {
            this.page.events.off(Events.PAGE_POINTERDOWN, this.onPagePointerDown);
            this.page.events.off(Events.PAGE_POINTERDRAG, this.onPagePointerDrag);
            this.page.events.off(Events.PAGE_POINTERUP, this.onPagePointerUp);
        }
    }

    private onPagePointerDown(eventData: PageEventsMap[typeof Events.PAGE_POINTERDOWN]) {
        // only start drawing if there are no other instances being interacted with under the mouse
        if (eventData.targets.length === 0) {
            this.drawing.onDown(eventData.point.x, eventData.point.y);
            // start listening to drag/up events
            this.page.events.on(Events.PAGE_POINTERDRAG, this.onPagePointerDrag);
            this.page.events.on(Events.PAGE_POINTERUP, this.onPagePointerUp);
        }
    }

    private onPagePointerDrag(eventData: PageEventsMap[typeof Events.PAGE_POINTERDRAG]) {
        this.drawing.onDrag(eventData.point.x, eventData.point.y);
    }

    private onPagePointerUp() {
        this.drawing.onUp();
        this.page.events.off(Events.PAGE_POINTERDRAG, this.onPagePointerDrag);
        this.page.events.off(Events.PAGE_POINTERUP, this.onPagePointerUp);
    }

    /**
     * resize the drawing area to match
     */
    private resizeDrawingArea() {
        const size = this.page.getComponent("background").getSize();
        this._canvas.width = size.width;
        this._canvas.height = size.height;
    }

    /**
     * The user changed the pen/rake/color etc
     * @param eventData
     */
    private onToolSettingsChange(eventData: PageEventsMap["drawingToolSettingsChange"]): void {
        if (this.drawing) {
            this.drawing.updateCurrentToolSettings(eventData.toolSetting);
        }
    }

    public setEnabled(enabled: boolean): void {
        this.data.enabled = enabled;
    }

    public getEnabled(): boolean {
        return this.data.enabled;
    }
}
