/**
 * Contents of a Droppable component
 */

import { TypedEventEmitter } from "../../utils/TypedEventEmitter";
import { IInstance } from "../../types/external";

// events it can emit
export type DroppableEventMap = {
    change: {
        type: "add" | "remove";
        instance: IInstance;
        instances: IInstance[];
    };
};

// interface for the droppable content - add/remove/destroy and getNames
export interface IDroppableContent extends TypedEventEmitter<DroppableEventMap> {
    add(instance: IInstance): void;
    setList(instances: IInstance[]): void;
    remove(instance: IInstance): boolean;
    destroy(): void;
    getNames(): string[];
    getIds(): string[];
}

class DroppableContent extends TypedEventEmitter<DroppableEventMap> implements IDroppableContent {
    // instances that are 'in' this droppable
    private _list: IInstance[] = [];

    constructor() {
        super();
    }

    public add(instance: IInstance): void {
        this._list.push(instance);
        this.emit("change", {
            type: "add",
            instance,
            instances: this._list,
        });
    }

    public setList(instances: IInstance[]): void {
        this._list = instances;
    }

    /**
     * @param instance
     * @returns boolean - was it removed or not?
     */
    public remove(instance: IInstance): boolean {
        const id = instance.getId();
        const newList = this._list.filter((instance: IInstance) => {
            return instance.getId() !== id;
        });
        const wasRemoved: boolean = newList.length < this._list.length;
        this._list = newList;
        if (wasRemoved) {
            this.emit("change", {
                type: "remove",
                instance,
                instances: this._list,
            });
        }
        return wasRemoved;
    }

    public getIds(): string[] {
        return this._list.map((instance: IInstance) => {
            return instance.getId();
        });
    }

    public getNames(): string[] {
        return this._list.map((instance: IInstance) => {
            return instance.getName();
        });
    }

    public destroy(): void {
        this._list = [];
    }
}

export const getDroppableContent = () => {
    return new DroppableContent();
};
