/**
 * events component
 */
import { IPage } from "../../types/internal";
import { Events } from "../../types/external";

export interface IResizeEventHandler {
    destroy(): void;
}

class ResizeEventHandler implements IResizeEventHandler {
    // when we resize the window, trigger a 'pageSize' event that other components can listen to
    private _resizeObserver: ResizeObserver;

    constructor(protected page: IPage) {
        this.onResize = this.onResize.bind(this);
        if ("ResizeObserver" in window) {
            this._resizeObserver = new ResizeObserver(this.onResize);
            this._resizeObserver.observe(this.page.getActivityContainer());
        } 
        else {
            //@ts-ignore
            window.addEventListener("resize", this.onResize);
        } 
    }

    private onResize(): void {
        this.page.events.emit(Events.PAGE_RESIZE, {});
    }

    public destroy(): void {
        if(this._resizeObserver) {
            this._resizeObserver.unobserve(this.page.getActivityContainer());
        }
        window.removeEventListener("resize", this.onResize);
    }
}

export const getResizeEventHandler = (page: IPage):IResizeEventHandler => {
    return new ResizeEventHandler(page);
}