import { IPage } from "../../types/internal";
import { IInstance } from "../../types/external";

export interface IDropHandler {
    handleDrop(): boolean;
    onFail(): void;
    onStartDrag(): void;
}

export abstract class ADropHandler implements IDropHandler {
    constructor(
        protected page: IPage,
        protected droppedInstance: IInstance,
        protected allInstances: IInstance[],
    ) {}

    // when the user dropped it - see if any instance will accept it
    public abstract handleDrop(): boolean;

    // when the user started dragging - perhaps remove it from where it was placed
    public abstract onStartDrag(): void;

    // when the drop failed completely
    public onFail(): void {}
}
