/**
 * material handler - you dropped an instance onto a material component
 *
 */
import { ADropHandler, IDropHandler } from "./types";
import { IInstance } from "../../types/external";

export class MaterialDropHandler extends ADropHandler implements IDropHandler {
    // find the one you dropped on
    private getAcceptingInstance(): IInstance | undefined {
        let materialInstances = this.allInstances
            .filter((instance: IInstance) => {
                const materialComponent = instance.getComponent("material");
                const collisionComponent = instance.getComponent("collision");
                // find ones that are enabled, have space and the rectange contains the point
                return (
                    instance !== this.droppedInstance &&
                    materialComponent &&
                    materialComponent.getMaterialType() !== "none" &&
                    // see if there is room
                    materialComponent.willAccept(this.droppedInstance) &&
                    collisionComponent.contains(this.droppedInstance)
                );
            })
            .sort((instanceA: IInstance, instanceB: IInstance) => {
                // find the top-most one
                const zA = instanceA.getComponent("render").getZIndex();
                const zB = instanceB.getComponent("render").getZIndex();
                return zA === zB ? 0 : zA < zB ? 1 : -1;
            });

        return materialInstances && materialInstances.length >= 1
            ? materialInstances[0]
            : undefined;
    }

    /**
     * Handle the drop
     * @returns
     */
    public handleDrop(): boolean {
        const instanceDroppedOn = this.getAcceptingInstance();

        if (instanceDroppedOn) {
            const centre = this.droppedInstance.getComponent("collision").getCentre();
            const materialComponent = instanceDroppedOn.getComponent("material");

            // actually add it
            materialComponent.addContent(this.droppedInstance, centre);
            return true;
        } else {
            return false;
        }
    }

    public override onFail(): void {
        const dragComponent = this.droppedInstance.getComponent("draggable");
        if (dragComponent.getDeleteOnFail()) {
            this.page.instances.destroyInstance(this.droppedInstance);
        }
    }

    /**
     * remove from all instances when you pick it up
     * @returns
     */
    public onStartDrag(): void {
        this.allInstances.forEach((instance: IInstance) => {
            const materialComponent = instance.getComponent("material");
            if (materialComponent && materialComponent.getEnabled()) {
                instance.getComponent("material").removeFromContent(this.droppedInstance);
            }
        });
    }
}
