/**
 * This file contains exports for the Salad library
 */

import { TypedEventEmitter as _TypedEventEmitter } from "./utils/TypedEventEmitter";
import { getUUID as _getUUID } from "./utils/uuid";
import { createActivity as _createActivity} from "./world/Activity";
import { defaultScript as _defaultInstanceScript} from "./defaultSchema";
import { defaultScript as _defaultPageScript} from "./defaultPageSchema";
import { ActivityOptions as _ActivityOptions} from "./types/internal";
import { getAssetManager } from "./utils/AssetManager";
import * as Utils_ from "./utils"
import {Salad as SaladTypes} from "./salad-types";
import { getPMSoundSequencer } from "@root/utils/pmapi/PMSoundSequencer";

/**
 * Ext contains types that are external - in other words exposed to authors via the monaco code editor
 * Int contains types that are only used by the framework - in other words ones that authors never need
 */

import * as ExternalTypes from "./types/external";

let currentActivity: Salad.IActivity;

namespace Salad {
    
    export const version = "1.0.0";

    export const defaultInstanceScript = _defaultInstanceScript;
    export const defaultPageScript = _defaultPageScript;

    // consts
    export const getAllComponentNames = () => ExternalTypes.allComponentNames;
    export const Events = ExternalTypes.Events;

    export type Modal = ExternalTypes.PageSchema["modalslist"]["modals"][string];

    //types
    export type ComponentName = SaladTypes.ComponentName;
    export type ComponentUpdate = SaladTypes.ComponentUpdate;
    export type PageComponentUpdate = SaladTypes.PageComponentUpdate;
    export type Schema = SaladTypes.Schema;
    export type PartialSchema = SaladTypes.PartialSchema;
    export type PageSchema = SaladTypes.PageSchema;
    export type KeyOfComponent<T extends ComponentName = ComponentName> = SaladTypes.KeyOfComponent<T>;
    export type Point = SaladTypes.Point;
    export type Polygon = SaladTypes.Polygon;
    export type Size = SaladTypes.Size;
    export type InstanceData = SaladTypes.InstanceData;
    export type ActivityMode = SaladTypes.ActivityMode;
    export type ActivitySettings = SaladTypes.IActivitySettings;
    export type InstanceLayerInfo = SaladTypes.InstanceLayerInfo;
    export type IPageData = SaladTypes.IPageData;
    export type InfoScreen = SaladTypes.InfoScreen;
    export type MaterialType = SaladTypes.MaterialType;
    export type MaterialBase64Map = SaladTypes.MaterialBase64Map;
    export type MaterialContentsJSON = SaladTypes.MaterialContentsJSON;
    export type DrawingToolSetting = SaladTypes.DrawingToolSetting;
    export type DrawingToolMenuItem = SaladTypes.DrawingToolMenuItem;
    export type PageEventsMap = SaladTypes.PageEventsMap;
    export type ActivityEventsMap = SaladTypes.ActivityEventsMap;
    export type ActivityHistory = SaladTypes.ActivityHistory;
    export type AssetsMap = SaladTypes.AssetsMap;
    export type Asset = SaladTypes.Asset;
    export type ModalOutput = SaladTypes.ModalOutput;
    export type PageSelection = SaladTypes.PageSelection;
    export type ColorString = SaladTypes.ColorString;
    export type ActivityOptions = SaladTypes.ActivityOptions;
    export type SaladAPI = SaladTypes.SaladAPI
    export type SaladJSONObject = SaladTypes.SaladJSONObject

    //interfaces
    export interface IInstance extends SaladTypes.IInstance {}
    export interface IComponent<K extends ComponentName> extends SaladTypes.IComponent<K> {}
    export interface IActivitySettings extends SaladTypes.IActivitySettings {}
    export interface IPage extends SaladTypes.IPage {}
    export interface IPageExternal extends SaladTypes.IPageExternal {}
    export interface IActivity extends SaladTypes.IActivity {}
    export interface IPageComponentFactory extends SaladTypes.IPageComponentFactory {}
    export interface IScript extends SaladTypes.IScript {}
    export interface IAssetManager extends SaladTypes.IAssetManager {}
    export interface ITranslator extends SaladTypes.ITranslator {}
    export interface ISoundSequencer extends SaladTypes.ISoundSequencer {}
    export interface IStatsCreator extends SaladTypes.IStatsCreator {}
    export interface ISound extends SaladTypes.ISound {}
    export interface IResolver extends SaladTypes.IResolver {}
    export interface IModalHelper extends SaladTypes.IModalHelper {}
    export interface IModalOpener extends SaladTypes.IModalOpener {}
    export interface IInfoOpener extends SaladTypes.IInfoOpener {}
    export interface ILottieAnimationItem extends SaladTypes.ILottieAnimationItem {}
    export interface ITypedEventEmitter<T extends { [key in string]: object }> extends SaladTypes.ITypedEventEmitter<T> {}
    
    export const TypedEventEmitter = _TypedEventEmitter;

    /**
     * misc utils
     */
    export namespace Utils {
               
        export const getUUID = _getUUID;

        export const getRandomNumber = Utils_.getRandomNumber;
        export const getRandomInt = Utils_.getRandomInt;
        export const getRandomColor = Utils_.getRandomColor;
        export const getRandomPrimaryColor = Utils_.getRandomPrimaryColor;
        export const getRandomChoice = Utils_.getRandomChoice;
        export const Geom = Utils_.Geom;
        export const Dragging = Utils_.Dragging
        export const Code = Utils_.Code

        export const log = (message: any) => {
            currentActivity?.log(message);
        }
    }

    export namespace Factory{
        /**
         * Create and return a new activity, also sets it as the current activity for ease of access
         * @param options 
         * @returns 
         */
        export const createActivity = async (options: _ActivityOptions): Promise<Salad.IActivity> => {
            const activity = await _createActivity(options);
            currentActivity = activity;
            await activity.start();
            return activity;
        };

        export const createAssetManager = (assetsMap:Salad.AssetsMap, resolver: Salad.IResolver, soundSequencer: Salad.ISoundSequencer)=>{
            return getAssetManager(() => assetsMap, resolver, soundSequencer);
        }

        export const getCurrentActivity = () => {
            return currentActivity
        }

        export const getDefaultSoundSequencer = () => {
            return getPMSoundSequencer();
        }

    }
}

export default Salad;
