/**
 * Abstract class for highlighting an instance
 */

import { IHighlightComponent, IInstance, Schema } from "../../types/external";
import { IPage } from "../../types/internal";
import { AComponent } from "../AComponent";

export default abstract class AHighlightComponent
    extends AComponent<"highlight">
    implements IHighlightComponent
{
    public name: "highlight" = "highlight";

    constructor(data: Schema["highlight"], instance: IInstance, page: IPage) {
        super(data, instance, page);
    }

    public override update(data: Schema["highlight"]): void {
        super.update(data);
    }

    // apply the highlight
    public setHighlight(type: Schema["highlight"]["type"]): void {
        this.data.type = type;
    }

    override getDependencies() {
        return ["render"] as const;
    }
}
