import { DrawingToolSetting } from "../../../../types/external";
import { ASimpleBrush } from "./ASimpleBrush";
import { DrawingArea } from "./types";
import { cutOff } from "./utils";
import Salad from "../../../..";

export class SimpleBrushPencil extends ASimpleBrush {
    protected prevX: number;
    protected prevY: number;

    constructor(drawingArea: DrawingArea, setting: DrawingToolSetting) {
        super(drawingArea, setting);
    }

    public start(x: number, y: number): void {
        this.prevX = x;
        this.prevY = y;
    }

    public move(x: number, y: number): void {
        this.smearFromTo(this.prevX, this.prevY, x, y);

        const size = this.getDrawingSize(y);
        const dx = x - this.prevX;
        const dy = y - this.prevY;
        const dist = Math.sqrt(dx * dx + dy * dy);

        const MIN_DIST_FOR_SCALE = 6;
        const MAX_DIST_FOR_SCALE = 20;
        const MIN_SCALE = 0.333;
        const sketchinessFactor = 0.2;

        const scale = cutOff(dist, 1, MIN_SCALE, {
            min: MIN_DIST_FOR_SCALE,
            max: MAX_DIST_FOR_SCALE,
        });

        this.ctx!.strokeStyle = this.settings.options.color!;
        this.ctx!.lineWidth = 1;

        const NUM_LINES = 4;
        const SKETCHINESS = Math.round(Math.max(1, scale * size * sketchinessFactor));

        const r = () => Salad.Utils.getRandomInt(-SKETCHINESS, SKETCHINESS);

        const drawLine = (random: boolean = false) => {
            this.ctx.beginPath();
            this.ctx.moveTo(this.prevX + (random ? r() : 0), this.prevY + (random ? r() : 0));
            this.ctx.lineTo(x + (random ? r() : 0), y + (random ? r() : 0));
            this.ctx.stroke();
        };

        //draw some random lines and then one final line from x to y

        for (let i = 1; i <= NUM_LINES; i++) {
            drawLine(true);
        }
        drawLine(false);

        this.prevX = x;
        this.prevY = y;
    }
    public end(): void {}
}
