type NoiseOptions = {
    scale: number
    octaves:number
    persistence:number
}

const defaultOptions: NoiseOptions = {
    scale: 0.035,
    octaves: 7,
    persistence: 0.5
}

const noise = (x:number, y:number):number => {
    const n = Math.sin(x * 12.9898 + y * 78.233) * 43758.5453;
    return (n - Math.floor(n));
};

const perlin = (x:number, y:number, options:NoiseOptions) => {
    let total = 0;
    let frequency = options.scale;
    let amplitude = 1;
    let maxValue = 0;

    for (let i = 0; i < options.octaves; i++) {
        total += smoothNoise(x * frequency, y * frequency) * amplitude;
        maxValue += amplitude;
        amplitude *= options.persistence;
        frequency *= 2;
    }

    return total / maxValue;
}

function smoothNoise(x:number, y:number):number {
    const xf = Math.floor(x);
    const yf = Math.floor(y);

    const tl = noise(xf, yf);
    const tr = noise(xf + 1, yf);
    const bl = noise(xf, yf + 1);
    const br = noise(xf + 1, yf + 1);

    const xt = x - xf;
    const yt = y - yf;

    const u = fade(xt);
    const v = fade(yt);

    return lerp(lerp(tl, tr, u), lerp(bl, br, u), v);
}

function fade(t:number): number {
    return t * t * t * (t * (t * 6 - 15) + 10);
}

function lerp(a:number, b:number, t:number):number {
    return a + t * (b - a);
}

let cachedNoiseCanvas: HTMLCanvasElement = null;

const getNoiseCanvas = (width:number, height:number, options: NoiseOptions = defaultOptions): HTMLCanvasElement => {
    if(!!cachedNoiseCanvas){
        return cachedNoiseCanvas;
    }
    const noiseCanvas = document.createElement("canvas");
    noiseCanvas.width = width;
    noiseCanvas.height = height;
    const noiseCtx = noiseCanvas.getContext("2d");
    const imageData = noiseCtx.createImageData(width, height);
    const randomWeight = 0.5;
    for (let y = 0; y < height; y++) {
        for (let x = 0; x < width; x++) {
            const value = Math.floor(perlin(x, y, options) * 255);
            const index = (y * width + x) * 4;
            imageData.data[index] = 0;
            imageData.data[index + 1] = 0;
            imageData.data[index + 2] = 0;
            const rnd = Math.random() * 255
            imageData.data[index + 3] = randomWeight * rnd + (1 - randomWeight) * value;
        }
    }
    noiseCtx.putImageData(imageData, 0, 0);
    cachedNoiseCanvas = noiseCanvas;
    Object.assign(noiseCanvas.style, {
        position: "fixed",
        top: "0",
        left: "0",
        zIndex: "99999",
        width: `${width}px`,
        height: `${height}px`
    })
    return noiseCanvas;
}

export const generateNoiseWithColor = (canvas: HTMLCanvasElement, color: string):void => {
    const NOISE_SIZE = 384;
    // random offset so when we draw with chalk we get different offsets each time
    const randomX = Math.floor(Math.random() * 10);
    const randomY = Math.floor(Math.random() * 10);
    
    // get the noise canvas, use global composite operation to draw it on the canvas with a color
    const newCanvas = getNoiseCanvas(NOISE_SIZE, NOISE_SIZE);
    
    const ctx = canvas.getContext("2d");
    ctx!.fillStyle = color;
    ctx!.fillRect(0, 0, canvas.width, canvas.height);
    ctx!.globalCompositeOperation = "destination-in";
    
    ctx!.drawImage(
        newCanvas,
        -randomX,
        -randomY,
        canvas.width + randomX,
        canvas.height + randomY,
    );
    ctx!.globalCompositeOperation = "source-over";

}