/**
 * Abstract class for Button components
 */

import { ISelectComponent, IInstance } from "../../types/external";
import { Schema } from "../../types/external";
import { IPage } from "../../types/internal";
import { AComponent } from "../AComponent";
import { select, selectContainer } from "../../utils/domElementFactory";

type Options = Schema["select"]["options"];

export default abstract class ASelectComponent
    extends AComponent<"select">
    implements ISelectComponent
{
    public name: "select" = "select";

    /**
     * container
     */
    protected _element: HTMLElement | undefined;

    /**
     * select
     */
    protected _select: HTMLSelectElement | undefined;

    constructor(data: Schema["select"], instance: IInstance, page: IPage) {
        super(data, instance, page);
    }

    override getDependencies() {
        return ["render"] as const;
    }

    override onCreated() {
        super.onCreated();
        if (this.data.enabled) {
            this._redrawUI();
        }
    }

    public setState(state: Schema["select"]["state"]): void{
        this.data.state = state;
        this._redrawUI();
    }

    public getOptions(): Options {
        return this.data.options;
    }

    public setOptions(options: Options): void {
        this.data.options = options;
        this._redrawUI();
    }

    /**
     * lifecycle
     */
    public override onDestroyed(): void {
        this._destroyElement();
        super.onDestroyed();
    }

    private _updateSelectedValue() {
        this._select!.value = this.data.selectedValue;
    }

    public getSelectedValue(): string {
        return this.data.selectedValue;
    }

    public setSelectedValue(value: string): void {
        this.data.selectedValue = value;
        this._updateSelectedValue();
    }

    protected _redrawUI(): void {
        this._destroyElement();
        if (this.data.enabled) {
            this.addElement();
            this._updateSelectedValue();
            if(this.data.state === "disabled"){
                this._select!.setAttribute("disabled", "disabled");
            }
            else{
                this._select!.removeAttribute("disabled");
            }
        }
    }

    protected addElement(): void {
        const parent = this.getInstanceComponent("render").getElement();
        this._element = selectContainer(parent);
        this._select = select(this._element, this.data.options);
    }

    protected _destroyElement(): void {
        if (this._element) {
            while (this._element.firstChild) {
                this._element.removeChild(this._element.firstChild);
            }
            this._element.remove();
            this._element = undefined;
        }
    }

    /**
     * On update, reset the lottie animation
     * @param data
     */
    override update(data: Schema["select"]): void {
        super.update(data);
        this._destroyElement();
        if (this.data.enabled) {
            this.addElement();
            this._updateSelectedValue();
        }
    }

    public getElement(): HTMLElement {
        return this._element!;
    }
}
