export const allPageComponentNames = [
    "camera",
    "events",
    "selection",
    "coderunner",
    "grid",
    "identity",
    "background",
    "screenbackground",
    "modalslist",
    "dragndrop",
    "highlight",
    "domupdate",
    "data",
    "ticker",
    "drawing",
    "timers",
    "layers",
    "sound",
    "layout",
    "ui",
    "instances",
    "keyboard",
    "debug",
    "collisions",
    "script",
    "transitions",
    "settings",
    "undo"
] as const;

export type PageComponentName = (typeof allPageComponentNames)[number];

export const uiScrollTypes = ["none", "leftrightupdown", "leftright", "updown", "mouse"] as const;
export const uiPagePrevTypes = ["none", "prev", "historyback"] as const;
export const uiPageNextTypes = ["none", "next", "historynext"] as const;
export const cameraStartPositions = [
    "bottom-left",
    "top-left",
    "bottom-right",
    "top-right",
    "center",
] as const;
export const transitionTypes = [
    "fadein",
    "fadeout",
    "fadeouttoblack",
    "fadeinfromblack",
    "none",
] as const;
export const keyboardShowTypes = [
    "always",
    "tablet",
    "never"
] as const ;
export const keyboardPositions = [
    "top",
    "bottom",
] as const ;

export type Color = "" | `#${string}` | `rgb(${number}, ${number}, ${number})` | `rgba(${number}, ${number}, ${number}, ${number})`;

export const pageHighlightTypes = [
    "none",
    "stars",
    "unicorns",
    "heart",
    "dino",
    "robot",
    "bee",
    "wizard",
    "castle",
    "crown",
    "butterfly",
    "dolphin",
    "lightning",
    "crystal",
    "tree",
    "present",
] as const;


type ModalBlock =
    | {
          type: "title";
          text: string;
      }
    | {
          type: "text";
          text: string;
      }
    | {
          type: "image";
          path: string;
      }
    | {
          type: "audio";
          path: string;
      }
    | {
          type: "lottie";
          path: string;
      }
    | {
          type: "textinput";
          text: string;
      }
    | {
          type: "numberinput";
          text: string;
      };

export type ModalConfig = {
    [name: string]: {
        blocks: ModalBlock[];
        buttons?: {
            ok?: boolean;
            cancel?: boolean;
            next?: boolean;
        };
        playAudio? : boolean;
        pauseGame?: boolean;
    };
};

// Define a base type for Hash without self-referencing
type _BasePageSchema = {
    [name in PageComponentName]: any;
};

type SaladJSONValue_2 = 
  | string
  | number
  | boolean
  | null
  | SaladJSONArray
  | SaladJSONObject_2;

interface SaladJSONArray extends Array<SaladJSONValue_2> {}

type SaladJSONObject_2 = {
    [key: string]: SaladJSONValue_2;
}

type PositionUndoPayload = {
    type: "position";
    data:{
        startPos: {x: number, y: number};
        endPos: {x: number, y: number};
    }
}

type SizeUndoPayload = {
    type: "size";
    data:{
        startSize: {width: number, height: number};
        endSize: {width: number, height: number};
    }
}

type RotateUndoPayload = {
    type: "rotation";
    data:{
        startRot: number;
        endRot: number;
    }
}

type UndoAction = {
    id: string;
    payload: PositionUndoPayload | SizeUndoPayload | RotateUndoPayload;
}
interface BasePageSchema extends _BasePageSchema {
    camera: {
        size: {
            width: number;
            height: number;
        };
        view: {
            left: number;
            top: number;
            width: number;
            height: number;
        };
        follow: {
            name: string;
            deadZone: number;
        };
        startPosition: (typeof cameraStartPositions)[number];
        duration: number;
    };
    events: {};
    selection: {};
    coderunner: {};
    highlight:{
        type: typeof pageHighlightTypes[number];
    },
    grid: {
        size: number;
        snap: boolean;
    };
    identity: {
        displayName: string;
    };
    data: {
        // for the current page
        value: SaladJSONObject_2;
    };
    background: {
        layout: "fixed" | "fluid";
        size: {
            width: number;
            height: number;
        };
        name: string;
        color: Color;
    };
    modalslist: {
        modals: ModalConfig;
    };
    screenbackground: {
        name: string;
        color: Color;
        opacity: number;
    };
    settings:{
        save: "save" | "none";
    };
    dragndrop: {};
    domupdate:{},
    ticker: {};
    drawing: {
        data: string;
        type: "simple";
        tools: "builderstray",
        enabled: boolean;
    };
    undo:{
        enabled: boolean;
        action?: UndoAction;
    };
    keyboard:{
        type:string,
        position:  (typeof keyboardPositions)[number]
        keys: string,
        show: (typeof keyboardShowTypes)[number]
    },
    timers: {};
    layers: {};
    sound: {
        path: string;
        autoPlay: boolean;
        loop: boolean;
    };
    layout: {};
    ui: {
        scroll: (typeof uiScrollTypes)[number];
        prev: (typeof uiPagePrevTypes)[number];
        next: (typeof uiPageNextTypes)[number];
    };
    instances: {};
    debug: {
        collision: boolean;
        grid: boolean;
        containment: boolean;
        boundingCircle: boolean;
    };
    collisions: {};
    transitions: {
        in: {
            type: (typeof transitionTypes)[number];
            duration: number;
        };
        out: {
            type: (typeof transitionTypes)[number];
            duration: number;
        };
    };
    script: {
        content: string;
        transpiledCode?:string;
        ranOnce: boolean;
    };
}

type DeepPartial_2<T> = T extends object
    ? {
          [P in keyof T]?: DeepPartial_2<T[P]>;
      }
    : T;

export interface PartialPageSchema extends DeepPartial_2<BasePageSchema> {}
export interface PageSchema extends BasePageSchema {}
