import Salad from "../../../index";
import { IActivityFontsComponent } from "../../../types/external";
import { AActivityComponent } from "../AActivityComponent";
import { ActivityOptions } from "../../../types/internal";
import { FontImport } from "@root/utils/export/FontImport";

export class ActivityFontsComponent extends AActivityComponent implements IActivityFontsComponent{

    constructor(private activity: Salad.IActivity, private options: ActivityOptions) {
        super();
    }

    public async loadFonts(): Promise<void> {
        if(this.options.fonts){
            await new FontImport(this.options.fonts).importFonts();
        }
    }

}
