import WebAudioSoundSequencer from "./webaudioSequencer";

export default class {
    constructor(params = {}) {
        this.onFileLoad = this.onFileLoad.bind(this);
        this.options = {
            onTheFlyDecode: false,
            ...params,
        };
        if (typeof AudioContext === "undefined" && typeof webkitAudioContext === "undefined") {
            alert(
                "Sounds are not supported in your browser. Please use another browser such as Chrome, FireFox, Edge, or Safari.",
            );
        } else {
            this.plugin = new WebAudioSoundSequencer(this);
        }
    }
    mute() {
        this.plugin.mute();
    }
    unmute() {
        this.plugin.unmute();
    }
    setDisabled(disabled) {
        this.disableSound = disabled;
    }
    init() {
        this.disableSound = "AppVariables" in window && window.AppVariables && window.AppVariables.get("displayboardThumbnail") == 1;
        this.preloadedSounds = {};
        this.playRequests = {};
        this.loadRequests = {};
        this.tickers = [];
        if (this.plugin) {
            if (this.disableSound) {
                this.plugin.dispatchEvent("ready");
            } else {
                this.plugin.init();
            }
        } else {
            console.log("error - no sound sequencer plugin");
        }
        this.addEventListener("fileload", this.onFileLoad);
    }
    injectDefaultParams(params) {
        params.delay = typeof params.delay === "undefined" ? 0 : params.delay;
        params.offset = typeof params.offset === "undefined" ? 0 : params.offset;
        params.volume = typeof params.volume === "undefined" ? 0.8 : params.volume;
        params.loop = typeof params.loop === "undefined" ? false : params.loop;
        return params;
    }
    /**
     * Add a function to be called regularly while the sequencer or sound is playing
     * @param {function} ticker
     */
    addTicker(ticker) {
        this.tickers.push(ticker);
    }
    /**
     * Remove the function to be called regularly while the sequencer or sound is playing
     * @param {function} ticker
     */
    removeTicker(ticker) {
        const idx = this.tickers.indexOf(ticker);;
        if (idx >= 0) {
            this.tickers.splice(idx, 1);
            console.log("Ticker removed", this.tickers);
        }
        else {
            console.error("Ticker not found to remove");
        }
    }
    /**
     * Schedule a sound to play in advance, it won't start until the soundsequencer start function is called
     * @param params
     * @param.id {string} The id of the sound
     * @param.delay {number} The delay to play the sound in seconds
     * @param.volume {number} The volume of the sound
     * @param.ended {function} Function to call when the sound ends
     */
    scheduleSound(params) {
        if (this.disableSound) {
            return;
        }
        this.plugin.scheduleSound(this.injectDefaultParams(params));
    }
    /**
     * Preload and play a sound immediately
     * @param {object} params
     * @param.id {string} The id of the sound
     * @param.volume {number} The volume of the sound
     * @param.ended {function} Function to call when the sound ends
     * @param.onLoad [function] Function to call when the sound has loaded. 'sound' is passed as the first parameter
     */
    preloadAndPlaySound(params) {
        if (this.isPreloaded(params.id)) {
            return this.playSound(params);
        } else {
            this.playRequests[params.id] = params;
            this.preloadSound(params.src, params.id, params.onLoad);
        }
    }
    /**
     * @params {object} params
     * @params.id {string} The id of the sound
     * @params.volume {number} The volume of the sound
     * @params.ended {function} Function to call when the sound ends
     * @return {object | null} - an object you can use to stop this sound later
     */
    playSound(params) {
        if (this.disableSound) {
            return null;
        }
        return this.plugin.playSound(this.injectDefaultParams(params));
    }
    onFileLoad(e) {
        // we requested to preload and play immediately
        let sound;
        if (this.playRequests[e.id]) {
            sound = this.playSound(this.playRequests[e.id]);
            delete this.playRequests[e.id];
        }
        // we passed in an onLoad function we want to be called when the sound has loaded
        if (this.loadRequests[e.id]) {
            this.loadRequests[e.id](sound);
            delete this.loadRequests[e.id];
        }
    }
    /**
     * Stop a sound with an optional fadeOut
     * @param {object|string} sound object returned from the playSound function or a sound id
     * @param {number} fadeOutTime in seconds
     */
    stopSound(sound, fadeOutTime) {
        return this.plugin.stopSound(sound, fadeOutTime);
    }
    /**
     * Stops a sound from looping, it will play to the end and stop
     * @param {object} sound is returned from the playSound function
     * @return {*|void}
     */
    stopSoundLooping(sound) {
        return this.plugin.stopSoundLooping(sound);
    }
    /**
     * Starts the sound sequencer when sounds are scheduled in advance
     * @return {*|void}
     */
    start() {
        if (this.disableSound) {
            return;
        }
        this.plugin.start();
    }
    /**
     * Stops the sound sequencer when sounds are scheduled in advance
     * @return {*|void}
     */
    stop() {
        if (this.disableSound) {
            return;
        }
        this.plugin.stop();
    }
    /**
     * Get the time since the sound sequencer started
     * @return {number}
     */
    getTimeSinceStarted() {
        return this.plugin.getTimeSinceStarted();
    }
    /**
     * Determine if a sound has preloaded
     * @param {string} id
     * @return boolean
     */
    isPreloaded(id) {
        return this.preloadedSounds[id];
    }
    /**
     * Preload sound
     * @param source The src of the audio, could be a URL or a base64 URI
     * @param id The id of the sound used to play and refer to it
     * @param onLoad
     */

    preloadSound(source, id, onLoad) {
        if (this.disableSound) {
            return;
        }
        if (!id) {
            id = source;
        }
        if (!this.preloadedSounds[id]) {
            this.loadRequests[id] = onLoad;
            this.preloadedSounds[id] = true;
            return this.plugin.preloadSound(source, id);
        } else if (onLoad) {
            onLoad(this.preloadedSounds[id]);
        }
    }
    /**
     * Add an event to the sound sequencer, usually when it is ready or when a sound is loaded
     * @param {string} event The event type
     * @param callback The function to call when the event fires
     */
    addEventListener(event, callback) {
        this.plugin.addEventListener(event, callback);
    }

    /**
     * Adds unlock events to a window object (for iframes)
     */
    addUnlockEventsToWindow(unlockWindow) {
        if (this.disableSound) {
            return;
        }
        this.plugin.addUnlockEventsToWindow && this.plugin.addUnlockEventsToWindow(unlockWindow);
    }
}