/**
 * A component that runs typescript code using 'runInstanceScript' and 'runPageScript'
 */

import { IPage } from "../../types/internal";
import { PageSchema, IInstance } from "../../types/external";
import { APageComponent } from "../APageComponent";
import { ICodeRunnerComponent } from "../../types/internal";
import { CodeGenerator } from "./CodeGenerator";
import Salad from "../..";

export default class CodeRunnerComponent
    extends APageComponent<"coderunner">
    implements ICodeRunnerComponent
{
    public name: "coderunner" = "coderunner";

    constructor(data: PageSchema["coderunner"], page: IPage) {
        super(data, page);
    }

    public override getDependencies() {
        return ["script"] as const;
    }
    
    public runScript(tsCode:string): void {
        const activity = this.page.getCurrentActivity();
        const transpiledCode = Salad.Utils.Code.transpileCode(tsCode);
        const f = new CodeGenerator().getFunctionToExecute(transpiledCode, false);
        // 'this' = page
        f.apply(this.page, [activity]);
    }

    /**
     * Get the script component of an instance, compile it to JS and execute it
     * @param instance
     */
    public runInstanceCreatedScript(instance: IInstance, page:IPage): void {
        const comp = instance.getComponent("script");
        if(comp) {
            const activity = page.getCurrentActivity();
            const code = comp.getContent();
            const transpiledCode = comp.getTranspiledCode() || Salad.Utils.Code.transpileCode(code);
            const hasRunOnce = comp.getHasRunOnce();
            const f = new CodeGenerator().getFunctionToExecute(transpiledCode, hasRunOnce);
            // 'this' = the instance, page is the 2nd argument
            f.apply(instance, [this.page, activity]);
            comp.setHasRunOnce();
        }
    }

    /**
     * Get the script component of a page, compile it to JS and execute it
     */
    public runPageCreatedScript(): void {
        const comp = this.getPageComponent("script");
        if(comp){
            const activity = this.page.getCurrentActivity();
            const code = comp.getContent();
            const transpiledCode = comp.getTranspiledCode() || Salad.Utils.Code.transpileCode(code);
            const hasRunOnce = comp.getHasRunOnce();
            const f = new CodeGenerator().getFunctionToExecute(transpiledCode, hasRunOnce);
            // 'this' = page
            f.apply(this.page, [activity]);
            comp.setHasRunOnce();
        }
    }
}
