import { AActivityComponent } from "../AActivityComponent";
import { IActivityInfoComponent } from "../../../types/external";
import Salad from "../../../index";
import { ActivityOptions } from "../../../types/internal";

export abstract class AActivityInfoComponent extends AActivityComponent implements IActivityInfoComponent{

    constructor(protected activity: Salad.IActivity, protected options: ActivityOptions) {
        super();
    }

    public async open(): Promise<void> {
        const startPageIndex = this.activity.getComponent("pages").getCurrentPageIndex();
        if (this.getHasIntroScreen()) {
            //open info screen
            const index:number = await this.openIntroScreenAndGetPageIndex();
            if(index !== undefined){
                await this.activity.gotoPageByIndex(index);
            }
            else {
                await this.activity.gotoPageByIndex(startPageIndex);
            }
        }
        else {
            return await this.activity.gotoPageByIndex(startPageIndex);
        }
    }

    protected getHasIntroScreen(): boolean {
        return false;
    }

    // the index of the page to go to after the intro screen - in other words which one they selected
    protected async openIntroScreenAndGetPageIndex(): Promise<number> | undefined {
        return undefined;
    }
}

