import { PageSchema } from "../../types/external";

type StartPos = PageSchema["camera"]["startPosition"];

/**
 * Used to draw the viewport of the camera in edit mode, so authors can see the camera viewport
 * Nothing to do with the camera actually working in play mode
 * @param startPosition
 * @returns
 */

const mapStartPosToCSS: { [key in StartPos]: object } = {
    "bottom-left": {
        bottom: 0,
        left: 0,
        top: "auto",
        right: "auto",
        transform: "none"
    },
    "bottom-right": {
        bottom: 0,
        right: 0,
        top: "auto",
        left: "auto",
        transform: "none"
    },
    "top-left": {
        top: 0,
        left: 0,
        bottom: "auto",
        right: "auto",
        transform: "none"
    },
    "top-right": {
        top: 0,
        right: 0,
        bottom: "auto",
        left: "auto",
        transform: "none"
    },
    center: {
        top: "50%",
        left: "50%",
        bottom: "auto",
        right: "auto",
        transform: "translate(-50%, -50%)",
    },
};

export const startPositionToViewportCSS = (startPosition: StartPos) => {
    return mapStartPosToCSS[startPosition];
};
