import { Schema, IRotateableComponent, IInstance } from "../../types/external";
import { IPage } from "../../types/internal";
import { AComponent } from "../AComponent";
import { Point } from "../../types/external";

export default abstract class ARotateableComponent
    extends AComponent<"rotateable">
    implements IRotateableComponent
{

    public name: "rotateable" = "rotateable";

    constructor(data: Schema["rotateable"], instance: IInstance, page: IPage) {
        super(data, instance, page);
    }

    public getHandlePosition(): Point{
        return this.data.handlePosition;
    }
    public setHandlePosition(handlePosition: Point): void{
        this.data.handlePosition = handlePosition;
    }
    public getStep(): number{
        return this.data.step;
    }
    public setStep(step: number): void{
        this.data.step = step;
    }

    override getDependencies() {
        return ["transform", "render"] as const;
    }
}
