import { AssetPreloader } from "./AssetPreloader";
import { getMapExtensionToType } from "./AssetExtensions";
import { TypedEventEmitter } from "./TypedEventEmitter";
import { AssetsMap, IResolver, ISoundSequencer, Asset, IAssetManager } from "@root/salad/types/internal";
class AssetManager
    extends TypedEventEmitter<{ progress: { value: number } }>
    implements IAssetManager
{
    /**
     *
     * @param assetsMap - map of asset names to paths
     */

    private preloader: AssetPreloader;

    constructor(
        private getAssetsMap: () => AssetsMap,
        private assetResolver: IResolver,
        private soundSequencer: ISoundSequencer
    ) {
        super();
        this.preloader = new AssetPreloader(this.assetResolver, this.soundSequencer);
    }

    public hasKey(name: string): boolean {
        const assetsMap = this.getAssetsMap();
        return name in assetsMap;
    }

    public add(name:string, asset: AssetsMap[string]):void {
        const old = this.getAssetsMap();
        this.getAssetsMap = ()=>{
            return {
                ...old,
                [name]:asset
            }
        }
    }

    public async preload(): Promise<void> {
        let numLoaded = 0;
        const assetsMap = this.getAssetsMap();
        const keysToPreload = Object.keys(assetsMap).filter((key: string) => {
            const asset = assetsMap[key];
            const preload = asset?.metadata?.preload;
            // must be explicitly set to false to not preload. Eg. in builderstray there are hundreds of images - dont preload them all
            return  preload !== false;
        });
        for (const key of keysToPreload) {
            const asset = assetsMap[key];
            const resolvedPath = await this.getPathForKey(key);
            await this.preloader.preload(asset.type, resolvedPath);
            numLoaded++;
            this.emit("progress", {
                value: numLoaded / keysToPreload.length 
            });
        }
    }

    public loadImg(image: HTMLImageElement, src: string): void {
        if(this.assetResolver.loadImg){
            this.assetResolver.loadImg(image, src);
        }
        else{
            image.src = src;
        }
    }

    /**
     * @param key
     * @returns
     */
    public async getPathForKey(key: string): Promise<string> {
        const assetsMap = this.getAssetsMap();
        if (!key) {
            throw new Error("AssetManager.getPathForKey called with empty string");
        }
        else if (this.hasKey(key)) {
            // we found it in the asset map
            const asset = assetsMap[key];
            const type = asset.type;
            const resolverFn = this.assetResolver.getResolverFn(type);
            return await resolverFn(asset.src);
        }
        else{
            const extension = key.lastIndexOf(".") > -1 ? key.split(".").pop() : "";
            const mapExtensionToType = getMapExtensionToType();
            const type = mapExtensionToType[extension.toLowerCase()];
            if (type) {
                const resolverFn = this.assetResolver.getResolverFn(type);
                return await resolverFn(key);
            }
        }
        return key;
    }

    public destroy() : void{
        this.removeAllListeners();
    }
}

export const getAssetManager = (getAssets: () => AssetsMap, resolver: IResolver, soundSequencer: ISoundSequencer): IAssetManager => {
    return new AssetManager(getAssets, resolver, soundSequencer);
};
