/**
 * Drawing component in play mode
 *
 */

import { Schema, PartialSchema, IInstance, Events } from "../../types/external";
import { IPage } from "../../types/internal";
import { drawingCanvas } from "../../utils/domElementFactory";
import { getDrawing } from "../../pageComponents/drawing/DrawingFactory";
import ADrawingComponent from "./ADrawingComponent";
import { InstanceEventsMap } from "../../types/external";
import { PageEventsMap } from "../../types/external";
import { IDrawing } from "../../pageComponents/drawing/types";
import { ComponentUpdate } from "../../types/external";

export default class PlayDrawingComponent extends ADrawingComponent {
    // the actual drawing
    private drawing: IDrawing | undefined;

    // element you draw on
    private _element: HTMLCanvasElement | undefined;

    // drawing or not?
    private _isDrawing: boolean = false;

    constructor(data: Schema["drawing"], instance: IInstance, page: IPage) {
        super(data, instance, page);
        this.onDown = this.onDown.bind(this);
        this.onDrag = this.onDrag.bind(this);
        this.onUp = this.onUp.bind(this);
        this.onToolSettingsChange = this.onToolSettingsChange.bind(this);
        this.handleResize = this.handleResize.bind(this);
    }

    public override getElement(): HTMLCanvasElement | undefined {
        return this._element;
    }

    public override getContext(): CanvasRenderingContext2D | undefined {
        if(!this._element) {
            this._addElement();
        }
        return this._element?.getContext("2d")!;
    }

    public override update(data: Partial<Schema["drawing"]>): void {
        super.update(data);
        this._update();
    }

    // the element you draw in
    private _addElement() {
        const parent = this.getInstanceComponent("render").getElement();
        this._element = drawingCanvas(parent);
        this._element.width = parent.offsetWidth;
        this._element.height = parent.offsetHeight;
    }

    private _removeElement(): void {
        if (this._element && this._element.parentElement) {
            this._element.parentElement.removeChild(this._element);
        }
        this._element = undefined;
    }

    /**
     * Tell the drawing that the tool changed (eg. red pen, blue pencil...)
     * @param eventData
     */
    private onToolSettingsChange(
        eventData: PageEventsMap[typeof Events.DRAWING_TOOL_CHANGE],
    ): void {
        if (this.drawing) {
            this.drawing.updateCurrentToolSettings(eventData.toolSetting);
        }
    }

    /**
     * lifecycle
     */
    public override onCreated(): void {
        super.onCreated();
        this.onComponentUpdated = this.onComponentUpdated.bind(this);
        this._update();
        this.handleResize();
        if (this.data.data) {
            this.drawing!.setData(this.data.data);
        }
    }

    // update the drawing depending whether it's enabled or not
    private _update(): void {
        const tool = this.page.drawing.getCurrentDrawingSetting();

        if (this.data.enabled) {
            this._addElement();
            this._addListeners();
            this.drawing = getDrawing("paper", this._element!, {
                perspectiveScale: 0,
            }, this.getAssetManager());
            this.drawing.updateCurrentToolSettings(tool);
        } else {
            this._removeElement();
            this._removeListeners();
            if (this.drawing) {
                this.drawing.destroy();
                this.drawing = undefined;
            }
            this._isDrawing = false;
        }
    }

    /**
     * listen to the relevant events - pointer down, component resized and tool settings change
     */
    private _addListeners(): void {
        this.instance.events.on(Events.INSTANCE_POINTERDOWN, this.onDown);
        this.instance.events.c.size.on(Events.COMPONENT_UPDATE, this.onComponentUpdated);
        this.page.events.on(Events.DRAWING_TOOL_CHANGE, this.onToolSettingsChange);
    }

    private _removeListeners(): void {
        this.instance.events.off(Events.INSTANCE_POINTERDOWN, this.onDown);
        this.instance.events.off(Events.COMPONENT_UPDATE, this.onComponentUpdated);
        this.page.events.off(Events.PAGE_POINTERDRAG, this.onDrag);
        this.page.events.off(Events.PAGE_POINTERUP, this.onUp);
        this.page.events.off(Events.DRAWING_TOOL_CHANGE, this.onToolSettingsChange);
    }

    /**
     * when you resize the element, we need to resize the drawing
     */
    private onComponentUpdated(update: ComponentUpdate): void {
        this.handleResize();
    }

    public override onDestroyed(): void {
        super.onDestroyed();
        if (this.drawing) {
            this.drawing.destroy();
        }
        this._removeListeners();
        this.instance.events.c.size.off(Events.COMPONENT_UPDATE, this.onComponentUpdated);
    }

    /**
     * On pointer down, start drawing
     * @param eventData
     */
    private onDown(eventData: InstanceEventsMap[typeof Events.INSTANCE_POINTERDOWN]) {
        const localPoint = this.getInstanceComponent("position").globalToLocal(eventData.point);
        this.drawing!.onDown(localPoint.x, localPoint.y);
        this.page.events.on(Events.PAGE_POINTERDRAG, this.onDrag);
        this.page.events.on(Events.PAGE_POINTERUP, this.onUp);
        this._isDrawing = true;
    }

    /**
     * Draw a line
     * @param eventData
     */
    private onDrag(eventData: PageEventsMap[typeof Events.PAGE_POINTERDRAG]) {
        if (this._isDrawing) {
            const localPoint = this.getInstanceComponent("position").globalToLocal(eventData.point);
            this.drawing!.onDrag(localPoint.x, localPoint.y);
        }
    }

    private saveData(): void {
        // save the data
        const base64 = this._element!.toDataURL();
        this.update({
            data: base64,
        });
    }

    /**
     * Stop drawing
     */
    private onUp(): void {
        if (this.data.enabled && this.drawing) {
            this.drawing.onUp();
            this.saveData();
            this._isDrawing = false;
        }
    }

    /**
     * page resized, resize the drawing
     */
    private handleResize(): void {}
}
