/**
 * Different ways of highlighting an element on hover
 */
import { Schema } from "../../types/external";
import { ConstructorOf } from "@root/salad/types/utils";
import {IInstance} from "@root/salad/types/external";
import { getReadyMadeAnimationByName } from "../animations/readyMadeAnimations";
import { AnimatableProps} from "../../types/external";
import { AnimationSettings } from "@root/salad/schema/schema";

export interface IHover {
    destroy(): void;

}

abstract class AHover implements IHover {
    constructor(protected instance: IInstance, protected element: HTMLElement) {}
    public destroy(): void{

    }
}
    
abstract class AFilterHover extends AHover {
    // just a CSS filter
    
    protected abstract getFilter():string;

    constructor(instance: IInstance, element: HTMLElement) {
        super(instance, element);
        const filter = this.getFilter();
        const el = this.element;
        el.style.filter = filter;
    }

    public override destroy(): void {
        const el = this.element;
        el.style.filter = "none";
    }
}

class BlurHover extends AFilterHover {
    protected getFilter():string {
        return "blur(2px)";
    }
}

class GrayscaleHover extends AFilterHover {
    protected getFilter():string {
        return "grayscale(0.75)";
    }
}

class YellowShadowHover extends AFilterHover {
    protected getFilter():string {
        return "drop-shadow(0 0 5px yellow)";
    }
}

class LightenHover extends AFilterHover {
    protected getFilter():string {
        return "brightness(1.15)";
    }
}

class DarkenHover extends AFilterHover {
    protected getFilter():string {
        return "brightness(0.85)";
    }
}

abstract class AAnimationHover extends AHover {

    protected abstract getProps(): AnimatableProps

    protected getSettings(): AnimationSettings{
        return {
            duration: 1,
            repeat: 0
        }
    }

    constructor(instance: IInstance, element: HTMLElement) {
        super(instance, element);
        const animComp = instance.getComponent("animation");
        animComp.playAnimation(this.getProps(), this.getSettings());
    }

    public override destroy(): void {
        const animComp = this.instance.getComponent("animation");
        animComp.stopAnimation();
    }
}

class YellowShadowShakeHover extends AAnimationHover{

    constructor(instance: IInstance, element: HTMLElement) {
        super(instance, element);
        const el = this.element;
        el.style.filter = "drop-shadow(0 0 5px yellow)";
    }

    protected override getProps(): AnimatableProps {
        const shakeAnim = getReadyMadeAnimationByName("shake");
        return shakeAnim!.props;
    }

    protected override getSettings(): AnimationSettings {
        return {
            duration: 1,
            repeat: 3
        }
    }

    public override destroy(): void {
        super.destroy();
        const el = this.element;
        el.style.filter = "none";
    }
}

class FadeInHover extends AAnimationHover{

    protected override getProps(): AnimatableProps {
        const shakeAnim = getReadyMadeAnimationByName("fadein");
        return shakeAnim!.props;
    }
}

class FadeOutHover extends AAnimationHover{

    protected override getProps(): AnimatableProps {
        const shakeAnim = getReadyMadeAnimationByName("fadeout");
        return shakeAnim!.props;
    }
}

class ShakeHover extends AAnimationHover{

    protected override getProps(): AnimatableProps {
        const shakeAnim = getReadyMadeAnimationByName("shake");
        return shakeAnim!.props;
    }

    protected override getSettings(): AnimationSettings {
        return {
            duration: 1,
            repeat: 3
        }
    }
}

type HoverType = Exclude<Schema["hover"]["type"], "none">

const hoverMap:{[name in HoverType]: ConstructorOf<AHover, [IInstance, HTMLElement]>} = {
    lighten: LightenHover,
    darken: DarkenHover,
    shake: ShakeHover,
    blur: BlurHover,
    yellowshadow: YellowShadowHover,
    yellowshadowshake: YellowShadowShakeHover,
    fadein: FadeInHover,
    fadeout: FadeOutHover,
    grayscale: GrayscaleHover
}

export const getHover = (type: HoverType, instance: IInstance): IHover => {
    const Klass = hoverMap[type];
    if (Klass) {
        const renderComponent = instance.getComponent("render");
        const el = renderComponent.getElement();
        return new Klass(instance, el);
    }
    return undefined;
};
