import { InstanceEventsMap, IInstanceEventEmitter } from "../types/external";
import { TypedEventEmitter } from "../utils/TypedEventEmitter";
import { ComponentName, allComponentNames } from "../types/external";
import { IndividualComponentUpdate } from "../types/external";

class ComponentEventEmitter extends TypedEventEmitter<IndividualComponentUpdate>  {
    constructor() {
        super();
    }

    public destroy(): void {
        this.removeAllListeners();
    }
}


export class InstanceEventEmitter
    extends TypedEventEmitter<InstanceEventsMap>
    implements IInstanceEventEmitter
{
    
    c:{
        [k in ComponentName]: ComponentEventEmitter;
    }

    constructor() {
        super();
        this.c = {} as any;
        for (const key of allComponentNames) {
            this.c[key] = new ComponentEventEmitter();
        }
    }

    public destroy(): void {
        this.removeAllListeners();
    }
}

export const getEventEmitter = (): IInstanceEventEmitter => {
    return new InstanceEventEmitter();
};
