import { Schema } from "../../types/external";

const buttonColors: { [type in Schema["button"]["type"]]: string } = {
    green: "#43A047",
    purple: "#8E24AA",
    red: "#E53935",
    blue: "#1E88E5",
    transparent_white: "transparent",
    transparent_black: "transparent"
};

export const getColorForTheme = (type: Schema["button"]["type"]) => buttonColors[type];
