import { IInstance } from "../../types/external";
import { Point } from "../../types/external";
import { IPage } from "../../types/internal";

export class PositionConstraints {
    constructor(
        private instance: IInstance,
        private page: IPage,
    ) {}

    public applyConstraints(newPosition: Point): Point | undefined {
        const fns = [
            this.applyDestroy.bind(this),
            this.applyWrap.bind(this),
            this.applyContainment.bind(this),
        ];

        for (let fn of fns) {
            newPosition = fn(newPosition);
            if (!newPosition) {
                return undefined;
            }
        }

        return newPosition;
    }

    private applyDestroy(newPosition: Point): Point | undefined {
        const movementComp = this.instance.getComponent("movement");
        // put it back on the screen when it goes off. Use the centre of the object

        if (movementComp && movementComp.getDestroy()) {
            const bgSize = this.page.getComponent("background").getSize();
            // this is where the centre would be if it moved
            const futureCentre = this.instance
                .getComponent("collision")
                .getFutureCentreAtNewPosition(newPosition);

            const offScreenX = futureCentre.x < 0 || futureCentre.x > bgSize.width;
            const offScreenY = futureCentre.y < 0 || futureCentre.y > bgSize.height;

            if (offScreenX || offScreenY) {
                //destroy it
                this.page.instances.destroyInstance(this.instance);
                return undefined;
            }
        }

        return newPosition;
    }

    private applyWrap(newPosition: Point): Point | undefined {
        const movementComp = this.instance.getComponent("movement");
        // put it back on the screen when it goes off. Use the centre of the object

        if (movementComp && movementComp.getWrap()) {

            const circle = this.instance.getComponent("transform").getMaximalBoundingCircle(newPosition);
            const bgSize = this.page.getComponent("background").getSize();

            // if the circle is on the screen then the lelement is
            if(circle.centre.x + circle.radius < bgSize.width && circle.centre.x - circle.radius > 0 && circle.centre.y + circle.radius < bgSize.height && circle.centre.y - circle.radius > 0){
                // no way it's going off the screen!
                return newPosition;
            }

            // this is where the centre would be if it moved
            const futureCentre = this.instance
                .getComponent("collision")
                .getFutureCentreAtNewPosition(newPosition);

            /**
             * eg. if the bg is 1024 and the object is at 1023 then this is 0 - do nothing
             * if the bg is 1024 and the object is at 1025 then this is 1 - subtract 1024 to get it back
             * if the bg is 1024 and the object is at 2049 then this is 2 - subtract 2048 to get it back
            */

            let pageThatContainsCentreX = Math.floor(futureCentre.x / bgSize.width);
            let pageThatContainsCentreY = Math.floor(futureCentre.y / bgSize.height);

            const correctionX = pageThatContainsCentreX * bgSize.width;
            const correctionY = pageThatContainsCentreY * bgSize.height;

            return {
                x: newPosition.x - correctionX,
                y: newPosition.y - correctionY,
            };
        }
        return newPosition;
    }

    private applyContainment(newPosition: Point): Point | undefined {
        const containmentComp = this.instance.getComponent("containment");
        if (containmentComp && !containmentComp.canMoveTo(newPosition)) {
            //nope, put it back and stop it moving
            this.instance.getComponent("velocity").stop();
            return undefined;
        } else {
            return newPosition;
        }
    }
}
