/**
 * transform component. Handles rotation, scale, and origin
 */

import { ITransformComponent, IInstance, Schema, Point } from "../../types/external";
import { IPage } from "../../types/internal";
import { AComponent } from "../AComponent";
import { CSSDomUpdate } from "../../types/external";
export default class TransformComponent
    extends AComponent<"transform">
    implements ITransformComponent
{
    public name: "transform" = "transform";

    constructor(data: Schema["transform"], instance: IInstance, page: IPage) {
        super(data, instance, page);
    }

    override getDependencies() {
        return ["render", "size", "position"] as const;
    }

    override onCreated() {
        super.onCreated();
        this._updateElement();
    }

    /**
     * set the rotation, but by making it face a point
     * @param x
     * @param y
     */
    public facePoint(x: number, y: number): void {
        const pos = this.getInstanceComponent("position").getPosition();
        const dy = y - pos.y;
        const dx = x - pos.x;
        const angle = Math.atan2(dy, dx);
        this.setRotationWithOffset((angle * 180) / Math.PI);
    }

    public getMaximalBoundingCircle(pos: Point): { centre: Point; radius: number }{
        const origin = this.getOriginPoint();
        const sizeComp = this.instance.getComponent("size");
        const size = sizeComp.getSize();

        const diagX = Math.max(origin.x, size.width - origin.x);
        const diagY = Math.max(origin.y, size.height - origin.y);

        const radius = Math.sqrt(diagX * diagX + diagY * diagY);

        return {
            centre: {
                x: pos.x + origin.x,
                y: pos.y + origin.y,
            },
            radius
        };
    }

    public getScale(): { x: number; y: number } {
        return {
            x: this.data.scale.x,
            y: this.data.scale.y,
        };
    }

    public getOrigin(): `${number}% ${number}%` {
        return this.data.origin;
    }

    public getLockAspectRatio(): number {
        return this.data.lockAspectRatio;
    }

    public setLockAspectRatio(ratio: number): void {
        this.data.lockAspectRatio = ratio;
    }

    public setOrigin(p: `${number}% ${number}%`): void {
        this.data.origin = p;
    }

    public getRotation(): number {
        return this.data.rotation;
    }

    /**
     * in degrees. along the x axis is zero
     * @returns
     */
    public getDirectionFacing(): number {
        const rot = this.getRotation();
        const offset = this.instance.getComponent("movement").getOffsetAngle();
        return rot + offset;
    }
    /**
     * scale the element. If only one argument is passed, it is assumed to be the same for x and y
     * Eg. scale(2) = scale(2, 2)
     * @param sx
     * @param sy
     */
    public setScale(s: Point): void {
        this.data.scale = {
            x: s.x,
            y: s.y,
        };
        this._updateElement();
    }

    public setRotationWithOffset(angleDegrees: number): void {
        const offset = this.instance.getComponent("movement").getOffsetAngle();
        this.setRotation(offset + angleDegrees);
    }

    public setRotation(angleDegrees: number): void {
        this.data.rotation = angleDegrees;
        this._updateElement();
    }

    /**
     * Like in CSS, the origin is a string with two numbers separated by a space
     * Eg "50% 50%" is the center, and the default.
     * @returns
     */
    public getOriginPoint(): Point {
        const origin: `${number}% ${number}%` = this.getOrigin();
        const size = this.getInstanceComponent("size").getSize();
        const [originX, originY] = origin.split(" ").map((value) => parseInt(value)); // eg. [70, 30]
        const x = (size.width * originX) / 100;
        const y = (size.height * originY) / 100;
        return {
            x,
            y,
        };
    }

    /**
     * 
     * @returns - the origin point, but relative to the page
     */
    public getCurrentOriginPoint(): Point {
        const pos = this.getInstanceComponent("position").getPosition();
        // if the shape was not rotated the origin would be here:
        const origin = this.getOriginPoint();
        const unRotatedOrigin = {
            x: pos.x + origin.x,
            y: pos.y + origin.y,
        }
        // but the origin of rotation does not move when we rotate it
       return unRotatedOrigin;
    }

    /**
     * the CSS we should actually use
     * @returns
     */
    public getCSS(): CSSDomUpdate["css"] {
        return {
            transform:{
                rotate: `${this.data.rotation}deg`,
                scaleX: this.data.scale.x,
                scaleY: this.data.scale.y,
                skew: `${this.data.skew}deg`,

            },
            transformOrigin: this.getOrigin(),
        };
    }

    public override update(data: Schema["transform"]) {
        super.update(data);
        this._updateElement();
    }

    /**
     * Position the element at the right place each frame
     * @param copy
     * @param world
     */
    private _updateElement() {
        const renderComp = this.getInstanceComponent("render");
        const element = renderComp.getElement();
        if (element) {
            const css = this.getCSS();
            this.page.getComponent("domupdate").addCSSUpdate({
                element,
                css,
            })
        }
    }
}
