/**
 * Each page has a name, which is used to identify it
 */

import { IPage, IPageIdentityComponent } from "../../types/internal";
import { APageComponent } from "../APageComponent";
import { PageSchema } from "../../types/external";

export default class PageIdentityComponent
    extends APageComponent<"identity">
    implements IPageIdentityComponent
{
    public name: "identity" = "identity";

    constructor(data: PageSchema["identity"], page: IPage) {
        super(data, page);
    }

    public setDisplayName(name: string): void {
        this.data.displayName = name;
    }

    public getDisplayName(): string {
        return this.data.displayName;
    }
}
