import Salad from "../../../index";
import { SaladJSONValue, SaladJSONObject } from "../../../types/external";
import { IActivityDataComponent } from "../../../types/external";
import { AActivityComponent } from "../AActivityComponent";
import { ActivityOptions } from "../../../types/internal";

export class ActivityDataComponent extends AActivityComponent implements IActivityDataComponent{

    private data: SaladJSONObject = {}

    constructor(private activity: Salad.IActivity, private options: ActivityOptions) {
        super();
        this.data = options.data || {};
    }

    public getAll(): SaladJSONObject {
        return this.data;
    }

    /**
     *
     * @param key get value for key
     * @returns
     */
    public getForKey(key: string): SaladJSONValue{
        return this.data![key];
    }

    /**
     * set value for key
     * @param key
     * @param value
     */
    public setValueForKey(key: string, value: SaladJSONValue): void {
        this.data![key] = value;
    }

    public getForPage(pageName: string):SaladJSONObject{
        const pages = this.options.pages
        const pageData = pages.find((page) => page.schema!.identity!.displayName === pageName)
        if(pageData){
            const schema = pageData ? pageData.schema : undefined;
            return schema!.data!.value as SaladJSONObject || {};
        }
        return {};
    }

}
