

import { IGroupComponent } from "../../types/external";
import { IInstance, Schema } from "../../types/external";
import { IPage } from "../../types/internal";
import { AComponent } from "../AComponent";
import Salad from "../..";

type Groups = Salad.Schema["group"]["value"];

export default abstract class AGroupComponent
    extends AComponent<"group">
    implements IGroupComponent
{
    public name: "group" = "group";

    constructor(data: Schema["group"], instance: IInstance, page: IPage) {
        super(data, instance, page);
    }

    public addToGroup(instanceName:string, offset?:{x:number, y:number}):void{
        const newValue = [
            ...this.data.value,
            {
                name: instanceName,
                offset: offset
            }
        ]
        this.update({
            value: newValue
        })
    }

    public setGroups(newValue: Groups):void{
        this.update({
            value: newValue
        })
    }
}
