import {Polygon as FPolygon, Point as FPoint} from "@flatten-js/core";
import { Polygon } from "../../types/external";
import { Point } from "../../types/external";
import { getCentre } from "../PolygonUtils";
import { applyTransforms, applyTranslate } from "../PolygonUtils";
import { drawPolygon } from "../PolygonUtils";
import { AShape } from "./Shapes";
import { toAxisAlignedRect, AAR, isAxisAlignedRect } from "./AxisAlignedRect";
export class PolygonShape extends AShape {

    private _implementation: InstanceType<typeof FPolygon>;
    private _isAxisAlignedRect = false;

    constructor(private _poly: Polygon) {
        super();
        this._isAxisAlignedRect = isAxisAlignedRect(_poly);
    }

    public override toAxisAlignedRect(): AAR | undefined{
        return this._isAxisAlignedRect ? toAxisAlignedRect(this._poly): undefined;   
    }

    public getImplementation(): InstanceType<typeof FPolygon> {
        if(!this._implementation){
            this._implementation = new FPolygon();
            const face = this._poly.map((p) => new FPoint(p.x, p.y));
            this._implementation.addFace(face);
        }
        return this._implementation;
    }

    public toJSON(){
        const vertices = this.getImplementation()
            .vertices
            .map(v=>v.toJSON())
            .map((v: any)=>({
                x:v["x"],
                y:v["y"]
            }));

        return {
            vertices
        }
    }

    public override getCentre(): Point {
        return getCentre(this._poly);
    }

    public override offset(p: Point): PolygonShape {
        const poly = applyTranslate(this._poly, p);
        return new PolygonShape(poly);
    }

    public override transform(
        trans: Point,
        scale: Point,
        rot: number,
        origin: Point,
    ): PolygonShape {
        const poly = applyTransforms(this._poly, trans, scale, rot, origin);
        return new PolygonShape(poly);
    }

    public override drawIn(ctx: CanvasRenderingContext2D): void {
        return drawPolygon(this._poly, ctx);
    }

}
