import { IAngularVelocityComponent } from "../../types/external";
import { Schema, IInstance } from "../../types/external";
import { AComponent } from "../AComponent";
import { IPage } from "../../types/internal";

/**
 * angular velocity controls the speed of rotation of an object
 */
export default abstract class AAngularVelocityComponent
    extends AComponent<"angularvelocity">
    implements IAngularVelocityComponent
{
    public name: "angularvelocity" = "angularvelocity";

    constructor(data: Schema["angularvelocity"], instance: IInstance, page: IPage) {
        super(data, instance, page);
    }
    override getDependencies() {
        return ["transform"] as const;
    }

    public increaseBy(val: number): void {
        this.setAngularVelocity(this.data!.value! + val);
    }

    public setAngularVelocity(value: number): void {
        const max = this.instance.getComponent("movement")!.getMaxAngularSpeed();
        if (value > max) {
            value = max;
        } else if (value < -max) {
            value = -max;
        }
        this.data.value = value;
    }

    public getAngularVelocity(): number {
        return this.data.value!;
    }
}
