import { CSSDomUpdate } from "../../types/external";

// Optimized merge function
export const mergeCSS = (currentValue: CSSDomUpdate["css"] | undefined, newValue: CSSDomUpdate["css"]): CSSDomUpdate["css"] => {
    if (!currentValue) {
        return newValue;
    }
    
    const result = {} as CSSDomUpdate["css"];
    
    for (const key in currentValue) {
        if (key === 'transform') {
            continue;
        }
        (result as any)[key] = (currentValue as any)[key];
    }

    for (const key in newValue) {
        if (key === 'transform'){
            continue;
        }
        (result as any)[key] = (newValue as any)[key];
    }

    if(currentValue.transform || newValue.transform){
        result.transform = {};
    }
    
    if (currentValue.transform) {
        const currentTransform = currentValue.transform;
        for (const key in currentTransform) {
            (result.transform as any)[key] = (currentTransform as any)[key];
        }
    }
    
    if (newValue.transform) {
        const newTransform = newValue.transform;
        for (const key in newTransform) {
            (result.transform as any)[key] = (newTransform as any)[key];
        }
    }
    
    return result;
}
