// t = 0 means 100% of the first value, t = 1 means 100% of the second value
type Rect = {
    x: number;
    y: number;
    size: number;
};

function mixColorsWithWeight(
    colorA: [number, number, number, number],
    colorB: [number, number, number, number],
    weight: number,
) {
    const normalizedWeightA = weight;
    const normalizedWeightB = 1 - weight;

    // Extract RGBA components and normalize them to the range [0, 1]
    const [rA, gA, bA, aA] = colorA.map((x) => x / 255);
    const [rB, gB, bB, aB] = colorB.map((x) => x / 255);

    // Compute the resulting alpha
    const aR = aA * normalizedWeightA + aB * normalizedWeightB;

    // Compute the resulting RGB components
    let rR, gR, bR;
    if (aR > 0) {
        rR = (rA * aA * normalizedWeightA + rB * aB * normalizedWeightB) / aR;
        gR = (gA * aA * normalizedWeightA + gB * aB * normalizedWeightB) / aR;
        bR = (bA * aA * normalizedWeightA + bB * aB * normalizedWeightB) / aR;
    } else {
        rR = gR = bR = 0;
    }

    // Convert the resulting components back to the range [0, 255]
    return [Math.round(rR * 255), Math.round(gR * 255), Math.round(bR * 255), Math.round(aR * 255)];
}

export const smearCanvas = (
    canvas: HTMLCanvasElement,
    src: Rect,
    dest: Rect,
    mix: number = 0.5,
) => {
    const ctx = canvas.getContext("2d");

    src.x = Math.round(src.x);
    src.y = Math.round(src.y);

    dest.x = Math.round(dest.x);
    dest.y = Math.round(dest.y);

    const srcData = ctx!.getImageData(src.x, src.y, src.size, src.size);
    const destData = ctx!.getImageData(dest.x, dest.y, dest.size, dest.size);

    // use a circle
    const radius = dest.size / 2;
    const halfDestSizeSqr = radius * radius;

    for (let i = 0; i < dest.size; i++) {
        for (let j = 0; j < dest.size; j++) {
            const di = i - dest.size / 2;
            const dj = j - dest.size / 2;
            const radiusSqr = di * di + dj * dj;
            if (radiusSqr < halfDestSizeSqr) {
                const t = radiusSqr / halfDestSizeSqr;
                let _mix = mix * (1 - t);
                const destIndex = (i * dest.size + j) * 4;
                const srcI = Math.floor((i * src.size) / dest.size);
                const srcJ = Math.floor((j * src.size) / dest.size);
                const srcIndex = (srcI * src.size + srcJ) * 4;

                if (srcIndex >= 0 && srcIndex < srcData.data.length) {
                    // ok

                    const srcColor = [
                        srcData.data[srcIndex],
                        srcData.data[srcIndex + 1],
                        srcData.data[srcIndex + 2],
                        srcData.data[srcIndex + 3],
                    ] as [number, number, number, number];

                    const destColor = [
                        destData.data[destIndex],
                        destData.data[destIndex + 1],
                        destData.data[destIndex + 2],
                        destData.data[destIndex + 3],
                    ] as [number, number, number, number];

                    const mixed = mixColorsWithWeight(srcColor, destColor, _mix);

                    destData.data[destIndex] = mixed[0];
                    destData.data[destIndex + 1] = mixed[1];
                    destData.data[destIndex + 2] = mixed[2];
                    destData.data[destIndex + 3] = mixed[3];
                }
            }
        }
    }
    ctx!.putImageData(destData, dest.x, dest.y, 0, 0, dest.size, dest.size);
};
