/**
 * Highlight in play mode
 */

import { Schema, IInstance, Events } from "../../types/external";
import AHoverComponent from "./AHoverComponent";
import { IPage } from "../../types/internal";
import { IHover, getHover } from "./HoverEffects";
export default class PlayHoverComponent extends AHoverComponent {

    private hover: IHover;

    constructor(data: Schema["hover"], instance: IInstance, page: IPage) {
        super(data, instance, page);
        this.onMouseOut = this.onMouseOut.bind(this);
        this.onMouseOver = this.onMouseOver.bind(this);
    }

    /**
     * lifecycle
     */
    public override onCreated(): void {
        super.onCreated();
        if (this.data.type !== "none") {
            this.addListeners();
        }
    }

    public override onDestroyed(): void {
        super.onDestroyed();
        this.removeListeners();
        this.updateHover(undefined);
    }

    private addListeners(): void {
        this.instance.events.on(Events.INSTANCE_MOUSEOVER, this.onMouseOver);
        this.instance.events.on(Events.INSTANCE_MOUSEOUT, this.onMouseOut);
    }

    private updateHover(type: Schema["hover"]["type"] | undefined): void {
        if(this.hover){
            this.hover.destroy();
            this.hover = undefined;
        }
        if(type && type !== "none"){
            this.hover = getHover(type, this.instance);
        }
    }

    private onMouseOver() {
        this.updateHover(this.data.type);
    }

    private onMouseOut() {
        this.updateHover(undefined);
    }

    private removeListeners(): void {
        this.instance.events.off(Events.INSTANCE_MOUSEOVER, this.onMouseOver);
        this.instance.events.off(Events.INSTANCE_MOUSEOUT, this.onMouseOut);
    }

    /**
     * in play mode we can change the highlight type and it actually makes the highlight too
     * @param type
     */
    public override setHover(type: Schema["hover"]["type"]): void {
        super.setHover(type);
        this.removeListeners();
        if (this.data.type !== "none") {
            this.addListeners();
        }
    }
}
